{
  "timeline": [
    {
      "headline": "Formation of the Five Families",
      "text": "In 1931, Salvatore Maranzano reorganized the Italian American gangs in New York City into five families following his victory in the Castellammarese War. These families were initially known as the Maranzano, Profaci, Mangano, Luciano, and Gagliano families.",
      "date": "1931"
    },
    {
      "headline": "Renaming of the Families",
      "text": "Over time, the original names of the families were changed to Bonanno, Colombo, Gambino, Genovese, and Lucchese, reflecting the names of prominent leaders within each family.",
      "date": "1931"
    },
    {
      "headline": "Establishment of the Commission",
      "text": "In 1931, following the formation of the Five Families, a governing body known as 'The Commission' was established to oversee organized crime activities and mediate disputes among the families.",
      "date": "1931"
    },
    {
      "headline": "The Apalachin Meeting",
      "text": "On November 14, 1957, a meeting of the American Mafia leaders was held in Apalachin, New York, which was attended by members of the Five Families. The meeting was raided by law enforcement, leading to increased scrutiny of Mafia activities.",
      "date": "1957-11-14"
    },
    {
      "headline": "The Commission Trial",
      "text": "From 1985 to 1986, the Commission Trial took place, which was a significant legal case against the leaders of the Five Families. It resulted in the conviction of several top Mafia figures, including heads of the families.",
      "date": "1985"
    }
  ]
}

