  "timeline": [
    {
      "headline": "First European Exploration",
      "text": "In 1539, the first European to explore Arizona was Marcos de Niza, a Spanish Franciscan friar.",
      "date": "1539"
    },
    {
      "headline": "Spanish Expedition",
      "text": "In 1540, Francisco Vázquez de Coronado led a large Spanish expedition through Arizona in search of the fabled Seven Cities of Gold.",
      "date": "1540"
    },
    {
      "headline": "Establishment of Missions",
      "text": "In the late 1600s, Jesuit missionaries, including Father Eusebio Francisco Kino, established missions in southern Arizona.",
      "date": "1690"
    },
    {
      "headline": "Gadsden Purchase",
      "text": "In 1853, the United States acquired the southern part of Arizona from Mexico through the Gadsden Purchase.",
      "date": "1853"
    },
    {
      "headline": "Arizona Territory Established",
      "text": "On February 24, 1863, the Arizona Territory was officially established, separating it from the New Mexico Territory.",
      "date": "1863-02-24"
    },
    {
      "headline": "Statehood",
      "text": "Arizona became the 48th state of the United States on February 14, 1912.",
      "date": "1912-02-14"
    },
    {
      "headline": "Grand Canyon National Park Established",
      "text": "On February 26, 1919, the Grand Canyon was designated as a National Park.",
      "date": "1919-02-26"
    },
    {
      "headline": "Central Arizona Project",
      "text": "In 1968, the Central Arizona Project was authorized to provide water from the Colorado River to central and southern Arizona.",
      "date": "1968"
    },
    {
      "headline": "Martin Luther King Jr. Day Controversy",
      "text": "In 1992, Arizona voters approved the observance of Martin Luther King Jr. Day as a state holiday after a national boycott.",
      "date": "1992"
    },
    {
      "headline": "Arizona Immigration Law",
      "text": "In 2010, Arizona passed SB 1070, a controversial immigration law that was challenged in the courts.",
      "date": "2010"
    }
  ]
}

