  "timeline": [
    {
      "headline": "Origin of Kabaddi",
      "text": "Kabaddi is believed to have originated in ancient India. It is a traditional sport that has been played for centuries, with its roots tracing back to Indian mythology and history.",
      "date": "-0400"
    },
    {
      "headline": "Kabaddi in Ancient Texts",
      "text": "The game of Kabaddi is mentioned in ancient Indian texts such as the Mahabharata, where it is said that Arjuna used a form of Kabaddi to sneak into enemy territory.",
      "date": "-0300"
    },
    {
      "headline": "Kabaddi in the 20th Century",
      "text": "Kabaddi gained formal recognition and began to be played in a more organized manner in the early 20th century. It was popularized in various regions of India.",
      "date": "1920"
    },
    {
      "headline": "Formation of the All India Kabaddi Federation",
      "text": "The All India Kabaddi Federation was formed in 1950 to promote the sport at a national level and organize competitions.",
      "date": "1950"
    },
    {
      "headline": "Introduction to Asian Games",
      "text": "Kabaddi was introduced as a demonstration sport in the 1951 Asian Games held in New Delhi, India.",
      "date": "1951"
    },
    {
      "headline": "First National Championship",
      "text": "The first national championship for Kabaddi was held in Chennai, India, in 1952.",
      "date": "1952"
    },
    {
      "headline": "Kabaddi in the Asian Games",
      "text": "Kabaddi was included as a regular sport in the Asian Games starting from the 1990 Asian Games held in Beijing, China.",
      "date": "1990"
    },
    {
      "headline": "Inception of Pro Kabaddi League",
      "text": "The Pro Kabaddi League, a professional Kabaddi league in India, was launched in 2014, bringing a new level of popularity and commercial success to the sport.",
      "date": "2014"
    }
  ]
}

