{
  "timeline": [
    {
      "headline": "Emergence of Samurai",
      "text": "The samurai class began to emerge as provincial warriors serving the Kuge and imperial court in the late 12th century.",
      "date": "1180"
    },
    {
      "headline": "Kamakura Shogunate Established",
      "text": "In 1192, Minamoto no Yoritomo established the Kamakura Shogunate, marking the rise of samurai political power.",
      "date": "1192"
    },
    {
      "headline": "Muromachi Period",
      "text": "The Muromachi period (1336-1573) saw the Ashikaga Shogunate rule, during which samurai culture and influence continued to grow.",
      "date": "1336"
    },
    {
      "headline": "Sengoku Period",
      "text": "The Sengoku period (1467-1615) was a time of social upheaval, political intrigue, and near-constant military conflict, where samurai played a central role.",
      "date": "1467"
    },
    {
      "headline": "Tokugawa Shogunate Established",
      "text": "In 1603, Tokugawa Ieyasu established the Tokugawa Shogunate, ushering in a period of peace and stability where samurai became bureaucrats and administrators.",
      "date": "1603"
    },
    {
      "headline": "Meiji Restoration",
      "text": "The Meiji Restoration in 1868 marked the beginning of the end for the samurai class as Japan modernized and abolished the feudal system.",
      "date": "1868"
    },
    {
      "headline": "Abolition of Samurai Privileges",
      "text": "In the late 1870s, the Meiji government formally abolished the samurai class and their privileges, integrating them into the new conscripted military.",
      "date": "1876"
    }
  ]
}

{
  "timeline": [
