    },
    {
      "headline": "Establishment of Green Bay",
      "text": "In 1669, the first permanent European settlement in Wisconsin was established at Green Bay by French fur traders.",
      "date": "1669"
    },
    {
      "headline": "Wisconsin Becomes Part of the United States",
      "text": "In 1783, following the American Revolutionary War, the Treaty of Paris was signed, and the land that would become Wisconsin was ceded to the United States.",
      "date": "1783"
    },
    {
      "headline": "Northwest Ordinance",
      "text": "In 1787, the Northwest Ordinance was enacted, establishing the Northwest Territory, which included present-day Wisconsin.",
      "date": "1787"
    },
    {
      "headline": "Creation of Wisconsin Territory",
      "text": "On July 3, 1836, the Wisconsin Territory was created, separating it from the Michigan Territory.",
      "date": "1836-07-03"
    },
    {
      "headline": "Wisconsin Achieves Statehood",
      "text": "On May 29, 1848, Wisconsin was admitted to the Union as the 30th state.",
      "date": "1848-05-29"
    },
    {
      "headline": "Milwaukee Becomes a City",
      "text": "In 1846, Milwaukee was incorporated as a city, becoming a major center for industry and immigration.",
      "date": "1846"
    },
    {
      "headline": "University of Wisconsin Founded",
      "text": "In 1848, the University of Wisconsin was founded in Madison, becoming a major educational institution.",
      "date": "1848"
    },
    {
      "headline": "Progressive Era Reforms",
      "text": "In the early 20th century, under leaders like Robert M. La Follette, Wisconsin became a leader in progressive reforms, including labor rights and government transparency.",
      "date": "1900"
    },
    {
      "headline": "Great Depression and New Deal",
      "text": "During the 1930s, Wisconsin was significantly affected by the Great Depression, and many New Deal programs were implemented to aid recovery.",
      "date": "1930"
    },
    {
      "headline": "Civil Rights Movement",
      "text": "In the 1960s, Wisconsin was active in the Civil Rights Movement, with significant protests and legislative changes occurring throughout the state.",
      "date": "1960"
    },
    {
      "headline": "Act 10 Protests",
      "text": "In 2011, large-scale protests occurred in Wisconsin in response to Governor Scott Walker's Act 10, which affected collective bargaining rights for public employees.",
