{
  "timeline": [
    {
      "headline": "Discovery of Epstein–Barr Virus",
      "text": "In 1964, the Epstein–Barr virus (EBV) was discovered by Michael Anthony Epstein and Yvonne Barr at the University of Bristol. It was identified as the first human virus capable of causing cancer.",
      "date": "1964"
    },
    {
      "headline": "Link to Infectious Mononucleosis",
      "text": "In the late 1960s, EBV was linked to infectious mononucleosis, a condition characterized by fever, sore throat, and swollen lymph glands.",
      "date": "1960s"
    },
    {
      "headline": "Association with Burkitt's Lymphoma",
      "text": "In the 1960s, EBV was associated with Burkitt's lymphoma, a type of cancer common in Africa, marking it as the first virus linked to cancer in humans.",
      "date": "1960s"
    },
    {
      "headline": "Connection to Nasopharyngeal Carcinoma",
      "text": "In the 1970s, EBV was found to be associated with nasopharyngeal carcinoma, a type of cancer prevalent in Southeast Asia.",
      "date": "1970s"
    },
    {
      "headline": "Identification as an Oncogenic Virus",
      "text": "EBV was recognized as the first identified oncogenic virus, meaning it has the potential to cause cancer in humans.",
      "date": "1970s"
    },
    {
      "headline": "Research on EBV Vaccines",
      "text": "Various vaccine formulations have been tested in animals and humans over the years, but none have successfully prevented EBV infection. As of 2023, no vaccine has been approved.",
      "date": "2023"
    }
  ]
}

