    {
      "headline": "Middle High German Period",
      "text": "The Middle High German period lasted from approximately 1050 to 1350. This era saw the development of a more standardized form of German, influenced by the cultural and political changes of the time.",
      "date": "1050"
    },
    {
      "headline": "Early New High German Period",
      "text": "The Early New High German period spanned from 1350 to 1650. This period was marked by significant linguistic changes and the influence of the printing press, which helped standardize the language.",
      "date": "1350"
    },
    {
      "headline": "Martin Luther's Bible Translation",
      "text": "In 1534, Martin Luther completed his translation of the Bible into German. This translation played a crucial role in the development of a standardized German language and increased literacy among German speakers.",
      "date": "1534"
    },
    {
      "headline": "New High German Period",
      "text": "The New High German period began around 1650 and continues to the present day. This period is characterized by the standardization of the German language and its establishment as a major European language.",
      "date": "1650"
    },
    {
      "headline": "German as an Official Language",
      "text": "German is recognized as an official language in several countries, including Germany, Austria, Switzerland, Liechtenstein, and the Italian autonomous province of South Tyrol. It is also an official language of Luxembourg, Belgium, and the Italian autonomous region of Friuli-Venezia Giulia.",
      "date": "1900"
    },
    {
      "headline": "German Language in the European Union",
      "text": "German is the most spoken native language within the European Union, reflecting its widespread use and importance in Europe.",
      "date": "2000"
    }
  ]
}

