      "headline": "Hillsborough Disaster Occurs",
      "text": "On 15 April 1989, a fatal crowd crush occurred at Hillsborough Stadium in Sheffield, South Yorkshire, England, during an FA Cup semi-final between Liverpool and Nottingham Forest. The disaster resulted in 97 fatalities and 766 injuries, making it the deadliest in British sporting history.",
      "date": "1989-04-15"
    },
    {
      "headline": "Immediate Aftermath and Initial Death Toll",
      "text": "Ninety-four people died on the day of the disaster, and one more died in hospital days later, bringing the initial death toll to 95.",
      "date": "1989-04"
    },
    {
      "headline": "FA Cup Semi-final Match Abandoned and Rescheduled",
      "text": "The FA Cup semi-final match was abandoned due to the disaster and was restaged at Old Trafford in Manchester on 7 May 1989. Liverpool won the match and went on to win that season's FA Cup.",
      "date": "1989-05-07"
    },
    {
      "headline": "Tony Bland's Death",
      "text": "Tony Bland, who suffered irreversible brain damage on the day of the disaster, died in 1993, becoming the 96th victim of the Hillsborough disaster.",
      "date": "1993"
    },
    {
      "headline": "97th Victim Dies",
      "text": "In 2021, a 97th victim died as a result of injuries sustained during the Hillsborough disaster, having suffered irreversible brain damage on the day.",
      "date": "2021"
    }
  ]
}

