    {
      "headline": "First Settlement",
      "text": "The area of present-day Beijing was first settled around 1045 BCE during the Zhou Dynasty.",
      "date": "-1045"
    },
    {
      "headline": "Ji City Established",
      "text": "In 1045 BCE, the city of Ji was established as a city-state, marking the early beginnings of what would become Beijing.",
      "date": "-1045"
    },
    {
      "headline": "Yanjing Capital",
      "text": "During the Warring States period (473–221 BCE), the city became the capital of the State of Yan and was known as Yanjing.",
      "date": "-0473"
    },
    {
      "headline": "Jin Dynasty Capital",
      "text": "In 1153, the Jin dynasty made Beijing its central capital, known as Zhongdu.",
      "date": "1153"
    },
    {
      "headline": "Mongol Conquest",
      "text": "In 1215, the city was captured by the Mongols under Genghis Khan.",
      "date": "1215"
    },
    {
      "headline": "Yuan Dynasty Capital",
      "text": "In 1271, Kublai Khan established the Yuan dynasty and made Beijing the capital, renaming it Dadu.",
      "date": "1271"
    },
    {
      "headline": "Ming Dynasty Capital",
      "text": "In 1421, the Ming dynasty moved the capital from Nanjing to Beijing, making it the primary capital of China.",
      "date": "1421"
    },
    {
      "headline": "Qing Dynasty Era",
      "text": "From 1644, Beijing served as the capital of the Qing dynasty until its fall in 1912.",
      "date": "1644"
    },
    {
      "headline": "Republic of China",
      "text": "In 1912, following the fall of the Qing dynasty, Beijing became the capital of the Republic of China.",
      "date": "1912"
    },
    {
      "headline": "Japanese Occupation",
      "text": "During the Second Sino-Japanese War, Beijing was occupied by Japanese forces from 1937 to 1945.",
      "date": "1937"
    },
    {
      "headline": "People's Republic of China",
      "text": "On October 1, 1949, Mao Zedong proclaimed the establishment of the People's Republic of China in Beijing, which became the capital.",
      "date": "1949-10-01"
    },
    {
      "headline": "Cultural Revolution",
      "text": "From 1966 to 1976, Beijing was a central location for the Cultural Revolution initiated by Mao Zedong.",
      "date": "1966"
    },
    {
      "headline": "1989 Tiananmen Square Protests",
      "text": "In 1989, Beijing was the site of the Tiananmen Square protests, a pro-democracy movement that ended in a military crackdown.",
      "date": "1989"
    },
    {
      "headline": "2008 Summer Olympics",
      "text": "Beijing hosted the 2008 Summer Olympics, showcasing China's development and modernization.",
      "date": "2008"
    },
    {
      "headline": "2022 Winter Olympics",
      "text": "Beijing became the first city to host both the Summer and Winter Olympics, with the Winter Games held in 2022.",
      "date": "2022"
