{
  "timeline": [
    {
      "headline": "Beginning of the Hundred Years' War",
      "text": "The Hundred Years' War began in 1337 when King Edward III of England claimed the French throne, challenging King Philip VI of France.",
      "date": "1337"
    },
    {
      "headline": "Battle of Sluys",
      "text": "On June 24, 1340, the English fleet defeated the French at the Battle of Sluys, gaining control of the English Channel.",
      "date": "1340-06-24"
    },
    {
      "headline": "Battle of Crécy",
      "text": "The Battle of Crécy took place on August 26, 1346, where the English army, led by Edward III, won a decisive victory over the French.",
      "date": "1346-08-26"
    },
    {
      "headline": "Siege of Calais",
      "text": "The Siege of Calais ended on August 3, 1347, with the English capturing the city, which became a strategic English stronghold.",
      "date": "1347-08-03"
    },
    {
      "headline": "Black Death",
      "text": "The Black Death struck Europe in 1348, causing a temporary halt in the hostilities of the Hundred Years' War.",
      "date": "1348"
    },
    {
      "headline": "Treaty of Brétigny",
      "text": "Signed on May 8, 1360, the Treaty of Brétigny temporarily ended hostilities, with significant territorial concessions to England.",
      "date": "1360-05-08"
    },
    {
      "headline": "Renewal of War",
      "text": "Hostilities resumed in 1369 when Charles V of France declared war on England, seeking to reclaim lost territories.",
      "date": "1369"
    },
    {
      "headline": "Battle of Agincourt",
      "text": "On October 25, 1415, the English army, led by Henry V, achieved a major victory against the French at the Battle of Agincourt.",
      "date": "1415-10-25"
    },
    {
      "headline": "Treaty of Troyes",
      "text": "The Treaty of Troyes was signed on May 21, 1420, recognizing Henry V as heir to the French throne and regent of France.",
      "date": "1420-05-21"
    },
    {
      "headline": "Joan of Arc's Campaign",
      "text": "In 1429, Joan of Arc led French forces to lift the Siege of Orléans and achieved several victories, boosting French morale.",
      "date": "1429"
    },
    {
      "headline": "Coronation of Charles VII",
      "text": "Charles VII was crowned King of France on July 17, 1429, in Reims, largely due to Joan of Arc's efforts.",
      "date": "1429-07-17"
    },
    {
      "headline": "End of the Hundred Years' War",
      "text": "The Hundred Years' War effectively ended in 1453 with the French recapture of Bordeaux, leaving Calais as the only English possession in France.",
      "date": "1453"
    }
  ]
}

