    {
      "headline": "Caliphate of Ali ibn Abi Talib",
      "text": "Ali ibn Abi Talib became the fourth caliph in 656. His rule was marked by civil strife and conflict, known as the First Fitna, until his assassination in 661.",
      "date": "0656"
    },
    {
      "headline": "Umayyad Caliphate Established",
      "text": "The Umayyad Caliphate was established in 661 after the death of Ali, marking the beginning of a dynastic rule that lasted until 750.",
      "date": "0661"
    },
    {
      "headline": "Abbasid Caliphate Begins",
      "text": "The Abbasid Caliphate began in 750, overthrowing the Umayyad Caliphate and establishing a new era in Islamic governance.",
      "date": "0750"
