      "headline": "Death of Mu'awiya I",
      "text": "Mu'awiya I died in 680, leading to a succession conflict known as the Second Fitna.",
      "date": "0680"
    },
    {
      "headline": "Second Fitna",
      "text": "The Second Fitna was a period of civil war and unrest following the death of Mu'awiya I, lasting from 680 to 692.",
      "date": "0680-0692"
    },
    {
      "headline": "Reign of Marwan I",
      "text": "Marwan I became caliph in 684 during the Second Fitna, stabilizing the Umayyad rule and re-establishing control over the caliphate.",
      "date": "0684-0685"
    },
    {
      "headline": "Reign of Abd al-Malik",
      "text": "Abd al-Malik ruled from 685 to 705, known for administrative reforms and the construction of the Dome of the Rock in Jerusalem.",
      "date": "0685-0705"
    },
    {
      "headline": "Construction of the Dome of the Rock",
      "text": "The Dome of the Rock in Jerusalem was completed in 691 under the rule of Abd al-Malik.",
      "date": "0691"
    },
    {
      "headline": "Reign of Al-Walid I",
      "text": "Al-Walid I ruled from 705 to 715, overseeing the expansion of the caliphate into the Iberian Peninsula and Central Asia.",
      "date": "0705-0715"
    },
    {
      "headline": "Conquest of Hispania",
      "text": "The Umayyad forces began the conquest of the Iberian Peninsula in 711, marking the expansion of the caliphate into Europe.",
      "date": "0711"
    },
    {
      "headline": "Reign of Umar II",
      "text": "Umar II ruled from 717 to 720, known for his piety and attempts at reforming the administration and taxation systems.",
      "date": "0717-0720"
    },
    {
      "headline": "Reign of Hisham ibn Abd al-Malik",
      "text": "Hisham ibn Abd al-Malik ruled from 724 to 743, during which the caliphate reached its greatest territorial extent.",
      "date": "0724-0743"
    },
    {
      "headline": "Battle of Tours",
      "text": "In 732, the Umayyad forces were defeated by the Frankish leader Charles Martel at the Battle of Tours, halting further expansion into Europe.",
      "date": "0732"
    },
    {
      "headline": "Fall of the Umayyad Caliphate",
      "text": "The Umayyad Caliphate fell in 750 after the Abbasid Revolution, which led to the establishment of the Abbasid Caliphate.",
      "date": "0750"
    }
  ]
}

