{
  "timeline": [
    {
      "headline": "Founding of Rashtriya Swayamsevak Sangh",
      "text": "The Rashtriya Swayamsevak Sangh (RSS) was founded on September 27, 1925, by Keshav Baliram Hedgewar in Nagpur, Maharashtra, India. It was established as a volunteer organization to promote the idea of a united Hindu community.",
      "date": "1925-09-27"
    },
    {
      "headline": "First Sarsanghchalak",
      "text": "Keshav Baliram Hedgewar served as the first Sarsanghchalak (chief) of the RSS from its founding in 1925 until his death in 1940.",
      "date": "1925"
    },
    {
      "headline": "Death of Keshav Baliram Hedgewar",
      "text": "Keshav Baliram Hedgewar, the founder and first Sarsanghchalak of the RSS, passed away on June 21, 1940.",
      "date": "1940-06-21"
    },
    {
      "headline": "M. S. Golwalkar becomes Sarsanghchalak",
      "text": "Madhav Sadashiv Golwalkar, also known as Guruji, became the second Sarsanghchalak of the RSS in 1940, following the death of Keshav Baliram Hedgewar.",
      "date": "1940"
    },
    {
      "headline": "RSS Banned After Gandhi Assassination",
      "text": "The RSS was banned on February 4, 1948, following the assassination of Mahatma Gandhi by Nathuram Godse, who was a former member of the RSS. The ban was lifted in July 1949 after the organization agreed to adopt a constitution.",
      "date": "1948-02-04"
    },
    {
      "headline": "Lifting of the Ban on RSS",
      "text": "The ban on the RSS was lifted in July 1949 after the organization agreed to adopt a constitution and distance itself from political activities.",
      "date": "1949-07"
    },
    {
      "headline": "Vishva Hindu Parishad Founded",
      "text": "The Vishva Hindu Parishad (VHP), an affiliate of the RSS, was founded on August 29, 1964, to promote Hindu values and culture.",
      "date": "1964-08-29"
    },
    {
      "headline": "Bharatiya Janata Party Formation",
      "text": "The Bharatiya Janata Party (BJP), a political party with close ties to the RSS, was founded on April 6, 1980.",
      "date": "1980-04-06"
    },
    {
      "headline": "Mohan Bhagwat becomes Sarsanghchalak",
      "text": "Mohan Bhagwat became the Sarsanghchalak of the RSS in March 2009, succeeding K. S. Sudarshan.",
      "date": "2009-03"
    }
  ]
}

{
