    {
      "headline": "Founding of the Nation of Islam",
      "text": "The Nation of Islam was founded in July 1930 by Wallace Fard Muhammad in Detroit, Michigan. It was established as a religious organization with a focus on black nationalism and the African diaspora, particularly African Americans.",
      "date": "1930-07"
    },
    {
      "headline": "Disappearance of Wallace Fard Muhammad",
      "text": "Wallace Fard Muhammad, the founder of the Nation of Islam, mysteriously disappeared in 1934. His disappearance led to Elijah Muhammad taking over the leadership of the organization.",
      "date": "1934"
    },
    {
      "headline": "Elijah Muhammad's Leadership",
      "text": "After the disappearance of Wallace Fard Muhammad, Elijah Muhammad became the leader of the Nation of Islam in 1934. Under his leadership, the organization grew significantly and became more structured.",
      "date": "1934"
    },
    {
      "headline": "Malcolm X Joins the Nation of Islam",
      "text": "In 1952, Malcolm X joined the Nation of Islam while serving a prison sentence. He became one of the most prominent and influential leaders within the organization.",
      "date": "1952"
    },
    {
      "headline": "Malcolm X Leaves the Nation of Islam",
      "text": "In March 1964, Malcolm X left the Nation of Islam due to growing tensions with Elijah Muhammad and disagreements over the direction of the organization.",
      "date": "1964-03"
    },
    {
      "headline": "Death of Elijah Muhammad",
      "text": "Elijah Muhammad, the long-time leader of the Nation of Islam, passed away on February 25, 1975. His death marked a significant turning point for the organization.",
      "date": "1975-02-25"
    },
    {
      "headline": "Leadership of Wallace D. Muhammad",
      "text": "Following the death of Elijah Muhammad, his son Wallace D. Muhammad (later known as Warith Deen Mohammed) took over leadership of the Nation of Islam in 1975. He began to reform the organization, moving it towards mainstream Sunni Islam.",
      "date": "1975"
    },
    {
      "headline": "Louis Farrakhan Revives the Nation of Islam",
      "text": "In 1977, Louis Farrakhan broke away from Wallace D. Muhammad's reforms and re-established the Nation of Islam, maintaining the original teachings of Elijah Muhammad.",
      "date": "1977"
    },
    {
      "headline": "Million Man March",
      "text": "On October 16, 1995, the Nation of Islam organized the Million Man March in Washington, D.C., led by Louis Farrakhan. The event aimed to promote African American unity and family values.",
      "date": "1995-10-16"
    }
  ]
}

