      "headline": "Discovery of Neptune",
      "text": "Neptune was discovered on September 23, 1846, by astronomers Johann Galle and Heinrich d'Arrest, based on predictions by Urbain Le Verrier.",
      "date": "1846-09-23"
    },
    {
      "headline": "Naming of Neptune",
      "text": "Shortly after its discovery, the planet was named Neptune after the Roman god of the sea, reflecting its deep blue color.",
      "date": "1846"
    },
    {
      "headline": "First Observation of Neptune's Rings",
      "text": "The rings of Neptune were first observed in 1984, although their existence was confirmed by the Voyager 2 spacecraft in 1989.",
      "date": "1984"
    },
    {
      "headline": "Voyager 2 Flyby",
      "text": "NASA's Voyager 2 spacecraft made its closest approach to Neptune on August 25, 1989, providing the first detailed images and data about the planet and its moons.",
      "date": "1989-08-25"
    },
    {
      "headline": "Discovery of Neptune's Great Dark Spot",
      "text": "During the Voyager 2 flyby in 1989, a large storm system known as the Great Dark Spot was discovered in Neptune's atmosphere.",
      "date": "1989-08-25"
    },
    {
      "headline": "Neptune Completes First Orbit Since Discovery",
      "text": "In 2011, Neptune completed its first full orbit around the Sun since its discovery in 1846, taking approximately 164.8 years.",
      "date": "2011"
    }
  ]
}

