{
  "timeline": [
    {
      "headline": "Preclassic Period Begins",
      "text": "The Preclassic period of the Maya civilization begins around 2000 BCE, marking the start of agricultural communities and the development of early Maya culture.",
      "date": "-2000"
    },
    {
      "headline": "Rise of Nakbe",
      "text": "Around 750 BCE, the city of Nakbe in the Mirador Basin becomes one of the earliest major Maya cities, featuring monumental architecture.",
      "date": "-0750"
    },
    {
      "headline": "El Mirador Flourishes",
      "text": "By 300 BCE, El Mirador becomes a major city in the Maya lowlands, known for its massive pyramids and complex society.",
      "date": "-0300"
    },
    {
      "headline": "Classic Period Begins",
      "text": "The Classic period of the Maya civilization begins around 250 CE, characterized by the rise of city-states, monumental architecture, and the development of the Maya script.",
      "date": "0250"
    },
    {
      "headline": "Tikal's Ascendancy",
      "text": "In 378 CE, Tikal becomes a dominant power in the Maya region, expanding its influence over other city-states.",
      "date": "0378"
    },
    {
      "headline": "Calakmul-Tikal Rivalry",
      "text": "During the 6th century, the rivalry between the city-states of Calakmul and Tikal intensifies, leading to numerous conflicts and alliances.",
      "date": "0500"
    },
    {
      "headline": "Peak of Maya Civilization",
      "text": "The Maya civilization reaches its peak during the Late Classic period (600-900 CE), with advancements in art, architecture, and astronomy.",
      "date": "0600"
    },
    {
      "headline": "Collapse of Southern Lowlands",
      "text": "Around 900 CE, many major cities in the southern Maya lowlands are abandoned, marking the beginning of the Classic Maya collapse.",
      "date": "0900"
    },
    {
      "headline": "Postclassic Period Begins",
      "text": "The Postclassic period begins around 950 CE, with the rise of new centers such as Chichen Itza and Mayapan in the northern Yucatan Peninsula.",
      "date": "0950"
    },
    {
      "headline": "Spanish Conquest",
      "text": "The Spanish conquest of the Maya region begins in the early 16th century, leading to the eventual fall of the last independent Maya city, Nojpetén, in 1697.",
      "date": "1697"
    }
  ]
}

{
  "timeline": [
    {
      "headline": "Earliest Use of Cannabis",
      "text": "Cannabis has been used for thousands of years, with evidence of its use dating back to at least the 3rd millennium BCE in Central or South Asia.",
      "date": "-3000"
    },
    {
      "headline": "Cannabis in Ancient China",
      "text": "Cannabis was used in ancient China for its psychoactive properties and as a traditional medicine. The earliest recorded use of cannabis as a medicine was in 2737 BCE by Emperor Shen Nung.",
      "date": "-2737"
    },
    {
      "headline": "Cannabis in Ancient India",
      "text": "Cannabis was used in ancient India for religious and medicinal purposes. It is mentioned in the Atharva Veda, which dates back to around 1500 BCE.",
      "date": "-1500"
    },
    {
      "headline": "Cannabis in Ancient Greece",
      "text": "Cannabis was used in ancient Greece for its medicinal properties. The Greek historian Herodotus mentioned its use by the Scythians around 440 BCE.",
      "date": "-0440"
    },
    {
      "headline": "Cannabis in the Islamic Golden Age",
      "text": "During the Islamic Golden Age, cannabis was used for medicinal purposes and was documented by several scholars, including Avicenna in the 11th century.",
      "date": "1000"
    },
    {
      "headline": "Cannabis in the New World",
      "text": "Cannabis was introduced to the New World by the Spanish in 1545, and it was grown in Chile for its fiber.",
      "date": "1545"
    },
    {
      "headline": "Cannabis in Colonial America",
      "text": "Cannabis was grown in colonial America for its fiber, and it was a required crop in several colonies, including Virginia, starting in 1619.",
      "date": "1619"
    },
    {
      "headline": "Cannabis in the 19th Century",
      "text": "Cannabis was widely used in the 19th century as a medicinal product in the United States and Europe. It was included in the United States Pharmacopeia from 1850 until 1942.",
      "date": "1850"
    },
    {
      "headline": "The Marihuana Tax Act",
      "text": "The Marihuana Tax Act of 1937 effectively criminalized cannabis in the United States by imposing strict regulations and taxes on its sale and use.",
      "date": "1937"
    },
    {
      "headline": "Controlled Substances Act",
      "text": "In 1970, the Controlled Substances Act classified cannabis as a Schedule I drug, indicating it had a high potential for abuse and no accepted medical use.",
      "date": "1970"
    },
    {
      "headline": "Medical Cannabis Legalization",
      "text": "California became the first U.S. state to legalize medical cannabis with the passage of Proposition 215 in 1996.",
      "date": "1996"
    },
    {
      "headline": "Recreational Cannabis Legalization",
      "text": "In 2012, Colorado and Washington became the first U.S. states to legalize cannabis for recreational use.",
      "date": "2012"
    }
  ]
}

