{
  "timeline": [
    {
      "headline": "Establishment of Guantanamo Bay Detention Camp",
      "text": "In January 2002, the Guantanamo Bay detention camp was established by U.S. President George W. Bush to hold terrorism suspects and 'illegal enemy combatants' during the Global War on Terrorism following the attacks of September 11, 2001.",
      "date": "2002-01"
    },
    {
      "headline": "First Detainees Arrive",
      "text": "On January 11, 2002, the first detainees arrived at Guantanamo Bay detention camp. These detainees were primarily captured in Afghanistan during the U.S. invasion following the September 11 attacks.",
      "date": "2002-01-11"
    },
    {
      "headline": "Supreme Court Ruling on Detainee Rights",
      "text": "On June 28, 2004, the U.S. Supreme Court ruled in Rasul v. Bush that Guantanamo detainees had the right to challenge their detention in U.S. courts.",
      "date": "2004-06-28"
    },
    {
      "headline": "Detainee Treatment Act",
      "text": "In December 2005, the Detainee Treatment Act was passed by the U.S. Congress, which aimed to prohibit inhumane treatment of detainees and restrict detainees' access to U.S. courts.",
      "date": "2005-12"
    },
    {
      "headline": "Military Commissions Act",
      "text": "On October 17, 2006, President George W. Bush signed the Military Commissions Act, which established military commissions to try detainees for war crimes and limited detainees' rights to challenge their detention.",
      "date": "2006-10-17"
    },
    {
      "headline": "Executive Order to Close Guantanamo",
      "text": "On January 22, 2009, President Barack Obama signed an executive order to close the Guantanamo Bay detention camp within a year. However, the camp remained open due to political and legal challenges.",
      "date": "2009-01-22"
    },
    {
      "headline": "First Detainee Transferred to U.S. for Trial",
      "text": "In June 2009, Ahmed Ghailani became the first Guantanamo detainee to be transferred to the United States for trial in a civilian court.",
      "date": "2009-06"
    },
    {
      "headline": "Habeas Corpus Rights Restored",
      "text": "On June 12, 2008, the U.S. Supreme Court ruled in Boumediene v. Bush that Guantanamo detainees had the right to file habeas corpus petitions in U.S. federal courts.",
      "date": "2008-06-12"
    },
    {
      "headline": "Transfer of Detainees to Other Countries",
      "text": "By December 2024, at least 743 detainees had been transferred from Guantanamo Bay to other countries.",
      "date": "2024-12"
    },
    {
      "headline": "Current Status of Detainees",
      "text": "As of December 2024, 27 detainees remain at Guantanamo Bay, with only 16 having ever been charged with criminal offenses.",
      "date": "2024-12"
    }
  ]
}

