{
  "timeline": [
    {
      "headline": "Birth of Richard Feynman",
      "text": "Richard Phillips Feynman was born on May 11, 1918, in Queens, New York City, USA.",
      "date": "1918-05-11"
    },
    {
      "headline": "Bachelor's Degree from MIT",
      "text": "In 1939, Feynman graduated with a Bachelor of Science degree in physics from the Massachusetts Institute of Technology.",
      "date": "1939"
    },
    {
      "headline": "Ph.D. from Princeton University",
      "text": "Feynman received his Ph.D. in physics from Princeton University in 1942. His thesis was supervised by John Archibald Wheeler.",
      "date": "1942"
    },
    {
      "headline": "Manhattan Project",
      "text": "During World War II, Feynman worked on the Manhattan Project at Los Alamos, contributing to the development of the atomic bomb.",
      "date": "1943"
    },
    {
      "headline": "Path Integral Formulation",
      "text": "In 1948, Feynman introduced the path integral formulation of quantum mechanics, which became a fundamental tool in theoretical physics.",
      "date": "1948"
    },
    {
      "headline": "Nobel Prize in Physics",
      "text": "In 1965, Richard Feynman was awarded the Nobel Prize in Physics jointly with Julian Schwinger and Shin'ichirō Tomonaga for their fundamental work in quantum electrodynamics.",
      "date": "1965"
    },
    {
      "headline": "Challenger Disaster Investigation",
      "text": "In 1986, Feynman served on the Rogers Commission, which investigated the Space Shuttle Challenger disaster. He famously demonstrated the effect of cold on the shuttle's O-rings.",
      "date": "1986"
    },
    {
      "headline": "Death of Richard Feynman",
      "text": "Richard Feynman passed away on February 15, 1988, in Los Angeles, California, USA, due to complications from cancer.",
      "date": "1988-02-15"
    }
  ]
}

{
  "timeline": [
    {
      "headline": "Birth of Ashoka",
      "text": "Ashoka was born in 304 BCE to Emperor Bindusara and Queen Subhadrangi.",
      "date": "-0304"
    },
    {
      "headline": "Ascension to the Throne",
      "text": "Ashoka became the Emperor of the Mauryan Empire in 268 BCE after a succession struggle following the death of his father, Bindusara.",
      "date": "-0268"
    },
    {
      "headline": "Conquest of Kalinga",
      "text": "In 261 BCE, Ashoka waged a brutal war against the state of Kalinga, resulting in massive loss of life and suffering, which deeply affected him.",
      "date": "-0261"
    },
    {
      "headline": "Conversion to Buddhism",
      "text": "Following the Kalinga War, Ashoka embraced Buddhism and began to promote it throughout his empire, marking a significant shift in his policies and personal beliefs.",
      "date": "-0260"
    },
    {
      "headline": "Edicts of Ashoka",
      "text": "Between 260 BCE and 232 BCE, Ashoka issued a series of edicts inscribed on pillars and rocks across his empire, promoting Buddhist moral teachings and ethical governance.",
      "date": "-0260"
    },
    {
      "headline": "Third Buddhist Council",
      "text": "Ashoka is believed to have convened the Third Buddhist Council around 250 BCE in Pataliputra to purify the Buddhist movement of its various corruptions and to spread Buddhism further.",
      "date": "-0250"
    },
    {
      "headline": "Death of Ashoka",
      "text": "Ashoka died in 232 BCE, marking the end of his reign and leaving a legacy as a ruler who significantly contributed to the spread of Buddhism.",
      "date": "-0232"
    }
  ]
}

{
  "timeline": [
    {
      "headline": "Development of the German Shepherd Breed",
      "text": "The German Shepherd breed was developed by Max von Stephanitz using various traditional German herding dogs. This development began in 1899.",
      "date": "1899"
    },
    {
      "headline": "First German Shepherd Registered",
      "text": "The first German Shepherd was registered in 1899. The dog's name was Horand von Grafrath, and he became the first registered German Shepherd Dog.",
      "date": "1899"
    },
    {
      "headline": "Foundation of the Society for the German Shepherd Dog",
      "text": "In 1899, Max von Stephanitz founded the Society for the German Shepherd Dog (Verein für Deutsche Schäferhunde, or SV), which became the breed's official governing body.",
      "date": "1899"
    },
    {
      "headline": "Introduction to Britain",
      "text": "The German Shepherd was introduced to Britain and became known as the Alsatian during World War I due to anti-German sentiment.",
      "date": "1914"
    },
    {
      "headline": "Name Change to Alsatian Wolf Dog",
      "text": "In 1919, the breed was officially renamed the Alsatian Wolf Dog in Britain to distance it from its German origins.",
      "date": "1919"
    },
    {
      "headline": "Return to Original Name",
      "text": "In 1977, the breed's name was changed back to German Shepherd in Britain, although 'Alsatian' is still commonly used.",
      "date": "1977"
    }
  ]
}

