  "timeline": [
    {
      "headline": "Birth of Toyotomi Hideyoshi",
      "text": "Toyotomi Hideyoshi was born in 1537 in Nakamura, Owari Province, Japan.",
      "date": "1537"
    },
    {
      "headline": "Service under Oda Nobunaga",
      "text": "In 1558, Hideyoshi joined the service of Oda Nobunaga, a powerful daimyō, marking the beginning of his rise in the samurai ranks.",
