      "date": "1567"
    },
    {
      "headline": "Battle of Anegawa",
      "text": "In 1570, Hideyoshi fought in the Battle of Anegawa, where Nobunaga's forces defeated the Azai and Asakura clans.",
      "date": "1570"
    },
    {
      "headline": "Battle of Nagashino",
      "text": "In 1575, Hideyoshi participated in the Battle of Nagashino, where Oda Nobunaga's forces defeated the Takeda clan.",
      "date": "1575"
    },
    {
      "headline": "Death of Oda Nobunaga",
      "text": "In 1582, Oda Nobunaga was betrayed and killed by Akechi Mitsuhide. Hideyoshi quickly avenged Nobunaga's death by defeating Mitsuhide at the Battle of Yamazaki.",
      "date": "1582"
    },
    {
      "headline": "Battle of Shizugatake",
      "text": "In 1583, Hideyoshi defeated Shibata Katsuie at the Battle of Shizugatake, solidifying his power and influence.",
      "date": "1583"
    },
    {
      "headline": "Battle of Komaki and Nagakute",
      "text": "In 1584, Hideyoshi fought against Tokugawa Ieyasu in the Battle of Komaki and Nagakute, which ended in a stalemate.",
      "date": "1584"
    },
    {
      "headline": "Appointment as Kampaku",
      "text": "In 1585, Hideyoshi was appointed as Kampaku, becoming the first person of non-noble birth to hold this high-ranking position.",
      "date": "1585"
    },
    {
      "headline": "Unification of Japan",
      "text": "By 1590, Hideyoshi completed the unification of Japan after the Siege of Odawara, bringing the Hōjō clan under his control.",
      "date": "1590"
    },
    {
      "headline": "Invasion of Korea",
      "text": "In 1592, Hideyoshi launched the first of two invasions of Korea, aiming to conquer the Korean Peninsula and eventually China.",
      "date": "1592"
    },
    {
      "headline": "Retirement as Kampaku",
      "text": "In 1591, Hideyoshi retired as Kampaku and assumed the title of Taikō, passing the position to his nephew Toyotomi Hidetsugu.",
      "date": "1591"
    },
    {
      "headline": "Second Invasion of Korea",
      "text": "In 1597, Hideyoshi ordered a second invasion of Korea, which ultimately ended in failure.",
      "date": "1597"
    },
    {
      "headline": "Death of Toyotomi Hideyoshi",
      "text": "Toyotomi Hideyoshi died on September 18, 1598, at Fushimi Castle in Kyoto, Japan.",
