    {
      "headline": "Formation of the Whig Party",
      "text": "The Whig Party was formed in 1833 in opposition to the policies of President Andrew Jackson and the Democratic Party. It was a coalition of National Republicans, Anti-Masons, and disaffected Democrats.",
      "date": "1833"
    },
    {
      "headline": "First Whig Presidential Candidate",
      "text": "In 1836, the Whig Party ran its first presidential candidate, William Henry Harrison, who was one of several Whig candidates in that election.",
      "date": "1836"
    },
    {
      "headline": "William Henry Harrison Elected President",
      "text": "William Henry Harrison, a Whig, was elected as the 9th President of the United States in 1840. His presidency was short-lived as he died just a month after taking office.",
      "date": "1840"
    },
    {
      "headline": "John Tyler's Presidency",
      "text": "John Tyler, Harrison's Vice President, assumed the presidency after Harrison's death in 1841. Although he was elected as a Whig, Tyler's policies were more aligned with the Democrats, leading to tensions with the Whig Party.",
      "date": "1841"
    },
    {
      "headline": "Henry Clay's Influence",
      "text": "Henry Clay, a leading figure in the Whig Party, played a significant role in shaping the party's platform and policies throughout the 1840s.",
      "date": "1840s"
    },
    {
      "headline": "Zachary Taylor Elected President",
      "text": "Zachary Taylor, a Whig, was elected as the 12th President of the United States in 1848. His presidency was marked by debates over the expansion of slavery into new territories.",
      "date": "1848"
    },
    {
      "headline": "Millard Fillmore's Presidency",
      "text": "Millard Fillmore became the 13th President of the United States in 1850 after the death of Zachary Taylor. Fillmore was the last Whig president.",
      "date": "1850"
    },
    {
      "headline": "Decline of the Whig Party",
      "text": "The Whig Party began to decline in the early 1850s due to internal divisions over the issue of slavery and the rise of the Republican Party.",
      "date": "1850s"
    },
    {
      "headline": "End of the Whig Party",
      "text": "The Whig Party effectively dissolved after the 1856 presidential election, with many of its members joining the newly formed Republican Party.",
      "date": "1856"
    }
  ]
}

