      "headline": "Early Inhabitants",
      "text": "The Sao civilization around Lake Chad and the Baka hunter-gatherers in the southeastern rainforest were among the early inhabitants of the territory that is now Cameroon.",
      "date": "-1000"
    },
    {
      "headline": "Portuguese Exploration",
      "text": "Portuguese explorers reached the coast of present-day Cameroon in the 15th century and named the area Rio dos Camarões, which means 'River of Prawns', eventually becoming Cameroon in English.",
      "date": "1472"
    },
    {
      "headline": "Adamawa Emirate Founded",
      "text": "In the 19th century, Fulani soldiers founded the Adamawa Emirate in the northern region of present-day Cameroon.",
      "date": "1809"
    },
    {
      "headline": "German Protectorate",
      "text": "Cameroon became a German protectorate known as Kamerun in 1884 following agreements with local chiefs.",
      "date": "1884"
    },
    {
      "headline": "World War I and Allied Occupation",
      "text": "During World War I, British and French troops occupied Cameroon, leading to the eventual division of the territory between the two colonial powers.",
      "date": "1916"
    },
    {
      "headline": "League of Nations Mandate",
      "text": "In 1922, the League of Nations formalized the division of Cameroon into British and French mandates.",
      "date": "1922"
    },
    {
      "headline": "United Nations Trusteeship",
      "text": "After World War II, the League of Nations mandates were converted into United Nations Trust Territories, with British and French Cameroon continuing under their respective administrations.",
      "date": "1946"
    },
    {
      "headline": "French Cameroon Independence",
      "text": "French Cameroon gained independence on January 1, 1960, and became the Republic of Cameroon.",
      "date": "1960-01-01"
    },
    {
      "headline": "Reunification of Cameroon",
      "text": "On October 1, 1961, the British Southern Cameroons joined the Republic of Cameroon to form the Federal Republic of Cameroon.",
      "date": "1961-10-01"
    },
    {
      "headline": "Unitary State Established",
      "text": "In 1972, a national referendum led to the abolition of the federal system and the establishment of a unitary state, the United Republic of Cameroon.",
      "date": "1972"
    },
    {
      "headline": "Renaming to Republic of Cameroon",
      "text": "In 1984, the country was renamed the Republic of Cameroon.",
      "date": "1984"
    }
  ]
}

