{
  "timeline": [
    {
      "headline": "First European Settlement",
      "text": "In 1666, the first European settlement in Vermont was established by the French at Fort Sainte Anne on Isle La Motte, located in Lake Champlain.",
      "date": "1666"
    },
    {
      "headline": "New Hampshire Grants",
      "text": "In 1749, Benning Wentworth, the governor of the Province of New Hampshire, began issuing land grants for the area that is now Vermont, known as the New Hampshire Grants.",
      "date": "1749"
    },
    {
      "headline": "Battle of Bennington",
      "text": "On August 16, 1777, the Battle of Bennington was fought, which was a significant victory for the American forces during the Revolutionary War.",
      "date": "1777-08-16"
    },
    {
      "headline": "Vermont Republic Established",
      "text": "On January 15, 1777, Vermont declared its independence from the jurisdictions and land claims of the British colonies of Quebec, New Hampshire, and New York, becoming the Vermont Republic.",
      "date": "1777-01-15"
    },
    {
      "headline": "Vermont Abolishes Slavery",
      "text": "In 1777, Vermont became the first colony to abolish slavery outright.",
      "date": "1777"
    },
    {
      "headline": "Admission to the Union",
      "text": "On March 4, 1791, Vermont was admitted to the United States as the 14th state.",
      "date": "1791-03-04"
    },
    {
      "headline": "Vermont State Constitution Adopted",
      "text": "In 1793, Vermont adopted its state constitution, which was based on the 1777 constitution of the Vermont Republic.",
      "date": "1793"
    },
    {
      "headline": "Completion of the Champlain Canal",
      "text": "In 1823, the Champlain Canal was completed, connecting Lake Champlain to the Hudson River and facilitating trade and transportation.",
      "date": "1823"
    },
    {
      "headline": "Establishment of the University of Vermont",
      "text": "In 1791, the University of Vermont was chartered, and it opened in 1800.",
      "date": "1800"
    },
    {
      "headline": "Vermont's First Railroads",
      "text": "In 1848, Vermont's first railroads began operation, significantly enhancing transportation and economic development in the state.",
      "date": "1848"
    },
    {
      "headline": "Flood of 1927",
      "text": "In November 1927, Vermont experienced one of its most devastating floods, causing widespread destruction and loss of life.",
      "date": "1927-11"
    },
    {
      "headline": "Vermont's First Female Governor",
      "text": "In 1985, Madeleine Kunin became the first female governor of Vermont.",
      "date": "1985"
    },
    {
      "headline": "Civil Unions Legalized",
      "text": "In 2000, Vermont became the first state to legalize civil unions for same-sex couples.",
      "date": "2000"
    },
    {
      "headline": "Same-Sex Marriage Legalized",
      "text": "On September 1, 2009, Vermont became the first state to legalize same-sex marriage through legislative action without a court order.",
      "date": "2009-09-01"
    }
  ]
}

