    {
      "headline": "Agreement Between NHA and PCHA",
      "text": "In 1915, the National Hockey Association (NHA) and the Pacific Coast Hockey Association (PCHA) reached an agreement that their respective champions would face each other annually for the Stanley Cup.",
      "date": "1915"
    },
