    },
    {
      "headline": "Legal Issues with Dracula",
      "text": "Nosferatu was an unauthorized adaptation of Bram Stoker's Dracula. Stoker's widow, Florence Stoker, sued the filmmakers, resulting in a court ruling that ordered all copies of the film to be destroyed.",
      "date": "1923"
    },
    {
      "headline": "Survival of the Film",
      "text": "Despite the court ruling, several copies of Nosferatu survived and the film became a classic of the horror genre.",
      "date": "1920s"
    },
    {
      "headline": "Rediscovery and Restoration",
      "text": "Nosferatu was rediscovered and restored in the late 20th century, leading to renewed interest and appreciation for the film.",
      "date": "1970s-1980s"
    },
    {
      "headline": "Cultural Impact",
      "text": "Nosferatu is now considered one of the most influential horror films of all time, noted for its innovative use of shadow and light, and its eerie portrayal of the vampire Count Orlok.",
      "date": "Present"
    }
  ]
}

