    {
      "headline": "Arrival in New Zealand",
      "text": "Māori settlers from East Polynesia arrived in New Zealand in several waves of canoe voyages between roughly 1320 and 1350. These settlers developed a distinct culture over several centuries in isolation.",
      "date": "1350"
    },
    {
      "headline": "Development of Māori Culture",
      "text": "Over centuries, the Māori developed a unique culture, with its own language, mythology, crafts, and performing arts, distinct from other eastern Polynesian cultures.",
      "date": "1400"
    },
    {
      "headline": "Settlement of Chatham Islands",
      "text": "Some early Māori moved to the Chatham Islands, where their descendants became known as the Moriori, New Zealand's other indigenous Polynesian ethnic group.",
      "date": "1500"
    },
    {
      "headline": "First European Contact",
      "text": "The first known European contact with the Māori was by Dutch explorer Abel Tasman in 1642.",
      "date": "1642"
