      "headline": "Captain James Cook's Arrival",
      "text": "British explorer Captain James Cook arrived in New Zealand in 1769, marking the beginning of significant European contact.",
      "date": "1769"
    },
    {
      "headline": "Treaty of Waitangi",
      "text": "On February 6, 1840, the Treaty of Waitangi was signed between the British Crown and various Māori chiefs, establishing British law in New Zealand while ostensibly guaranteeing Māori land rights.",
      "date": "1840-02-06"
    },
    {
      "headline": "New Zealand Wars",
      "text": "A series of conflicts known as the New Zealand Wars occurred between 1845 and 1872, primarily over land disputes between Māori and European settlers.",
      "date": "1845"
    },
    {
      "headline": "Māori Renaissance",
      "text": "Beginning in the late 20th century, there was a revival of Māori culture and language, known as the Māori Renaissance, which continues into the present day.",
      "date": "1970"
    }
  ]
