    {
      "headline": "Merger with International Pictures",
      "text": "In 1946, Universal Pictures merged with International Pictures to form Universal-International.",
      "date": "1946"
    },
    {
      "headline": "Acquisition by MCA",
      "text": "In 1962, MCA Inc. acquired Universal Pictures, marking a new era for the studio.",
      "date": "1962"
