    },
    {
      "headline": "Brown v. Board of Education",
      "text": "In 1954, the Supreme Court decision in Brown v. Board of Education used the Fourteenth Amendment as a basis to rule that racial segregation in public schools was unconstitutional.",
      "date": "1954"
    },
    {
      "headline": "Loving v. Virginia",
      "text": "In 1967, the Supreme Court case Loving v. Virginia struck down laws banning interracial marriage, citing the Fourteenth Amendment.",
      "date": "1967"
    },
    {
      "headline": "Roe v. Wade",
      "text": "The 1973 Supreme Court decision in Roe v. Wade used the Fourteenth Amendment to establish a woman's legal right to an abortion.",
      "date": "1973"
    },
    {
      "headline": "Bush v. Gore",
      "text": "In 2000, the Supreme Court case Bush v. Gore, which resolved the 2000 presidential election, involved the Fourteenth Amendment.",
      "date": "2000"
    },
    {
      "headline": "Obergefell v. Hodges",
      "text": "In 2015, the Supreme Court decision in Obergefell v. Hodges used the Fourteenth Amendment to legalize same-sex marriage nationwide.",
      "date": "2015"
    },
    {
      "headline": "Students for Fair Admissions v. Harvard",
      "text": "In 2023, the Supreme Court case Students for Fair Admissions v. Harvard addressed race-based college admissions, involving the Fourteenth Amendment.",
      "date": "2023"
    }
  ]
}

