{
  "timeline": [
    {
      "headline": "Formation of the Ghana Empire",
      "text": "The Ghana Empire, which included parts of present-day Mali, was established around the 6th century. It was a powerful trading empire known for its wealth and trade in gold.",
      "date": "-0500"
    },
    {
      "headline": "Rise of the Mali Empire",
      "text": "The Mali Empire was founded by Sundiata Keita in 1235. It became one of the largest and wealthiest empires in West Africa, known for its trade in gold and salt.",
      "date": "1235"
    },
    {
      "headline": "Reign of Mansa Musa",
      "text": "Mansa Musa, one of the most famous rulers of the Mali Empire, reigned from 1312 to 1337. He is known for his pilgrimage to Mecca in 1324, which showcased the empire's wealth.",
      "date": "1312"
    },
    {
      "headline": "Mansa Musa's Pilgrimage",
      "text": "In 1324, Mansa Musa embarked on a pilgrimage to Mecca, distributing gold along the way and establishing diplomatic ties with other Muslim states.",
      "date": "1324"
    },
    {
      "headline": "Decline of the Mali Empire",
      "text": "The Mali Empire began to decline in the late 14th century due to internal strife and external pressures from neighboring states.",
      "date": "1400"
    },
    {
      "headline": "Rise of the Songhai Empire",
      "text": "The Songhai Empire rose to prominence in the 15th century, eventually eclipsing the Mali Empire. It controlled much of the territory that is now Mali.",
      "date": "1464"
    },
    {
      "headline": "French Colonization",
      "text": "In the late 19th century, France began colonizing the region, and by 1892, Mali became part of French Sudan.",
      "date": "1892"
    },
    {
      "headline": "Independence from France",
      "text": "Mali gained independence from France on September 22, 1960, becoming the Republic of Mali.",
      "date": "1960-09-22"
    },
    {
      "headline": "First President of Mali",
      "text": "Modibo Keïta became the first President of Mali after its independence in 1960.",
      "date": "1960"
    },
    {
      "headline": "Military Coup",
      "text": "In 1968, a military coup led by Lieutenant Moussa Traoré overthrew President Modibo Keïta.",
      "date": "1968"
    },
    {
      "headline": "Democratic Transition",
      "text": "In 1991, a coup led to a transition to democracy, and Alpha Oumar Konaré was elected as president in 1992.",
      "date": "1992"
    },
    {
      "headline": "Tuareg Rebellion",
      "text": "In 2012, a Tuareg rebellion in northern Mali led to a coup and the temporary division of the country.",
      "date": "2012"
    },
    {
      "headline": "French Military Intervention",
      "text": "In January 2013, France launched a military intervention to help Mali regain control of its northern territories from Islamist militants.",
      "date": "2013-01"
    }
  ]
}

