{
  "timeline": [
    {
      "headline": "Origin of Hindi",
      "text": "Hindi originated from the Khariboli dialect of the Delhi region, which itself is a part of the Western Hindi languages. The development of Hindi as a distinct language began around the 7th century CE.",
      "date": "0700"
    },
    {
      "headline": "Development of Hindustani",
      "text": "By the 13th century, the Khariboli dialect evolved into Hindustani, which became the lingua franca of northern India. It was influenced by Persian, Arabic, and Turkic languages due to the Delhi Sultanate and Mughal Empire.",
      "date": "1300"
    },
    {
      "headline": "Emergence of Modern Hindi",
      "text": "Modern Standard Hindi began to take shape in the 19th century as a standardized form of Hindustani, with a greater emphasis on Sanskrit vocabulary.",
      "date": "1800"
    },
    {
      "headline": "Hindi as an Official Language",
      "text": "In 1949, Hindi was adopted as one of the official languages of India, alongside English, as per the Indian Constitution.",
      "date": "1949"
    },
    {
      "headline": "Hindi in the Eighth Schedule",
      "text": "Hindi was included in the Eighth Schedule of the Indian Constitution, recognizing it as one of the 22 scheduled languages of India.",
      "date": "1950"
    },
    {
      "headline": "Hindi Day Established",
      "text": "Hindi Day is celebrated annually on September 14th, marking the adoption of Hindi as one of the official languages of India in 1949.",
      "date": "1953-09-14"
    }
  ]
}

