{
  "timeline": [
    {
      "headline": "UN Partition Plan",
      "text": "On November 29, 1947, the United Nations General Assembly adopted Resolution 181, recommending the partition of Mandatory Palestine into independent Arab and Jewish states, with Jerusalem under international administration.",
      "date": "1947-11-29"
    },
    {
      "headline": "Civil War in Mandatory Palestine",
      "text": "Following the UN Partition Plan, violence erupted between Jewish and Arab communities in Palestine, marking the beginning of the civil war phase of the 1948 Palestine war.",
      "date": "1947-12"
    },
    {
      "headline": "Deir Yassin Massacre",
      "text": "On April 9, 1948, Zionist paramilitary groups attacked the Palestinian Arab village of Deir Yassin, resulting in the massacre of over 100 villagers, which contributed to the flight of Palestinian Arabs from their homes.",
      "date": "1948-04-09"
    },
    {
      "headline": "Declaration of the State of Israel",
      "text": "On May 14, 1948, David Ben-Gurion declared the establishment of the State of Israel, leading to the withdrawal of British forces and the end of the British Mandate for Palestine.",
      "date": "1948-05-14"
    },
    {
      "headline": "Arab-Israeli War",
      "text": "Following the declaration of the State of Israel, neighboring Arab states invaded, marking the beginning of the Arab-Israeli War. This conflict resulted in significant territorial changes and the displacement of hundreds of thousands of Palestinians.",
      "date": "1948-05-15"
    },
    {
      "headline": "Fall of Lydda and Ramle",
      "text": "In July 1948, Israeli forces captured the towns of Lydda and Ramle, leading to the expulsion of approximately 50,000 Palestinian Arabs from these areas.",
      "date": "1948-07"
    },
    {
      "headline": "UN Mediator Count Folke Bernadotte Assassinated",
      "text": "On September 17, 1948, UN mediator Count Folke Bernadotte was assassinated in Jerusalem by members of the Zionist group Lehi, impacting international mediation efforts.",
      "date": "1948-09-17"
    },
    {
      "headline": "1949 Armistice Agreements",
      "text": "In 1949, Israel signed armistice agreements with Egypt, Lebanon, Jordan, and Syria, establishing the armistice lines that became the de facto borders of Israel until 1967.",
      "date": "1949"
    },
    {
      "headline": "Palestinian Refugee Crisis",
      "text": "By the end of the 1948 Arab-Israeli War, approximately 700,000 Palestinian Arabs had become refugees, unable to return to their homes, marking the beginning of the ongoing Palestinian refugee crisis.",
      "date": "1949"
    }
  ]
}

{
  "timeline": [
    {
      "headline": "Mexican Troops Arrive at San Antonio de Béxar",
      "text": "On February 23, 1836, approximately 1,500 Mexican troops under President General Antonio López de Santa Anna marched into San Antonio de Béxar as the first step in a campaign to retake Texas.",
      "date": "1836-02-23"
    },
    {
      "headline": "Siege of the Alamo Begins",
      "text": "The siege of the Alamo began on February 23, 1836, when Mexican troops surrounded the Alamo Mission, where about one hundred Texians were garrisoned.",
      "date": "1836-02-23"
    },
    {
      "headline": "Reinforcements Arrive at the Alamo",
      "text": "Subsequent reinforcements, led by eventual Alamo co-commanders James Bowie and William B. Travis, arrived at the Alamo during the siege.",
      "date": "1836-02"
    },
    {
      "headline": "Final Assault on the Alamo",
      "text": "In the early morning hours of March 6, 1836, the Mexican Army advanced on the Alamo. After repelling two attacks, the Texians were unable to fend off a third attack.",
      "date": "1836-03-06"
    },
    {
      "headline": "Mexican Troops Breach the Alamo",
      "text": "As Mexican soldiers scaled the walls on March 6, 1836, most of the Texian fighters withdrew into interior buildings. Those unable to reach these points were slain by the Mexican cavalry as they attempted to escape.",
      "date": "1836-03-06"
    },
    {
      "headline": "End of the Battle of the Alamo",
      "text": "The Battle of the Alamo ended on March 6, 1836, with the Mexican troops reclaiming the Alamo Mission. Almost all of the Texian inhabitants were killed, and between five and seven Texians may have surrendered but were quickly executed.",
      "date": "1836-03-06"
    }
  ]
}

