    {
      "headline": "Birth of Harland Sanders",
      "text": "Harland David Sanders was born on September 9, 1890, in Henryville, Indiana, USA.",
      "date": "1890-09-09"
    },
    {
      "headline": "Sanders' Father Passes Away",
      "text": "In 1895, when Sanders was just five years old, his father passed away, leaving his mother to care for the family.",
      "date": "1895"
    },
    {
      "headline": "Sanders Leaves School",
      "text": "At the age of 13, in 1903, Sanders dropped out of school and began working various jobs to support his family.",
      "date": "1903"
    },
    {
      "headline": "Sanders Joins the Army",
      "text": "In 1906, Sanders falsified his date of birth and enlisted in the United States Army, serving in Cuba for several months.",
      "date": "1906"
    },
    {
      "headline": "Sanders Starts a Ferry Boat Company",
      "text": "In 1920, Sanders started a ferry boat company on the Ohio River, which was his first successful business venture.",
      "date": "1920"
    },
    {
      "headline": "Sanders Opens a Service Station",
      "text": "In 1930, Sanders opened a service station in Corbin, Kentucky, where he began serving meals to travelers.",
      "date": "1930"
    },
    {
      "headline": "Sanders Receives Honorary Title of 'Colonel'",
      "text": "In 1935, Kentucky Governor Ruby Laffoon awarded Sanders the honorary title of 'Kentucky Colonel' in recognition of his contributions to the state's cuisine.",
      "date": "1935"
    },
    {
      "headline": "Sanders Develops Original Recipe",
      "text": "In 1940, Sanders finalized his 'Original Recipe' of 11 herbs and spices, which became the foundation of Kentucky Fried Chicken.",
      "date": "1940"
    },
    {
      "headline": "Sanders Sells KFC Franchise",
      "text": "In 1952, Sanders franchised his chicken recipe for the first time to Pete Harman of South Salt Lake, Utah, marking the beginning of the KFC franchise.",
      "date": "1952"
    },
    {
      "headline": "Sanders Sells KFC Corporation",
      "text": "In 1964, Sanders sold the Kentucky Fried Chicken corporation for $2 million to a group of investors led by John Y. Brown Jr. and Jack C. Massey.",
      "date": "1964"
    },
    {
      "headline": "Sanders Becomes KFC Brand Ambassador",
      "text": "After selling the company, Sanders remained active as a brand ambassador and symbol for KFC, traveling over 200,000 miles a year to promote the brand.",
      "date": "1964"
    },
    {
      "headline": "Death of Harland Sanders",
      "text": "Harland Sanders passed away on December 16, 1980, at the age of 90, in Louisville, Kentucky, USA.",
      "date": "1980-12-16"
    }
  ]
}

