{
  "timeline": [
    {
      "headline": "Birth of Sai Baba of Shirdi",
      "text": "Sai Baba of Shirdi was born around the year 1838. The exact date and place of his birth are unknown, and there are various theories regarding his origins.",
      "date": "1838"
    },
    {
      "headline": "Arrival in Shirdi",
      "text": "Sai Baba arrived in the village of Shirdi, Maharashtra, India, around the year 1858. He initially lived under a neem tree and later took residence in a mosque, which he named Dwarkamai.",
      "date": "1858"
    },
    {
      "headline": "Establishment of Dwarkamai",
      "text": "Sai Baba established Dwarkamai, a mosque in Shirdi, as a place of worship and spiritual teaching. It became a central place for his followers to gather and receive his teachings.",
      "date": "1858"
    },
    {
      "headline": "Performing Miracles and Gaining Followers",
      "text": "Throughout his life in Shirdi, Sai Baba performed numerous miracles, which included healing the sick, providing food, and helping people in distress. These acts attracted a large number of followers from various religious backgrounds.",
      "date": "1858-1918"
    },
    {
      "headline": "Construction of the Samadhi Mandir",
      "text": "In the later years of his life, a devotee named Shreemant Gopalrao, also known as Buti, began the construction of a temple in Shirdi, which was intended to house a statue of Muralidhar (a form of Krishna). However, Sai Baba expressed his wish to be interred there after his death.",
      "date": "1917"
    },
    {
      "headline": "Death of Sai Baba of Shirdi",
      "text": "Sai Baba of Shirdi passed away on October 15, 1918. His body was interred in the Samadhi Mandir, which became a major pilgrimage site for his devotees.",
      "date": "1918-10-15"
    }
  ]
}

{
  "timeline": [
    {
      "headline": "Development of the Patriot System",
      "text": "The development of the MIM-104 Patriot system began in the late 1960s as a replacement for the Nike Hercules and Hawk systems.",
      "date": "1960"
    },
    {
      "headline": "First Successful Test",
      "text": "The first successful test of the Patriot missile system occurred in 1976.",
      "date": "1976"
    },
    {
      "headline": "Introduction into Service",
      "text": "In 1984, the Patriot system began to replace the Nike Hercules system as the U.S. Army's primary high to medium air defense (HIMAD) system and the MIM-23 Hawk system as the U.S. Army's medium tactical air defense system.",
      "date": "1984"
    },
    {
      "headline": "Gulf War Deployment",
      "text": "The Patriot missile system gained fame during the Gulf War in 1991 when it was used to intercept Iraqi Scud missiles.",
      "date": "1991"
    },
    {
      "headline": "Upgrade to PAC-3",
      "text": "The Patriot system was upgraded to the PAC-3 configuration, which included improvements for missile defense capabilities, in the late 1990s.",
      "date": "1990"
    },
    {
      "headline": "Continued Use and Upgrades",
      "text": "As of 2016, the Patriot system is expected to stay fielded until at least 2040, with ongoing upgrades and improvements.",
      "date": "2016"
    }
  ]
}

{
  "timeline": [
    {
      "headline": "Establishment of the United States Space Force",
      "text": "On December 20, 2019, the United States Space Force was officially established as a separate branch of the United States Armed Forces, following the signing of the National Defense Authorization Act for Fiscal Year 2020 by President Donald Trump.",
      "date": "2019-12-20"
    },
    {
      "headline": "First Chief of Space Operations",
      "text": "On December 20, 2019, General John W. Raymond was sworn in as the first Chief of Space Operations, the highest-ranking officer in the United States Space Force.",
      "date": "2019-12-20"
    },
    {
      "headline": "First Space Force Doctrine",
      "text": "In August 2020, the United States Space Force released its first doctrine, titled 'Spacepower: Doctrine for Space Forces,' outlining the principles and strategies for military operations in space.",
      "date": "2020-08"
    },
    {
      "headline": "First Space Force Member in Orbit",
      "text": "On November 15, 2020, Colonel Michael S. Hopkins transferred from the United States Air Force to the United States Space Force while aboard the International Space Station, becoming the first Space Force member in orbit.",
      "date": "2020-11-15"
    },
    {
      "headline": "First Space Force Base Renaming",
      "text": "On December 9, 2020, Cape Canaveral Air Force Station was officially renamed Cape Canaveral Space Force Station, marking the first renaming of a base to reflect the establishment of the Space Force.",
      "date": "2020-12-09"
    },
    {
      "headline": "First Space Force Launch",
      "text": "On March 26, 2020, the United States Space Force conducted its first launch, deploying the Advanced Extremely High Frequency (AEHF-6) satellite into orbit.",
      "date": "2020-03-26"
    },
    {
      "headline": "First Space Force Enlisted Member",
      "text": "On October 20, 2020, Chief Master Sergeant Roger A. Towberman was sworn in as the first Senior Enlisted Advisor of the United States Space Force.",
      "date": "2020-10-20"
    }
  ]
}

{
  "timeline": [
    {
      "headline": "Birth of Chiropractic",
      "text": "Chiropractic was founded by Daniel David Palmer in Davenport, Iowa, in 1895. Palmer claimed to have restored the hearing of a deaf janitor by adjusting his spine.",
      "date": "1895"
    },
    {
      "headline": "First Chiropractic School",
      "text": "In 1897, Daniel David Palmer established the Palmer School of Chiropractic in Davenport, Iowa, which was the first chiropractic school in the world.",
      "date": "1897"
    },
    {
      "headline": "Legal Recognition",
      "text": "In 1913, Kansas became the first state in the United States to license chiropractors, marking the beginning of legal recognition for the practice.",
      "date": "1913"
    },
    {
      "headline": "Formation of the American Chiropractic Association",
      "text": "The American Chiropractic Association (ACA) was formed in 1922, becoming the largest professional association for chiropractors in the United States.",
      "date": "1922"
    },
    {
      "headline": "Chiropractic Education Standardization",
      "text": "In 1974, the Council on Chiropractic Education (CCE) was recognized by the U.S. Department of Education, standardizing chiropractic education and accreditation.",
      "date": "1974"
    },
    {
      "headline": "Wilk v. American Medical Association",
      "text": "In 1987, the Wilk v. American Medical Association case concluded with a ruling that the AMA had engaged in an unlawful conspiracy to prevent chiropractors from practicing, marking a significant legal victory for chiropractic.",
      "date": "1987"
    },
    {
      "headline": "Chiropractic in the Military",
      "text": "In 1992, chiropractic care was included in the U.S. Department of Defense health care system, allowing military personnel access to chiropractic services.",
      "date": "1992"
    },
    {
      "headline": "Chiropractic in the Veterans Health Administration",
      "text": "In 2004, chiropractic care was integrated into the Veterans Health Administration, providing veterans with access to chiropractic services.",
      "date": "2004"
    }
  ]
}

