{
  "timeline": [
    {
      "headline": "Abduction of Michelle Knight",
      "text": "On August 23, 2002, Michelle Knight was abducted by Ariel Castro in Cleveland, Ohio. She was the first of the three women to be kidnapped and held captive in Castro's home.",
      "date": "2002-08-23"
    },
    {
      "headline": "Abduction of Amanda Berry",
      "text": "On April 21, 2003, Amanda Berry was abducted by Ariel Castro the day before her 17th birthday. She was held captive in Castro's home along with Michelle Knight.",
      "date": "2003-04-21"
    },
    {
      "headline": "Abduction of Gina DeJesus",
      "text": "On April 2, 2004, Gina DeJesus was abducted by Ariel Castro while walking home from school. She became the third victim to be held captive in Castro's home.",
      "date": "2004-04-02"
    },
    {
      "headline": "Amanda Berry's Escape and Rescue",
      "text": "On May 6, 2013, Amanda Berry escaped from Ariel Castro's home with her six-year-old daughter, whom she had given birth to while in captivity. Berry contacted the police, leading to the rescue of Michelle Knight and Gina DeJesus.",
      "date": "2013-05-06"
    },
    {
      "headline": "Arrest of Ariel Castro",
      "text": "On May 6, 2013, Ariel Castro was arrested by the police hours after Amanda Berry's escape and the rescue of the other captives.",
      "date": "2013-05-06"
    },
    {
      "headline": "Ariel Castro's Guilty Plea",
      "text": "On July 26, 2013, Ariel Castro pleaded guilty to 937 criminal counts of rape, kidnapping, and aggravated murder as part of a plea bargain to avoid the death penalty.",
      "date": "2013-07-26"
    },
    {
      "headline": "Ariel Castro Sentenced",
      "text": "On August 1, 2013, Ariel Castro was sentenced to life in prison without the possibility of parole plus 1,000 years.",
      "date": "2013-08-01"
    },
    {
      "headline": "Death of Ariel Castro",
      "text": "On September 3, 2013, Ariel Castro was found dead in his prison cell from an apparent suicide.",
      "date": "2013-09-03"
    }
  ]
}

