{
  "timeline": [
    {
      "headline": "Earliest Human Habitation",
      "text": "Archaeological evidence suggests that the area of Edinburgh has been inhabited since at least the Bronze Age, around 8500 BCE.",
      "date": "-8500"
    },
    {
      "headline": "Castle Rock Settlement",
      "text": "By the 7th century, the Gododdin tribe had established a hillfort on Castle Rock, which later became the site of Edinburgh Castle.",
      "date": "0600"
    },
    {
      "headline": "Edinburgh Becomes a Royal Burgh",
      "text": "In 1125, King David I of Scotland granted Edinburgh the status of a royal burgh, promoting its development as a center of trade and commerce.",
      "date": "1125"
    },
    {
      "headline": "Construction of St Giles' Cathedral",
      "text": "St Giles' Cathedral, the historic City Church of Edinburgh, was constructed in the 12th century, becoming a focal point for the city's religious life.",
      "date": "1120"
    },
    {
      "headline": "Edinburgh Castle Becomes a Royal Residence",
      "text": "In the 12th century, Edinburgh Castle became a royal residence, solidifying its importance in Scottish history.",
      "date": "1130"
    },
    {
      "headline": "University of Edinburgh Founded",
      "text": "The University of Edinburgh was founded in 1582, becoming one of the leading universities in the world.",
      "date": "1582"
    },
    {
      "headline": "Edinburgh Becomes Capital of Scotland",
      "text": "In 1437, Edinburgh officially became the capital of Scotland, a status it retains to this day.",
      "date": "1437"
    },
    {
      "headline": "Act of Union",
      "text": "In 1707, the Acts of Union were passed, uniting the Kingdom of Scotland and the Kingdom of England to form the Kingdom of Great Britain, with Edinburgh as the capital of Scotland.",
      "date": "1707"
    },
    {
      "headline": "Edinburgh New Town Construction Begins",
      "text": "Construction of the New Town began in 1767, designed to provide elegant and spacious accommodation for the city's wealthier residents.",
      "date": "1767"
    },
    {
      "headline": "Edinburgh Becomes a UNESCO World Heritage Site",
      "text": "In 1995, the Old Town and New Town of Edinburgh were designated a UNESCO World Heritage Site, recognizing their historical and architectural significance.",
      "date": "1995"
    }
  ]
}

