{
  "timeline": [
    {
      "headline": "Formation of the Rome-Berlin Axis",
      "text": "On October 25, 1936, Nazi Germany and Fascist Italy formed a coalition known as the Rome-Berlin Axis, marking the beginning of the Axis powers.",
      "date": "1936-10-25"
    },
    {
      "headline": "Anti-Comintern Pact",
      "text": "On November 25, 1936, Germany and Japan signed the Anti-Comintern Pact, an anti-communist agreement, which Italy joined in 1937, further solidifying the Axis alliance.",
      "date": "1936-11-25"
    },
    {
      "headline": "Pact of Steel",
      "text": "On May 22, 1939, Germany and Italy signed the Pact of Steel, a military and political alliance that further strengthened their cooperation.",
      "date": "1939-05-22"
    },
    {
      "headline": "Tripartite Pact",
      "text": "On September 27, 1940, Germany, Italy, and Japan signed the Tripartite Pact, officially establishing the Axis Powers and pledging mutual support in the event of an attack by a country not already involved in the war.",
      "date": "1940-09-27"
    },
    {
      "headline": "Axis Powers at their Peak",
      "text": "By 1942, the Axis Powers controlled large parts of Europe, North Africa, and Asia, reaching the height of their territorial expansion during World War II.",
      "date": "1942"
    },
    {
      "headline": "Defeat of Axis Powers",
      "text": "The Axis Powers began to face significant defeats starting in 1943, with the fall of Italy in September 1943, and the eventual surrender of Germany on May 8, 1945, and Japan on September 2, 1945, marking the end of World War II.",
      "date": "1945-09-02"
    }
  ]
}

{
  "timeline": [
    {
      "headline": "Founding of Psychology",
      "text": "In 1879, Wilhelm Wundt established the first laboratory dedicated to psychological research at the University of Leipzig in Germany, marking the formal beginning of psychology as a scientific discipline.",
      "date": "1879"
    },
    {
      "headline": "Publication of 'The Principles of Psychology'",
      "text": "In 1890, William James published 'The Principles of Psychology', a seminal text that laid the foundation for many psychological theories and practices.",
      "date": "1890"
    },
    {
      "headline": "Introduction of Psychoanalysis",
      "text": "Sigmund Freud introduced psychoanalysis in the late 19th century, with his first major work, 'The Interpretation of Dreams', published in 1899.",
      "date": "1899"
    },
    {
      "headline": "Behaviorism Emerges",
      "text": "In 1913, John B. Watson published 'Psychology as the Behaviorist Views It', which is considered the formal founding of behaviorism, a major school of thought in psychology.",
      "date": "1913"
    },
    {
      "headline": "Development of Humanistic Psychology",
      "text": "In the 1950s, humanistic psychology emerged as a response to psychoanalysis and behaviorism, with key figures like Carl Rogers and Abraham Maslow emphasizing personal growth and self-actualization.",
      "date": "1950"
    },
    {
      "headline": "Cognitive Revolution",
      "text": "The 1960s saw the cognitive revolution, which shifted psychology's focus back to the study of mental processes, influenced by advances in computer science and linguistics.",
      "date": "1960"
    },
    {
      "headline": "Establishment of the American Psychological Association",
      "text": "The American Psychological Association (APA) was founded in 1892, becoming a leading organization for the advancement of psychology.",
      "date": "1892"
    },
    {
      "headline": "Introduction of Cognitive Behavioral Therapy (CBT)",
      "text": "In the 1960s and 1970s, Cognitive Behavioral Therapy (CBT) was developed by Aaron Beck and Albert Ellis, combining cognitive and behavioral approaches to treat psychological disorders.",
      "date": "1970"
    },
    {
      "headline": "Positive Psychology Movement",
      "text": "In the late 1990s, Martin Seligman and others initiated the positive psychology movement, focusing on strengths, virtues, and factors that contribute to human flourishing.",
      "date": "1998"
    }
  ]
}

