{
  "timeline": [
    {
      "headline": "Founding of Athens",
      "text": "Athens is believed to have been continuously inhabited for at least 5,000 years. The earliest human presence in Athens is dated back to the Neolithic period, around 3000 BCE.",
      "date": "-3000"
    },
    {
      "headline": "Mycenaean Athens",
      "text": "During the Mycenaean period, Athens was a major center of the Mycenaean civilization and was fortified with a palace complex on the Acropolis, around 1400 BCE.",
      "date": "-1400"
    },
    {
      "headline": "The Rise of Classical Athens",
      "text": "In the 5th century BCE, Athens became the leading city of Ancient Greece. It was a center for the arts, learning, and philosophy, home of Plato's Academy and Aristotle's Lyceum.",
      "date": "-0500"
    },
    {
      "headline": "The Persian Wars",
      "text": "Athens played a key role in the Persian Wars, particularly in the Battle of Marathon in 490 BCE and the Battle of Salamis in 480 BCE.",
      "date": "-0480"
    },
    {
      "headline": "The Golden Age of Athens",
      "text": "The period from 480 to 404 BCE is known as the Golden Age of Athens, marked by the leadership of Pericles and the construction of the Parthenon.",
      "date": "-0480"
    },
    {
      "headline": "Peloponnesian War",
      "text": "The Peloponnesian War between Athens and Sparta lasted from 431 to 404 BCE, ending in the defeat of Athens.",
      "date": "-0431"
    },
    {
      "headline": "Conquest by Macedon",
      "text": "In 338 BCE, Athens was conquered by Philip II of Macedon after the Battle of Chaeronea.",
      "date": "-0338"
    },
    {
      "headline": "Roman Athens",
      "text": "Athens became part of the Roman Empire in 146 BCE and continued to be a center of philosophy and learning.",
      "date": "-0146"
    },
    {
      "headline": "Byzantine Period",
      "text": "During the Byzantine period, Athens experienced decline but remained an important religious center.",
      "date": "0500"
    },
    {
      "headline": "Ottoman Athens",
      "text": "Athens was conquered by the Ottoman Empire in 1458 and remained under Ottoman control until the Greek War of Independence.",
      "date": "1458"
    },
    {
      "headline": "Greek War of Independence",
      "text": "Athens was liberated from Ottoman rule in 1833 during the Greek War of Independence.",
      "date": "1833"
    },
    {
      "headline": "Athens Becomes Capital of Greece",
      "text": "In 1834, Athens was declared the capital of the newly independent Greek state.",
      "date": "1834"
    },
    {
      "headline": "Modern Olympic Games",
      "text": "Athens hosted the first modern Olympic Games in 1896.",
      "date": "1896"
    },
    {
      "headline": "Athens in World War II",
      "text": "During World War II, Athens was occupied by Axis forces from 1941 to 1944.",
      "date": "1941"
    },
    {
      "headline": "Athens Hosts the Olympics Again",
      "text": "Athens hosted the Summer Olympics for the second time in 2004.",
      "date": "2004"
    }
  ]
}

