{
  "timeline": [
    {
      "headline": "Defenestration of Prague",
      "text": "On May 23, 1618, the Defenestration of Prague occurred when Protestant nobles threw two Catholic officials out of a window in Prague Castle, sparking the Bohemian Revolt and the beginning of the Thirty Years' War.",
      "date": "1618-05-23"
    },
    {
      "headline": "Battle of White Mountain",
      "text": "On November 8, 1620, the Battle of White Mountain took place near Prague, resulting in a decisive Catholic victory over the Protestant forces of Bohemia.",
      "date": "1620-11-08"
    },
    {
      "headline": "Edict of Restitution",
      "text": "In March 1629, the Edict of Restitution was issued by Emperor Ferdinand II, aiming to restore Catholic properties lost to Protestantism since 1552, exacerbating tensions.",
      "date": "1629-03"
    },
    {
      "headline": "Swedish Intervention",
      "text": "In 1630, King Gustavus Adolphus of Sweden entered the war on the Protestant side, marking a significant turning point in the conflict.",
      "date": "1630"
    },
    {
      "headline": "Battle of Breitenfeld",
      "text": "On September 17, 1631, the Battle of Breitenfeld was fought, where Swedish forces under Gustavus Adolphus achieved a major victory against the Catholic League.",
      "date": "1631-09-17"
    },
    {
      "headline": "Death of Gustavus Adolphus",
      "text": "On November 6, 1632, King Gustavus Adolphus of Sweden was killed at the Battle of Lützen, a significant event that affected the Protestant cause.",
      "date": "1632-11-06"
    },
    {
      "headline": "Peace of Prague",
      "text": "In 1635, the Peace of Prague was signed, attempting to unify the Holy Roman Empire's forces by ending hostilities between the Emperor and some Protestant states.",
      "date": "1635"
    },
    {
      "headline": "French Intervention",
      "text": "In 1635, France entered the war directly against Spain and the Holy Roman Empire, shifting the conflict's focus to a Franco-Spanish rivalry.",
      "date": "1635"
    },
    {
      "headline": "Battle of Rocroi",
      "text": "On May 19, 1643, the Battle of Rocroi was fought, where French forces defeated the Spanish, marking the decline of Spanish military dominance.",
      "date": "1643-05-19"
    },
    {
      "headline": "Peace of Westphalia",
      "text": "On October 24, 1648, the Peace of Westphalia treaties were signed, ending the Thirty Years' War and redrawing the political map of Europe.",
      "date": "1648-10-24"
    }
  ]
}

