{
  "timeline": [
    {
      "headline": "Annexation of Texas",
      "text": "In 1845, the United States annexed the Republic of Texas, which Mexico still considered its territory. This event was a precursor to the Mexican–American War.",
      "date": "1845"
    },
    {
      "headline": "Outbreak of War",
      "text": "On April 25, 1846, the Mexican–American War began when Mexican forces attacked U.S. troops in the disputed area between the Rio Grande and Nueces River.",
      "date": "1846-04-25"
    },
    {
      "headline": "Battle of Palo Alto",
      "text": "The first major battle of the war, the Battle of Palo Alto, took place on May 8, 1846, near present-day Brownsville, Texas. U.S. forces, led by General Zachary Taylor, defeated the Mexican army.",
      "date": "1846-05-08"
    },
    {
      "headline": "Battle of Resaca de la Palma",
      "text": "On May 9, 1846, U.S. forces won another victory at the Battle of Resaca de la Palma, forcing Mexican troops to retreat across the Rio Grande.",
      "date": "1846-05-09"
    },
    {
      "headline": "Capture of Monterrey",
      "text": "In September 1846, U.S. forces captured the city of Monterrey after a three-day battle, marking a significant victory in the northern campaign.",
      "date": "1846-09"
    },
    {
      "headline": "Battle of Buena Vista",
      "text": "On February 22-23, 1847, the Battle of Buena Vista took place. General Zachary Taylor's forces repelled a larger Mexican army led by General Santa Anna.",
      "date": "1847-02-22"
    },
    {
      "headline": "Siege of Veracruz",
      "text": "From March 9 to March 29, 1847, U.S. forces conducted a successful siege of Veracruz, a crucial port city on the Gulf of Mexico.",
      "date": "1847-03-09"
    },
    {
      "headline": "Battle of Cerro Gordo",
      "text": "On April 18, 1847, U.S. forces under General Winfield Scott defeated the Mexican army at the Battle of Cerro Gordo, opening the way to Mexico City.",
      "date": "1847-04-18"
    },
    {
      "headline": "Capture of Mexico City",
      "text": "On September 14, 1847, U.S. forces captured Mexico City after a series of battles, effectively ending major combat operations in the war.",
      "date": "1847-09-14"
    },
    {
      "headline": "Treaty of Guadalupe Hidalgo",
      "text": "The Treaty of Guadalupe Hidalgo was signed on February 2, 1848, officially ending the Mexican–American War. Mexico ceded large territories to the U.S., including present-day California, Nevada, and Utah.",
      "date": "1848-02-02"
    },
    {
      "headline": "Ratification of the Treaty",
      "text": "The U.S. Senate ratified the Treaty of Guadalupe Hidalgo on March 10, 1848, finalizing the end of the war and the territorial gains for the United States.",
