{
  "timeline": [
    {
      "headline": "Emergence of Sundown Towns",
      "text": "Sundown towns began to emerge in the United States in the late 19th century, particularly after the Reconstruction era. These towns were characterized by their exclusion of African Americans and other non-white groups through discriminatory practices, including local laws and intimidation.",
      "date": "1870"
    },
    {
      "headline": "Peak of Sundown Towns",
      "text": "Sundown towns reached their peak prevalence in the early to mid-20th century. During this time, thousands of towns across the United States, particularly in the Midwest and West, enforced policies that excluded non-white individuals.",
      "date": "1920"
    },
    {
      "headline": "Civil Rights Movement Challenges Sundown Towns",
      "text": "The Civil Rights Movement of the 1950s and 1960s brought increased attention to the discriminatory practices of sundown towns. Activists and legal challenges began to dismantle the policies that enforced racial segregation in these areas.",
      "date": "1950"
    },
    {
      "headline": "Decline of Sundown Towns",
      "text": "By the late 20th century, the number of sundown towns had significantly decreased due to legal and social changes. The Civil Rights Act of 1964 and other legislation played a crucial role in reducing the prevalence of racially exclusive towns.",
      "date": "1970"
    },
    {
      "headline": "Recognition and Documentation",
      "text": "In the early 21st century, historians and researchers began to document and study the history of sundown towns more extensively, bringing awareness to their impact on racial segregation in the United States.",
      "date": "2000"
    }
  ]
}

