{
  "timeline": [
    {
      "headline": "Overthrow of the Roman Kingdom",
      "text": "The Roman Republic was established following the overthrow of the Roman Kingdom in 509 BC.",
      "date": "-0509"
    },
    {
      "headline": "Conflict of the Orders",
      "text": "The Conflict of the Orders was a political struggle between the Plebeians and Patricians of the Roman Republic, lasting from 494 BC to 287 BC.",
      "date": "-0494"
    },
    {
      "headline": "The Twelve Tables",
      "text": "In 450 BC, the Law of the Twelve Tables was created, which was the first set of laws written down in Rome.",
      "date": "-0450"
    },
    {
      "headline": "First Punic War",
      "text": "The First Punic War between Rome and Carthage began in 264 BC and ended in 241 BC, resulting in Roman victory and control over Sicily.",
      "date": "-0264"
    },
    {
      "headline": "Second Punic War",
      "text": "The Second Punic War, from 218 BC to 201 BC, was marked by Hannibal's crossing of the Alps and ended with Roman victory at the Battle of Zama.",
      "date": "-0218"
    },
    {
      "headline": "Third Punic War",
      "text": "The Third Punic War occurred from 149 BC to 146 BC, resulting in the destruction of Carthage and Roman dominance over the western Mediterranean.",
      "date": "-0149"
    },
    {
      "headline": "Gracchi Reforms",
      "text": "Tiberius Gracchus was elected tribune in 133 BC and initiated land reforms. His brother Gaius Gracchus continued these reforms in 123 BC.",
      "date": "-0133"
    },
    {
      "headline": "Social War",
      "text": "The Social War, from 91 BC to 88 BC, was a conflict between Rome and its Italian allies over citizenship rights.",
      "date": "-0091"
    },
    {
      "headline": "Sulla's Dictatorship",
      "text": "Lucius Cornelius Sulla became dictator of Rome in 82 BC, initiating constitutional reforms to strengthen the Senate.",
      "date": "-0082"
    },
    {
      "headline": "First Triumvirate",
      "text": "In 60 BC, Julius Caesar, Pompey, and Crassus formed the First Triumvirate, an informal political alliance.",
      "date": "-0060"
    },
    {
      "headline": "Caesar's Civil War",
      "text": "Caesar's Civil War began in 49 BC when Julius Caesar crossed the Rubicon River, leading to his dictatorship.",
      "date": "-0049"
    },
    {
      "headline": "Assassination of Julius Caesar",
      "text": "Julius Caesar was assassinated on March 15, 44 BC, in a conspiracy led by Brutus and Cassius.",
      "date": "-0044-03-15"
    },
    {
      "headline": "Second Triumvirate",
      "text": "The Second Triumvirate was formed in 43 BC by Octavian, Mark Antony, and Lepidus to defeat Caesar's assassins.",
      "date": "-0043"
    },
    {
      "headline": "Battle of Actium",
      "text": "The Battle of Actium occurred on September 2, 31 BC, where Octavian defeated the forces of Mark Antony and Cleopatra.",
      "date": "-0031-09-02"
    },
    {
      "headline": "End of the Roman Republic",
      "text": "The Roman Republic ended in 27 BC when Octavian became Augustus, the first Roman Emperor, marking the beginning of the Roman Empire.",
      "date": "-0027"
    }
  ]
}

