{
  "timeline": [
    {
      "headline": "Founding of Yale University",
      "text": "Yale University was founded in 1701 as the Collegiate School in the home of Abraham Pierson, its first rector, in Killingworth, Connecticut.",
      "date": "1701"
    },
    {
      "headline": "Relocation to New Haven",
      "text": "In 1716, the Collegiate School relocated to New Haven, Connecticut, where it has remained since.",
      "date": "1716"
    },
    {
      "headline": "Renaming to Yale College",
      "text": "In 1718, the Collegiate School was renamed Yale College in honor of Elihu Yale, a benefactor who donated a substantial sum of money and books.",
      "date": "1718"
    },
    {
      "headline": "First Yale College Building",
      "text": "In 1718, Yale College constructed its first building, a wooden structure called the College House.",
      "date": "1718"
    },
    {
      "headline": "Yale's First Graduate",
      "text": "In 1702, Yale College awarded its first degree to Nathaniel Chauncey.",
      "date": "1702"
    },
    {
      "headline": "Establishment of Yale Law School",
      "text": "Yale Law School was established in 1824, becoming one of the most prestigious law schools in the United States.",
      "date": "1824"
    },
    {
      "headline": "Yale School of Medicine",
      "text": "The Yale School of Medicine was founded in 1810, expanding Yale's offerings in medical education.",
      "date": "1810"
    },
    {
      "headline": "Yale School of Art",
      "text": "The Yale School of Art was founded in 1869, becoming the first professional fine arts school in the United States.",
      "date": "1869"
    },
    {
      "headline": "Yale School of Music",
      "text": "The Yale School of Music was established in 1894, offering advanced degrees in music.",
      "date": "1894"
    },
    {
      "headline": "Yale School of Drama",
      "text": "The Yale School of Drama was founded in 1924, becoming a leading institution for theater education.",
      "date": "1924"
    },
    {
      "headline": "Coeducation at Yale",
      "text": "In 1969, Yale College became coeducational, admitting women for the first time.",
      "date": "1969"
    },
    {
      "headline": "Yale's Tercentennial",
      "text": "In 2001, Yale University celebrated its 300th anniversary with a series of events and commemorations.",
      "date": "2001"
    }
  ]
}

