    {
      "headline": "Birth of Maximilien Robespierre",
      "text": "Maximilien François Marie Isidore de Robespierre was born on May 6, 1758, in Arras, France.",
      "date": "1758-05-06"
    },
    {
      "headline": "Education at Lycée Louis-le-Grand",
      "text": "In 1769, Robespierre was awarded a scholarship to attend the Lycée Louis-le-Grand in Paris, where he received a classical education.",
      "date": "1769"
    },
    {
      "headline": "Graduation and Legal Career",
      "text": "Robespierre graduated in law in 1781 and began practicing as a lawyer in Arras.",
      "date": "1781"
    },
    {
      "headline": "Elected to the Estates-General",
      "text": "In 1789, Robespierre was elected as a deputy to the Estates-General, representing the Third Estate.",
      "date": "1789"
    },
    {
      "headline": "Member of the National Constituent Assembly",
      "text": "Following the formation of the National Constituent Assembly in 1789, Robespierre became an active member, advocating for democratic reforms.",
      "date": "1789"
    },
    {
      "headline": "President of the Jacobin Club",
      "text": "In 1790, Robespierre became the president of the Jacobin Club, a political group that became influential during the French Revolution.",
      "date": "1790"
    },
    {
      "headline": "Elected to the National Convention",
      "text": "In 1792, Robespierre was elected to the National Convention, where he played a key role in the revolutionary government.",
      "date": "1792"
    },
    {
      "headline": "Role in the Execution of King Louis XVI",
      "text": "Robespierre was instrumental in the decision to execute King Louis XVI, which took place on January 21, 1793.",
      "date": "1793-01-21"
    },
    {
      "headline": "Committee of Public Safety",
      "text": "In July 1793, Robespierre was elected to the Committee of Public Safety, where he became a leading figure in the revolutionary government.",
      "date": "1793-07"
    },
    {
      "headline": "Reign of Terror",
      "text": "During 1793-1794, Robespierre was a central figure in the Reign of Terror, a period marked by mass executions of perceived enemies of the revolution.",
      "date": "1793"
    },
    {
      "headline": "Fall and Execution",
      "text": "Robespierre was arrested on July 27, 1794, during the Thermidorian Reaction, and was executed by guillotine the following day, July 28, 1794.",
      "date": "1794-07-28"
    }
  ]
}

