{
  "timeline": [
    {
      "headline": "Origin of the Term 'Sodomy'",
      "text": "The term 'sodomy' is derived from the story of Sodom and Gomorrah in the Book of Genesis, which is part of the Hebrew Bible and Christian Old Testament.",
      "date": "-1500"  },
    {
      "headline": "Sodomy Laws in Medieval Europe",
      "text": "During the medieval period, sodomy was considered a serious crime in Europe, often punishable by death. These laws were influenced by religious texts and moral teachings of the time.",
      "date": "1100"
    },
    {
      "headline": "Buggery Act 1533",
      "text": "In 1533, the Buggery Act was enacted in England under the reign of King Henry VIII. It was the first civil legislation against sodomy in the country, making it a capital offense.",
      "date": "1533"
    },
    {
      "headline": "Repeal of Sodomy Laws in France",
      "text": "In 1791, France became the first Western country to decriminalize sodomy, as part of the broader reforms during the French Revolution.",
      "date": "1791"
    },
    {
      "headline": "Wolfenden Report",
      "text": "In 1957, the Wolfenden Report was published in the United Kingdom, recommending the decriminalization of homosexual acts between consenting adults in private.",
      "date": "1957"
    },
    {
      "headline": "Decriminalization in the UK",
      "text": "The Sexual Offences Act 1967 was passed in the United Kingdom, decriminalizing homosexual acts in private between two men over the age of 21 in England and Wales.",
      "date": "1967"
    },
    {
      "headline": "Lawrence v. Texas",
      "text": "In 2003, the United States Supreme Court ruled in Lawrence v. Texas that sodomy laws were unconstitutional, effectively decriminalizing consensual same-sex sexual activity across the United States.",
      "date": "2003"
    }
  ]
}

