    },
    {
      "headline": "Ascension to the Throne",
      "text": "Suleiman became the Sultan of the Ottoman Empire on September 30, 1520, following the death of his father, Selim I.",
      "date": "1520-09-30"
    },
    {
      "headline": "Conquest of Belgrade",
      "text": "In 1521, Suleiman captured Belgrade, a key fortress in the Kingdom of Hungary, marking the beginning of his military campaigns in Europe.",
      "date": "1521"
    },
    {
      "headline": "Siege of Rhodes",
      "text": "Suleiman successfully led the siege of Rhodes in 1522, capturing the island from the Knights Hospitaller.",
      "date": "1522"
    },
    {
      "headline": "Battle of Mohács",
      "text": "On August 29, 1526, Suleiman defeated the Kingdom of Hungary at the Battle of Mohács, leading to the partition of Hungary.",
      "date": "1526-08-29"
    },
    {
      "headline": "First Siege of Vienna",
      "text": "In 1529, Suleiman led the first siege of Vienna, marking the Ottoman Empire's furthest advance into Central Europe, although the siege was unsuccessful.",
      "date": "1529"
    },
    {
      "headline": "Codification of Ottoman Laws",
      "text": "Suleiman was known as 'the Lawgiver' for his comprehensive legal reforms, which were completed around 1530.",
      "date": "1530"
    },
    {
      "headline": "Conquest of Baghdad",
      "text": "In 1534, Suleiman captured Baghdad, bringing Mesopotamia under Ottoman control.",
      "date": "1534"
    },
    {
      "headline": "Treaty of Constantinople",
      "text": "In 1536, Suleiman signed the Treaty of Constantinople with France, establishing a Franco-Ottoman alliance.",
      "date": "1536"
    },
    {
      "headline": "Naval Victory at Preveza",
      "text": "On September 28, 1538, the Ottoman navy, under Suleiman's command, defeated the Holy League at the Battle of Preveza, securing Ottoman dominance in the Mediterranean.",
      "date": "1538-09-28"
    },
    {
      "headline": "Second Siege of Vienna",
      "text": "In 1532, Suleiman attempted a second siege of Vienna, but it was ultimately unsuccessful.",
      "date": "1532"
    },
    {
      "headline": "Death of Suleiman the Magnificent",
      "text": "Suleiman the Magnificent died on September 6, 1566, during the Siege of Szigetvár in Hungary.",
      "date": "1566-09-06"
    }
  ]
}

