    },
    {
      "headline": "Commissioned as Brigadier General in the British Army",
      "text": "After defecting, Arnold was commissioned as a brigadier general in the British Army.",
      "date": "1780"
    },
    {
      "headline": "Command of the American Legion",
      "text": "Arnold was placed in command of the American Legion, a Loyalist unit in the British Army.",
      "date": "1780"
    },
    {
      "headline": "Battle of Groton Heights",
      "text": "On September 6, 1781, Arnold led British forces in the attack on New London, Connecticut, and the Battle of Groton Heights.",
      "date": "1781-09-06"
