{
  "timeline": [
    {
      "headline": "Pongal Festival Overview",
      "text": "Pongal, also known as Thai Pongal, is a multi-day Hindu harvest festival celebrated by Tamils. It is observed in the month of Thai according to the Tamil solar calendar and usually falls on 14 or 15 January. The festival is dedicated to Surya, the Sun God, and corresponds to Makar Sankranti, celebrated under many regional names throughout the Indian subcontinent.",
      "date": "0000-01-14"
    },
    {
      "headline": "Bhogi Festival",
      "text": "The first day of the Pongal festival is known as Bhogi. It is celebrated in honor of Lord Indra, the God of Rain, and involves discarding old belongings and focusing on new possessions. This day marks the beginning of the festival and is typically observed on January 13.",
      "date": "0000-01-13"
    },
    {
      "headline": "Surya Pongal",
      "text": "The second day of the festival is Surya Pongal, dedicated to the Sun God, Surya. It is the main day of the Pongal festival and is celebrated with the cooking of the Pongal dish, a sweet rice dish. This day usually falls on January 14.",
      "date": "0000-01-14"
    },
    {
      "headline": "Mattu Pongal",
      "text": "The third day of Pongal is Mattu Pongal, which is dedicated to cattle, especially cows, which are considered sacred in Hindu culture. Cattle are decorated and worshipped on this day, which typically occurs on January 15.",
      "date": "0000-01-15"
    },
    {
      "headline": "Kaanum Pongal",
      "text": "The fourth and final day of the Pongal festival is Kaanum Pongal. It is a day for socializing and visiting family and friends. People also perform rituals to honor their ancestors. This day is usually observed on January 16.",
      "date": "0000-01-16"
    }
  ]
}

