      "headline": "First Mention of Kashmir",
      "text": "The earliest mention of Kashmir is found in the Hindu epic Mahabharata, which dates back to ancient times.",
      "date": "-1000"
    },
    {
      "headline": "Buddhism in Kashmir",
      "text": "Buddhism was introduced to Kashmir during the reign of Emperor Ashoka in the 3rd century BCE.",
      "date": "-0300"
    },
    {
      "headline": "Kushan Empire",
      "text": "Kashmir became part of the Kushan Empire around the 1st century CE.",
      "date": "0100"
    },
    {
      "headline": "Karkota Dynasty",
      "text": "The Karkota Dynasty ruled Kashmir from the 7th to the 9th century, marking a period of political stability and cultural flourishing.",
      "date": "0650"
    },
    {
      "headline": "Lohara Dynasty",
      "text": "The Lohara dynasty ruled Kashmir from the 11th to the 14th century.",
      "date": "1003"
    },
    {
      "headline": "Islamic Rule",
      "text": "Islamic rule was established in Kashmir in the 14th century, beginning with the reign of Shams-ud-Din Shah Mir in 1339.",
      "date": "1339"
    },
    {
      "headline": "Mughal Empire",
      "text": "Kashmir became part of the Mughal Empire in 1586 under Emperor Akbar.",
      "date": "1586"
    },
    {
      "headline": "Afghan Durrani Empire",
      "text": "The Durrani Empire took control of Kashmir in 1752.",
      "date": "1752"
    },
    {
      "headline": "Sikh Empire",
      "text": "Kashmir was annexed by the Sikh Empire under Maharaja Ranjit Singh in 1819.",
      "date": "1819"
    },
    {
      "headline": "Treaty of Amritsar",
      "text": "The Treaty of Amritsar was signed in 1846, transferring Kashmir to the Dogra ruler Gulab Singh.",
      "date": "1846"
    },
    {
      "headline": "Partition of India",
      "text": "In 1947, the partition of India led to the division of Kashmir between India and Pakistan.",
      "date": "1947"
    },
    {
      "headline": "First Indo-Pakistani War",
      "text": "The first war between India and Pakistan over Kashmir took place from 1947 to 1948, resulting in a ceasefire and the establishment of the Line of Control.",
      "date": "1947"
    },
    {
      "headline": "Article 370",
      "text": "In 1954, Article 370 was added to the Indian Constitution, granting special autonomy to Jammu and Kashmir.",
      "date": "1954"
    },
    {
      "headline": "Abrogation of Article 370",
      "text": "On August 5, 2019, the Indian government abrogated Article 370, revoking the special status of Jammu and Kashmir.",
      "date": "2019-08-05"
    }
  ]
}

