    {
      "headline": "Arab Conquest",
      "text": "In 827 CE, Arab forces began the conquest of Sicily, which was completed in 902 CE, bringing Islamic culture and influence to the island.",
      "date": "0902"
    },
    {
      "headline": "Norman Conquest",
      "text": "In 1061, the Normans began their conquest of Sicily, which was completed in 1091, establishing the Kingdom of Sicily.",
      "date": "1091"
    },
    {
      "headline": "Sicilian Vespers",
      "text": "In 1282, the Sicilian Vespers rebellion led to the end of Angevin rule and the beginning of Aragonese control over Sicily.",
      "date": "1282"
    },
    {
      "headline": "Unification with Italy",
      "text": "In 1860, Giuseppe Garibaldi's Expedition of the Thousand led to the annexation of Sicily into the Kingdom of Italy.",
