{
  "timeline": [
    {
      "headline": "Synthesis of Barbituric Acid",
      "text": "Barbituric acid was first synthesized by German chemist Adolf von Baeyer in 1864. This compound is the parent structure of barbiturates.",
      "date": "1864"
    },
    {
      "headline": "Introduction of Barbital",
      "text": "Barbital, the first barbiturate used clinically, was introduced in 1903. It was marketed under the brand name Veronal and used as a sedative.",
      "date": "1903"
    },
    {
      "headline": "Development of Phenobarbital",
      "text": "Phenobarbital, another barbiturate, was developed in 1912. It became widely used for its anticonvulsant properties.",
      "date": "1912"
    },
    {
      "headline": "Peak Medical Use",
      "text": "Barbiturates reached their peak in medical use during the 1950s and 1960s. They were commonly prescribed for anxiety, insomnia, and seizure disorders.",
      "date": "1950"
    },
    {
      "headline": "Recognition of Addiction Potential",
      "text": "By the 1960s, the addiction potential and risk of overdose associated with barbiturates became widely recognized, leading to increased regulation.",
      "date": "1960"
    },
    {
      "headline": "Introduction of Benzodiazepines",
      "text": "In the 1960s, benzodiazepines were introduced as safer alternatives to barbiturates for treating anxiety and insomnia, leading to a decline in barbiturate prescriptions.",
      "date": "1960"
    },
    {
      "headline": "Controlled Substance Classification",
      "text": "In the 1970s, barbiturates were classified as controlled substances in many countries due to their potential for abuse and addiction.",
      "date": "1970"
    },
    {
      "headline": "Current Medical Use",
      "text": "Today, barbiturates are rarely used for anxiety or insomnia but are still used in certain medical contexts, such as anesthesia and the treatment of epilepsy.",
      "date": "2023"
    }
  ]
}

{
  "timeline": [
