{
  "timeline": [
    {
      "headline": "Synthesis of LSD",
      "text": "LSD was first synthesized on November 16, 1938, by Swiss chemist Albert Hofmann at the Sandoz Laboratories in Basel, Switzerland. Hofmann was researching lysergic acid derivatives as part of a program to synthesize medically useful ergot alkaloid derivatives.",
      "date": "1938-11-16"
    },
    {
      "headline": "Discovery of LSD's Psychoactive Effects",
      "text": "On April 19, 1943, Albert Hofmann intentionally ingested 250 micrograms of LSD, leading to the discovery of its powerful psychoactive effects. This day is now famously known as 'Bicycle Day' due to Hofmann's bicycle ride home while experiencing the effects.",
      "date": "1943-04-19"
    },
    {
      "headline": "Introduction to Psychiatry",
      "text": "In the 1950s, LSD began to be used in psychiatric research and therapy. It was believed to have potential for treating various mental health conditions, including alcoholism and anxiety.",
      "date": "1950"
    },
    {
      "headline": "CIA's MK-Ultra Program",
      "text": "During the 1950s and 1960s, the CIA conducted experiments with LSD as part of the MK-Ultra program, which aimed to explore mind control and chemical interrogation.",
      "date": "1950"
    },
    {
      "headline": "Counterculture Movement",
      "text": "In the 1960s, LSD became popular within the counterculture movement, particularly among artists, musicians, and writers. It was associated with the hippie movement and was used to promote personal and social change.",
      "date": "1960"
    },
    {
      "headline": "LSD Declared Illegal in the United States",
      "text": "On October 24, 1968, LSD was declared illegal in the United States, classified as a Schedule I drug under the Controlled Substances Act, which indicated a high potential for abuse and no accepted medical use.",
      "date": "1968-10-24"
    },
    {
      "headline": "Research Resurgence",
      "text": "In the 21st century, there has been a resurgence of interest in LSD research, focusing on its potential therapeutic benefits for mental health conditions such as PTSD, anxiety, and depression.",
      "date": "2000"
    }
  ]
}

{
