{
  "timeline": [
    {
      "headline": "Stamp Act Passed",
      "text": "The Stamp Act was passed by the British Parliament on March 22, 1765, imposing a direct tax on the colonies for stamped paper used for official documents, newspapers, and other publications.",
      "date": "1765-03-22"
    },
    {
      "headline": "Stamp Act Congress",
      "text": "In October 1765, representatives from nine colonies convened in New York City for the Stamp Act Congress to organize a unified protest against the Stamp Act.",
      "date": "1765-10"
    },
    {
      "headline": "Repeal of the Stamp Act",
      "text": "The Stamp Act was repealed by the British Parliament on March 18, 1766, due to widespread protest and economic pressure from the colonies.",
      "date": "1766-03-18"
    },
    {
      "headline": "Townshend Acts Enacted",
      "text": "The Townshend Acts were enacted by the British Parliament in June 1767, imposing duties on glass, lead, paints, paper, and tea imported into the colonies.",
      "date": "1767-06"
    },
    {
      "headline": "Boston Massacre",
      "text": "On March 5, 1770, British soldiers killed five colonial civilians in Boston, an event that became known as the Boston Massacre and fueled anti-British sentiments.",
      "date": "1770-03-05"
    },
    {
      "headline": "Boston Tea Party",
      "text": "On December 16, 1773, American colonists, frustrated with British taxation, dumped 342 chests of British tea into Boston Harbor in protest, an event known as the Boston Tea Party.",
      "date": "1773-12-16"
    },
    {
      "headline": "Intolerable Acts Passed",
      "text": "In response to the Boston Tea Party, the British Parliament passed the Intolerable Acts in 1774, a series of punitive measures aimed at reasserting control over the colonies.",
      "date": "1774"
    },
    {
      "headline": "First Continental Congress",
      "text": "The First Continental Congress convened on September 5, 1774, in Philadelphia, bringing together delegates from twelve colonies to coordinate a response to the Intolerable Acts.",
      "date": "1774-09-05"
    },
    {
      "headline": "Battles of Lexington and Concord",
      "text": "The first military engagements of the American Revolutionary War occurred on April 19, 1775, at Lexington and Concord, marking the outbreak of open armed conflict between Britain and the colonies.",
      "date": "1775-04-19"
    },
    {
      "headline": "Second Continental Congress",
      "text": "The Second Continental Congress convened on May 10, 1775, in Philadelphia, serving as the de facto national government of the colonies during the Revolutionary War.",
      "date": "1775-05-10"
    },
    {
      "headline": "Declaration of Independence",
      "text": "On July 4, 1776, the Continental Congress adopted the Declaration of Independence, formally declaring the colonies' independence from Great Britain.",
      "date": "1776-07-04"
    },
    {
