{
  "timeline": [
    {
      "headline": "Beginning of the Age of Enlightenment",
      "text": "The Age of Enlightenment began in the late 17th century, around the 1680s, as an intellectual and philosophical movement in Europe. It emphasized reason, individualism, and skepticism of traditional doctrines.",
      "date": "1680"
    },
    {
      "headline": "Publication of 'Philosophiae Naturalis Principia Mathematica'",
      "text": "In 1687, Isaac Newton published 'Philosophiae Naturalis Principia Mathematica', laying the groundwork for classical mechanics and influencing Enlightenment thought with its emphasis on rationality and empirical evidence.",
      "date": "1687"
    },
    {
      "headline": "Publication of 'Essay Concerning Human Understanding'",
      "text": "John Locke published 'Essay Concerning Human Understanding' in 1689, which became a foundational text for Enlightenment philosophy, advocating the idea of the mind as a 'tabula rasa' and emphasizing empirical knowledge.",
      "date": "1689"
    },
    {
      "headline": "Publication of 'The Spirit of the Laws'",
      "text": "In 1748, Montesquieu published 'The Spirit of the Laws', a seminal work in political theory that advocated the separation of powers, influencing modern democratic governance.",
      "date": "1748"
    },
    {
      "headline": "Publication of 'The Encyclopédie'",
      "text": "The first volume of 'The Encyclopédie', edited by Denis Diderot and Jean le Rond d'Alembert, was published in 1751. It aimed to gather and disseminate knowledge, reflecting Enlightenment ideals of reason and progress.",
      "date": "1751"
    },
    {
      "headline": "Publication of 'Candide'",
      "text": "Voltaire published 'Candide' in 1759, a satirical novella that critiqued optimism and organized religion, embodying Enlightenment values of skepticism and reason.",
      "date": "1759"
    },
    {
      "headline": "American Declaration of Independence",
      "text": "On July 4, 1776, the American Declaration of Independence was adopted, heavily influenced by Enlightenment ideas of liberty, equality, and democracy.",
      "date": "1776-07-04"
    },
    {
      "headline": "Publication of 'Critique of Pure Reason'",
      "text": "Immanuel Kant published 'Critique of Pure Reason' in 1781, a critical work in philosophy that sought to reconcile rationalism and empiricism, marking a significant development in Enlightenment thought.",
      "date": "1781"
    },
    {
      "headline": "French Revolution",
      "text": "The French Revolution began in 1789, driven by Enlightenment ideals of liberty, equality, and fraternity, leading to significant political and social changes in France and Europe.",
      "date": "1789"
    },
    {
      "headline": "End of the Age of Enlightenment",
      "text": "The Age of Enlightenment is generally considered to have ended in the late 18th century, around the 1780s to 1790s, as Romanticism began to emerge as the dominant intellectual movement.",
      "date": "1790"
    }
  ]
}

