    {
      "headline": "Road Signs Erected",
      "text": "In 1927, road signs for U.S. Route 66 were erected, marking the highway's official presence across the United States.",
      "date": "1927"
    },
    {
      "headline": "Route 66 Gains Popularity",
      "text": "During the 1930s, U.S. Route 66 gained popularity as a major path for those migrating west, especially during the Dust Bowl.",
      "date": "1930"
    },
    {
      "headline": "Route 66 Paved",
      "text": "By 1938, U.S. Route 66 became the first highway to be completely paved, enhancing its accessibility and popularity.",
      "date": "1938"
    },
    {
      "headline": "World War II Impact",
      "text": "During World War II, U.S. Route 66 served as a major military route, facilitating the movement of troops and materials.",
      "date": "1940"
