    {
      "headline": "Post-War Tourism Boom",
      "text": "In the post-war era of the 1950s, Route 66 experienced a tourism boom, becoming a symbol of freedom and adventure.",
      "date": "1950"
    },
    {
      "headline": "Interstate Highway System",
      "text": "The Federal Aid Highway Act of 1956 led to the development of the Interstate Highway System, which began to replace U.S. Route 66.",
      "date": "1956"
