{
  "timeline": [
    {
      "headline": "Beginning of the Rebellion",
      "text": "The Indian Rebellion of 1857 began on 10 May 1857 in Meerut when sepoys of the British East India Company's army mutinied.",
      "date": "1857-05-10"
    },
    {
      "headline": "Capture of Delhi",
      "text": "On 11 May 1857, the mutineers reached Delhi, where they were joined by other rebels and declared Bahadur Shah II as the Emperor of Hindustan.",
      "date": "1857-05-11"
    },
    {
      "headline": "Siege of Cawnpore",
      "text": "The Siege of Cawnpore began in June 1857, where British forces and civilians were besieged by rebel forces led by Nana Sahib.",
      "date": "1857-06"
    },
    {
      "headline": "Fall of Delhi",
      "text": "British forces recaptured Delhi on 21 September 1857 after a prolonged siege.",
      "date": "1857-09-21"
    },
    {
      "headline": "Relief of Lucknow",
      "text": "The British forces relieved the Siege of Lucknow on 25 September 1857, providing much-needed support to the besieged British residents.",
      "date": "1857-09-25"
    },
    {
      "headline": "Capture of Jhansi",
      "text": "The British recaptured Jhansi on 3 April 1858, after a fierce battle against Rani Lakshmibai and her forces.",
      "date": "1858-04-03"
    },
    {
      "headline": "Battle of Gwalior",
      "text": "The decisive Battle of Gwalior took place on 20 June 1858, leading to the defeat of the rebel forces.",
      "date": "1858-06-20"
    },
    {
      "headline": "Proclamation of Amnesty",
      "text": "On 1 November 1858, the British government proclaimed an amnesty to all rebels not involved in murder.",
      "date": "1858-11-01"
    },
    {
      "headline": "Formal End of Hostilities",
      "text": "The British formally declared the end of hostilities on 8 July 1859, marking the official conclusion of the rebellion.",
      "date": "1859-07-08"
    }
  ]
}

