{
  "timeline": [
    {
      "headline": "Foundation of the House of Habsburg",
      "text": "The House of Habsburg was founded in the 11th century, with its origins traced back to the Habsburg Castle in present-day Switzerland.",
      "date": "1000"
    },
    {
      "headline": "Rudolf I becomes King of Germany",
      "text": "In 1273, Rudolf I of Habsburg was elected King of Germany, marking the rise of the Habsburgs to prominence in European politics.",
      "date": "1273"
    },
    {
      "headline": "Acquisition of Austria",
      "text": "In 1278, Rudolf I defeated Ottokar II of Bohemia at the Battle of Marchfeld and acquired the Duchy of Austria, establishing Habsburg rule in the region.",
      "date": "1278"
    },
    {
      "headline": "Habsburgs become Holy Roman Emperors",
      "text": "In 1438, Albert II of Habsburg was elected as the Holy Roman Emperor, beginning a long tradition of Habsburg emperors.",
      "date": "1438"
    },
    {
      "headline": "Marriage of Maximilian I and Mary of Burgundy",
      "text": "In 1477, Maximilian I of Habsburg married Mary of Burgundy, bringing the wealthy Burgundian territories into the Habsburg domain.",
      "date": "1477"
    },
    {
      "headline": "Charles V becomes Holy Roman Emperor",
      "text": "In 1519, Charles V of Habsburg was elected Holy Roman Emperor, ruling over an empire where 'the sun never set'.",
      "date": "1519"
    },
    {
      "headline": "Division of the Habsburg Empire",
      "text": "In 1556, Charles V abdicated, leading to the division of the Habsburg Empire between the Spanish and Austrian branches.",
      "date": "1556"
    },
    {
      "headline": "End of the Spanish Habsburgs",
      "text": "In 1700, the Spanish Habsburg line ended with the death of Charles II, leading to the War of the Spanish Succession.",
      "date": "1700"
    },
    {
      "headline": "End of the Austrian Habsburgs",
      "text": "In 1780, the Austrian Habsburg line ended with the death of Maria Theresa, leading to the rise of the House of Habsburg-Lorraine.",
      "date": "1780"
    },
    {
      "headline": "Dissolution of the Holy Roman Empire",
      "text": "In 1806, Francis II dissolved the Holy Roman Empire following defeat by Napoleon, marking the end of Habsburg rule over the empire.",
      "date": "1806"
    },
    {
      "headline": "Austro-Hungarian Compromise",
      "text": "In 1867, the Austro-Hungarian Compromise established the Dual Monarchy of Austria-Hungary under Habsburg rule.",
      "date": "1867"
    },
    {
      "headline": "End of Habsburg Monarchy",
      "text": "In 1918, following World War I, the Austro-Hungarian Empire collapsed, ending Habsburg rule.",
      "date": "1918"
    }
  ]
}

