    {
      "headline": "Establishment of Democratic Kampuchea",
      "text": "In 1976, the Khmer Rouge established Democratic Kampuchea, with Pol Pot as the de facto leader, implementing radical policies that led to mass atrocities.",
      "date": "1976"
    },
    {
      "headline": "Vietnamese Invasion and Fall of the Khmer Rouge",
      "text": "On January 7, 1979, Vietnamese forces captured Phnom Penh, leading to the fall of the Khmer Rouge regime and the establishment of the People's Republic of Kampuchea.",
      "date": "1979-01-07"
    },
    {
      "headline": "Khmer Rouge Guerrilla Warfare",
      "text": "After their fall from power, the Khmer Rouge retreated to the jungles and continued to wage a guerrilla war against the Vietnamese-backed government throughout the 1980s and 1990s.",
      "date": "1980"
    },
    {
      "headline": "Dissolution of the Khmer Rouge",
