{
  "timeline": [
    {
      "headline": "Ancient Bengal",
      "text": "The region of Bengal, which includes present-day West Bengal, has a history dating back to the Vedic period. It was part of several ancient kingdoms, including the Maurya and Gupta Empires.",
      "date": "-0326"
    },
    {
      "headline": "Pala Empire",
      "text": "The Pala Empire, which originated in Bengal, was a major power in the Indian subcontinent from the 8th to the 12th century. It was known for its patronage of Buddhism.",
      "date": "0750"
    },
    {
      "headline": "Sena Dynasty",
      "text": "The Sena dynasty ruled Bengal from the 11th to the 12th century, known for establishing Hinduism as the state religion and promoting Sanskrit literature.",
      "date": "1070"
    },
    {
      "headline": "Muslim Rule",
      "text": "Bengal came under Muslim rule in the 13th century with the establishment of the Bengal Sultanate, which lasted until the Mughal conquest in the 16th century.",
      "date": "1204"
    },
    {
      "headline": "Mughal Empire",
      "text": "The Mughal Empire controlled Bengal from the 16th to the 18th century, during which time the region became a major center for trade and commerce.",
      "date": "1576"
    },
    {
      "headline": "British East India Company",
      "text": "The British East India Company gained control of Bengal after the Battle of Plassey in 1757, marking the beginning of British colonial rule in India.",
      "date": "1757-06-23"
    },
    {
      "headline": "Partition of Bengal",
      "text": "In 1905, the British partitioned Bengal into two provinces, East Bengal and West Bengal, to weaken the nationalist movement. The partition was annulled in 1911 due to widespread protests.",
      "date": "1905"
    },
    {
      "headline": "Independence and Partition of India",
      "text": "In 1947, India gained independence from British rule, and Bengal was partitioned into West Bengal (India) and East Bengal (Pakistan, later Bangladesh).",
      "date": "1947-08-15"
    },
    {
      "headline": "Formation of West Bengal",
      "text": "West Bengal was formed as a state of India in 1947, with Kolkata as its capital.",
      "date": "1947-08-15"
    },
    {
      "headline": "Naxalite Movement",
      "text": "The Naxalite movement, a radical communist movement, began in West Bengal in the late 1960s, leading to significant political and social upheaval.",
      "date": "1967"
    },
    {
      "headline": "Left Front Government",
      "text": "The Left Front, led by the Communist Party of India (Marxist), came to power in West Bengal in 1977 and ruled the state for 34 years until 2011.",
      "date": "1977"
    },
    {
      "headline": "Trinamool Congress Government",
      "text": "The All India Trinamool Congress, led by Mamata Banerjee, won the state elections in 2011, ending the Left Front's long rule.",
      "date": "2011"
    }
  ]
}

