    {
      "headline": "Establishment of Fort Frontenac",
      "text": "In 1673, Fort Frontenac was established by the French at the site of present-day Kingston, Ontario.",
      "date": "1673"
    },
    {
      "headline": "Treaty of Paris",
      "text": "In 1763, the Treaty of Paris ended the Seven Years' War, and France ceded its territories in Canada, including Ontario, to Britain.",
      "date": "1763"
    },
    {
      "headline": "Creation of Upper Canada",
      "text": "In 1791, the Constitutional Act divided the Province of Quebec into Upper Canada (now Ontario) and Lower Canada (now Quebec).",
      "date": "1791"
    },
    {
      "headline": "War of 1812",
      "text": "From 1812 to 1815, the War of 1812 took place, involving battles in Ontario between British and American forces.",
      "date": "1812"
    },
    {
      "headline": "Rebellions of 1837",
      "text": "In 1837, the Rebellions of 1837 occurred, with uprisings in Upper Canada against the British colonial government.",
      "date": "1837"
    },
    {
      "headline": "Act of Union",
      "text": "In 1841, the Act of Union merged Upper and Lower Canada into the Province of Canada, with Ontario becoming Canada West.",
      "date": "1841"
    },
    {
      "headline": "Confederation of Canada",
      "text": "On July 1, 1867, Ontario became one of the four original provinces of the Dominion of Canada.",
      "date": "1867-07-01"
    },
    {
      "headline": "Establishment of Ottawa as Capital",
      "text": "In 1867, Ottawa was established as the capital of Canada, located in Ontario.",
      "date": "1867"
    },
    {
      "headline": "Toronto Becomes Provincial Capital",
      "text": "In 1867, Toronto was designated as the provincial capital of Ontario.",
      "date": "1867"
