      "headline": "Start of the Mumbai Attacks",
      "text": "On 26 November 2008, the Mumbai attacks began when 10 members of the terrorist organization Lashkar-e-Taiba carried out coordinated shooting and bombing attacks across Mumbai.",
      "date": "2008-11-26"
    },
    {
      "headline": "Attack on Chhatrapati Shivaji Maharaj Terminus",
      "text": "On 26 November 2008, two attackers opened fire at the Chhatrapati Shivaji Maharaj Terminus railway station, killing 58 people and injuring over 100.",
      "date": "2008-11-26"
    },
    {
      "headline": "Siege at the Taj Mahal Palace Hotel",
      "text": "On 26 November 2008, attackers entered the Taj Mahal Palace Hotel, taking hostages and setting parts of the building on fire. The siege lasted until 29 November 2008.",
      "date": "2008-11-26"
    },
    {
      "headline": "Attack on Leopold Cafe",
      "text": "On 26 November 2008, gunmen attacked the popular Leopold Cafe, killing 10 people and injuring many others.",
      "date": "2008-11-26"
    },
    {
      "headline": "Attack on Nariman House",
      "text": "On 26 November 2008, attackers took hostages at the Nariman House, a Jewish community center, leading to a prolonged siege.",
      "date": "2008-11-26"
    },
    {
      "headline": "Oberoi Trident Hotel Attack",
      "text": "On 26 November 2008, attackers entered the Oberoi Trident Hotel, taking hostages and killing several people. The siege ended on 28 November 2008.",
      "date": "2008-11-26"
    },
    {
      "headline": "End of the Taj Mahal Palace Hotel Siege",
      "text": "On 29 November 2008, Indian security forces regained control of the Taj Mahal Palace Hotel, ending the siege and killing the last remaining attackers.",
      "date": "2008-11-29"
    },
    {
      "headline": "End of the Nariman House Siege",
      "text": "On 28 November 2008, Indian commandos stormed Nariman House, killing the attackers and rescuing hostages, although some hostages had already been killed.",
      "date": "2008-11-28"
    },
    {
      "headline": "Capture of Ajmal Kasab",
      "text": "On 26 November 2008, Ajmal Kasab, one of the attackers, was captured alive by Indian police, providing crucial information about the attacks.",
      "date": "2008-11-26"
    },
    {
      "headline": "End of the Mumbai Attacks",
      "text": "On 29 November 2008, the Mumbai attacks officially ended after Indian security forces neutralized the attackers and secured all affected locations.",
      "date": "2008-11-29"
    }
  ]
}

