{
  "timeline": [
    {
      "headline": "Origin of Latin",
      "text": "Latin originated as the language of the Latins, an Italic tribe in the region of Latium, around the lower Tiber River in Italy. The earliest known inscriptions in Latin date back to the 7th century BCE.",
      "date": "-0700"
    },
    {
      "headline": "Expansion of Latin through Roman Republic",
      "text": "As the Roman Republic expanded its territory, Latin spread throughout the Italian Peninsula and became the dominant language. This expansion began in the early centuries of the Republic, around the 5th century BCE.",
      "date": "-0500"
    },
    {
      "headline": "Latin as the Official Language of the Roman Empire",
      "text": "Latin became the official language of the Roman Empire, facilitating administration and communication across vast territories. This was solidified during the late Republic and early Empire periods, around the 1st century BCE.",
      "date": "-0027"
    },
    {
      "headline": "Classical Latin Period",
      "text": "The Classical Latin period, marked by the works of authors such as Cicero, Virgil, and Ovid, spanned from the late Republic to the early Empire, approximately from 75 BCE to 200 CE.",
      "date": "-0075"
    },
    {
      "headline": "Vulgar Latin and the Fall of the Western Roman Empire",
      "text": "After the fall of the Western Roman Empire in 476 CE, Latin evolved into various regional dialects known as Vulgar Latin, which eventually developed into the Romance languages.",
      "date": "0476"
    },
    {
      "headline": "Medieval Latin",
      "text": "During the Middle Ages, Latin remained the language of scholarship, science, and the Catholic Church. This period lasted from the 5th century to the Renaissance, around the 15th century.",
      "date": "0500"
    },
    {
      "headline": "Renaissance and the Revival of Classical Latin",
      "text": "The Renaissance saw a revival of interest in Classical Latin, with scholars and writers striving to emulate the language of ancient Rome. This movement began in the 14th century and continued into the 17th century.",
      "date": "1400"
    },
    {
      "headline": "Latin as a Liturgical Language",
      "text": "Latin continues to be used as the liturgical language of the Roman Catholic Church, maintaining its significance in religious contexts.",
      "date": "2023"
    }
  ]
}

