      "headline": "Establishment as a Military Fort",
      "text": "Kowloon Walled City was originally established as a military fort by the Qing dynasty to manage the salt trade and defend against pirates.",
      "date": "-1847"
    },
    {
      "headline": "Convention for the Extension of Hong Kong Territory",
      "text": "In 1898, the Convention for the Extension of Hong Kong Territory was signed, leasing the New Territories to the United Kingdom for 99 years. The Walled City was not mentioned in the lease, leading to its ambiguous status.",
      "date": "1898"
    },
    {
      "headline": "Japanese Occupation of Hong Kong",
      "text": "During World War II, from 1941 to 1945, the Japanese occupied Hong Kong, including the Kowloon Walled City.",
      "date": "1941"
    },
    {
      "headline": "Post-War Population Surge",
      "text": "After the end of the Japanese occupation in 1945, the population of Kowloon Walled City surged as refugees from the Chinese Civil War sought shelter.",
      "date": "1945"
    },
    {
      "headline": "Demolition of the City Walls",
      "text": "In 1948, the British colonial government attempted to demolish the city walls, but the plan was largely unsuccessful due to resistance from residents.",
      "date": "1948"
    },
    {
      "headline": "Peak Population Density",
      "text": "By the 1950s and 1960s, Kowloon Walled City became known for its extremely high population density and lack of government oversight, with an estimated population of 30,000 people living in 6.4 acres.",
      "date": "1960"
    },
    {
      "headline": "Joint Declaration on the Future of Hong Kong",
      "text": "In 1984, the Sino-British Joint Declaration was signed, setting the stage for the eventual handover of Hong Kong to China and influencing the decision to clear the Walled City.",
      "date": "1984"
    },
    {
      "headline": "Announcement of Demolition",
      "text": "In 1987, the Hong Kong government announced plans to demolish the Kowloon Walled City, citing health and safety concerns.",
      "date": "1987"
    },
    {
      "headline": "Demolition and Redevelopment",
      "text": "Demolition of the Kowloon Walled City began in 1993 and was completed in 1994. The site was redeveloped into Kowloon Walled City Park.",
      "date": "1993"
    }
  ]
}

