{
  "timeline": [
    {
      "headline": "First European Settlement",
      "text": "In 1510, the first permanent European settlement in Panama was established by the Spanish at Santa María la Antigua del Darién.",
      "date": "1510"
    },
    {
      "headline": "Vasco Núñez de Balboa Crosses the Isthmus",
      "text": "On September 25, 1513, Vasco Núñez de Balboa became the first European to see the Pacific Ocean from the New World after crossing the Isthmus of Panama.",
      "date": "1513-09-25"
    },
    {
      "headline": "Founding of Panama City",
      "text": "Panama City was founded on August 15, 1519, by Spanish conquistador Pedro Arias Dávila.",
      "date": "1519-08-15"
    },
    {
      "headline": "Destruction of Old Panama City",
      "text": "In 1671, the original Panama City was destroyed by the pirate Henry Morgan.",
      "date": "1671"
    },
    {
      "headline": "Construction of the Panama Canal Begins",
      "text": "The construction of the Panama Canal began in 1881 under French leadership.",
      "date": "1881"
    },
    {
      "headline": "Panama Declares Independence from Colombia",
      "text": "On November 3, 1903, Panama declared its independence from Colombia with the support of the United States.",
      "date": "1903-11-03"
    },
    {
      "headline": "Completion of the Panama Canal",
      "text": "The Panama Canal was officially completed and opened on August 15, 1914.",
      "date": "1914-08-15"
    },
    {
      "headline": "Torrijos-Carter Treaties Signed",
      "text": "On September 7, 1977, the Torrijos-Carter Treaties were signed, agreeing to transfer control of the Panama Canal from the United States to Panama by the end of the 20th century.",
      "date": "1977-09-07"
    },
    {
      "headline": "U.S. Invasion of Panama",
      "text": "The United States invaded Panama on December 20, 1989, in an operation known as Operation Just Cause, to depose Panamanian leader Manuel Noriega.",
      "date": "1989-12-20"
    },
    {
