  "timeline": [
    {
      "headline": "First Recorded Appearance",
      "text": "The first known recorded appearance of Halley's Comet was in 240 BCE, as noted in Chinese historical texts.",
      "date": "-0240"
    },
    {
      "headline": "Appearance in 1066",
      "text": "Halley's Comet appeared in 1066 and was depicted in the Bayeux Tapestry, which commemorates the Norman Conquest of England.",
      "date": "1066"
    },
    {
      "headline": "Edmond Halley's Prediction",
      "text": "In 1705, Edmond Halley used Newton's laws of motion to calculate that the comet would return in 1758. This was the first prediction of a comet's return.",
      "date": "1705"
    },
    {
      "headline": "Return in 1758",
      "text": "Halley's Comet returned as predicted by Edmond Halley, confirming his calculations and marking the first time a comet's return was successfully predicted.",
      "date": "1758"
    },
    {
      "headline": "Appearance in 1835",
      "text": "The comet appeared in 1835, during which time it was observed by astronomers around the world.",
      "date": "1835"
    },
    {
      "headline": "Appearance in 1910",
      "text": "Halley's Comet made a particularly bright appearance in 1910, passing close to Earth and causing widespread public interest.",
      "date": "1910"
    },
    {
      "headline": "Appearance in 1986",
      "text": "In 1986, Halley's Comet was visited by several spacecraft, including ESA's Giotto, marking the first time a comet was closely studied by spacecraft.",
      "date": "1986"
    },
    {
      "headline": "Next Predicted Appearance",
      "text": "Halley's Comet is predicted to next appear in the inner parts of the Solar System in mid-2061.",
      "date": "2061"
    }
  ]
}

