{
  "timeline": [
    {
      "headline": "Initial Conception",
      "text": "The idea of a canal across the Isthmus of Panama dates back to the early 16th century when Vasco Núñez de Balboa first crossed the isthmus in 1513.",
      "date": "1513"
    },
    {
      "headline": "First Attempt by the French",
      "text": "The first attempt to construct a canal was made by the French under the leadership of Ferdinand de Lesseps, who began work in 1881. However, the project was plagued by engineering problems and a high worker mortality rate due to disease.",
      "date": "1881"
    },
    {
      "headline": "French Abandonment",
      "text": "The French effort to build the canal was abandoned in 1889 after spending nearly $287 million and losing an estimated 22,000 workers to accidents and disease.",
      "date": "1889"
    },
    {
      "headline": "U.S. Acquisition",
      "text": "The United States acquired the rights to build the canal from the French in 1904, following the Hay-Bunau-Varilla Treaty with Panama.",
      "date": "1904"
    },
    {
      "headline": "Construction Under U.S. Control",
      "text": "Construction of the canal under U.S. control began in earnest in 1904, with significant improvements in engineering and health measures, including the control of malaria and yellow fever.",
      "date": "1904"
    },
    {
      "headline": "Completion of the Canal",
      "text": "The Panama Canal was officially completed and opened on August 15, 1914, with the passage of the cargo ship SS Ancon.",
      "date": "1914-08-15"
    },
    {
      "headline": "Panama Canal Treaties",
      "text": "The Torrijos-Carter Treaties were signed in 1977, agreeing to transfer control of the canal from the United States to Panama by the end of the 20th century.",
      "date": "1977"
    },
    {
      "headline": "Transfer to Panama",
      "text": "Control of the Panama Canal was officially transferred from the United States to Panama on December 31, 1999.",
      "date": "1999-12-31"
    },
    {
      "headline": "Expansion Project",
      "text": "The Panama Canal Expansion Project, also known as the Third Set of Locks Project, was completed on June 26, 2016, allowing larger ships to pass through the canal.",
      "date": "2016-06-26"
    }
  ]
}

{
  "timeline": [
    {
      "headline": "Foundational Beginnings",
      "text": "Critical race theory (CRT) began to take shape in the mid-1970s as a movement in the legal academy, spearheaded by scholars such as Derrick Bell, Kimberlé Crenshaw, and Richard Delgado. It emerged as a response to perceived shortcomings in the civil rights movement and critical legal studies.",
      "date": "1970"
    },
    {
      "headline": "First CRT Workshop",
      "text": "In 1989, the first workshop on critical race theory was held, marking a significant moment in the formalization of CRT as an academic movement.",
      "date": "1989"
    },
    {
      "headline": "Introduction of Intersectionality",
      "text": "Kimberlé Crenshaw introduced the concept of intersectionality in 1989, which became a foundational aspect of CRT. Intersectionality examines how various social identities such as race, gender, and class intersect to create unique modes of discrimination.",
      "date": "1989"
    },
    {
      "headline": "Expansion into Education",
      "text": "During the 1990s, CRT expanded beyond the legal field into education, influencing how race and racism were studied and understood in educational contexts.",
      "date": "1990"
    },
    {
      "headline": "Publication of 'Critical Race Theory: The Key Writings That Formed the Movement'",
      "text": "In 1995, Kimberlé Crenshaw, Neil Gotanda, Gary Peller, and Kendall Thomas published 'Critical Race Theory: The Key Writings That Formed the Movement,' a seminal text that compiled foundational CRT writings.",
      "date": "1995"
    },
    {
      "headline": "Development of LatCrit",
      "text": "LatCrit, or Latino Critical Race Theory, emerged in the mid-1990s as a branch of CRT focusing on issues specific to the Latino community.",
      "date": "1995"
    },
    {
      "headline": "Influence on Public Policy and Debate",
      "text": "In the 2000s and 2010s, CRT began influencing public policy and debate, particularly around issues of racial inequality, affirmative action, and systemic racism.",
      "date": "2000"
    },
    {
      "headline": "Controversy and Political Debate",
      "text": "In the 2020s, CRT became a focal point of political debate in the United States, with discussions around its role in education and its portrayal in media and politics.",
      "date": "2020"
    }
  ]
}

