{
  "timeline": [
    {
      "headline": "Incident at Drexel Building",
      "text": "On May 30, 1921, a young Black teenager named Dick Rowland was accused of assaulting a white woman, Sarah Page, in an elevator of the Drexel Building in Tulsa, Oklahoma.",
      "date": "1921-05-30"
    },
    {
      "headline": "Arrest of Dick Rowland",
      "text": "On May 31, 1921, Dick Rowland was arrested and taken to the courthouse. Rumors of a lynching spread throughout the city.",
      "date": "1921-05-31"
    },
    {
      "headline": "Confrontation at the Courthouse",
      "text": "On the evening of May 31, 1921, a group of Black men, including World War I veterans, went to the courthouse to protect Rowland from a rumored lynching. A confrontation ensued between them and a larger group of white men.",
      "date": "1921-05-31"
    },
    {
      "headline": "Outbreak of Violence",
      "text": "Violence broke out late on May 31, 1921, when shots were fired during the confrontation at the courthouse, leading to widespread chaos.",
      "date": "1921-05-31"
    },
    {
      "headline": "Destruction of Greenwood District",
      "text": "From May 31 to June 1, 1921, white mobs attacked the Greenwood District, looting and burning homes and businesses over 35 square blocks, known as 'Black Wall Street.'",
      "date": "1921-06-01"
    },
    {
      "headline": "Martial Law Declared",
      "text": "On June 1, 1921, martial law was declared, and the National Guard was deployed to restore order in Tulsa.",
      "date": "1921-06-01"
    },
    {
      "headline": "End of the Massacre",
      "text": "By June 1, 1921, the violence had subsided, leaving hundreds of Black residents dead and thousands homeless.",
      "date": "1921-06-01"
    },
    {
      "headline": "Aftermath and Rebuilding",
      "text": "In the aftermath, the Black community of Greenwood began to rebuild, despite facing significant challenges and lack of support from the city and insurance companies.",
      "date": "1921"
    }
  ]
}

