{
  "timeline": [
    {
      "headline": "Ancient Roman Traffic",
      "text": "In Ancient Rome, evidence suggests that traffic kept to the left. This is inferred from the discovery of a Roman quarry in Swindon, England, where wear patterns indicate that carts were driven on the left side of the road.",
      "date": "-0050"
    },
    {
      "headline": "Napoleon's Influence",
      "text": "Napoleon Bonaparte's conquests in Europe led to the spread of right-hand traffic (RHT) in the early 19th century. Countries conquered by Napoleon adopted RHT, which was already in use in France.",
      "date": "1800"
    },
    {
      "headline": "United Kingdom's Left-Hand Traffic",
      "text": "The United Kingdom formally established left-hand traffic (LHT) with the Highway Act of 1835, which mandated that traffic keep to the left.",
      "date": "1835"
    },
    {
      "headline": "Japan Adopts Left-Hand Traffic",
      "text": "Japan adopted left-hand traffic in 1872, influenced by British engineers involved in the construction of the country's first railway.",
      "date": "1872"
    },
    {
      "headline": "Sweden's 'Dagen H'",
      "text": "On September 3, 1967, Sweden switched from left-hand traffic to right-hand traffic in a massive operation known as 'Dagen H' (H Day).",
      "date": "1967-09-03"
    },
    {
      "headline": "Samoa Switches to Left-Hand Traffic",
      "text": "On September 7, 2009, Samoa switched from right-hand traffic to left-hand traffic to align with other countries in the region and facilitate the import of cheaper vehicles from Australia and New Zealand.",
      "date": "2009-09-07"
    }
  ]
}

