  "timeline": [
    {
      "headline": "Manufacture of the Demon Core",
      "text": "The Demon Core was manufactured in 1945 by the Manhattan Project as part of the U.S. nuclear weapon development effort during World War II. It was a subcritical mass of plutonium that weighed 6.2 kilograms and was 8.9 centimeters in diameter.",
      "date": "1945"
    },
    {
      "headline": "Preparation for Shipment",
      "text": "The core was prepared for shipment to the Pacific Theater as part of the third nuclear weapon to be dropped on Japan. However, the plan was halted when Japan surrendered in August 1945.",
      "date": "1945-08"
    },
    {
      "headline": "First Criticality Accident",
      "text": "On August 21, 1945, physicist Harry Daghlian accidentally dropped a tungsten carbide brick onto the core, causing a criticality accident. Daghlian received a lethal dose of radiation and died 25 days later.",
      "date": "1945-08-21"
    },
    {
      "headline": "Second Criticality Accident",
      "text": "On May 21, 1946, physicist Louis Slotin accidentally caused another criticality accident while performing an experiment with the core. Slotin received a fatal dose of radiation and died nine days later.",
      "date": "1946-05-21"
    },
