    {
      "headline": "First Use of the Term 'Multiple Personality Disorder'",
      "text": "The term 'multiple personality disorder' was first used in the early 20th century to describe the condition now known as dissociative identity disorder.",
      "date": "1900"
    },
    {
      "headline": "DSM-III Inclusion",
      "text": "In 1980, the third edition of the Diagnostic and Statistical Manual of Mental Disorders (DSM-III) included multiple personality disorder as a diagnosable condition.",
      "date": "1980"
    },
    {
      "headline": "Name Change to Dissociative Identity Disorder",
      "text": "In 1994, the DSM-IV was published, and the disorder was renamed from multiple personality disorder to dissociative identity disorder to better reflect the understanding of the condition.",
      "date": "1994"
    },
    {
      "headline": "Inclusion in DSM-5",
      "text": "Dissociative identity disorder was included in the DSM-5, published in 2013, with updated criteria for diagnosis.",
      "date": "2013"
    },
    {
      "headline": "Inclusion in ICD-11",
      "text": "The International Classification of Diseases, 11th Revision (ICD-11), published by the World Health Organization, includes dissociative identity disorder, reflecting its recognition as a mental health condition.",
      "date": "2018"
    }
  ]
}

