{
  "timeline": [
    {
      "headline": "First Nations Settlement",
      "text": "Indigenous peoples have lived in the area now known as British Columbia for thousands of years, with diverse cultures and languages.",
      "date": "-10000"
    },
    {
      "headline": "European Exploration",
      "text": "In 1778, British explorer Captain James Cook arrived at Nootka Sound on Vancouver Island, marking the first known European contact with the region.",
      "date": "1778"
    },
    {
      "headline": "Nootka Crisis",
      "text": "The Nootka Crisis (1789-1794) was a dispute between Spain and Britain over territories on the Pacific Northwest coast, including parts of present-day British Columbia.",
      "date": "1789"
    },
    {
      "headline": "Establishment of Fort Vancouver",
      "text": "In 1825, the Hudson's Bay Company established Fort Vancouver on the Columbia River, which became a major center for the fur trade.",
      "date": "1825"
    },
    {
      "headline": "Oregon Treaty",
      "text": "The Oregon Treaty of 1846 established the 49th parallel as the boundary between British North America and the United States, affecting the territory of British Columbia.",
      "date": "1846"
    },
    {
      "headline": "Colony of Vancouver Island",
      "text": "In 1849, the Colony of Vancouver Island was established by the British government.",
      "date": "1849"
    },
    {
      "headline": "Colony of British Columbia",
      "text": "The Colony of British Columbia was established in 1858 following the Fraser River Gold Rush.",
      "date": "1858"
    },
    {
      "headline": "Union of Colonies",
      "text": "In 1866, the colonies of Vancouver Island and British Columbia were united into a single colony.",
      "date": "1866"
    },
    {
      "headline": "Confederation with Canada",
      "text": "British Columbia joined the Canadian Confederation on July 20, 1871, becoming the sixth province of Canada.",
      "date": "1871-07-20"
    },
    {
      "headline": "Completion of the Canadian Pacific Railway",
      "text": "In 1885, the Canadian Pacific Railway was completed, linking British Columbia to the rest of Canada and facilitating economic growth.",
      "date": "1885"
    },
    {
      "headline": "Vancouver Incorporation",
      "text": "The city of Vancouver was incorporated on April 6, 1886, and quickly grew to become the largest city in British Columbia.",
      "date": "1886-04-06"
    },
    {
      "headline": "Expo 86",
      "text": "In 1986, Vancouver hosted the World's Fair, known as Expo 86, which celebrated the city's centennial and showcased technological advancements.",
      "date": "1986"
    },
    {
      "headline": "2010 Winter Olympics",
      "text": "Vancouver and Whistler hosted the 2010 Winter Olympics, bringing international attention and development to the region.",
      "date": "2010"
    }
  ]
}

