    },
    {
      "headline": "Civil War and Secession",
      "text": "In 1861, Louisiana seceded from the Union and joined the Confederate States of America.",
      "date": "1861"
    },
    {
      "headline": "Re-admittance to the Union",
      "text": "In 1868, Louisiana was readmitted to the United States after the Civil War.",
      "date": "1868"
