{
  "timeline": [
    {
      "headline": "Matsya Avatar",
      "text": "In Hindu mythology, Matsya is the first avatar of Vishnu, appearing as a fish. This avatar is said to have saved the sacred texts, the Vedas, from a great deluge. The story is mentioned in several Hindu texts, including the Shatapatha Brahmana and the Puranas.",
      "date": "-3000"
    },
    {
      "headline": "Kurma Avatar",
      "text": "Kurma is the second avatar of Vishnu, depicted as a tortoise. In this form, Vishnu supported Mount Mandara, which was used as a churning rod to churn the ocean of milk during the Samudra Manthan, a pivotal event in Hindu mythology.",
      "date": "-3000"
    },
    {
      "headline": "Varaha Avatar",
      "text": "Varaha is the third avatar of Vishnu, depicted as a boar. In this form, Vishnu rescued the Earth (personified as the goddess Bhudevi) from the demon Hiranyaksha, who had submerged it in the primordial waters.",
      "date": "-3000"
    },
    {
      "headline": "Narasimha Avatar",
      "text": "Narasimha is the fourth avatar of Vishnu, depicted as a half-man, half-lion. This avatar was taken to protect his devotee Prahlada and to destroy the demon king Hiranyakashipu, who was immune to being killed by man or beast.",
      "date": "-3000"
    },
    {
      "headline": "Vamana Avatar",
      "text": "Vamana is the fifth avatar of Vishnu, depicted as a dwarf Brahmin. In this form, Vishnu subdued the demon king Bali by asking for three paces of land and then expanding to cover the entire universe in three steps.",
      "date": "-3000"
    },
    {
      "headline": "Parashurama Avatar",
      "text": "Parashurama is the sixth avatar of Vishnu, depicted as a Brahmin warrior with an axe. He is known for ridding the world of corrupt Kshatriyas (warrior class) twenty-one times and for his role in several Hindu epics.",
      "date": "-3000"
    },
    {
      "headline": "Rama Avatar",
      "text": "Rama is the seventh avatar of Vishnu, the protagonist of the Hindu epic Ramayana. He is known for his adherence to dharma and his role in defeating the demon king Ravana.",
      "date": "-3000"
    },
    {
      "headline": "Krishna Avatar",
      "text": "Krishna is the eighth avatar of Vishnu, a central figure in the Mahabharata and the Bhagavad Gita. He is known for his teachings on dharma and devotion, and for his role in the Kurukshetra War.",
      "date": "-3000"
    },
    {
      "headline": "Buddha Avatar",
      "text": "In some traditions, Buddha is considered the ninth avatar of Vishnu. This avatar is said to have appeared to teach compassion and non-violence, and to reform the Vedic rituals.",
      "date": "-3000"
    },
    {
      "headline": "Kalki Avatar",
      "text": "Kalki is the tenth and future avatar of Vishnu, who is prophesied to appear at the end of the current Kali Yuga to destroy the forces of evil and restore dharma.",
      "date": "427000"
    }
  ]
}

