{
  "timeline": [
    {
      "headline": "Construction of the Hanging Gardens",
      "text": "The Hanging Gardens of Babylon are traditionally attributed to King Nebuchadnezzar II, who ruled from 605 to 562 BCE. According to ancient sources, they were built to please his wife, Amytis of Media, who missed the green hills and valleys of her homeland.",
      "date": "-0605"
    },
    {
      "headline": "Description by Ancient Writers",
      "text": "The Hanging Gardens were described by several ancient writers, including Strabo and Philo of Byzantium. They depicted the gardens as an extraordinary feat of engineering with terraces of greenery and complex irrigation systems.",
      "date": "-0300"
    },
    {
      "headline": "Inclusion in the Seven Wonders",
      "text": "The Hanging Gardens were listed as one of the Seven Wonders of the Ancient World by Hellenic culture, highlighting their significance and the awe they inspired in ancient visitors.",
      "date": "-0225"
    },
    {
      "headline": "Debate on Existence",
      "text": "Modern historians and archaeologists debate the actual existence of the Hanging Gardens, as there is no definitive archaeological evidence found in Babylon. Some theories suggest they might have been located in Nineveh instead.",
      "date": "2000"
    }
  ]
}

