      "headline": "Birth of Johann Sebastian Bach",
      "text": "Johann Sebastian Bach was born on March 31, 1685, in Eisenach, in the duchy of Saxe-Eisenach, part of the Holy Roman Empire.",
      "date": "1685-03-31"
    },
    {
      "headline": "Bach's Early Musical Education",
      "text": "In 1695, after the death of both his parents, Bach moved to Ohrdruf to live with his eldest brother, Johann Christoph Bach, who taught him music.",
      "date": "1695"
    },
    {
      "headline": "Bach's First Professional Position",
      "text": "In 1703, Bach was appointed as a court musician in the chapel of Duke Johann Ernst in Weimar.",
      "date": "1703"
    },
    {
      "headline": "Bach's Marriage to Maria Barbara Bach",
      "text": "On October 17, 1707, Bach married his second cousin Maria Barbara Bach in Dornheim.",
      "date": "1707-10-17"
    },
    {
      "headline": "Appointment in Weimar",
      "text": "In 1708, Bach was appointed as an organist and chamber musician to the Duke of Weimar.",
      "date": "1708"
    },
    {
      "headline": "Bach's Move to Köthen",
      "text": "In 1717, Bach became Kapellmeister at the court of Prince Leopold of Anhalt-Köthen.",
      "date": "1717"
    },
    {
      "headline": "Death of Maria Barbara Bach",
      "text": "Bach's first wife, Maria Barbara Bach, died suddenly in 1720 while Bach was away with Prince Leopold.",
      "date": "1720"
    },
    {
      "headline": "Bach's Marriage to Anna Magdalena Wilcke",
      "text": "On December 3, 1721, Bach married Anna Magdalena Wilcke, a young soprano.",
      "date": "1721-12-03"
    },
    {
      "headline": "Bach's Appointment in Leipzig",
      "text": "In 1723, Bach was appointed as Thomaskantor in Leipzig, where he remained for the rest of his life.",
      "date": "1723"
    },
    {
      "headline": "Completion of the St Matthew Passion",
      "text": "Bach completed the St Matthew Passion in 1727, one of his most famous choral works.",
      "date": "1727"
    },
    {
      "headline": "Completion of the Mass in B minor",
      "text": "Bach completed the Mass in B minor in 1749, which is considered one of his greatest choral compositions.",
      "date": "1749"
    },
    {
      "headline": "Death of Johann Sebastian Bach",
      "text": "Johann Sebastian Bach died on July 28, 1750, in Leipzig, after complications from eye surgery.",
      "date": "1750-07-28"
    }
  ]
}

