{
  "timeline": [
    {
      "headline": "Manchester Arena Bombing",
      "text": "On 22 May 2017, a suicide bombing occurred at the Manchester Arena in Manchester, England, following a concert by American pop singer Ariana Grande. The attack was perpetrated by Islamic extremist Salman Abedi, with assistance from his brother Hashem Abedi. The bombing took place at 22:31 and resulted in the deaths of 22 people, injuries to 1,017 others, and significant damage to the arena's foyer. It was the deadliest act of terrorism in the United Kingdom since the 7 July 2005 London bombings.",
      "date": "2017-05-22"
    },
    {
      "headline": "Identification of the Bomber",
      "text": "On 23 May 2017, the bomber was identified as Salman Abedi, a 22-year-old British citizen of Libyan descent.",
      "date": "2017-05-23"
    },
    {
      "headline": "Arrest of Hashem Abedi",
      "text": "Hashem Abedi, the brother of Salman Abedi, was arrested in Libya on 23 May 2017, in connection with the bombing.",
      "date": "2017-05-23"
    },
    {
      "headline": "Ariana Grande's Benefit Concert",
      "text": "On 4 June 2017, Ariana Grande organized and performed at the 'One Love Manchester' benefit concert to raise funds for the victims and families affected by the bombing.",
      "date": "2017-06-04"
    },
    {
      "headline": "Hashem Abedi Extradited to the UK",
      "text": "On 17 July 2019, Hashem Abedi was extradited from Libya to the United Kingdom to face charges related to the bombing.",
      "date": "2019-07-17"
    },
    {
      "headline": "Hashem Abedi Found Guilty",
      "text": "On 17 March 2020, Hashem Abedi was found guilty of 22 counts of murder, attempted murder, and conspiring to cause explosions.",
      "date": "2020-03-17"
    },
    {
      "headline": "Sentencing of Hashem Abedi",
      "text": "On 20 August 2020, Hashem Abedi was sentenced to life imprisonment with a minimum term of 55 years for his role in the Manchester Arena bombing.",
      "date": "2020-08-20"
    }
  ]
}

{
  "timeline": [
    {
      "headline": "Industrial Revolution Begins",
      "text": "The Industrial Revolution, which began in the late 18th century, marks the start of significant human impact on the Earth's climate due to the increased use of fossil fuels.",
      "date": "1760"
    },
    {
      "headline": "First Scientific Prediction of Climate Change",
      "text": "In 1896, Swedish scientist Svante Arrhenius published the first calculation of global warming from human emissions of CO2.",
      "date": "1896"
    },
    {
      "headline": "Keeling Curve Initiated",
      "text": "In 1958, Charles David Keeling began measuring atmospheric CO2 at Mauna Loa Observatory, providing the first significant evidence of rapidly increasing CO2 levels.",
      "date": "1958"
    },
    {
      "headline": "First Earth Day",
      "text": "On April 22, 1970, the first Earth Day was celebrated, raising public awareness about environmental issues, including climate change.",
      "date": "1970-04-22"
    },
    {
      "headline": "Establishment of the Intergovernmental Panel on Climate Change (IPCC)",
      "text": "In 1988, the IPCC was established by the United Nations to assess the science related to climate change.",
      "date": "1988"
    },
    {
      "headline": "Kyoto Protocol Adopted",
      "text": "In 1997, the Kyoto Protocol was adopted, committing its parties to reduce greenhouse gas emissions, based on the premise that global warming exists and human-made CO2 emissions have caused it.",
      "date": "1997"
    },
    {
      "headline": "Paris Agreement Signed",
      "text": "On December 12, 2015, the Paris Agreement was signed by 196 parties, aiming to limit global warming to well below 2 degrees Celsius above pre-industrial levels.",
      "date": "2015-12-12"
    },
    {
      "headline": "Global Climate Strike",
      "text": "In September 2019, millions of people worldwide participated in the Global Climate Strike, demanding action to address climate change.",
      "date": "2019-09"
    }
  ]
}

