{
  "timeline": [
    {
      "headline": "Formation of the Gambino Crime Family",
      "text": "The Gambino crime family was formed in the early 1900s as part of the larger Italian-American Mafia network in New York City. It is one of the 'Five Families' that dominate organized crime activities in the city.",
      "date": "1910"
    },
    {
      "headline": "Leadership of Vincent Mangano",
      "text": "Vincent Mangano became the boss of the family in 1931, leading it until his disappearance in 1951. His leadership marked the family's early years of establishment and expansion.",
      "date": "1931"
    },
    {
      "headline": "Albert Anastasia Takes Over",
      "text": "After the disappearance of Vincent Mangano in 1951, Albert Anastasia took control of the family. Anastasia was known for his violent methods and was a key figure in the Mafia's rise to power.",
      "date": "1951"
    },
    {
      "headline": "Murder of Albert Anastasia",
      "text": "Albert Anastasia was murdered in a barber shop in Manhattan on October 25, 1957. His death led to a power struggle within the family.",
      "date": "1957-10-25"
    },
    {
      "headline": "Carlo Gambino Becomes Boss",
      "text": "Following the murder of Albert Anastasia, Carlo Gambino took over as the boss of the family. Under his leadership, the family became one of the most powerful Mafia organizations in the United States.",
      "date": "1957"
    },
    {
      "headline": "McClellan Hearings",
      "text": "In 1963, the McClellan hearings brought the structure of organized crime, including the Gambino family, to public attention. Carlo Gambino was the boss at this time, and the family was named after him.",
      "date": "1963"
    },
    {
      "headline": "Paul Castellano's Leadership",
      "text": "After Carlo Gambino's death in 1976, Paul Castellano became the boss of the Gambino crime family. His leadership was marked by attempts to modernize the family's operations.",
      "date": "1976"
    },
    {
      "headline": "Assassination of Paul Castellano",
      "text": "Paul Castellano was assassinated on December 16, 1985, outside Sparks Steak House in Manhattan. His murder was orchestrated by John Gotti, who subsequently took over the family.",
      "date": "1985-12-16"
    },
    {
      "headline": "John Gotti's Reign",
      "text": "John Gotti became the boss of the Gambino crime family after the assassination of Paul Castellano. Known as 'The Teflon Don' for his ability to avoid conviction, Gotti's leadership was highly publicized.",
      "date": "1985"
    },
    {
      "headline": "Conviction of John Gotti",
      "text": "John Gotti was convicted of murder and racketeering on April 2, 1992, after being brought down by the testimony of his underboss, Sammy Gravano. This marked a significant blow to the Gambino crime family.",
      "date": "1992-04-02"
    }
  ]
}

