{
  "timeline": [
    {
      "headline": "Portuguese Exploration",
      "text": "In 1462, Portuguese explorer Pedro de Sintra mapped the hills surrounding what is now Freetown Harbour, naming the area Serra Lyoa (Lion Mountains).",
      "date": "1462"
    },
    {
      "headline": "Establishment of Freetown",
      "text": "In 1787, the British established a settlement in Sierra Leone as a home for freed African American, West Indian, and African slaves.",
      "date": "1787"
    },
    {
      "headline": "Sierra Leone Company",
      "text": "In 1792, the Sierra Leone Company was established to administer the colony, and Freetown was founded as the capital.",
      "date": "1792"
    },
    {
      "headline": "Crown Colony",
      "text": "In 1808, Sierra Leone became a British Crown Colony, with Freetown as its capital.",
      "date": "1808"
    },
    {
      "headline": "Abolition of Slave Trade",
      "text": "In 1807, the British Parliament passed the Slave Trade Act, which led to the establishment of Freetown as a base for the British Royal Navy's West Africa Squadron to enforce the abolition of the slave trade.",
      "date": "1807"
    },
    {
      "headline": "Protectorate Established",
      "text": "In 1896, the British declared a protectorate over the hinterland of Sierra Leone, extending their control beyond the coastal colony.",
      "date": "1896"
    },
    {
      "headline": "Independence from Britain",
      "text": "On April 27, 1961, Sierra Leone gained independence from the United Kingdom, with Sir Milton Margai as its first Prime Minister.",
      "date": "1961-04-27"
    },
    {
      "headline": "Republic Declared",
      "text": "On April 19, 1971, Sierra Leone became a republic, with Siaka Stevens as its first President.",
      "date": "1971-04-19"
    },
    {
      "headline": "Civil War Begins",
      "text": "In March 1991, the Sierra Leone Civil War began when the Revolutionary United Front (RUF) launched an insurgency against the government.",
      "date": "1991-03"
    },
    {
      "headline": "Civil War Ends",
      "text": "On January 18, 2002, the Sierra Leone Civil War officially ended, declared by President Ahmad Tejan Kabbah.",
      "date": "2002-01-18"
    },
    {
      "headline": "Ebola Outbreak",
      "text": "In May 2014, Sierra Leone was heavily affected by the West African Ebola outbreak, which lasted until 2016.",
      "date": "2014-05"
    },
    {
      "headline": "General Elections",
      "text": "On March 7, 2018, Sierra Leone held general elections, leading to the election of Julius Maada Bio as President.",
      "date": "2018-03-07"
    }
  ]
}

