{
  "timeline": [
    {
      "headline": "Founding of Sparta",
      "text": "Sparta was founded in the 10th century BC as a Dorian Greek military settlement in the Eurotas valley of Laconia.",
      "date": "-1000"
    },
    {
      "headline": "Lycurgan Reforms",
      "text": "Around 650 BC, the legendary lawgiver Lycurgus is said to have established the military-oriented reformation of Spartan society, which included the creation of the agoge, the rigorous education and training regimen for male Spartans.",
      "date": "-0650"
    },
    {
      "headline": "First Messenian War",
      "text": "The First Messenian War, fought between Sparta and Messenia, began around 743 BC and resulted in the conquest of Messenia by Sparta.",
      "date": "-0743"
    },
    {
      "headline": "Second Messenian War",
      "text": "The Second Messenian War occurred around 685 BC, where the Messenians revolted against Spartan rule but were eventually subdued.",
      "date": "-0685"
    },
    {
      "headline": "Battle of Thermopylae",
      "text": "In 480 BC, during the Persian Wars, King Leonidas I of Sparta led a small Greek force, including 300 Spartans, against the much larger Persian army at the Battle of Thermopylae.",
      "date": "-0480"
    },
    {
      "headline": "Battle of Plataea",
      "text": "In 479 BC, the Spartans played a crucial role in the Greek victory over the Persians at the Battle of Plataea, which effectively ended the Persian invasion.",
      "date": "-0479"
    },
    {
      "headline": "Peloponnesian War",
      "text": "The Peloponnesian War, fought between Athens and Sparta along with their respective allies, began in 431 BC and lasted until 404 BC, resulting in a Spartan victory.",
      "date": "-0431"
    },
    {
      "headline": "Battle of Leuctra",
      "text": "In 371 BC, the Thebans, led by Epaminondas, defeated the Spartans at the Battle of Leuctra, marking the end of Spartan dominance in Greece.",
      "date": "-0371"
    },
    {
      "headline": "Incorporation into the Achaean League",
      "text": "In 192 BC, Sparta was forcibly incorporated into the Achaean League by the Roman Republic.",
      "date": "-0192"
    },
    {
      "headline": "Roman Conquest",
      "text": "In 146 BC, Sparta, along with the rest of Greece, came under Roman control following the Roman conquest of the Achaean League.",
      "date": "-0146"
    }
  ]
}

