{
  "timeline": [
    {
      "headline": "Construction Begins",
      "text": "Construction of the Leaning Tower of Pisa began in 1173. It was intended to be a freestanding bell tower for the cathedral of Pisa.",
      "date": "1173"
    },
    {
      "headline": "First Signs of Leaning",
      "text": "By the time builders completed the second floor in 1178, the tower began to lean due to a shallow three-meter foundation set in weak, unstable subsoil.",
      "date": "1178"
    },
    {
      "headline": "Construction Halted",
      "text": "Construction was halted for almost a century due to wars between the Pisan Republic and other city-states, which allowed the soil to settle.",
      "date": "1178"
    },
    {
      "headline": "Construction Resumed",
      "text": "Construction resumed in 1272 under Giovanni di Simone, who attempted to compensate for the lean by building upper floors with one side taller than the other.",
      "date": "1272"
    },
    {
      "headline": "Construction Completed",
      "text": "The construction of the tower was completed in 1372, with the addition of the bell chamber.",
      "date": "1372"
    },
    {
      "headline": "Galileo's Experiment",
      "text": "According to legend, Galileo Galilei dropped two spheres of different masses from the tower to demonstrate that their time of descent was independent of their mass.",
      "date": "1589"
    },
    {
      "headline": "Restoration Efforts",
      "text": "In the late 20th century, extensive restoration and stabilization efforts were undertaken to reduce the lean and prevent collapse.",
      "date": "1990"
    },
    {
      "headline": "Reopening to the Public",
      "text": "After the stabilization efforts, the Leaning Tower of Pisa was reopened to the public in 2001.",
      "date": "2001"
    }
  ]
}

