{
  "timeline": [
    {
      "headline": "Start of the Seven Years' War",
      "text": "The Seven Years' War began in 1756, involving major European powers in a global conflict. It was primarily fought in Europe and the Americas.",
      "date": "1756"
    },
    {
      "headline": "Battle of Plassey",
      "text": "On June 23, 1757, the British East India Company, led by Robert Clive, defeated the Nawab of Bengal and his French allies at the Battle of Plassey, marking a significant British victory in India.",
      "date": "1757-06-23"
    },
    {
      "headline": "Battle of Rossbach",
      "text": "On November 5, 1757, Frederick the Great of Prussia achieved a decisive victory against the French and Holy Roman Empire forces at the Battle of Rossbach.",
      "date": "1757-11-05"
    },
    {
      "headline": "Battle of Leuthen",
      "text": "On December 5, 1757, Frederick the Great won another significant victory against the Austrian army at the Battle of Leuthen.",
      "date": "1757-12-05"
    },
    {
      "headline": "Treaty of Easton",
      "text": "In October 1758, the Treaty of Easton was signed, in which the British promised to stop settlements west of the Alleghenies in exchange for neutrality from several Native American tribes.",
      "date": "1758-10"
    },
    {
      "headline": "Capture of Quebec",
      "text": "On September 13, 1759, British forces under General James Wolfe defeated the French at the Battle of the Plains of Abraham, leading to the capture of Quebec.",
      "date": "1759-09-13"
    },
    {
      "headline": "Battle of Quiberon Bay",
      "text": "On November 20, 1759, the British Royal Navy defeated the French fleet at the Battle of Quiberon Bay, securing British naval dominance.",
      "date": "1759-11-20"
    },
    {
      "headline": "Fall of Montreal",
      "text": "On September 8, 1760, Montreal fell to British forces, effectively ending French rule in Canada.",
      "date": "1760-09-08"
    },
    {
      "headline": "Treaty of Paris",
      "text": "The Treaty of Paris was signed on February 10, 1763, ending the Seven Years' War. France ceded Canada and lands east of the Mississippi River to Britain.",
      "date": "1763-02-10"
    },
    {
      "headline": "Treaty of Hubertusburg",
      "text": "On February 15, 1763, the Treaty of Hubertusburg was signed, ending the conflict between Prussia, Austria, and Saxony, and restoring the status quo in Central Europe.",
      "date": "1763-02-15"
    }
  ]
}

