    {
      "headline": "Traditional Death of Saint Patrick",
      "text": "Saint Patrick, the foremost patron saint of Ireland, is traditionally believed to have died on 17 March, which is now celebrated as Saint Patrick's Day.",
      "date": "0461-03-17"
    },
    {
      "headline": "First Saint Patrick's Day Parade",
      "text": "The first recorded Saint Patrick's Day parade was held in New York City on 17 March 1762, organized by Irish soldiers serving in the British army.",
      "date": "1762-03-17"
    },
    {
      "headline": "Saint Patrick's Day Becomes an Official Public Holiday in Ireland",
      "text": "In 1903, Saint Patrick's Day was made an official public holiday in Ireland, thanks to the efforts of Irish nationalist politician James O'Mara.",
      "date": "1903"
    },
    {
      "headline": "First Saint Patrick's Day Parade in Dublin",
      "text": "The first official, state-sponsored Saint Patrick's Day parade in Dublin took place in 1931.",
      "date": "1931"
    },
    {
      "headline": "Introduction of the Saint Patrick's Festival",
      "text": "In 1996, the Irish government established the Saint Patrick's Festival, a multi-day celebration in Dublin to showcase Irish culture.",
      "date": "1996"
    },
    {
      "headline": "Global Celebrations of Saint Patrick's Day",
      "text": "By the late 20th and early 21st centuries, Saint Patrick's Day was celebrated by people of Irish descent and others around the world, with parades, wearing of green attire, and public festivals.",
      "date": "2000"
    }
  ]
}

