{
  "timeline": [
    {
      "headline": "Hallstatt Culture Emergence",
      "text": "The Hallstatt culture, considered the early phase of Celtic culture, emerged around 1200 BCE in what is now Austria. It is characterized by its distinct art, burial rites, and metalwork.",
      "date": "-1200"
    },
    {
      "headline": "La Tène Culture Development",
      "text": "Around 450 BCE, the La Tène culture developed, succeeding the Hallstatt culture. It spread across much of Europe and is often associated with the height of Celtic cultural influence.",
      "date": "-0450"
    },
    {
      "headline": "Sack of Rome by the Gauls",
      "text": "In 390 BCE, a group of Gauls led by Brennus sacked Rome, marking a significant event in Roman history and demonstrating the military prowess of the Celtic tribes.",
      "date": "-0390"
    },
    {
      "headline": "Gallic Wars",
      "text": "From 58 to 50 BCE, Julius Caesar led the Roman legions in the Gallic Wars, resulting in the Roman conquest of the Celtic tribes in Gaul.",
      "date": "-0058"
    },
    {
      "headline": "Battle of Alesia",
      "text": "In 52 BCE, the Battle of Alesia took place, where Julius Caesar defeated the Gallic chieftain Vercingetorix, leading to the Roman domination of Gaul.",
      "date": "-0052"
    },
    {
      "headline": "Roman Conquest of Britain",
      "text": "The Roman conquest of Britain began in 43 CE under Emperor Claudius, gradually subjugating the Celtic tribes of Britain.",
      "date": "0043"
    },
    {
      "headline": "Boudica's Revolt",
      "text": "In 60-61 CE, Boudica, queen of the Iceni tribe, led a major uprising against the occupying Roman forces in Britain.",
      "date": "0060"
    },
    {
      "headline": "Christianization of Ireland",
      "text": "By the 5th century CE, the Christianization of Ireland was underway, significantly influenced by figures such as St. Patrick, leading to the decline of traditional Celtic paganism.",
      "date": "0400"
    },
    {
      "headline": "Viking Invasions",
      "text": "Starting in the late 8th century, Viking invasions began to impact Celtic regions, particularly in Ireland and Scotland, leading to cultural and political changes.",
      "date": "0793"
    },
    {
      "headline": "Battle of Clontarf",
      "text": "In 1014, the Battle of Clontarf took place near Dublin, where Irish forces led by High King Brian Boru defeated a coalition of Irish and Viking forces, marking a significant event in Irish history.",
      "date": "1014"
    },
    {
      "headline": "Norman Invasion of Ireland",
      "text": "In 1169, the Norman invasion of Ireland began, leading to significant changes in the political landscape and the decline of Gaelic power.",
      "date": "1169"
    }
  ]
}

