{
  "timeline": [
    {
      "headline": "Founding of Nashville",
      "text": "Nashville was founded by James Robertson, John Donelson, and a party of Overmountain Men in 1779. It was named after Francis Nash, a general of the Continental Army during the American Revolutionary War.",
      "date": "1779"
    },
    {
      "headline": "Incorporation as a City",
      "text": "Nashville was incorporated as a city in 1806, marking its official establishment as a recognized municipality.",
      "date": "1806"
    },
    {
      "headline": "Becomes State Capital",
      "text": "Nashville became the capital of Tennessee in 1843, solidifying its importance in the state.",
      "date": "1843"
    },
    {
      "headline": "Battle of Nashville",
      "text": "The Battle of Nashville took place during the American Civil War on December 15-16, 1864. It was a significant Union victory.",
      "date": "1864-12-15"
    },
    {
      "headline": "Grand Ole Opry Begins",
      "text": "The Grand Ole Opry, a weekly country music stage concert in Nashville, began broadcasting on November 28, 1925, contributing to Nashville's reputation as Music City.",
      "date": "1925-11-28"
    },
    {
      "headline": "Nashville Sit-ins",
      "text": "The Nashville sit-ins, part of the Civil Rights Movement, began on February 13, 1960, and were instrumental in the desegregation of lunch counters in the city.",
      "date": "1960-02-13"
    },
