      "headline": "London Charter of the International Military Tribunal",
      "text": "On August 8, 1945, the London Charter of the International Military Tribunal was signed by the Allies, establishing the laws and procedures for the Nuremberg Trials.",
      "date": "1945-08-08"
    },
    {
      "headline": "First Nuremberg Trial Begins",
      "text": "The first and most famous of the Nuremberg Trials, the Trial of the Major War Criminals, began on November 20, 1945. It involved 24 of the most important captured leaders of Nazi Germany.",
      "date": "1945-11-20"
    },
    {
      "headline": "Judgment Day of the First Nuremberg Trial",
      "text": "On October 1, 1946, the International Military Tribunal delivered its verdicts, sentencing twelve of the defendants to death, three to life imprisonment, four to prison terms ranging from 10 to 20 years, and acquitting three.",
      "date": "1946-10-01"
    },
    {
      "headline": "Execution of Sentences",
      "text": "On October 16, 1946, ten of the twelve condemned to death were executed by hanging. Hermann Göring, one of the condemned, committed suicide the night before the execution.",
      "date": "1946-10-16"
    },
    {
      "headline": "Subsequent Nuremberg Trials",
      "text": "Between 1946 and 1949, twelve additional trials were held in Nuremberg, known as the Subsequent Nuremberg Trials, which prosecuted other Nazi officials, military leaders, industrialists, and doctors.",
      "date": "1946"
    },
    {
      "headline": "Final Nuremberg Trial Concludes",
      "text": "The last of the Subsequent Nuremberg Trials concluded on April 13, 1949, marking the end of the Nuremberg Trials process.",
      "date": "1949-04-13"
    }
  ]
}

