{
  "timeline": [
    {
      "headline": "Outbreak of the Second Boer War",
      "text": "The Second Boer War began on October 11, 1899, when the Boer republics of the South African Republic and the Orange Free State declared war on the British Empire.",
      "date": "1899-10-11"
    },
    {
      "headline": "Battle of Talana Hill",
      "text": "The first major battle of the war, the Battle of Talana Hill, took place on October 20, 1899, resulting in a British victory.",
      "date": "1899-10-20"
    },
    {
      "headline": "Siege of Ladysmith",
      "text": "The Siege of Ladysmith began on November 2, 1899, when Boer forces encircled the town, trapping British troops and civilians.",
      "date": "1899-11-02"
    },
    {
      "headline": "Battle of Magersfontein",
      "text": "On December 11, 1899, the Battle of Magersfontein was fought, resulting in a significant Boer victory over the British forces.",
      "date": "1899-12-11"
    },
    {
      "headline": "Relief of Kimberley",
      "text": "The Siege of Kimberley was lifted on February 15, 1900, when British forces relieved the town after a prolonged siege by Boer forces.",
      "date": "1900-02-15"
    },
    {
      "headline": "Battle of Paardeberg",
      "text": "The Battle of Paardeberg took place from February 18 to February 27, 1900, culminating in a British victory and the surrender of Boer General Piet Cronjé.",
      "date": "1900-02-18"
    },
    {
      "headline": "Relief of Ladysmith",
      "text": "The Siege of Ladysmith was lifted on February 28, 1900, when British forces broke through the Boer lines.",
      "date": "1900-02-28"
    },
    {
      "headline": "Occupation of Bloemfontein",
      "text": "British forces occupied Bloemfontein, the capital of the Orange Free State, on March 13, 1900.",
      "date": "1900-03-13"
    },
    {
      "headline": "Occupation of Johannesburg",
      "text": "British forces captured Johannesburg on May 31, 1900, marking a significant advance into Boer territory.",
      "date": "1900-05-31"
    },
    {
      "headline": "Occupation of Pretoria",
      "text": "The British occupied Pretoria, the capital of the South African Republic, on June 5, 1900.",
      "date": "1900-06-05"
    },
    {
      "headline": "Battle of Bergendal",
      "text": "The Battle of Bergendal, fought from August 21 to August 27, 1900, was the last set-piece battle of the war, resulting in a British victory.",
      "date": "1900-08-21"
    },
    {
      "headline": "Guerrilla Phase of the War",
      "text": "Following the fall of major cities, the Boer forces adopted guerrilla warfare tactics from September 1900 onwards, prolonging the conflict.",
      "date": "1900-09"
    },
    {
      "headline": "Treaty of Vereeniging",
      "text": "The Second Boer War officially ended with the signing of the Treaty of Vereeniging on May 31, 1902, which brought the Boer republics under British control.",
