    {
      "headline": "Discovery by Europeans",
      "text": "The Pitcairn Islands were first discovered by Europeans in 1606 by Portuguese sailor Pedro Fernandes de Queirós, who was serving the Spanish crown.",
      "date": "1606"
    },
    {
      "headline": "Rediscovery by British",
      "text": "The islands were rediscovered by the British in 1767 by the crew of the British sloop HMS Swallow, commanded by Captain Philip Carteret.",
      "date": "1767"
    },
    {
      "headline": "Settlement by Bounty Mutineers",
      "text": "In 1790, the mutineers of HMS Bounty, led by Fletcher Christian, settled on Pitcairn Island along with Tahitian companions.",
      "date": "1790"
    },
    {
      "headline": "Pitcairn Becomes British Colony",
      "text": "The Pitcairn Islands were officially annexed by the British Empire in 1838, becoming a British colony.",
      "date": "1838"
    },
    {
      "headline": "Introduction of Seventh-day Adventism",
      "text": "In 1886, the Seventh-day Adventist Church was introduced to the island by John Tay, and it became the predominant religion.",
      "date": "1886"
    },
    {
      "headline": "Henderson Island Designated as World Heritage Site",
      "text": "In 1988, Henderson Island, one of the Pitcairn Islands, was designated as a UNESCO World Heritage Site due to its natural beauty and biodiversity.",
      "date": "1988"
    },
    {
      "headline": "Pitcairn Sexual Assault Trials",
      "text": "In 2004, several men on Pitcairn Island were tried and convicted of sexual offenses, bringing international attention to the island.",
      "date": "2004"
    }
  ]
}

{
  "timeline": [
    {
      "headline": "Founding of Metro-Goldwyn-Mayer",
      "text": "Metro-Goldwyn-Mayer (MGM) was founded on April 17, 1924, through a merger of Metro Pictures, Goldwyn Pictures, and Louis B. Mayer Pictures.",
      "date": "1924-04-17"
    },
    {
      "headline": "Release of 'Ben-Hur'",
      "text": "In 1925, MGM released 'Ben-Hur: A Tale of the Christ', which became one of the most expensive silent films ever made and a major box office success.",
      "date": "1925"
    },
    {
      "headline": "Introduction of Leo the Lion",
      "text": "In 1928, MGM introduced its iconic mascot, Leo the Lion, with the slogan 'Ars Gratia Artis' (Art for Art's Sake) in the opening credits of its films.",
      "date": "1928"
    },
    {
      "headline": "Release of 'Gone with the Wind'",
      "text": "In 1939, MGM released 'Gone with the Wind', which became one of the most successful films in history, winning 10 Academy Awards.",
      "date": "1939"
    },
    {
      "headline": "Release of 'The Wizard of Oz'",
      "text": "In 1939, MGM also released 'The Wizard of Oz', which became a classic of American cinema and is known for its innovative use of Technicolor.",
      "date": "1939"
    },
    {
      "headline": "MGM's Golden Age",
      "text": "During the 1940s and 1950s, MGM was considered the most prestigious and profitable studio in Hollywood, producing numerous successful films and stars.",
      "date": "1940"
    },
    {
      "headline": "Financial Decline",
      "text": "By the late 1960s, MGM began to experience financial difficulties due to changes in the film industry and competition from television.",
      "date": "1969"
    },
    {
      "headline": "Acquisition by Kirk Kerkorian",
      "text": "In 1969, MGM was acquired by businessman Kirk Kerkorian, who shifted the company's focus towards real estate and other ventures.",
      "date": "1969"
    },
    {
      "headline": "Sale to Turner Broadcasting",
      "text": "In 1986, MGM was sold to Turner Broadcasting System, which led to the sale of its film library to finance the acquisition.",
      "date": "1986"
    },
    {
      "headline": "Acquisition by Sony-led Consortium",
      "text": "In 2005, MGM was acquired by a consortium led by Sony Corporation of America, Comcast, and private equity firms.",
      "date": "2005"
    },
    {
      "headline": "Bankruptcy and Restructuring",
      "text": "In 2010, MGM filed for bankruptcy and underwent restructuring, emerging from bankruptcy later that year with new leadership.",
      "date": "2010"
    },
    {
      "headline": "Acquisition by Amazon",
      "text": "In 2022, MGM was acquired by Amazon, becoming part of the Amazon MGM Studios subsidiary.",
      "date": "2022"
    }
  ]
}

