    {
      "headline": "Creation of the Dead Sea Scrolls",
      "text": "The Dead Sea Scrolls were created over a period from the 3rd century BCE to the 1st century CE. These ancient Jewish manuscripts include the oldest surviving manuscripts of entire books later included in the biblical canons.",
      "date": "-0300"
    },
    {
      "headline": "Discovery of the Dead Sea Scrolls Begins",
      "text": "The discovery of the Dead Sea Scrolls began in 1946 when the first scrolls were found in the Qumran Caves near the Dead Sea.",
      "date": "1946"
    },
    {
      "headline": "Continued Discovery of the Scrolls",
      "text": "The discovery of the Dead Sea Scrolls continued until 1956, with scrolls being found in multiple caves in the Qumran area.",
      "date": "1956"
    },
    {
      "headline": "Acquisition by Israel",
      "text": "After the 1967 Arab–Israeli War, Israel acquired the Dead Sea Scrolls, which were mostly discovered following the Jordanian annexation of the West Bank.",
      "date": "1967"
    },
    {
      "headline": "Custody Dispute",
      "text": "The Israeli government's custody of the Dead Sea Scrolls is disputed by Jordan and the Palestinian Authority on territorial, legal, and humanitarian grounds.",
      "date": "1967"
    },
    {
      "headline": "Housing at the Shrine of the Book",
      "text": "Almost all of the 15,000 scrolls and scroll fragments are held in the Shrine of the Book at the Israel Museum located in Jerusalem.",
      "date": "1967"
    }
  ]
}

