{
  "timeline": [
    {
      "headline": "Stanford Prison Experiment Begins",
      "text": "The Stanford prison experiment began on August 14, 1971. It was a psychological study conducted by a research team led by Stanford University psychology professor Philip Zimbardo. The experiment was designed to investigate the psychological effects of perceived power, focusing on the struggle between prisoners and prison officers.",
      "date": "1971-08-14"
    },
    {
      "headline": "Experiment Terminated Early",
      "text": "The Stanford prison experiment was terminated on August 20, 1971, after only six days instead of the planned two weeks. The decision to end the experiment early was made due to the extreme and distressing reactions of the participants, which raised ethical concerns.",
      "date": "1971-08-20"
