  "timeline": [
    {
      "headline": "First Indications of Dark Matter",
      "text": "In 1933, Swiss astronomer Fritz Zwicky first inferred the existence of dark matter. He observed that the mass of all the stars in the Coma cluster of galaxies provided only about 1% of the mass needed to keep the galaxies from escaping the cluster's gravitational pull.",
      "date": "1933"
    },
    {
      "headline": "Vera Rubin's Observations",
      "text": "In the 1970s, American astronomer Vera Rubin and her colleague Kent Ford provided strong evidence for dark matter. They observed that the outer regions of spiral galaxies rotated at the same speed as regions closer to the center, contrary to what would be expected if only visible matter were present.",
      "date": "1970"
    },
    {
      "headline": "Dark Matter in Cosmic Microwave Background",
      "text": "In 1992, data from the Cosmic Background Explorer (COBE) satellite provided evidence of the anisotropies in the cosmic microwave background radiation, supporting the existence of dark matter.",
      "date": "1992"
    },
    {
      "headline": "Bullet Cluster Evidence",
      "text": "In 2006, observations of the Bullet Cluster provided some of the best evidence for dark matter. The collision of two galaxy clusters showed a separation between the normal matter and the gravitational effects attributed to dark matter.",
      "date": "2006"
    },
    {
      "headline": "Planck Satellite Findings",
      "text": "In 2013, the Planck satellite released data that provided a detailed map of the cosmic microwave background, further supporting the presence of dark matter in the universe.",
      "date": "2013"
    }
  ]
}

