      "headline": "Planning for Operation Overlord",
      "text": "The planning for Operation Overlord began in earnest in 1943, with the decision to launch a major Allied invasion of German-occupied Western Europe.",
      "date": "1943"
    },
    {
      "headline": "D-Day: Normandy Landings",
      "text": "On 6 June 1944, Operation Overlord was launched with the Normandy landings, also known as D-Day. This involved a massive amphibious assault on the beaches of Normandy, France.",
      "date": "1944-06-06"
    },
    {
      "headline": "Airborne Assault",
      "text": "A 1,200-plane airborne assault preceded the amphibious landings on 6 June 1944, with paratroopers landing behind enemy lines to secure key positions.",
      "date": "1944-06-06"
    },
    {
      "headline": "Amphibious Assault",
      "text": "The amphibious assault on 6 June 1944 involved more than 5,000 vessels and nearly 160,000 troops crossing the English Channel to land on the beaches of Normandy.",
      "date": "1944-06-06"
    },
    {
      "headline": "Securing the Beachheads",
      "text": "In the days following D-Day, Allied forces worked to secure the beachheads and push inland, facing strong German resistance.",
      "date": "1944-06"
    },
    {
      "headline": "Liberation of Paris",
      "text": "By the end of August 1944, more than two million Allied troops were in France, leading to the liberation of Paris on 25 August 1944.",
      "date": "1944-08-25"
    },
    {
      "headline": "End of Operation Overlord",
      "text": "Operation Overlord concluded with the successful liberation of Normandy and the establishment of a strong Allied presence in France, setting the stage for further advances into German-occupied Europe.",
      "date": "1944-08"
    }
  ]
}

