{
  "timeline": [
    {
      "headline": "Origins of the House of Lords",
      "text": "The origins of the House of Lords can be traced back to the early 11th century, when the Anglo-Saxon Witenagemot, a council of nobles and clergy, advised the king.",
      "date": "-1000"
    },
    {
      "headline": "Emergence of Bicameralism",
      "text": "In the 13th century, the English Parliament began to take on a bicameral form, with the Lords and the Commons meeting separately. This development laid the foundation for the modern House of Lords.",
      "date": "1200"
    },
    {
      "headline": "Model Parliament",
      "text": "In 1295, King Edward I summoned what became known as the Model Parliament, which included both lords and commoners, establishing a precedent for future parliaments.",
      "date": "1295"
    },
    {
      "headline": "House of Lords Established",
      "text": "By the 14th century, the House of Lords had become a distinct body within the English Parliament, consisting of bishops, abbots, and peers.",
      "date": "1300"
    },
    {
      "headline": "Dissolution of Monasteries",
      "text": "In the 1530s, King Henry VIII's Dissolution of the Monasteries led to the removal of abbots from the House of Lords, reducing the number of spiritual lords.",
      "date": "1530"
    },
    {
      "headline": "English Civil War and Interregnum",
      "text": "During the English Civil War (1642-1651), the House of Lords was abolished in 1649 following the execution of King Charles I, and England became a republic under Oliver Cromwell.",
      "date": "1649"
    },
    {
      "headline": "Restoration of the Monarchy",
      "text": "In 1660, the monarchy was restored under King Charles II, and the House of Lords was reestablished as part of the English Parliament.",
      "date": "1660"
    },
    {
      "headline": "Act of Union 1707",
      "text": "The Act of Union 1707 united the English and Scottish Parliaments, creating the Parliament of Great Britain. The House of Lords included Scottish peers.",
      "date": "1707"
    },
    {
      "headline": "Reform Act 1832",
      "text": "The Reform Act 1832, also known as the Great Reform Act, significantly changed the British electoral system but left the composition of the House of Lords largely unchanged.",
      "date": "1832"
    },
    {
      "headline": "Parliament Act 1911",
      "text": "The Parliament Act 1911 reduced the power of the House of Lords, removing its ability to veto money bills and limiting its ability to delay other legislation.",
      "date": "1911"
    },
    {
      "headline": "Life Peerages Act 1958",
      "text": "The Life Peerages Act 1958 allowed for the creation of life peers, who could sit in the House of Lords without passing their titles to their descendants.",
      "date": "1958"
    },
    {
      "headline": "House of Lords Act 1999",
      "text": "The House of Lords Act 1999 removed most hereditary peers from the House of Lords, reducing its membership significantly.",
      "date": "1999"
    },
    {
      "headline": "Constitutional Reform Act 2005",
      "text": "The Constitutional Reform Act 2005 established the Supreme Court of the United Kingdom, transferring the judicial functions of the House of Lords to the new court.",
      "date": "2005"
    }
  ]
}

