    {
      "headline": "First Publication of the Corruption Perceptions Index",
      "text": "The Corruption Perceptions Index (CPI) was first published by Transparency International in 1995. It was created to rank countries by their perceived levels of public sector corruption, as assessed by experts and business executives.",
      "date": "1995"
    },
    {
      "headline": "Introduction of the CPI Methodology",
      "text": "The CPI methodology was introduced to provide a comprehensive measure of perceived corruption in the public sector. It aggregates data from various sources, including surveys and assessments from experts and business executives.",
      "date": "1995"
    },
    {
      "headline": "Annual Publication of the CPI",
      "text": "Since its inception, the CPI has been published annually by Transparency International, providing updated rankings and scores for countries around the world.",
      "date": "1995"
    },
    {
      "headline": "Expansion of CPI Coverage",
      "text": "Over the years, the CPI has expanded its coverage to include more countries and territories, providing a broader view of global corruption perceptions.",
      "date": "1995"
    },
    {
      "headline": "Methodological Revisions",
      "text": "The CPI has undergone several methodological revisions to improve its accuracy and reliability. These revisions have included changes in data sources and scoring methods.",
      "date": "2012"
    },
    {
      "headline": "CPI 2012 Methodology Update",
      "text": "In 2012, Transparency International updated the CPI methodology to allow for better comparison of scores over time. This included changes to the way scores were calculated and presented.",
      "date": "2012"
    },
    {
      "headline": "CPI 2017 Methodology Update",
      "text": "In 2017, further updates were made to the CPI methodology to enhance its robustness and transparency. These updates aimed to improve the index's ability to reflect changes in perceived corruption levels.",
      "date": "2017"
    }
  ]
}

