{
  "timeline": [
    {
      "headline": "Incident Occurs",
      "text": "On 2012-12-16, Jyoti Singh, a 22-year-old physiotherapy intern, was beaten, gang-raped, and tortured in a private bus in Munirka, South Delhi. Her male friend was also beaten by the attackers.",
      "date": "2012-12-16"
    },
    {
      "headline": "Hospitalization in Delhi",
      "text": "Following the attack, Jyoti Singh was admitted to Safdarjung Hospital in Delhi for treatment. Her condition was critical due to severe injuries.",
      "date": "2012-12-16"
    },
    {
      "headline": "Transfer to Singapore",
      "text": "On 2012-12-27, Jyoti Singh was transferred to Mount Elizabeth Hospital in Singapore for further treatment as her condition remained critical.",
      "date": "2012-12-27"
    },
    {
      "headline": "Death of Jyoti Singh",
      "text": "Jyoti Singh succumbed to her injuries and passed away on 2012-12-29 at Mount Elizabeth Hospital in Singapore.",
      "date": "2012-12-29"
    },
    {
      "headline": "Public Protests Erupt",
      "text": "Following the incident, widespread public protests erupted across India, particularly in New Delhi, demanding justice and better security for women. These protests continued for several days.",
      "date": "2012-12"
    },
    {
      "headline": "Arrests and Charges",
      "text": "All six accused, including the bus driver, were arrested and charged with rape and murder. The legal proceedings began shortly after the incident.",
      "date": "2012-12"
    },
    {
      "headline": "Trial and Sentencing",
      "text": "The trial of the accused began in a fast-track court. On 2013-09-13, four of the adult defendants were sentenced to death. The juvenile was sentenced to three years in a reform facility.",
      "date": "2013-09-13"
    },
    {
      "headline": "Execution of Convicts",
      "text": "On 2020-03-20, four of the convicts were executed by hanging after their appeals were exhausted and mercy petitions were rejected.",
      "date": "2020-03-20"
    }
  ]
}

{
  "timeline": [
    {
      "headline": "Introduction of Entropy in Thermodynamics",
      "text": "The concept of entropy was introduced in 1865 by the German physicist Rudolf Clausius. He formulated the second law of thermodynamics, which states that the total entropy of an isolated system can never decrease over time.",
      "date": "1865"
    },
    {
      "headline": "Ludwig Boltzmann's Statistical Interpretation",
      "text": "In the 1870s, Ludwig Boltzmann provided a statistical interpretation of entropy, relating it to the number of microscopic configurations that correspond to a thermodynamic system's macroscopic state.",
      "date": "1870"
    },
    {
      "headline": "Entropy in Information Theory",
      "text": "In 1948, Claude Shannon introduced the concept of entropy in the context of information theory, defining it as a measure of the uncertainty in a set of possible messages.",
      "date": "1948"
    },
    {
      "headline": "Entropy and the Arrow of Time",
      "text": "Entropy is often associated with the arrow of time, as it provides a direction to time's flow in thermodynamic processes. This concept was explored throughout the 20th century.",
      "date": "1900-1999"
    },
    {
      "headline": "Applications in Cosmology",
      "text": "Entropy has been applied to cosmology, particularly in understanding the thermodynamic properties of black holes and the universe's evolution.",
      "date": "1900-2000"
    },
    {
      "headline": "Entropy in Biological Systems",
      "text": "Entropy is used to understand biological processes, such as the organization of living systems and the flow of energy through ecosystems.",
      "date": "1900-2000"
    },
    {
      "headline": "Entropy and Climate Science",
      "text": "Entropy concepts are applied in climate science to study the Earth's energy balance and the impact of human activities on climate change.",
      "date": "1900-2000"
    }
  ]
}

