    {
      "headline": "Publication of 'Venus in Furs' by Leopold von Sacher-Masoch",
      "text": "In 1870, Leopold von Sacher-Masoch published 'Venus in Furs', a novella that became his most famous work. It explores themes of female dominance and male submission, and the term 'masochism' is derived from his name.",
      "date": "1870"
    },
    {
      "headline": "Coining of the term 'Sadism'",
      "text": "The term 'sadism' was coined in the late 19th century, derived from the name of Marquis de Sade, to describe the derivation of pleasure from inflicting pain, suffering, or humiliation on others.",
      "date": "1800s"
    },
    {
      "headline": "Coining of the term 'Masochism'",
      "text": "The term 'masochism' was coined in the late 19th century, derived from the name of Leopold von Sacher-Masoch, to describe the derivation of pleasure from one's own pain or humiliation.",
      "date": "1800s"
