    {
      "headline": "Earliest Written Records of Greek",
      "text": "The earliest written records of the Greek language date back to around 1400 BCE, using the Linear B script, which was used by the Mycenaean civilization.",
      "date": "-1400"
    },
    {
      "headline": "Development of the Greek Alphabet",
      "text": "Around 800 BCE, the Greek alphabet was developed from the Phoenician script. This new writing system became the basis for many other alphabets, including Latin and Cyrillic.",
      "date": "-0800"
    },
    {
      "headline": "Classical Greek Period",
      "text": "The Classical Greek period, from approximately 500 BCE to 300 BCE, saw the flourishing of Greek literature, philosophy, and science, with works by authors such as Homer, Plato, and Aristotle.",
      "date": "-0500"
    },
    {
      "headline": "Hellenistic Period",
      "text": "Following the conquests of Alexander the Great, from 323 BCE to 31 BCE, the Greek language spread across the Eastern Mediterranean and into Asia, becoming a lingua franca of the Hellenistic world.",
      "date": "-0323"
    },
    {
      "headline": "Koine Greek",
      "text": "From around 300 BCE to 300 CE, Koine Greek emerged as a common dialect that was widely used across the Eastern Mediterranean and the Near East, facilitating communication and trade.",
      "date": "-0300"
    },
    {
      "headline": "Byzantine Greek",
      "text": "During the Byzantine Empire, from approximately 330 CE to 1453 CE, Greek evolved into Byzantine Greek, which was used in administration, literature, and liturgy.",
      "date": "0330"
    },
    {
      "headline": "Modern Greek",
      "text": "The transition to Modern Greek began around the 15th century, following the fall of Constantinople in 1453, leading to the development of the Greek language as it is known today.",
      "date": "1453"
    },
    {
      "headline": "Official Language of Greece",
      "text": "In 1830, following the Greek War of Independence, Greek was established as the official language of the newly independent Greek state.",
      "date": "1830"
    },
    {
      "headline": "Greek Language Reform",
      "text": "In 1976, the Greek government officially adopted the Demotic Greek as the standard language of the country, replacing the more archaic Katharevousa.",
      "date": "1976"
    }
  ]
}

