{
  "timeline": [
    {
      "headline": "Start of the Second Persian Invasion of Greece",
      "text": "In 480 BC, the Achaemenid Persian Empire under King Xerxes I launched the second Persian invasion of Greece, aiming to conquer the Greek city-states.",
      "date": "-0480"
    },
    {
      "headline": "Greek Alliance Formed",
      "text": "In response to the Persian threat, an alliance of Greek city-states was formed, led by Sparta under King Leonidas I, to defend against the invasion.",
      "date": "-0480"
    },
    {
      "headline": "Battle of Thermopylae Begins",
      "text": "The Battle of Thermopylae began in August 480 BC, with Greek forces led by King Leonidas I taking a defensive position at the narrow pass of Thermopylae to block the advancing Persian army.",
      "date": "-0480-08"
    },
    {
      "headline": "First Day of Battle",
      "text": "On the first day of the battle, the Greek forces successfully repelled the initial Persian attacks, utilizing the narrow terrain to their advantage.",
      "date": "-0480-08"
    },
    {
      "headline": "Second Day of Battle",
      "text": "On the second day, the Persians launched renewed assaults but were again held back by the Greek defenders, who continued to exploit the strategic position of the pass.",
      "date": "-0480-08"
    },
    {
      "headline": "Ephialtes' Betrayal",
      "text": "A Greek traitor named Ephialtes revealed a secret path to the Persians, allowing them to outflank the Greek forces on the third day of the battle.",
      "date": "-0480-08"
    },
    {
      "headline": "Final Stand of the Greeks",
      "text": "On the third day, King Leonidas I and his remaining Greek forces, including the famous 300 Spartans, made a heroic last stand against the overwhelming Persian army, ultimately being defeated.",
      "date": "-0480-08"
    },
    {
      "headline": "Aftermath of the Battle",
      "text": "Despite their defeat, the Greek forces' valiant stand at Thermopylae became a symbol of courage and sacrifice, inspiring further Greek resistance against the Persians.",
      "date": "-0480"
    }
  ]
}

