{
  "timeline": [
    {
      "headline": "First Recorded Pandemic: Plague of Justinian",
      "text": "The first recorded pandemic of bubonic plague occurred during the reign of Byzantine Emperor Justinian I. It began in 541 CE and continued to recur until 750 CE, causing widespread mortality across the Mediterranean region.",
      "date": "0541"
    },
    {
      "headline": "The Black Death",
      "text": "The most infamous outbreak of bubonic plague, known as the Black Death, began in 1347 and lasted until 1351. It originated in Asia and spread to Europe, killing an estimated 25 million people, which was about a third of Europe's population at the time.",
      "date": "1347"
    },
    {
      "headline": "Third Pandemic",
      "text": "The third pandemic of bubonic plague began in Yunnan, China, in 1855 and spread to all inhabited continents, leading to over 12 million deaths in India and China alone. This pandemic lasted until the early 20th century.",
      "date": "1855"
    },
    {
      "headline": "Discovery of Yersinia pestis",
      "text": "In 1894, during the third pandemic, Alexandre Yersin, a Swiss-French bacteriologist, discovered the bacterium responsible for the bubonic plague, later named Yersinia pestis in his honor.",
      "date": "1894"
    },
    {
      "headline": "Development of Plague Vaccine",
      "text": "The first effective vaccine against bubonic plague was developed in the late 19th century by Waldemar Haffkine, a bacteriologist working in India.",
      "date": "1897"
    },
    {
      "headline": "Modern Outbreaks",
      "text": "Although rare, outbreaks of bubonic plague still occur in modern times. Notable outbreaks have occurred in Madagascar, the Democratic Republic of the Congo, and Peru in the 20th and 21st centuries.",
      "date": "1900"
    }
  ]
}

