    {
      "headline": "Aboriginal Inhabitation",
      "text": "Tasmania was inhabited by the Tasmanian Aboriginal people for at least 35,000 years before European settlement.",
      "date": "-033000"
    },
    {
      "headline": "Discovery by Europeans",
      "text": "In 1642, Dutch explorer Abel Tasman became the first European to sight Tasmania, naming it Van Diemen's Land after Anthony van Diemen, the Governor-General of the Dutch East Indies.",
      "date": "1642"
    },
    {
      "headline": "British Claim",
      "text": "In 1803, the British established a penal colony at Risdon Cove on the eastern shore of the Derwent River, marking the beginning of British settlement in Tasmania.",
      "date": "1803"
    },
    {
      "headline": "Hobart Founded",
      "text": "In 1804, Hobart was founded as a penal colony by Lieutenant David Collins.",
      "date": "1804"
    },
    {
      "headline": "Black War",
      "text": "Between 1820 and 1832, the Black War occurred, a period of violent conflict between British colonists and Aboriginal Tasmanians.",
      "date": "1820"
    },
    {
      "headline": "Van Diemen's Land Renamed",
      "text": "In 1856, Van Diemen's Land was officially renamed Tasmania.",
      "date": "1856"
    },
    {
      "headline": "Self-Government Granted",
      "text": "In 1856, Tasmania was granted responsible self-government by the British Parliament.",
      "date": "1856"
    },
    {
      "headline": "Federation of Australia",
      "text": "On January 1, 1901, Tasmania became a state of the Commonwealth of Australia.",
      "date": "1901-01-01"
    },
    {
      "headline": "Hydro-Electric Power Development",
      "text": "In the early 20th century, Tasmania began developing its hydro-electric power resources, which became a significant part of its economy.",
      "date": "1910"
    },
    {
      "headline": "Port Arthur Massacre",
      "text": "On April 28, 1996, the Port Arthur massacre occurred, where a gunman killed 35 people and wounded 23 others, leading to significant changes in Australia's gun laws.",
      "date": "1996-04-28"
    },
    {
      "headline": "Tasmanian Wilderness World Heritage Area",
      "text": "In 1982, the Tasmanian Wilderness was inscribed on the World Heritage List for its outstanding natural and cultural values.",
      "date": "1982"
    }
  ]
}

{
