    {
      "headline": "Cook's First Voyage to Newfoundland",
      "text": "In 1763, Cook was appointed to survey the coasts of Newfoundland, which he did until 1767.",
      "date": "1763"
    },
    {
      "headline": "Cook's First Pacific Voyage Begins",
      "text": "On August 26, 1768, Cook set sail on his first voyage to the Pacific Ocean aboard the HMS Endeavour.",
      "date": "1768-08-26"
    },
    {
      "headline": "Cook Reaches New Zealand",
      "text": "On October 6, 1769, Cook reached New Zealand, becoming the first European to make contact with the islands since Abel Tasman in 1642.",
      "date": "1769-10-06"
    },
    {
      "headline": "Cook's First Voyage Ends",
      "text": "Cook returned to England on July 12, 1771, completing his first voyage.",
      "date": "1771-07-12"
    },
    {
      "headline": "Cook's Second Pacific Voyage Begins",
      "text": "On July 13, 1772, Cook embarked on his second voyage to the Pacific Ocean aboard the HMS Resolution.",
      "date": "1772-07-13"
    },
    {
      "headline": "Cook Crosses the Antarctic Circle",
      "text": "On January 17, 1773, Cook became the first recorded European to cross the Antarctic Circle.",
      "date": "1773-01-17"
    },
    {
      "headline": "Cook's Second Voyage Ends",
      "text": "Cook returned to England on July 30, 1775, after completing his second voyage.",
      "date": "1775-07-30"
    },
    {
      "headline": "Cook's Third Pacific Voyage Begins",
      "text": "On July 12, 1776, Cook set out on his third and final voyage to the Pacific Ocean.",
      "date": "1776-07-12"
    },
    {
      "headline": "Cook Reaches Hawaii",
      "text": "In January 1778, Cook became the first European to visit the Hawaiian Islands.",
      "date": "1778-01"
    },
    {
