      "headline": "End of First Reign",
      "text": "Mehmed II's first reign ended in September 1446 when his father, Murad II, returned to the throne.",
      "date": "1446-09"
    },
    {
      "headline": "Second Reign as Sultan",
      "text": "Mehmed II began his second reign as Sultan of the Ottoman Empire in February 1451 after the death of his father, Murad II.",
      "date": "1451-02"
    },
    {
      "headline": "Conquest of Constantinople",
      "text": "On May 29, 1453, Mehmed II successfully conquered Constantinople, marking the end of the Byzantine Empire and earning him the title 'The Conqueror'.",
      "date": "1453-05-29"
    },
    {
      "headline": "Conquest of Serbia",
      "text": "In 1459, Mehmed II conquered Serbia, further expanding the Ottoman Empire's territories in the Balkans.",
      "date": "1459"
    },
    {
      "headline": "Conquest of Morea",
      "text": "Mehmed II conquered the Despotate of Morea in 1460, consolidating Ottoman control over the Peloponnese.",
      "date": "1460"
    },
    {
      "headline": "Conquest of Trebizond",
      "text": "In 1461, Mehmed II captured the Empire of Trebizond, the last Byzantine successor state.",
      "date": "1461"
    },
    {
      "headline": "Conquest of Bosnia",
      "text": "Mehmed II conquered Bosnia in 1463, further expanding the Ottoman Empire's reach in Europe.",
      "date": "1463"
    },
    {
      "headline": "Death of Mehmed II",
      "text": "Mehmed II died on May 3, 1481, in Gebze, near Istanbul, marking the end of his reign and life.",
      "date": "1481-05-03"
    }
  ]
}

