{
  "timeline": [
    {
      "headline": "First European Discovery",
      "text": "The Cayman Islands were first sighted by Europeans on 10 May 1503, when Christopher Columbus, on his fourth and final voyage to the New World, discovered the islands.",
      "date": "1503-05-10"
    },
    {
      "headline": "Naming of the Islands",
      "text": "In 1523, the islands were named 'Las Tortugas' by the Spanish explorer Diego Velázquez due to the large number of sea turtles found there.",
      "date": "1523"
    },
    {
      "headline": "Renaming to Caymanas",
      "text": "In 1540, the islands were renamed 'Caymanas' after the Carib word for marine crocodile, which were found in the area.",
      "date": "1540"
    },
    {
      "headline": "British Control Established",
      "text": "In 1670, the Treaty of Madrid was signed, and the Cayman Islands, along with Jamaica, were ceded to England by Spain.",
      "date": "1670"
    },
    {
      "headline": "First Permanent Settlement",
      "text": "The first permanent settlement on the Cayman Islands was established in Little Cayman in 1730.",
      "date": "1730"
    },
    {
      "headline": "Separation from Jamaica",
      "text": "In 1863, the Cayman Islands became a dependency of Jamaica, which was then a British colony.",
      "date": "1863"
    },
    {
      "headline": "Cayman Islands Constitution",
      "text": "The Cayman Islands received their first constitution in 1959, which provided for a Legislative Assembly.",
      "date": "1959"
    },
    {
      "headline": "Separation from Jamaica",
      "text": "In 1962, when Jamaica gained independence from Britain, the Cayman Islands chose to remain a British Overseas Territory.",
      "date": "1962"
    },
    {
      "headline": "Current Constitution Enacted",
      "text": "The current constitution of the Cayman Islands was enacted on 6 November 2009, providing for greater autonomy and a more modern governance structure.",
      "date": "2009-11-06"
    }
  ]
}

