    {
      "headline": "Establishment of WHO",
      "text": "The World Health Organization (WHO) was established on 7 April 1948. It is a specialized agency of the United Nations responsible for international public health.",
      "date": "1948-04-07"
    },
    {
      "headline": "First World Health Assembly",
      "text": "The first World Health Assembly was held in Geneva, Switzerland, from 24 June to 24 July 1948. This assembly marked the beginning of WHO's work in coordinating international health efforts.",
      "date": "1948-06-24"
    },
    {
      "headline": "Adoption of the International Classification of Diseases",
      "text": "In 1948, WHO adopted the International Classification of Diseases (ICD), which is used to standardize the diagnosis of diseases and other health conditions.",
      "date": "1948"
    },
    {
      "headline": "Launch of the Global Malaria Eradication Programme",
      "text": "In 1955, WHO launched the Global Malaria Eradication Programme, aiming to eradicate malaria worldwide through vector control and treatment.",
      "date": "1955"
    },
    {
      "headline": "Smallpox Eradication Campaign",
      "text": "In 1967, WHO intensified its efforts to eradicate smallpox, leading to the successful eradication of the disease in 1980.",
      "date": "1967"
    },
    {
      "headline": "Declaration of Alma-Ata",
      "text": "In 1978, the Declaration of Alma-Ata was adopted at the International Conference on Primary Health Care, emphasizing the importance of primary health care and the goal of 'Health for All by the year 2000'.",
      "date": "1978"
    },
    {
      "headline": "Eradication of Smallpox",
      "text": "On 8 May 1980, the World Health Assembly officially declared the eradication of smallpox, marking a significant achievement in global health.",
      "date": "1980-05-08"
    },
    {
      "headline": "Launch of the Global Programme on AIDS",
      "text": "In 1986, WHO launched the Global Programme on AIDS to coordinate the international response to the HIV/AIDS epidemic.",
      "date": "1986"
    },
    {
      "headline": "Framework Convention on Tobacco Control",
      "text": "In 2003, WHO adopted the Framework Convention on Tobacco Control, the first international treaty negotiated under WHO's auspices, aimed at reducing tobacco consumption and exposure.",
      "date": "2003"
    },
    {
      "headline": "Response to the H1N1 Influenza Pandemic",
      "text": "In 2009, WHO declared the H1N1 influenza outbreak a pandemic and coordinated global response efforts.",
      "date": "2009"
    },
    {
      "headline": "Launch of the Global Health Observatory",
      "text": "In 2010, WHO launched the Global Health Observatory, a platform providing access to data and analyses on global health priorities.",
      "date": "2010"
    },
    {
      "headline": "Ebola Virus Outbreak Response",
      "text": "In 2014, WHO played a critical role in responding to the Ebola virus outbreak in West Africa, coordinating international efforts to control the epidemic.",
      "date": "2014"
    },
    {
      "headline": "COVID-19 Pandemic Declaration",
      "text": "On 11 March 2020, WHO declared the COVID-19 outbreak a pandemic, leading global efforts to combat the virus.",
      "date": "2020-03-11"
    }
  ]
}

