{
  "timeline": [
    {
      "headline": "Formation of the Provisional IRA",
      "text": "The Provisional Irish Republican Army (IRA) was formed in December 1969 as a splinter group from the original IRA, following a split in the republican movement over the direction and methods of achieving Irish reunification.",
      "date": "1969-12"
    },
    {
      "headline": "Beginning of the Troubles",
      "text": "The Provisional IRA became active in the early 1970s, marking the beginning of the Troubles, a conflict in Northern Ireland that lasted for about three decades. The IRA aimed to end British rule in Northern Ireland and reunify Ireland.",
      "date": "1970"
    },
    {
      "headline": "Bloody Sunday",
      "text": "On January 30, 1972, British soldiers shot 26 unarmed civilians during a protest march in Derry, Northern Ireland. This event, known as Bloody Sunday, significantly increased support for the Provisional IRA.",
      "date": "1972-01-30"
    },
    {
      "headline": "Ceasefire Announcement",
      "text": "In 1975, the Provisional IRA announced a ceasefire, which lasted for most of the year. However, the ceasefire eventually broke down, and violence resumed.",
      "date": "1975"
    },
    {
      "headline": "Hunger Strikes",
      "text": "In 1981, a series of hunger strikes by IRA prisoners in the Maze Prison brought international attention to the IRA's cause. The most notable of these was Bobby Sands, who died after 66 days on hunger strike.",
      "date": "1981"
    },
    {
      "headline": "IRA Bombing Campaign in England",
      "text": "Throughout the 1980s and early 1990s, the Provisional IRA conducted a bombing campaign in England, targeting military and political sites, as well as civilian areas, to pressure the British government.",
      "date": "1980"
    },
    {
      "headline": "Downing Street Declaration",
      "text": "On December 15, 1993, the British and Irish governments issued the Downing Street Declaration, which laid the groundwork for peace talks. The IRA responded with a temporary ceasefire in 1994.",
      "date": "1993-12-15"
    },
    {
      "headline": "IRA Ceasefire",
      "text": "On August 31, 1994, the Provisional IRA announced a complete cessation of military operations, marking a significant step towards peace in Northern Ireland.",
      "date": "1994-08-31"
    },
    {
      "headline": "Good Friday Agreement",
      "text": "The Good Friday Agreement was signed on April 10, 1998, marking the end of the Troubles. The Provisional IRA supported the agreement, which included provisions for disarmament and political reform.",
      "date": "1998-04-10"
    },
    {
      "headline": "IRA Decommissioning",
      "text": "On July 28, 2005, the Provisional IRA announced that it had formally ended its armed campaign and would decommission its weapons, marking the end of its paramilitary activities.",
      "date": "2005-07-28"
    }
  ]
}

