{
  "timeline": [
    {
      "headline": "February Revolution Begins",
      "text": "The February Revolution began on March 8, 1917, with mass protests and strikes in Petrograd (now Saint Petersburg), leading to the abdication of Tsar Nicholas II.",
      "date": "1917-03-08"
    },
    {
      "headline": "Abdication of Tsar Nicholas II",
      "text": "On March 15, 1917, Tsar Nicholas II abdicated the throne, ending centuries of Romanov rule in Russia.",
      "date": "1917-03-15"
    },
    {
      "headline": "Formation of the Provisional Government",
      "text": "Following the abdication of the Tsar, the Russian Provisional Government was formed on March 16, 1917, to manage the transition of power.",
      "date": "1917-03-16"
    },
    {
      "headline": "April Theses",
      "text": "Vladimir Lenin returned to Petrograd from exile and issued the April Theses on April 17, 1917, calling for Soviet control of state power.",
      "date": "1917-04-17"
    },
    {
      "headline": "July Days",
      "text": "From July 3 to July 7, 1917, spontaneous armed demonstrations by soldiers, sailors, and industrial workers took place in Petrograd, known as the July Days.",
      "date": "1917-07-03"
    },
    {
      "headline": "Kornilov Affair",
      "text": "In August 1917, General Lavr Kornilov attempted a coup against the Provisional Government, which failed and strengthened the Bolsheviks.",
      "date": "1917-08"
    },
    {
      "headline": "October Revolution",
      "text": "The Bolsheviks, led by Lenin, overthrew the Provisional Government in Petrograd on October 25, 1917, in what is known as the October Revolution.",
      "date": "1917-10-25"
    },
    {
      "headline": "Treaty of Brest-Litovsk",
      "text": "On March 3, 1918, the Bolshevik government signed the Treaty of Brest-Litovsk with Germany, ending Russia's involvement in World War I.",
      "date": "1918-03-03"
    },
    {
      "headline": "Russian Civil War",
      "text": "The Russian Civil War began in 1918 between the Red Army (Bolsheviks) and the White Army (anti-Bolsheviks), lasting until 1922.",
      "date": "1918"
    },
    {
      "headline": "Execution of the Romanov Family",
      "text": "On July 17, 1918, Tsar Nicholas II and his family were executed by Bolsheviks in Yekaterinburg.",
      "date": "1918-07-17"
    },
    {
      "headline": "End of the Russian Civil War",
      "text": "The Russian Civil War ended in 1922 with the victory of the Bolsheviks, leading to the establishment of the Soviet Union.",
      "date": "1922"
    }
  ]
}

