{
  "timeline": [
    {
      "headline": "Ten-Day War in Slovenia",
      "text": "The Ten-Day War in Slovenia began on June 27, 1991, when Slovenia declared independence from Yugoslavia. The conflict lasted until July 7, 1991, resulting in a Slovenian victory and the withdrawal of the Yugoslav People's Army.",
      "date": "1991-06-27"
    },
    {
      "headline": "Croatian War of Independence Begins",
      "text": "The Croatian War of Independence began on March 31, 1991, following Croatia's declaration of independence. The conflict was marked by ethnic tensions and territorial disputes between Croats and Serbs.",
      "date": "1991-03-31"
    },
    {
      "headline": "Bosnian War Begins",
      "text": "The Bosnian War began on April 6, 1992, following Bosnia and Herzegovina's declaration of independence. The war involved multiple ethnic groups, including Bosniaks, Serbs, and Croats, and was characterized by widespread atrocities.",
      "date": "1992-04-06"
    },
    {
      "headline": "Siege of Sarajevo",
      "text": "The Siege of Sarajevo, the longest siege in modern warfare, began on April 5, 1992, and lasted until February 29, 1996. It was a key event in the Bosnian War, resulting in significant civilian casualties and destruction.",
      "date": "1992-04-05"
    },
    {
      "headline": "Vukovar Massacre",
      "text": "The Vukovar Massacre occurred in November 1991, following the capture of the Croatian town of Vukovar by the Yugoslav People's Army and Serbian paramilitaries. Hundreds of Croatian prisoners of war and civilians were executed.",
      "date": "1991-11"
    },
    {
      "headline": "Srebrenica Massacre",
      "text": "In July 1995, the Srebrenica Massacre took place, where more than 8,000 Bosniak men and boys were killed by Bosnian Serb forces. It is considered one of the worst atrocities in Europe since World War II.",
      "date": "1995-07"
    },
    {
      "headline": "Dayton Agreement",
      "text": "The Dayton Agreement was signed on December 14, 1995, officially ending the Bosnian War. The agreement established Bosnia and Herzegovina as a single state composed of two entities.",
      "date": "1995-12-14"
    },
    {
      "headline": "Kosovo War",
      "text": "The Kosovo War began in February 1998 and lasted until June 1999. It was fought between the Federal Republic of Yugoslavia and the Kosovo Liberation Army, with NATO intervening in 1999.",
      "date": "1998-02"
    },
    {
      "headline": "NATO Bombing of Yugoslavia",
      "text": "NATO launched an aerial bombing campaign against Yugoslavia on March 24, 1999, to halt the humanitarian crisis in Kosovo. The campaign lasted until June 10, 1999, leading to the withdrawal of Yugoslav forces from Kosovo.",
      "date": "1999-03-24"
    },
    {
      "headline": "Ohrid Agreement",
      "text": "The Ohrid Agreement was signed on August 13, 2001, ending the insurgency in Macedonia. It provided greater rights and representation for the ethnic Albanian minority in Macedonia.",
      "date": "2001-08-13"
    }
  ]
}

{
  "timeline": [
    {
      "headline": "Establishment of the International Court of Justice",
      "text": "The International Court of Justice (ICJ) was established in 1945 by the Charter of the United Nations and began work in 1946. It is the principal judicial organ of the United Nations.",
      "date": "1945"
    },
    {
      "headline": "First Case Adjudicated",
      "text": "The first case adjudicated by the ICJ was the Corfu Channel case between the United Kingdom and Albania, which began in 1947 and concluded in 1949.",
      "date": "1947"
    },
    {
      "headline": "Advisory Opinion on the Legality of Nuclear Weapons",
      "text": "In 1996, the ICJ issued an advisory opinion on the legality of the threat or use of nuclear weapons, stating that the use of nuclear weapons would generally be contrary to the rules of international law.",
      "date": "1996"
    },
    {
      "headline": "Case Concerning Avena and Other Mexican Nationals",
      "text": "In 2004, the ICJ ruled in the Avena case that the United States had violated the Vienna Convention on Consular Relations by not informing Mexican nationals of their right to consular assistance.",
      "date": "2004"
    },
    {
      "headline": "Advisory Opinion on Kosovo's Declaration of Independence",
      "text": "In 2010, the ICJ issued an advisory opinion stating that Kosovo's declaration of independence from Serbia did not violate international law.",
      "date": "2010"
    },
    {
      "headline": "Case Concerning Maritime Delimitation in the Caribbean Sea and the Pacific Ocean",
      "text": "In 2018, the ICJ delivered a judgment on the maritime boundary dispute between Costa Rica and Nicaragua, establishing a single maritime boundary in the Caribbean Sea and the Pacific Ocean.",
      "date": "2018"
    }
  ]
}

