    },
    {
      "headline": "Life Sentences",
      "text": "On September 25, 2014, Samuel Little was sentenced to three consecutive life sentences without the possibility of parole.",
      "date": "2014-09-25"
    },
    {
      "headline": "Confession to 93 Murders",
      "text": "In 2018, Samuel Little confessed to the murder of 93 individuals, spanning from 1970 to 2005.",
      "date": "2018"
    },
    {
      "headline": "FBI Confirms 60 Murders",
      "text": "By 2019, the FBI's Violent Criminal Apprehension Program confirmed Samuel Little's involvement in at least 60 murders, making him the most prolific serial killer in U.S. history.",
      "date": "2019"
    },
