{
  "timeline": [
    {
      "headline": "Emergence of Phoenician Civilization",
      "text": "The Phoenician civilization began to emerge around 2500 BCE in the Levant region, primarily in modern-day Lebanon. They were known for their maritime trading culture.",
      "date": "-2500"
    },
    {
      "headline": "Development of the Phoenician Alphabet",
      "text": "Around 1050 BCE, the Phoenicians developed one of the first alphabets, which greatly influenced the writing systems of the Mediterranean and beyond.",
      "date": "-1050"
    },
    {
      "headline": "Founding of Carthage",
      "text": "In 814 BCE, the Phoenicians founded the city of Carthage in present-day Tunisia, which became a major power in the western Mediterranean.",
      "date": "-0814"
    },
    {
      "headline": "Phoenician Expansion",
      "text": "During the 9th to 6th centuries BCE, the Phoenicians expanded their trade networks and established colonies throughout the Mediterranean, including in Cyprus, Sicily, Sardinia, and the Iberian Peninsula.",
      "date": "-0900"
    },
    {
      "headline": "Assyrian Domination",
      "text": "From the 9th century BCE, the Phoenician city-states came under the influence and control of the Assyrian Empire, paying tribute to the Assyrian kings.",
      "date": "-0900"
    },
    {
      "headline": "Neo-Babylonian and Persian Rule",
      "text": "After the fall of the Assyrian Empire, the Phoenician city-states came under the control of the Neo-Babylonian Empire in the 6th century BCE, followed by the Persian Empire.",
      "date": "-0600"
    },
    {
      "headline": "Alexander the Great's Conquest",
      "text": "In 332 BCE, Alexander the Great conquered the Phoenician city of Tyre after a seven-month siege, marking the end of Phoenician independence.",
      "date": "-0332"
    },
    {
      "headline": "Roman Conquest",
      "text": "By 64 BCE, the Phoenician territories were incorporated into the Roman Empire, marking the end of Phoenician political autonomy.",
      "date": "-0064"
    }
  ]
}

