    },
    {
      "headline": "Joins the Nazi Party",
      "text": "On November 12, 1937, von Braun joined the Nazi Party.",
      "date": "1937-11-12"
    },
    {
      "headline": "Develops the V-2 Rocket",
      "text": "During World War II, von Braun was the technical director of the Peenemünde Army Research Center, where he led the development of the V-2 rocket, the world's first long-range guided ballistic missile.",
      "date": "1944"
    },
    {
      "headline": "Surrenders to American forces",
      "text": "On May 2, 1945, von Braun and his team surrendered to American forces in Austria.",
      "date": "1945-05-02"
    },
    {
      "headline": "Moves to the United States under Operation Paperclip",
      "text": "In 1945, von Braun was brought to the United States as part of Operation Paperclip, a secret program to recruit scientists from Nazi Germany.",
      "date": "1945"
    },
    {
      "headline": "Becomes a U.S. citizen",
      "text": "On April 14, 1955, von Braun became a naturalized citizen of the United States.",
      "date": "1955-04-14"
    },
    {
      "headline": "Launch of Explorer 1",
      "text": "On January 31, 1958, von Braun's team successfully launched Explorer 1, the first American satellite, into orbit.",
      "date": "1958-01-31"
    },
    {
      "headline": "Appointed Director of NASA's Marshall Space Flight Center",
      "text": "In 1960, von Braun was appointed the first Director of NASA's Marshall Space Flight Center in Huntsville, Alabama.",
      "date": "1960"
