{
  "timeline": [
    {
      "headline": "Kyōtoku Incident",
      "text": "The Kyōtoku Incident occurred in 1454, marking the beginning of the Sengoku period. It was a conflict between the Ashikaga shogunate and the Kantō kubō, a branch of the Ashikaga family.",
      "date": "1454"
    },
    {
      "headline": "Ōnin War Begins",
      "text": "The Ōnin War began in 1467, a major civil war that lasted for ten years and led to the collapse of central authority in Japan, further intensifying the Sengoku period.",
      "date": "1467"
    },
    {
      "headline": "Ōnin War Ends",
      "text": "The Ōnin War ended in 1477, leaving Kyoto devastated and the Ashikaga shogunate weakened, which contributed to the ongoing chaos of the Sengoku period.",
      "date": "1477"
    },
    {
      "headline": "Meiō Incident",
      "text": "The Meiō Incident occurred in 1493, a political coup that further destabilized the Ashikaga shogunate and contributed to the power struggles of the Sengoku period.",
      "date": "1493"
    },
    {
      "headline": "Oda Nobunaga's March on Kyoto",
      "text": "In 1568, Oda Nobunaga marched on Kyoto, marking a significant turning point in the Sengoku period as he began to consolidate power and restore central authority.",
      "date": "1568"
    },
    {
      "headline": "Battle of Sekigahara",
      "text": "The Battle of Sekigahara took place in 1600, a decisive conflict that led to the establishment of the Tokugawa shogunate, effectively ending the Sengoku period.",
      "date": "1600"
    },
    {
      "headline": "Suppression of the Shimabara Rebellion",
      "text": "The suppression of the Shimabara Rebellion in 1638 marked the final end of the Sengoku period, as it was a significant event deep into the Edo period.",
      "date": "1638"
    }
  ]
}

