      "headline": "First Major Commission",
      "text": "In 1599, Caravaggio received his first major public commission to decorate the Contarelli Chapel in the Church of San Luigi dei Francesi in Rome.",
      "date": "1599"
    },
    {
      "headline": "Completion of 'The Calling of Saint Matthew'",
      "text": "Caravaggio completed 'The Calling of Saint Matthew' in 1600, one of his most famous works.",
      "date": "1600"
    },
    {
      "headline": "Murder and Flight from Rome",
      "text": "In 1606, Caravaggio killed a man named Ranuccio Tomassoni in a brawl and fled Rome to avoid prosecution.",
      "date": "1606"
    },
    {
      "headline": "Arrival in Naples",
      "text": "Caravaggio arrived in Naples in 1606, where he continued to paint and received several commissions.",
      "date": "1606"
    },
    {
      "headline": "Knighthood in Malta",
      "text": "In 1608, Caravaggio was knighted by the Grand Master of the Knights of Malta.",
      "date": "1608"
    },
    {
      "headline": "Imprisonment and Escape from Malta",
      "text": "Later in 1608, Caravaggio was imprisoned in Malta but managed to escape to Sicily.",
      "date": "1608"
    },
    {
      "headline": "Return to Naples",
      "text": "Caravaggio returned to Naples in 1609, where he was involved in a violent incident that left him severely injured.",
      "date": "1609"
    },
    {
      "headline": "Death of Caravaggio",
      "text": "Caravaggio died on July 18, 1610, in Porto Ercole, Tuscany, under mysterious circumstances.",
      "date": "1610-07-18"
    }
  ]
}

