{
  "timeline": [
    {
      "headline": "Emergence of Urdu",
      "text": "Urdu began to emerge as a distinct language in the 12th century in the region of Delhi, India, as a result of the interaction between local Indo-Aryan languages and Persian, Arabic, and Turkic languages brought by Muslim conquerors.",
      "date": "1100"
    },
    {
      "headline": "Development under the Delhi Sultanate",
      "text": "During the Delhi Sultanate (1206-1526), Urdu developed further as a lingua franca in the Indian subcontinent, incorporating elements from Persian, Arabic, and Turkic languages.",
      "date": "1206"
    },
    {
      "headline": "Urdu in the Mughal Empire",
      "text": "Under the Mughal Empire (1526-1857), Urdu continued to evolve and was used in the royal courts. It became a symbol of cultural and literary expression, with poets like Mirza Ghalib and Mir Taqi Mir contributing to its literature.",
      "date": "1526"
    },
    {
      "headline": "Urdu as a Literary Language",
      "text": "By the 18th century, Urdu had established itself as a major literary language in South Asia, with a rich tradition of poetry and prose.",
      "date": "1700"
    },
    {
      "headline": "British Colonial Period",
      "text": "During British rule in India (1858-1947), Urdu was promoted as a language of administration and education in northern India, alongside English and Hindi.",
      "date": "1858"
    },
    {
      "headline": "Partition of India and Pakistan",
      "text": "In 1947, with the partition of India and the creation of Pakistan, Urdu was declared the national language of Pakistan. It became a symbol of national identity and unity.",
      "date": "1947"
    },
    {
      "headline": "Urdu in the Constitution of India",
      "text": "In 1950, the Constitution of India recognized Urdu as one of the 22 scheduled languages, acknowledging its cultural and historical significance in the country.",
      "date": "1950"
    },
    {
      "headline": "Urdu as an Official Language in Indian States",
      "text": "Urdu holds official language status in several Indian states, including Jammu and Kashmir, Telangana, Uttar Pradesh, Bihar, and West Bengal, reflecting its widespread use and cultural importance.",
      "date": "1950"
    }
  ]
}

