{
  "timeline": [
    {
      "headline": "First Recorded Use of Psilocybin Mushrooms",
      "text": "The use of psilocybin mushrooms dates back to prehistoric times, with evidence of their use in religious ceremonies and rituals. The earliest known depictions of mushrooms in rock art are found in the Sahara desert and are estimated to be from 7000 to 9000 years ago.",
      "date": "-07000"
    },
    {
      "headline": "Mesoamerican Use of Psilocybin Mushrooms",
      "text": "Psilocybin mushrooms were used by indigenous peoples in Mesoamerica for religious and spiritual purposes. The Aztecs referred to them as 'teonanácatl', meaning 'flesh of the gods'.",
      "date": "1500"
    },
    {
      "headline": "Spanish Conquest and Suppression",
      "text": "During the Spanish conquest of the Americas in the 16th century, the use of psilocybin mushrooms was suppressed by Christian missionaries who considered them heretical.",
      "date": "1521"
    },
    {
      "headline": "Rediscovery by Western Society",
      "text": "In 1955, R. Gordon Wasson, an American banker and amateur mycologist, participated in a mushroom ceremony in Mexico and later published an article in Life magazine, bringing psilocybin mushrooms to the attention of Western society.",
      "date": "1955"
    },
    {
      "headline": "Isolation of Psilocybin",
      "text": "In 1958, Swiss chemist Albert Hofmann, who also discovered LSD, successfully isolated psilocybin and psilocin as the active compounds in psilocybin mushrooms.",
      "date": "1958"
    },
    {
      "headline": "Psilocybin Becomes a Controlled Substance",
      "text": "In 1970, the United States classified psilocybin as a Schedule I controlled substance under the Controlled Substances Act, making it illegal to possess, distribute, or manufacture.",
      "date": "1970"
    },
    {
      "headline": "Renewed Scientific Interest",
      "text": "In the 2000s, there was a resurgence of scientific interest in psilocybin mushrooms, with studies exploring their potential therapeutic benefits for conditions such as depression, anxiety, and PTSD.",
      "date": "2000"
    },
    {
      "headline": "Decriminalization Efforts",
      "text": "In 2019, Denver, Colorado became the first U.S. city to decriminalize psilocybin mushrooms, followed by other cities and states considering similar measures.",
      "date": "2019"
    }
  ]
}

