{
  "timeline": [
    {
      "headline": "Birth of Joseph Smith",
      "text": "Joseph Smith, the founder of Mormonism, was born on December 23, 1805, in Sharon, Vermont.",
      "date": "1805-12-23"
    },
    {
      "headline": "First Vision",
      "text": "In the spring of 1820, Joseph Smith reported having a vision in which God the Father and Jesus Christ appeared to him, an event known as the First Vision.",
      "date": "1820"
    },
    {
      "headline": "Angel Moroni's Visit",
      "text": "On September 21, 1823, Joseph Smith claimed to have been visited by an angel named Moroni, who told him about golden plates containing the history of ancient American peoples.",
      "date": "1823-09-21"
    },
    {
      "headline": "Translation of the Book of Mormon",
      "text": "Between 1827 and 1829, Joseph Smith translated the golden plates into what would become the Book of Mormon, published in 1830.",
      "date": "1827"
    },
    {
      "headline": "Publication of the Book of Mormon",
      "text": "The Book of Mormon was published on March 26, 1830, in Palmyra, New York.",
      "date": "1830-03-26"
    },
    {
      "headline": "Founding of the Church",
      "text": "On April 6, 1830, Joseph Smith and five others formally organized the Church of Christ, later known as The Church of Jesus Christ of Latter-day Saints, in Fayette, New York.",
      "date": "1830-04-06"
    },
    {
      "headline": "Move to Kirtland, Ohio",
      "text": "In 1831, Joseph Smith and his followers moved to Kirtland, Ohio, which became one of the early centers of the Latter Day Saint movement.",
      "date": "1831"
    },
    {
      "headline": "Establishment of Zion in Missouri",
      "text": "In 1831, Joseph Smith declared Independence, Missouri, as the location for the city of Zion, a gathering place for the Saints.",
      "date": "1831"
    },
    {
      "headline": "Kirtland Temple Dedicated",
      "text": "The Kirtland Temple, the first temple built by the Latter Day Saints, was dedicated on March 27, 1836.",
      "date": "1836-03-27"
    },
    {
      "headline": "Exodus to Nauvoo, Illinois",
      "text": "Following persecution in Missouri, the Latter Day Saints moved to Nauvoo, Illinois, in 1839, where they built a new community.",
      "date": "1839"
    },
    {
      "headline": "Joseph Smith's Death",
      "text": "Joseph Smith was killed by a mob on June 27, 1844, in Carthage, Illinois.",
      "date": "1844-06-27"
    },
    {
      "headline": "Brigham Young Leads Exodus to Utah",
      "text": "In 1846, Brigham Young led the Latter Day Saints on a westward migration to the Salt Lake Valley in present-day Utah.",
      "date": "1846"
    },
    {
      "headline": "Settlement in Salt Lake Valley",
      "text": "The first group of Latter Day Saints arrived in the Salt Lake Valley on July 24, 1847, marking the beginning of settlement in Utah.",
      "date": "1847-07-24"
    },
    {
      "headline": "Utah War",
      "text": "The Utah War, a confrontation between Mormon settlers in the Utah Territory and the United States government, occurred from 1857 to 1858.",
      "date": "1857"
    },
    {
      "headline": "Manifesto Ending Polygamy",
      "text": "In 1890, the LDS Church issued the Manifesto, officially ending the practice of polygamy.",
      "date": "1890"
    },
    {
      "headline": "Utah Becomes a State",
      "text": "On January 4, 1896, Utah was admitted to the United States as the 45th state.",
      "date": "1896-01-04"
    },
    {
      "headline": "LDS Church's Name Emphasis",
      "text": "In 2018, the LDS Church emphasized the use of its full name, The Church of Jesus Christ of Latter-day Saints, and discouraged the use of the term 'Mormonism.'",
      "date": "2018"
    }
  ]
}

