{
  "timeline": [
    {
      "headline": "Start of the Boxer Rebellion",
      "text": "The Boxer Rebellion began in North China in 1899 as an anti-foreign, anti-imperialist, and anti-Christian uprising by the Society of Righteous and Harmonious Fists.",
      "date": "1899"
    },
    {
      "headline": "Expansion of the Rebellion",
      "text": "By late 1899 and early 1900, the Boxer Rebellion expanded as Boxers attacked foreign nationals and Chinese Christians, leading to widespread violence and chaos.",
      "date": "1900"
    },
    {
      "headline": "Siege of the Legations",
      "text": "On June 20, 1900, the Boxers, supported by Qing troops, laid siege to the foreign legation quarter in Beijing, trapping diplomats, civilians, and soldiers.",
      "date": "1900-06-20"
    },
    {
      "headline": "Declaration of War by Empress Dowager Cixi",
      "text": "On June 21, 1900, Empress Dowager Cixi declared war on all foreign nations with diplomatic ties to China, aligning the Qing dynasty with the Boxers.",
      "date": "1900-06-21"
    },
    {
      "headline": "Formation of the Eight-Nation Alliance",
      "text": "In response to the Boxer Rebellion, an Eight-Nation Alliance consisting of Japan, Russia, Britain, France, the United States, Germany, Italy, and Austria-Hungary was formed to intervene.",
      "date": "1900"
    },
    {
      "headline": "Battle of Tientsin",
      "text": "On July 14, 1900, the Eight-Nation Alliance captured the city of Tientsin (Tianjin) after a fierce battle, marking a turning point in the conflict.",
      "date": "1900-07-14"
    },
    {
      "headline": "Relief of the Legations",
      "text": "On August 14, 1900, the Eight-Nation Alliance forces relieved the siege of the foreign legations in Beijing, effectively ending the Boxer Rebellion.",
      "date": "1900-08-14"
    },
    {
      "headline": "Signing of the Boxer Protocol",
      "text": "On September 7, 1901, the Boxer Protocol was signed, ending the Boxer Rebellion. It imposed severe penalties and indemnities on China.",
      "date": "1901-09-07"
    }
  ]
}

{
  "timeline": [
    {
      "headline": "First Michelin Guide Published",
      "text": "The first Michelin Guide was published in 1900 by the French tire company Michelin. It was originally intended to help drivers maintain their cars, find decent lodging, and eat well while touring France.",
      "date": "1900"
    },
    {
      "headline": "Introduction of Star Ratings",
      "text": "In 1926, the Michelin Guide began to award stars for fine dining establishments. Initially, only a single star was awarded.",
      "date": "1926"
    },
    {
      "headline": "Three-Star Rating System Introduced",
      "text": "In 1931, the Michelin Guide introduced the hierarchy of zero, one, two, and three stars, with three stars being the highest honor.",
      "date": "1931"
    },
    {
      "headline": "Publication of Green Guides",
      "text": "Michelin began publishing the Green Guides, a series of general guides to cities, regions, and countries, in 1926.",
      "date": "1926"
    },
    {
      "headline": "Suspension During World War II",
      "text": "The publication of the Michelin Guide was suspended during World War II, from 1940 to 1944.",
      "date": "1940"
    },
    {
      "headline": "Post-War Resumption",
      "text": "The Michelin Guide resumed publication in 1945 after the end of World War II.",
      "date": "1945"
    },
    {
      "headline": "Expansion Beyond France",
      "text": "In 1956, the Michelin Guide expanded beyond France, starting with the publication of a guide for Italy.",
      "date": "1956"
