{
  "timeline": [
    {
      "headline": "Formation of the American Mafia",
      "text": "The American Mafia began to take shape in the late 19th and early 20th centuries as Italian immigrants, particularly Sicilians, settled in the United States and organized into criminal groups.",
      "date": "1900"
    },
    {
      "headline": "Prohibition Era",
      "text": "During the Prohibition era (1920-1933), the American Mafia expanded its operations significantly by engaging in bootlegging, which involved the illegal production and distribution of alcohol.",
      "date": "1920"
    },
    {
      "headline": "Castellammarese War",
      "text": "The Castellammarese War was a bloody power struggle for control of the Italian-American Mafia that took place in New York City from 1929 to 1931. It ended with the establishment of the Commission, a governing body for organized crime.",
      "date": "1931"
    },
    {
      "headline": "Establishment of The Commission",
      "text": "In 1931, after the end of the Castellammarese War, the American Mafia established The Commission, a governing body to oversee Mafia activities and mediate disputes among families.",
      "date": "1931"
    },
    {
      "headline": "Apalachin Meeting",
      "text": "On November 14, 1957, a meeting of high-level Mafia leaders from across the United States was raided by law enforcement in Apalachin, New York. This event exposed the existence of the Mafia to the public.",
      "date": "1957-11-14"
    },
    {
      "headline": "Valachi Hearings",
      "text": "In 1963, Joseph Valachi, a member of the American Mafia, testified before a U.S. Senate committee, publicly confirming the existence of the Mafia and providing details about its operations.",
      "date": "1963"
    },
    {
      "headline": "RICO Act Enactment",
      "text": "The Racketeer Influenced and Corrupt Organizations (RICO) Act was enacted in 1970, providing law enforcement with powerful tools to combat organized crime, including the American Mafia.",
      "date": "1970"
    },
    {
      "headline": "The Mafia Commission Trial",
      "text": "From 1985 to 1986, the Mafia Commission Trial took place, leading to the conviction of several top Mafia leaders under the RICO Act, significantly weakening the American Mafia's power.",
      "date": "1985"
    },
    {
      "headline": "Decline of the American Mafia",
      "text": "By the late 20th and early 21st centuries, the American Mafia's influence had significantly declined due to law enforcement efforts, internal conflicts, and competition from other criminal organizations.",
      "date": "2000"
    }
  ]
}

