{
  "timeline": [
    {
      "headline": "Founding of Sunda Kelapa",
      "text": "Sunda Kelapa, the port that would eventually become Jakarta, was founded as a trading port of the Sunda Kingdom. It was an important hub for trade with other regions in Southeast Asia.",
      "date": "-0397"
    },
    {
      "headline": "Portuguese Arrival",
      "text": "In 1522, the Portuguese signed a treaty with the Sunda Kingdom to build a fort at Sunda Kelapa, marking the beginning of European influence in the region.",
      "date": "1522"
    },
    {
      "headline": "Conquest by Fatahillah",
      "text": "In 1527, Fatahillah, a commander from the Sultanate of Demak, conquered Sunda Kelapa and renamed it Jayakarta.",
      "date": "1527"
    },
    {
      "headline": "Dutch Establish Batavia",
      "text": "In 1619, the Dutch East India Company (VOC) established Batavia on the site of the razed Jayakarta, making it the center of their colonial administration in the East Indies.",
      "date": "1619"
    },
    {
      "headline": "Japanese Occupation",
      "text": "During World War II, the Japanese occupied Batavia in 1942, renaming it Jakarta, and it remained under Japanese control until 1945.",
      "date": "1942"
    },
    {
      "headline": "Indonesian Independence",
      "text": "Following the end of World War II, Indonesia declared its independence on August 17, 1945, and Jakarta became the capital of the newly independent nation.",
      "date": "1945-08-17"
    },
    {
      "headline": "Official Renaming to Jakarta",
      "text": "In 1949, following the recognition of Indonesian sovereignty by the Dutch, Batavia was officially renamed Jakarta.",
      "date": "1949"
    },
    {
      "headline": "Jakarta Becomes a Special Capital Region",
      "text": "In 1966, Jakarta was granted the status of a special capital region, giving it a level of autonomy similar to that of a province.",
      "date": "1966"
    },
    {
      "headline": "Asian Games 1962",
      "text": "Jakarta hosted the 4th Asian Games in 1962, marking a significant event in the city's history as it showcased its development and modernization.",
      "date": "1962"
    },
    {
      "headline": "ASEAN Secretariat Established",
      "text": "In 1976, the ASEAN Secretariat was established in Jakarta, reinforcing the city's role as a diplomatic hub in Southeast Asia.",
      "date": "1976"
    },
    {
      "headline": "Reformation Era",
      "text": "The Reformation Era began in 1998, following the fall of President Suharto, leading to significant political and social changes in Jakarta and Indonesia.",
      "date": "1998"
    },
    {
      "headline": "Jakarta Hosts Asian Games 2018",
      "text": "Jakarta co-hosted the 18th Asian Games in 2018, further solidifying its status as a major city in Asia.",
      "date": "2018"
    }
  ]
}

