{
  "timeline": [
    {
      "headline": "Establishment of the Silk Road",
      "text": "The Silk Road was established during the Han Dynasty of China, around the second century BCE, facilitating trade and cultural exchange between the East and West.",
      "date": "-0200"
    },
    {
      "headline": "Expansion under the Roman Empire",
      "text": "During the Roman Empire, the Silk Road expanded significantly, with Roman demand for Chinese silk driving trade along these routes. This expansion occurred around the first century CE.",
      "date": "0001"
    },
    {
      "headline": "Height of the Silk Road",
      "text": "The Silk Road reached its height during the Tang Dynasty (618-907 CE), when trade and cultural exchanges flourished between China and the West.",
      "date": "0618"
    },
    {
      "headline": "Spread of Buddhism",
      "text": "Buddhism spread along the Silk Road from India to China and other parts of Asia, facilitated by the movement of monks and traders, particularly during the first few centuries CE.",
      "date": "0200"
    },
    {
      "headline": "Mongol Empire and the Pax Mongolica",
      "text": "During the 13th and 14th centuries, the Mongol Empire established the Pax Mongolica, which provided security and stability along the Silk Road, enhancing trade and cultural exchange.",
      "date": "1200"
    },
    {
      "headline": "Decline of the Silk Road",
      "text": "The decline of the Silk Road began in the mid-15th century due to the rise of maritime trade routes and the fall of the Mongol Empire, which disrupted overland trade.",
      "date": "1450"
    },
    {
      "headline": "Coining of the Term 'Silk Road'",
      "text": "The term 'Silk Road' was coined by the German geographer Ferdinand von Richthofen in the late 19th century to describe the trade routes connecting the East and West.",
      "date": "1877"
    }
  ]
}

