      "headline": "Birth of Patty Hearst",
      "text": "Patricia Campbell Hearst was born on February 20, 1954, in San Francisco, California, USA.",
      "date": "1954-02-20"
    },
    {
      "headline": "Kidnapping by the Symbionese Liberation Army",
      "text": "On February 4, 1974, Patty Hearst was kidnapped from her apartment in Berkeley, California, by the Symbionese Liberation Army (SLA), a left-wing terrorist group.",
      "date": "1974-02-04"
    },
    {
      "headline": "Announcement of Joining the SLA",
      "text": "On April 3, 1974, Patty Hearst announced in an audio tape that she had joined the Symbionese Liberation Army and adopted the name 'Tania'.",
      "date": "1974-04-03"
    },
    {
      "headline": "Involvement in Hibernia Bank Robbery",
      "text": "On April 15, 1974, Patty Hearst was photographed participating in a bank robbery at the Hibernia Bank in San Francisco, alongside other SLA members.",
      "date": "1974-04-15"
    },
    {
      "headline": "Arrest of Patty Hearst",
      "text": "Patty Hearst was arrested on September 18, 1975, in San Francisco by the FBI after being on the run for 19 months.",
      "date": "1975-09-18"
    },
    {
      "headline": "Trial and Conviction",
      "text": "On March 20, 1976, Patty Hearst was convicted of bank robbery and using a firearm during the commission of a felony. She was sentenced to seven years in prison.",
      "date": "1976-03-20"
    },
    {
      "headline": "Commutation of Sentence",
      "text": "On February 1, 1979, President Jimmy Carter commuted Patty Hearst's sentence, reducing it to time served. She was released from prison after serving 22 months.",
      "date": "1979-02-01"
    },
    {
      "headline": "Presidential Pardon",
      "text": "On January 20, 2001, Patty Hearst was granted a full pardon by President Bill Clinton on his last day in office.",
      "date": "2001-01-20"
    }
  ]
}

