{
  "timeline": [
    {
      "headline": "Arrival of Anatomically Modern Humans",
      "text": "Anatomically modern humans first arrived on the Indian subcontinent between 73,000 and 55,000 years ago.",
      "date": "-073000"
    },
    {
      "headline": "Earliest Known Human Remains",
      "text": "The earliest known human remains in South Asia date to 30,000 years ago.",
      "date": "-030000"
    },
    {
      "headline": "Beginning of Sedentariness",
      "text": "Sedentariness began in South Asia around 7000 BCE.",
      "date": "-07000"
    },
    {
      "headline": "Spread of Settled Life",
      "text": "By 4500 BCE, settled life had spread across South Asia.",
      "date": "-04500"
    },
    {
      "headline": "Indus Valley Civilisation",
      "text": "The Indus Valley Civilisation, one of the early cradles of civilisation, flourished between 2500 BCE and 1900 BCE in present-day Pakistan and north-western India.",
      "date": "-02500"
    },
    {
      "headline": "Decline of Indus Valley Civilisation",
      "text": "Early in the second millennium BCE, persistent drought caused the population of the Indus Valley to scatter from large urban centres to villages.",
      "date": "-02000"
    },
    {
      "headline": "Indo-Aryan Migration",
      "text": "Indo-Aryan tribes moved into the Punjab from Central Asia in several waves of migration.",
      "date": "-01500"
    },
    {
      "headline": "Vedic Period",
      "text": "The Vedic Period was marked by the composition of the Vedas and the development of the varna system, which evolved into the present-day Jāti system.",
      "date": "-01500"
    },
    {
      "headline": "Expansion into the Gangetic Plain",
      "text": "The pastoral and nomadic Indo-Aryans spread from the Punjab into the Gangetic plain.",
      "date": "-01000"
    },
    {
      "headline": "Rise of Mahajanapadas",
      "text": "Around 600 BCE, small chieftaincies (janapadas) were consolidated into larger states (mahajanapadas).",
      "date": "-0600"
    },
    {
      "headline": "Second Urbanization",
      "text": "The second urbanization took place around 600 BCE, leading to the rise of new ascetic movements and religious concepts, including Jainism and Buddhism.",
      "date": "-0600"
    },
    {
      "headline": "Synthesis into Hinduism",
      "text": "Buddhism and other religious movements were synthesized with preexisting religious cultures, giving rise to Hinduism.",
      "date": "-0500"
    }
  ]
}

