{
  "timeline": [
    {
      "headline": "Establishment of Yellowstone National Park",
      "text": "Yellowstone National Park was established by the 42nd U.S. Congress through the Yellowstone National Park Protection Act and signed into law by President Ulysses S. Grant on March 1, 1872. It became the first national park in the United States and is widely considered the first national park in the world.",
      "date": "1872-03-01"
    },
    {
      "headline": "First Superintendent Appointed",
      "text": "Nathaniel P. Langford was appointed as the first superintendent of Yellowstone National Park in 1872. However, he served without a salary and had no funding to enforce regulations.",
      "date": "1872"
    },
    {
      "headline": "First U.S. Army Protection",
      "text": "In 1886, the U.S. Army was tasked with managing Yellowstone National Park due to lack of funding and enforcement issues. The Army's presence continued until the National Park Service was established.",
      "date": "1886"
    },
    {
      "headline": "Creation of the National Park Service",
      "text": "On August 25, 1916, the National Park Service was created by the National Park Service Organic Act, which provided a dedicated agency to manage national parks, including Yellowstone.",
      "date": "1916-08-25"
    },
    {
      "headline": "Old Faithful Inn Construction",
      "text": "The Old Faithful Inn, a historic hotel located in Yellowstone National Park, was completed in 1904. It is one of the most famous structures in the park and a prime example of National Park Service Rustic architecture.",
      "date": "1904"
    },
    {
      "headline": "Yellowstone Fire of 1988",
      "text": "In 1988, Yellowstone National Park experienced a series of large wildfires that burned approximately 36% of the park. The fires were part of a larger series of fires that affected the Greater Yellowstone Ecosystem.",
      "date": "1988"
    },
    {
      "headline": "UNESCO World Heritage Site Designation",
      "text": "Yellowstone National Park was designated a UNESCO World Heritage Site in 1978, recognizing its global significance as a natural area.",
      "date": "1978"
    }
  ]
}

