    {
      "headline": "Recruitment Begins",
      "text": "Recruitment for the Black and Tans began in Great Britain in January 1920. They were recruited as reinforcements for the Royal Irish Constabulary (RIC) during the Irish War of Independence.",
      "date": "1920-01"
    },
    {
      "headline": "Deployment to Ireland",
      "text": "The Black and Tans were deployed to Ireland in March 1920 to assist in quelling the Irish War of Independence. They were known for their harsh tactics and were involved in numerous controversial incidents.",
      "date": "1920-03"
    },
    {
      "headline": "Croke Park Massacre",
      "text": "On November 21, 1920, the Black and Tans were involved in the Croke Park Massacre, where they opened fire on a crowd at a Gaelic football match, killing 14 civilians.",
      "date": "1920-11-21"
    },
    {
      "headline": "Burning of Cork",
      "text": "In December 1920, the Black and Tans were implicated in the Burning of Cork, where they set fire to numerous buildings in the city, causing extensive damage.",
      "date": "1920-12"
    },
    {
      "headline": "Government of Ireland Act 1920",
      "text": "The Government of Ireland Act was passed in December 1920, which aimed to establish separate Home Rule institutions for Northern and Southern Ireland. The Black and Tans continued their operations amidst these political changes.",
      "date": "1920-12"
    },
    {
      "headline": "Truce and Anglo-Irish Treaty",
      "text": "A truce was declared on July 11, 1921, leading to the signing of the Anglo-Irish Treaty in December 1921. The Black and Tans were gradually disbanded following the treaty.",
      "date": "1921-07-11"
    },
    {
      "headline": "Disbandment",
      "text": "The Black and Tans were officially disbanded in 1922 following the establishment of the Irish Free State and the end of the Irish War of Independence.",
      "date": "1922"
    }
  ]
}

