    {
      "headline": "Christmas Declared a Federal Holiday in the United States",
      "text": "On June 26, 1870, Christmas was declared a federal holiday in the United States.",
      "date": "1870-06-26"
    },
    {
      "headline": "Introduction of Christmas Trees",
      "text": "The tradition of decorating Christmas trees became popular in the 19th century, particularly after Queen Victoria and Prince Albert were depicted with a Christmas tree in 1848.",
      "date": "1848"
