    {
      "headline": "Early Mentions of Ninja",
      "text": "The earliest recorded use of the term 'ninja' dates back to the 12th century, during the late Heian period in Japan. These early mentions describe individuals skilled in espionage and unconventional warfare.",
      "date": "-1100"
    },
    {
      "headline": "Rise of Ninja during the Sengoku Period",
      "text": "The Sengoku period (1467–1615) saw the rise of ninja as mercenaries and spies. They were employed by samurai and warlords for espionage, sabotage, and assassination missions.",
      "date": "1467"
    },
    {
      "headline": "Ninja Clans",
      "text": "During the Sengoku period, prominent ninja clans such as the Iga and Koga emerged. These clans were known for their specialized training and skills in stealth and guerrilla tactics.",
      "date": "1500"
    },
    {
      "headline": "Ninja in the Azuchi-Momoyama Period",
      "text": "In the late 16th century, during the Azuchi-Momoyama period, ninja were employed by powerful figures like Oda Nobunaga and Tokugawa Ieyasu for intelligence gathering and military operations.",
      "date": "1573"
    },
    {
      "headline": "Decline of Ninja",
      "text": "With the unification of Japan under the Tokugawa shogunate in the early 17th century, the demand for ninja services declined as the country entered a period of peace known as the Edo period.",
      "date": "1603"
    },
    {
      "headline": "Cultural Legacy of Ninja",
      "text": "Despite their decline, the legacy of ninja continued through folklore, literature, and later popular culture, where they were often romanticized as mysterious and skilled warriors.",
      "date": "1700"
    }
  ]
}

