{
  "timeline": [
    {
      "headline": "Establishment of the Holy See",
      "text": "The Holy See was established as the central governing body of the Catholic Church, traditionally considered to have been founded by Saint Peter, one of the twelve apostles of Jesus, in the 1st century.",
      "date": "0001"
    },
    {
      "headline": "Edict of Milan",
      "text": "In 313, the Edict of Milan was issued by Emperor Constantine, granting religious tolerance throughout the Roman Empire and allowing the Christian Church to own property, significantly impacting the status of the Holy See.",
      "date": "0313"
    },
    {
      "headline": "Donation of Pepin",
      "text": "In 756, the Donation of Pepin provided the Papal States to the Holy See, granting it temporal power over a significant territory in Italy.",
      "date": "0756"
    },
    {
      "headline": "First Lateran Council",
      "text": "In 1123, the First Lateran Council was convened, marking the first ecumenical council held in the West and reinforcing the authority of the Holy See.",
      "date": "1123"
    },
    {
      "headline": "Avignon Papacy",
      "text": "From 1309 to 1377, the papacy was based in Avignon, France, rather than Rome, a period known as the Avignon Papacy, which affected the influence and operations of the Holy See.",
      "date": "1309"
    },
    {
      "headline": "Return to Rome",
      "text": "In 1377, Pope Gregory XI returned the papal court to Rome, ending the Avignon Papacy and restoring the Holy See's presence in its traditional location.",
      "date": "1377"
    },
    {
      "headline": "Treaty of the Lateran",
      "text": "On February 11, 1929, the Lateran Treaty was signed between the Holy See and Italy, recognizing Vatican City as an independent sovereign state and resolving the 'Roman Question'.",
      "date": "1929-02-11"
    },
    {
      "headline": "Second Vatican Council",
      "text": "From 1962 to 1965, the Second Vatican Council was held, resulting in significant reforms in the Catholic Church and impacting the role of the Holy See in the modern world.",
      "date": "1962"
    }
  ]
}

