{
  "timeline": [
    {
      "headline": "Khmer Rouge Seizes Power",
      "text": "On April 17, 1975, the Khmer Rouge, led by Pol Pot, captured the Cambodian capital of Phnom Penh, marking the beginning of their rule and the start of the Cambodian genocide.",
      "date": "1975-04-17"
    },
    {
      "headline": "Evacuation of Cities",
      "text": "In April 1975, shortly after taking power, the Khmer Rouge began evacuating cities, forcing millions of people into the countryside to work in collective farms and labor projects.",
      "date": "1975-04"
    },
    {
      "headline": "Establishment of Democratic Kampuchea",
      "text": "In 1976, the Khmer Rouge officially established Democratic Kampuchea, a regime characterized by extreme agrarian socialism and totalitarian control.",
      "date": "1976"
    },
    {
      "headline": "Mass Executions and Purges",
      "text": "Throughout their rule from 1975 to 1979, the Khmer Rouge conducted mass executions and purges, targeting intellectuals, professionals, religious groups, and ethnic minorities.",
      "date": "1975"
    },
    {
      "headline": "Fall of the Khmer Rouge",
      "text": "On January 7, 1979, Vietnamese forces captured Phnom Penh, leading to the collapse of the Khmer Rouge regime and the end of the genocide.",
      "date": "1979-01-07"
    },
    {
      "headline": "Estimates of Death Toll",
      "text": "By the end of the genocide in 1979, it is estimated that 1.5 to 2 million people, nearly 25% of Cambodia's population, had died due to the policies of the Khmer Rouge.",
      "date": "1979"
    },
    {
      "headline": "Establishment of the People's Republic of Kampuchea",
      "text": "Following the fall of the Khmer Rouge, the People's Republic of Kampuchea was established with Vietnamese support, marking the beginning of a new era in Cambodian history.",
      "date": "1979"
    }
  ]
}

