{
  "timeline": [
    {
      "headline": "First Mention of Damascus",
      "text": "Damascus is first mentioned in the historical record in the 2nd millennium BCE as a city in the ancient Near East.",
      "date": "-2000"
    },
    {
      "headline": "Conquest by the Arameans",
      "text": "Around 1100 BCE, Damascus was conquered by the Arameans, who established it as the capital of the Aramean kingdom.",
      "date": "-1100"
    },
    {
      "headline": "Assyrian Conquest",
      "text": "In 732 BCE, Damascus was conquered by the Neo-Assyrian Empire under Tiglath-Pileser III.",
      "date": "-0732"
    },
    {
      "headline": "Incorporation into the Achaemenid Empire",
      "text": "In 539 BCE, Damascus became part of the Achaemenid Empire after the conquest of Babylon by Cyrus the Great.",
      "date": "-0539"
    },
    {
      "headline": "Conquest by Alexander the Great",
      "text": "In 333 BCE, Damascus was conquered by Alexander the Great during his campaign against the Persian Empire.",
      "date": "-0333"
    },
    {
      "headline": "Roman Control",
      "text": "In 64 BCE, Damascus was annexed by the Roman Republic under Pompey the Great.",
      "date": "-0064"
    },
    {
      "headline": "Islamic Conquest",
      "text": "In 634 CE, Damascus was conquered by Muslim Arab forces under Khalid ibn al-Walid during the early Islamic conquests.",
      "date": "0634"
    },
    {
      "headline": "Umayyad Caliphate Capital",
      "text": "In 661 CE, Damascus became the capital of the Umayyad Caliphate under Caliph Muawiya I.",
      "date": "0661"
    },
    {
      "headline": "Abbasid Caliphate Control",
      "text": "In 750 CE, the Abbasid Caliphate overthrew the Umayyads and moved the capital to Baghdad, reducing Damascus's political significance.",
      "date": "0750"
    },
    {
      "headline": "Mamluk Rule",
      "text": "In 1260 CE, Damascus came under the control of the Mamluk Sultanate after the defeat of the Mongols at the Battle of Ain Jalut.",
      "date": "1260"
    },
    {
      "headline": "Ottoman Empire Control",
      "text": "In 1516 CE, Damascus was incorporated into the Ottoman Empire following the Battle of Marj Dabiq.",
      "date": "1516"
    },
    {
      "headline": "French Mandate",
      "text": "In 1920 CE, following World War I, Damascus became part of the French Mandate for Syria and the Lebanon.",
      "date": "1920"
    },
    {
      "headline": "Independence of Syria",
      "text": "In 1946 CE, Syria gained independence from French control, and Damascus became the capital of the newly independent country.",
      "date": "1946"
    }
  ]
}

