    {
      "headline": "Promotion to SS-Obergruppenführer",
      "text": "Phleps was promoted to the rank of SS-Obergruppenführer und General der Waffen-SS, reflecting his high status within the Nazi military hierarchy.",
      "date": "1942"
    },
    {
      "headline": "Death of Artur Phleps",
      "text": "Artur Phleps was killed by Soviet forces on 1944-09-21 near Arad, Romania, during World War II.",
