{
  "timeline": [
    {
      "headline": "Formation of the Wehrmacht",
      "text": "The Wehrmacht was officially formed on March 16, 1935, as the unified armed forces of Nazi Germany, replacing the Reichswehr.",
      "date": "1935-03-16"
    },
    {
      "headline": "Reoccupation of the Rhineland",
      "text": "On March 7, 1936, the Wehrmacht reoccupied the Rhineland, violating the Treaty of Versailles and the Locarno Treaties.",
      "date": "1936-03-07"
    },
    {
      "headline": "Anschluss with Austria",
      "text": "In March 1938, the Wehrmacht entered Austria to enforce the Anschluss, the annexation of Austria into Nazi Germany.",
      "date": "1938-03"
    },
    {
      "headline": "Invasion of Czechoslovakia",
      "text": "On March 15, 1939, the Wehrmacht invaded and occupied Czechoslovakia, further expanding Nazi Germany's territory.",
      "date": "1939-03-15"
    },
    {
      "headline": "Invasion of Poland",
      "text": "The Wehrmacht invaded Poland on September 1, 1939, marking the beginning of World War II.",
      "date": "1939-09-01"
    },
    {
      "headline": "Battle of France",
      "text": "From May 10 to June 25, 1940, the Wehrmacht conducted a successful campaign against France, leading to the occupation of the country.",
      "date": "1940-05-10"
    },
    {
      "headline": "Operation Barbarossa",
      "text": "On June 22, 1941, the Wehrmacht launched Operation Barbarossa, the invasion of the Soviet Union, which became the largest military operation in history.",
      "date": "1941-06-22"
    },
    {
      "headline": "Battle of Stalingrad",
      "text": "The Battle of Stalingrad, one of the deadliest battles in history, took place from August 23, 1942, to February 2, 1943, resulting in a significant defeat for the Wehrmacht.",
      "date": "1942-08-23"
    },
    {
      "headline": "D-Day and the Normandy Invasion",
      "text": "On June 6, 1944, Allied forces launched the Normandy Invasion (D-Day), marking the beginning of the liberation of Western Europe from Nazi occupation.",
      "date": "1944-06-06"
    },
    {
      "headline": "Surrender of the Wehrmacht",
      "text": "The Wehrmacht officially surrendered to the Allied forces on May 8, 1945, marking the end of World War II in Europe.",
      "date": "1945-05-08"
    }
  ]
}

