    {
      "headline": "Implementation of Official Languages Act",
      "text": "In 1969, Trudeau's government passed the Official Languages Act, making Canada officially bilingual.",
      "date": "1969"
    },
    {
      "headline": "October Crisis",
      "text": "In October 1970, Trudeau invoked the War Measures Act during the October Crisis, a period of domestic terrorism in Quebec.",
      "date": "1970-10"
    },
    {
      "headline": "Defeat in Federal Election",
      "text": "Trudeau's Liberal Party was defeated in the federal election on May 22, 1979.",
      "date": "1979-05-22"
