    },
    {
      "headline": "Battle of Prokhorovka",
      "text": "On July 12, 1943, the Battle of Prokhorovka took place, one of the largest tank battles in history, where Soviet forces successfully halted the German advance.",
      "date": "1943-07-12"
    },
    {
      "headline": "Soviet Counteroffensive",
      "text": "Following the failure of the German offensive, the Soviets launched a counteroffensive on July 12, 1943, which eventually led to the recapture of Orel and Belgorod.",
      "date": "1943-07-12"
    },
    {
      "headline": "End of the Battle of Kursk",
      "text": "The Battle of Kursk effectively ended on August 23, 1943, with a decisive Soviet victory that marked a turning point on the Eastern Front.",
      "date": "1943-08-23"
    }
  ]
}

