{
  "timeline": [
    {
      "headline": "Coining of the Term 'Eugenics'",
      "text": "The term 'eugenics' was coined by Sir Francis Galton in 1883. He defined it as the science of improving the human race through selective breeding.",
      "date": "1883"
    },
    {
      "headline": "First International Eugenics Congress",
      "text": "The First International Eugenics Congress was held in London in 1912, bringing together scientists and policymakers to discuss eugenic ideas.",
      "date": "1912"
    },
    {
      "headline": "Eugenics Record Office Established",
      "text": "In 1910, the Eugenics Record Office was established in Cold Spring Harbor, New York, to collect and analyze data on human heredity.",
      "date": "1910"
    },
    {
      "headline": "Eugenics Laws in the United States",
      "text": "By the 1920s, many U.S. states had enacted eugenics laws, including forced sterilization laws targeting those deemed 'unfit'.",
      "date": "1920"
    },
    {
      "headline": "Second International Eugenics Congress",
      "text": "The Second International Eugenics Congress took place in New York City in 1921, further promoting eugenic policies.",
      "date": "1921"
    },
    {
      "headline": "Nazi Germany's Eugenics Program",
      "text": "In the 1930s and 1940s, Nazi Germany implemented a eugenics program that included forced sterilizations and the genocide of groups deemed 'racially inferior'.",
      "date": "1930"
    },
    {
      "headline": "Nuremberg Trials and Eugenics",
      "text": "After World War II, the Nuremberg Trials exposed the atrocities committed under Nazi eugenics policies, leading to a decline in the movement's popularity.",
      "date": "1945"
    },
    {
      "headline": "Decline of Eugenics Movement",
      "text": "Post-World War II, the eugenics movement faced significant backlash due to its association with Nazi atrocities, leading to a decline in its influence.",
      "date": "1945"
    },
    {
      "headline": "Apologies and Reparations",
      "text": "In the late 20th and early 21st centuries, several governments, including the U.S. and Canada, issued apologies and reparations for past eugenics policies.",
      "date": "2000"
    }
  ]
}

