    {
      "headline": "Trademark Registration",
      "text": "On June 16, 1903, the Pepsi-Cola trademark was registered with the U.S. Patent Office.",
      "date": "1903-06-16"
    },
    {
      "headline": "Bankruptcy and New Ownership",
      "text": "In 1923, the Pepsi-Cola Company went bankrupt due to financial difficulties and sugar price fluctuations. The assets were sold to Craven Holding Corporation.",
      "date": "1923"
    },
    {
      "headline": "Acquisition by Loft, Inc.",
      "text": "In 1931, the Pepsi-Cola Company was acquired by Charles Guth, the president of Loft, Inc., a candy manufacturer.",
      "date": "1931"
    },
    {
      "headline": "Introduction of 12-ounce Bottles",
      "text": "In 1934, Pepsi introduced 12-ounce bottles, offering twice the amount of soda for the same price as its competitors, which helped increase its popularity.",
      "date": "1934"
    },
    {
      "headline": "Pepsi-Cola Merges with Frito-Lay",
      "text": "In 1965, Pepsi-Cola merged with Frito-Lay, Inc. to form PepsiCo, Inc., expanding its product line to include snacks.",
      "date": "1965"
    },
    {
      "headline": "Launch of the 'Pepsi Challenge'",
      "text": "In 1975, Pepsi launched the 'Pepsi Challenge', a marketing campaign that involved blind taste tests to prove that consumers preferred Pepsi over Coca-Cola.",
      "date": "1975"
