  "timeline": [
    {
      "headline": "Charter Granted to Sir Walter Raleigh",
      "text": "In 1584, Queen Elizabeth I granted Sir Walter Raleigh a charter to explore and colonize the New World. This charter led to the establishment of the Roanoke Colony.",
      "date": "1584"
    },
    {
      "headline": "First Expedition to Roanoke",
      "text": "In 1585, the first group of settlers, led by Sir Richard Grenville, arrived at Roanoke Island. They established a fort and began the first attempt at colonization.",
      "date": "1585"
    },
    {
      "headline": "Return of Grenville to England",
      "text": "In 1586, Sir Richard Grenville returned to England for supplies, leaving Ralph Lane in charge of the colony.",
      "date": "1586"
    },
    {
      "headline": "Evacuation by Sir Francis Drake",
      "text": "In June 1586, Sir Francis Drake visited the colony and offered to take the settlers back to England. The majority accepted, effectively ending the first attempt at colonization.",
      "date": "1586-06"
    },
    {
      "headline": "Second Attempt at Colonization",
      "text": "In 1587, a second group of settlers, led by John White, arrived at Roanoke Island. This group included women and children, indicating a more permanent settlement was intended.",
      "date": "1587"
    },
    {
      "headline": "Birth of Virginia Dare",
      "text": "On August 18, 1587, Virginia Dare was born. She was the first English child born in the New World.",
      "date": "1587-08-18"
    },
    {
      "headline": "John White Returns to England",
      "text": "In late 1587, John White returned to England to gather more supplies for the colony. His return was delayed due to the Anglo-Spanish War.",
      "date": "1587"
    },
    {
      "headline": "John White's Return to Roanoke",
      "text": "In August 1590, John White returned to Roanoke Island to find the colony deserted with no trace of the settlers, except for the word 'CROATOAN' carved into a post.",
      "date": "1590-08"
    }
  ]
}

