{
  "timeline": [
    {
      "headline": "Discovery of Escherichia coli",
      "text": "Escherichia coli was discovered by Theodor Escherich, a German-Austrian pediatrician and bacteriologist, in 1885. He isolated the bacterium from the feces of healthy individuals and named it Bacterium coli commune.",
      "date": "1885"
    },
    {
      "headline": "Renaming to Escherichia coli",
      "text": "In 1919, the bacterium was renamed Escherichia coli in honor of its discoverer, Theodor Escherich.",
      "date": "1919"
    },
    {
      "headline": "E. coli as a model organism",
      "text": "Throughout the 20th century, Escherichia coli became one of the most studied prokaryotic model organisms in molecular biology and genetics, due to its simple genetics and rapid growth.",
      "date": "1900s"
    },
    {
      "headline": "Identification of pathogenic strains",
      "text": "In the mid-20th century, specific pathogenic strains of E. coli, such as EPEC (Enteropathogenic E. coli) and ETEC (Enterotoxigenic E. coli), were identified, which are responsible for causing foodborne illnesses.",
      "date": "1950s"
    },
    {
      "headline": "E. coli O157:H7 outbreak",
      "text": "In 1982, the strain E. coli O157:H7 was identified as a cause of serious foodborne illness in the United States, leading to increased awareness and research into pathogenic E. coli strains.",
      "date": "1982"
    },
    {
      "headline": "Genome sequencing of E. coli",
      "text": "In 1997, the complete genome of Escherichia coli K-12, a non-pathogenic laboratory strain, was sequenced, providing valuable insights into bacterial genetics and physiology.",
      "date": "1997"
    },
    {
      "headline": "E. coli in biotechnology",
      "text": "Escherichia coli has been extensively used in biotechnology for the production of recombinant proteins, including insulin and other pharmaceuticals, due to its well-understood genetics and ease of cultivation.",
      "date": "2000s"
    }
  ]
}

