    },
    {
      "headline": "Vietnam War Involvement",
      "text": "During the Vietnam War, the Green Berets played a crucial role in training and leading indigenous forces in unconventional warfare against the North Vietnamese Army and Viet Cong. Their involvement spanned from the early 1960s until the end of the war in 1975.",
      "date": "1960-1975"
    },
    {
      "headline": "Operation Urgent Fury",
      "text": "In October 1983, the Green Berets participated in Operation Urgent Fury, the U.S.-led invasion of Grenada, where they conducted reconnaissance and direct action missions.",
      "date": "1983-10"
    },
    {
      "headline": "Operation Just Cause",
      "text": "The Green Berets were involved in Operation Just Cause in December 1989, the U.S. invasion of Panama, where they played a key role in capturing key objectives and supporting conventional forces.",
      "date": "1989-12"
    },
    {
      "headline": "Gulf War Operations",
      "text": "During the Gulf War in 1990-1991, the Green Berets conducted special reconnaissance, direct action, and combat search and rescue missions in support of coalition forces.",
      "date": "1990-1991"
    },
    {
      "headline": "Global War on Terror",
      "text": "Following the September 11 attacks in 2001, the Green Berets were heavily involved in the Global War on Terror, including operations in Afghanistan and Iraq, where they conducted counter-terrorism and unconventional warfare missions.",
