      "headline": "Expansion by Louis XIV",
      "text": "In 1661, King Louis XIV began the expansion of the hunting lodge into a grand palace, marking the start of major construction projects.",
      "date": "1661"
    },
    {
      "headline": "Gardens of Versailles",
      "text": "The gardens of Versailles were designed and laid out by André Le Nôtre starting in 1661, becoming one of the most famous gardens in the world.",
      "date": "1661"
    },
    {
      "headline": "Hall of Mirrors Construction",
      "text": "The construction of the Hall of Mirrors, the most famous room in the Palace, began in 1678 and was completed in 1684.",
      "date": "1678"
    },
    {
      "headline": "Court Moves to Versailles",
      "text": "In 1682, King Louis XIV moved the French court and government to Versailles, making it the de facto capital of France.",
      "date": "1682"
    },
    {
      "headline": "Treaty of Versailles (1783)",
      "text": "The Treaty of Versailles was signed in 1783 in the palace, ending the American Revolutionary War.",
      "date": "1783"
    },
    {
      "headline": "French Revolution Impact",
      "text": "During the French Revolution in 1789, the royal family was forced to leave Versailles, and the palace ceased to be a royal residence.",
      "date": "1789"
    },
    {
      "headline": "Museum of the History of France",
      "text": "In 1837, King Louis-Philippe established the Museum of the History of France in the palace.",
      "date": "1837"
    },
    {
      "headline": "Treaty of Versailles (1919)",
      "text": "The Treaty of Versailles, which ended World War I, was signed in the Hall of Mirrors on June 28, 1919.",
      "date": "1919-06-28"
    },
    {
      "headline": "UNESCO World Heritage Site",
      "text": "The Palace of Versailles was designated as a UNESCO World Heritage Site in 1979.",
      "date": "1979"
    }
  ]
}

