    },
    {
      "headline": "Enrollment at the University of Königsberg",
      "text": "In 1740, Kant enrolled at the University of Königsberg, where he studied the philosophy of Leibniz and Wolff.",
      "date": "1740"
    },
    {
      "headline": "Publication of 'Thoughts on the True Estimation of Living Forces'",
      "text": "In 1747, Kant published his first work, 'Thoughts on the True Estimation of Living Forces', which dealt with the problem of kinetic forces.",
      "date": "1747"
    },
    {
      "headline": "Appointment as a Privatdozent",
      "text": "In 1755, Kant became a Privatdozent (unsalaried lecturer) at the University of Königsberg, where he lectured on a wide range of subjects.",
      "date": "1755"
    },
    {
      "headline": "Publication of 'Critique of Pure Reason'",
      "text": "In 1781, Kant published 'Critique of Pure Reason', a seminal work in modern philosophy that sought to explain the relationship between human experience and knowledge.",
      "date": "1781"
    },
    {
      "headline": "Publication of 'Critique of Practical Reason'",
      "text": "In 1788, Kant published 'Critique of Practical Reason', which focused on his moral philosophy and the concept of duty.",
      "date": "1788"
    },
    {
      "headline": "Publication of 'Critique of Judgment'",
      "text": "In 1790, Kant published 'Critique of Judgment', which addressed aesthetics and teleology.",
      "date": "1790"
    },
