{
  "timeline": [
    {
      "headline": "French Colonization",
      "text": "In 1894, the area that is now the Central African Republic was colonized by France and became part of French Equatorial Africa.",
      "date": "1894"
    },
    {
      "headline": "Formation of Ubangi-Shari",
      "text": "In 1903, the territory was organized as the colony of Ubangi-Shari, named after the Ubangi and Chari rivers.",
      "date": "1903"
    },
    {
      "headline": "World War II and Brazzaville Conference",
      "text": "During World War II, the Brazzaville Conference in 1944 marked a turning point in the relationship between France and its colonies, leading to increased autonomy for territories like Ubangi-Shari.",
      "date": "1944"
    },
    {
      "headline": "Autonomous Republic",
      "text": "In 1958, Ubangi-Shari became an autonomous republic within the French Community and was renamed the Central African Republic.",
      "date": "1958"
    },
    {
      "headline": "Independence",
      "text": "The Central African Republic gained independence from France on August 13, 1960.",
      "date": "1960-08-13"
    },
    {
      "headline": "David Dacko's Presidency",
      "text": "David Dacko became the first President of the Central African Republic after independence in 1960.",
      "date": "1960"
    },
    {
      "headline": "Bokassa's Coup",
      "text": "On January 1, 1966, Jean-Bédel Bokassa led a coup d'état and overthrew President David Dacko, establishing himself as the new leader.",
      "date": "1966-01-01"
    },
    {
      "headline": "Central African Empire",
      "text": "On December 4, 1976, Jean-Bédel Bokassa declared himself Emperor of the newly established Central African Empire.",
      "date": "1976-12-04"
    },
    {
      "headline": "Bokassa's Overthrow",
      "text": "On September 20, 1979, Bokassa was overthrown in a French-backed coup, and David Dacko was reinstated as President.",
      "date": "1979-09-20"
    },
    {
      "headline": "André Kolingba's Rule",
      "text": "In 1981, General André Kolingba seized power in a bloodless coup and ruled until 1993.",
      "date": "1981"
    },
    {
      "headline": "First Multiparty Elections",
      "text": "In 1993, the first multiparty elections were held, and Ange-Félix Patassé was elected President.",
      "date": "1993"
    },
    {
      "headline": "François Bozizé's Coup",
      "text": "On March 15, 2003, François Bozizé led a coup d'état, overthrowing President Ange-Félix Patassé.",
      "date": "2003-03-15"
    },
    {
      "headline": "Central African Republic Bush War",
      "text": "The Central African Republic Bush War began in 2004, involving various rebel groups against the government.",
      "date": "2004"
    },
    {
      "headline": "Séléka Rebellion",
      "text": "In December 2012, the Séléka coalition began a rebellion against the government, leading to a civil war.",
