      "headline": "Guangzhou Under Mongol Rule",
      "text": "In 1276, Guangzhou came under Mongol rule as part of the Yuan Dynasty.",
      "date": "1276"
    },
    {
      "headline": "Guangzhou in the Ming Dynasty",
      "text": "During the Ming Dynasty (1368–1644), Guangzhou became the only Chinese port open to foreign trade.",
      "date": "1368"
    },
    {
      "headline": "Guangzhou in the Qing Dynasty",
      "text": "In 1757, the Qing Dynasty restricted all foreign trade to Guangzhou, establishing the Canton System.",
      "date": "1757"
    },
    {
      "headline": "First Opium War and Treaty of Nanking",
      "text": "In 1842, following the First Opium War, the Treaty of Nanking opened Guangzhou to British trade.",
      "date": "1842"
    },
    {
      "headline": "Guangzhou Uprising",
      "text": "In 1911, the Guangzhou Uprising was one of the key events leading to the fall of the Qing Dynasty.",
      "date": "1911"
    },
    {
      "headline": "Japanese Occupation",
      "text": "Guangzhou was occupied by Japanese forces during the Second Sino-Japanese War from 1938 to 1945.",
      "date": "1938"
    },
    {
      "headline": "Liberation of Guangzhou",
      "text": "In 1949, Guangzhou was liberated by the People's Liberation Army during the Chinese Civil War.",
      "date": "1949"
    },
    {
      "headline": "Economic Reforms and Development",
      "text": "Since the 1980s, Guangzhou has undergone significant economic reforms and development, becoming a major economic center in China.",
      "date": "1980"
    }
  ]
}

