{
  "timeline": [
    {
      "headline": "Bretton Woods Conference",
      "text": "The International Monetary Fund (IMF) was conceived at the United Nations Monetary and Financial Conference, also known as the Bretton Woods Conference, held in July 1944. The conference aimed to establish a framework for international economic cooperation after World War II.",
      "date": "1944-07"
    },
    {
      "headline": "IMF Established",
      "text": "The IMF was formally established on December 27, 1945, when the first 29 countries signed the Articles of Agreement. The organization was created to promote international monetary cooperation and exchange rate stability.",
      "date": "1945-12-27"
    },
    {
      "headline": "IMF Begins Operations",
      "text": "The IMF began its financial operations on March 1, 1947. Its initial purpose was to provide short-term financial assistance to countries struggling with balance of payments problems.",
      "date": "1947-03-01"
    },
    {
      "headline": "First Loan Issued",
      "text": "On May 8, 1947, the IMF granted its first loan to France, amounting to $25 million, to help stabilize the country's economy post-World War II.",
      "date": "1947-05-08"
    },
    {
      "headline": "Special Drawing Rights (SDRs) Created",
      "text": "In 1969, the IMF created Special Drawing Rights (SDRs) as an international reserve asset to supplement its member countries' official reserves.",
      "date": "1969"
    },
    {
      "headline": "IMF's Role in the 1970s Oil Crisis",
      "text": "During the 1970s oil crisis, the IMF played a crucial role in providing financial assistance to countries affected by the sharp increase in oil prices, helping them to stabilize their economies.",
      "date": "1970s"
    },
    {
      "headline": "Structural Adjustment Programs",
      "text": "In the 1980s, the IMF began implementing Structural Adjustment Programs (SAPs) in developing countries, which included economic policy reforms aimed at stabilizing and restructuring economies.",
      "date": "1980s"
    },
    {
      "headline": "IMF's Involvement in the Asian Financial Crisis",
      "text": "The IMF was heavily involved in the Asian Financial Crisis of 1997-1998, providing financial assistance and policy advice to affected countries such as Thailand, Indonesia, and South Korea.",
      "date": "1997"
    },
    {
      "headline": "IMF's Response to the Global Financial Crisis",
      "text": "In response to the 2008 global financial crisis, the IMF increased its lending capacity and provided financial assistance to countries facing economic difficulties, playing a key role in stabilizing the global economy.",
      "date": "2008"
    },
    {
      "headline": "IMF's Role in the Eurozone Debt Crisis",
      "text": "The IMF was actively involved in addressing the Eurozone debt crisis, providing financial assistance and policy advice to countries such as Greece, Ireland, and Portugal to help them stabilize their economies.",
      "date": "2010"
    }
  ]
}

