{
  "timeline": [
    {
      "headline": "Invention of the Internet",
      "text": "The foundation for e-commerce was laid with the invention of the Internet, which began as a research project funded by the U.S. Department of Defense in the late 1960s.",
      "date": "1960"
    },
    {
      "headline": "Introduction of Electronic Data Interchange (EDI)",
      "text": "In the 1970s, Electronic Data Interchange (EDI) was introduced, allowing companies to conduct electronic transactions and exchange business documents.",
      "date": "1970"
    },
    {
      "headline": "Development of Online Shopping",
      "text": "The concept of online shopping was developed by Michael Aldrich in 1979, using a modified domestic television to connect to a real-time transaction processing computer via a telephone line.",
      "date": "1979"
    },
    {
      "headline": "Launch of CompuServe",
      "text": "CompuServe, the first major commercial online service in the United States, was launched in 1980, providing a platform for electronic commerce.",
      "date": "1980"
    },
    {
      "headline": "Introduction of the World Wide Web",
      "text": "The World Wide Web was invented by Tim Berners-Lee in 1989, revolutionizing the way information is shared and accessed, and paving the way for e-commerce.",
      "date": "1989"
    },
    {
      "headline": "First Secure Online Transaction",
      "text": "In 1994, the first secure online transaction was conducted using encryption technology developed by Netscape, marking a significant milestone in e-commerce.",
      "date": "1994"
    },
    {
      "headline": "Launch of Amazon and eBay",
      "text": "Amazon was founded by Jeff Bezos in 1994, and eBay was founded by Pierre Omidyar in 1995, both becoming major players in the e-commerce industry.",
      "date": "1994"
    },
    {
      "headline": "Introduction of PayPal",
      "text": "PayPal was founded in December 1998, providing a secure and convenient way to conduct online transactions and further boosting e-commerce.",
      "date": "1998-12"
    },
    {
      "headline": "Rise of Mobile Commerce",
      "text": "With the advent of smartphones in the early 2000s, mobile commerce began to rise, allowing consumers to shop online using their mobile devices.",
      "date": "2000"
    },
    {
      "headline": "Launch of Alibaba",
      "text": "Alibaba, a major Chinese e-commerce platform, was launched in 1999 by Jack Ma, significantly impacting global e-commerce.",
      "date": "1999"
    },
    {
      "headline": "Introduction of Social Commerce",
      "text": "Social media platforms began integrating e-commerce features in the 2010s, allowing users to shop directly through social networks.",
      "date": "2010"
    },
    {
      "headline": "Growth of E-commerce During COVID-19 Pandemic",
      "text": "The COVID-19 pandemic in 2020 led to a significant increase in e-commerce as consumers turned to online shopping due to lockdowns and social distancing measures.",
      "date": "2020"
    }
  ]
}

