  "timeline": [
    {
      "headline": "Birth of Archimedes",
      "text": "Archimedes was born in 287 BCE in the city of Syracuse, Sicily.",
      "date": "-0287"
    },
    {
      "headline": "Studies in Alexandria",
      "text": "Archimedes is believed to have studied in Alexandria, Egypt, where he was exposed to the works of Euclid and other scholars of the time. The exact dates of his studies are not known, but it is presumed to be during his early life.",
      "date": "-0270"
    },
    {
      "headline": "Archimedes' Principle",
      "text": "Archimedes formulated the principle of buoyancy, known as Archimedes' Principle, which states that a body submerged in a fluid experiences a buoyant force equal to the weight of the fluid displaced by the body. This discovery is traditionally dated to around 250 BCE.",
      "date": "-0250"
    },
    {
      "headline": "Invention of the Archimedes Screw",
      "text": "Archimedes invented the Archimedes Screw, a device used for raising water, which is still used in some parts of the world today. The invention is believed to have occurred around 250 BCE.",
      "date": "-0250"
    },
    {
      "headline": "The Method of Exhaustion",
      "text": "Archimedes used the method of exhaustion to calculate areas and volumes, a precursor to integral calculus. He applied this method to derive the area of a circle and the volume of a sphere, among other geometrical theorems.",
      "date": "-0240"
    },
    {
      "headline": "Archimedes' Death",
      "text": "Archimedes died in 212 BCE during the Second Punic War when the city of Syracuse was captured by Roman forces. According to legend, he was killed by a Roman soldier despite orders that he should not be harmed.",
      "date": "-0212"
    }
  ]
}

