{
  "timeline": [
    {
      "headline": "Establishment of the United Nations Security Council",
      "text": "The United Nations Security Council (UNSC) was established on October 24, 1945, following the ratification of the United Nations Charter by the five permanent members of the Security Council: China, France, the Soviet Union, the United Kingdom, and the United States.",
      "date": "1945-10-24"
    },
    {
      "headline": "First Session of the UNSC",
      "text": "The first session of the United Nations Security Council was held on January 17, 1946, at Church House, Westminster, London.",
      "date": "1946-01-17"
    },
    {
      "headline": "Resolution 1",
      "text": "On January 25, 1946, the UNSC adopted its first resolution, Resolution 1, which called for the establishment of a commission to deal with the problems raised by the discovery of atomic energy.",
      "date": "1946-01-25"
    },
    {
      "headline": "Korean War and UNSC Resolution 82",
      "text": "On June 25, 1950, the UNSC adopted Resolution 82, which called for the cessation of hostilities in Korea and the withdrawal of North Korean forces to the 38th parallel.",
      "date": "1950-06-25"
    },
    {
      "headline": "Suez Crisis and UNSC Involvement",
      "text": "During the Suez Crisis in 1956, the UNSC was involved in diplomatic efforts to resolve the conflict, leading to the establishment of the United Nations Emergency Force (UNEF) to supervise the cessation of hostilities.",
      "date": "1956"
    },
    {
      "headline": "Cuban Missile Crisis",
      "text": "In October 1962, the UNSC was a platform for discussions during the Cuban Missile Crisis, where the United States and the Soviet Union came close to nuclear conflict.",
      "date": "1962-10"
    },
    {
      "headline": "Resolution 242",
      "text": "On November 22, 1967, the UNSC adopted Resolution 242, following the Six-Day War, calling for the withdrawal of Israeli armed forces from territories occupied in the conflict and the recognition of every state in the area's right to live in peace.",
      "date": "1967-11-22"
    },
    {
      "headline": "End of Apartheid in South Africa",
      "text": "Throughout the 1980s and early 1990s, the UNSC imposed sanctions on South Africa to pressure the government to end apartheid, contributing to the eventual dismantling of the apartheid system.",
      "date": "1990s"
    },
    {
      "headline": "Gulf War and UNSC Resolution 678",
      "text": "On November 29, 1990, the UNSC adopted Resolution 678, authorizing member states to use all necessary means to uphold and implement Resolution 660 and subsequent resolutions to restore international peace and security in the area, leading to the Gulf War.",
      "date": "1990-11-29"
    },
    {
      "headline": "Rwanda Genocide",
      "text": "In 1994, the UNSC faced criticism for its inaction during the Rwandan Genocide, where an estimated 800,000 people were killed in a span of 100 days.",
      "date": "1994"
    },
    {
      "headline": "Resolution 1441 and Iraq War",
      "text": "On November 8, 2002, the UNSC adopted Resolution 1441, offering Iraq a final opportunity to comply with its disarmament obligations, which eventually led to the Iraq War in 2003.",
      "date": "2002-11-08"
    }
  ]
}

