    },
    {
      "headline": "First Medals of Honor Awarded",
      "text": "The first Medals of Honor were awarded on March 25, 1863, to six Union Army volunteers known as the Andrews Raiders for their actions during the Great Locomotive Chase in April 1862.",
      "date": "1863-03-25"
    },
    {
      "headline": "Air Force Medal of Honor Established",
      "text": "The Air Force Medal of Honor was established on April 14, 1965, to recognize acts of valor by members of the United States Air Force.",
      "date": "1965-04-14"
    },
    {
      "headline": "Coast Guard Medal of Honor",
      "text": "Although the Coast Guard does not have its own version of the Medal of Honor, its members are eligible to receive the Navy Medal of Honor for acts of valor.",
      "date": "N/A"
    },
    {
      "headline": "Medal of Honor Redesign",
      "text": "The Medal of Honor has undergone several redesigns since its inception, with significant changes made in 1904, 1944, and 1965 to improve its appearance and distinguish it from other military awards.",
      "date": "N/A"
    },
    {
      "headline": "First Female Recipient",
      "text": "Dr. Mary Edwards Walker became the first and only female recipient of the Medal of Honor for her service as a surgeon during the American Civil War. Her award was initially revoked in 1917 but was restored in 1977.",
      "date": "1865"
