{
  "timeline": [
    {
      "headline": "Start of Operation Market Garden",
      "text": "Operation Market Garden began on 1944-09-17. It was an Allied military operation during the Second World War, aimed at creating a salient into German territory in the Netherlands.",
      "date": "1944-09-17"
    },
    {
      "headline": "Airborne Landings",
      "text": "On 1944-09-17, the airborne phase of the operation, known as 'Market', commenced. Combined US and British airborne forces were tasked with seizing nine key bridges.",
      "date": "1944-09-17"
    },
    {
      "headline": "Ground Offensive Begins",
      "text": "The ground offensive, known as 'Garden', started on 1944-09-17. British land forces began their advance to link up with airborne units.",
      "date": "1944-09-17"
    },
    {
      "headline": "Capture of Eindhoven",
      "text": "On 1944-09-18, the city of Eindhoven was captured by the Allies, marking an early success in the operation.",
      "date": "1944-09-18"
    },
    {
      "headline": "Battle of Arnhem",
      "text": "The Battle of Arnhem began on 1944-09-17 and lasted until 1944-09-25. It was a key part of the operation, with the objective of capturing the bridge over the Nederrijn.",
      "date": "1944-09-17"
    },
    {
      "headline": "Failure to Secure Arnhem Bridge",
      "text": "By 1944-09-21, it became clear that the Allies had failed to secure the Arnhem bridge, a critical objective of the operation.",
      "date": "1944-09-21"
    },
    {
      "headline": "Withdrawal from Arnhem",
      "text": "On 1944-09-25, the remaining Allied forces withdrew from Arnhem, marking the end of the operation.",
      "date": "1944-09-25"
    },
    {
      "headline": "End of Operation Market Garden",
      "text": "Operation Market Garden officially ended on 1944-09-25. The operation failed to achieve its main objectives, resulting in a prolonged conflict in the region.",
      "date": "1944-09-25"
    }
  ]
}

