      "headline": "First Reported East of the Volga River",
      "text": "The Huns were first reported living east of the Volga River, in an area that was part of Scythia at the time.",
      "date": "0370"
    },
    {
      "headline": "Arrival on the Volga",
      "text": "By 370 AD, the Huns had arrived on the Volga River, causing the westwards movement of Goths and Alans.",
      "date": "0370"
    },
    {
      "headline": "Establishment of Hunnic Empire",
      "text": "By 430 AD, the Huns had established a vast, but short-lived, empire on the Danubian frontier of the Roman Empire in Europe.",
      "date": "0430"
    },
    {
      "headline": "Battle of the Catalaunian Plains",
      "text": "In 451 AD, the Huns, led by Attila, fought against a coalition of Roman and Visigothic forces in the Battle of the Catalaunian Plains, one of the last major military operations of the Western Roman Empire.",
      "date": "0451"
    },
    {
      "headline": "Death of Attila the Hun",
      "text": "Attila the Hun died in 453 AD, leading to the fragmentation of the Hunnic Empire.",
      "date": "0453"
    },
    {
      "headline": "Battle of Nedao",
      "text": "In 454 AD, the Battle of Nedao took place, where a coalition of Germanic tribes defeated the Huns, leading to the collapse of their empire.",
      "date": "0454"
    },
    {
      "headline": "Disintegration of the Hunnic Empire",
      "text": "Following the Battle of Nedao and the death of Attila, the Hunnic Empire disintegrated, with many of its subject peoples establishing their own kingdoms.",
      "date": "0454"
    }
  ]
}

{
  "timeline": [
    {
      "headline": "Release of Final Fantasy",
      "text": "The first game in the Final Fantasy series was released on December 18, 1987. It was developed and published by Square (now Square Enix) for the Nintendo Entertainment System (NES).",
      "date": "1987-12-18"
    },
    {
      "headline": "Release of Final Fantasy II",
      "text": "Final Fantasy II was released on December 17, 1988, in Japan for the NES. It introduced a new leveling system and expanded the narrative elements of the series.",
      "date": "1988-12-17"
    },
    {
      "headline": "Release of Final Fantasy III",
      "text": "Final Fantasy III was released on April 27, 1990, in Japan for the NES. It introduced the job system, allowing players to change characters' classes.",
      "date": "1990-04-27"
    },
    {
      "headline": "Release of Final Fantasy IV",
      "text": "Final Fantasy IV was released on July 19, 1991, for the Super Nintendo Entertainment System (SNES). It was the first game in the series to be released in North America, under the title Final Fantasy II.",
      "date": "1991-07-19"
    },
    {
      "headline": "Release of Final Fantasy V",
      "text": "Final Fantasy V was released on December 6, 1992, in Japan for the SNES. It expanded the job system and was later released internationally.",
      "date": "1992-12-06"
    },
    {
      "headline": "Release of Final Fantasy VI",
      "text": "Final Fantasy VI was released on April 2, 1994, in Japan for the SNES. It is known for its ensemble cast and complex narrative.",
      "date": "1994-04-02"
    },
    {
      "headline": "Release of Final Fantasy VII",
      "text": "Final Fantasy VII was released on January 31, 1997, for the PlayStation. It was the first game in the series to use 3D computer graphics and full motion video.",
      "date": "1997-01-31"
    },
    {
      "headline": "Release of Final Fantasy VIII",
      "text": "Final Fantasy VIII was released on February 11, 1999, for the PlayStation. It introduced a new junction system for character abilities.",
      "date": "1999-02-11"
    },
    {
      "headline": "Release of Final Fantasy IX",
      "text": "Final Fantasy IX was released on July 7, 2000, for the PlayStation. It returned to the series' roots with a medieval fantasy setting.",
      "date": "2000-07-07"
    },
    {
      "headline": "Release of Final Fantasy X",
      "text": "Final Fantasy X was released on July 19, 2001, for the PlayStation 2. It was the first game in the series to feature voice acting.",
      "date": "2001-07-19"
    },
    {
      "headline": "Release of Final Fantasy XI",
      "text": "Final Fantasy XI was released on May 16, 2002, for the PlayStation 2 and later for Windows. It was the first MMORPG in the series.",
