    {
      "headline": "Indian Independence Act Passed",
      "text": "The Indian Independence Act 1947 was passed by the British Parliament on 18 July 1947, which outlined the partition of British India into two new independent dominions: India and Pakistan.",
      "date": "1947-07-18"
    },
    {
      "headline": "Radcliffe Line Finalized",
      "text": "The boundary demarcation line, known as the Radcliffe Line, was finalized on 17 August 1947. It divided the provinces of Bengal and Punjab based on religious majorities.",
      "date": "1947-08-17"
    },
    {
      "headline": "Independence of Pakistan",
      "text": "Pakistan became an independent dominion on 14 August 1947, marking its official separation from British India.",
      "date": "1947-08-14"
    },
    {
      "headline": "Independence of India",
      "text": "India became an independent dominion on 15 August 1947, marking the end of British rule in India.",
      "date": "1947-08-15"
    },
    {
      "headline": "Mass Migration Begins",
      "text": "Following the partition, one of the largest mass migrations in human history began, with millions of Hindus and Sikhs moving to India and Muslims moving to Pakistan.",
      "date": "1947-08"
    },
    {
      "headline": "Communal Violence Erupts",
      "text": "The partition led to widespread communal violence, resulting in the deaths of hundreds of thousands of people and displacement of millions.",
      "date": "1947-08"
    },
    {
      "headline": "Division of Assets",
      "text": "The assets of British India, including the military, civil services, and treasury, were divided between India and Pakistan, a process that continued into 1948.",
      "date": "1947-08"
    }
  ]
}

