{
  "timeline": [
    {
      "headline": "Christchurch Mosque Shootings",
      "text": "On 15 March 2019, two consecutive mass shootings took place in Christchurch, New Zealand. They were committed by a single perpetrator during Friday prayer, first at the Al Noor Mosque in Riccarton at 1:40 p.m. and almost immediately afterwards at the Linwood Islamic Centre at 1:52 p.m. Altogether, 51 people were killed and 89 others were injured, including 40 by gunfire.",
      "date": "2019-03-15"
    },
    {
      "headline": "Perpetrator Arrested",
      "text": "The perpetrator was arrested by police approximately 21 minutes after the first emergency call was received, at 2:11 p.m. on 15 March 2019.",
      "date": "2019-03-15"
    },
    {
      "headline": "National Mourning and Vigils",
      "text": "In the days following the attacks, vigils and memorials were held across New Zealand and around the world to honor the victims and show solidarity with the Muslim community.",
      "date": "2019-03"
    },
    {
      "headline": "New Zealand Gun Law Reforms",
      "text": "On 21 March 2019, New Zealand Prime Minister Jacinda Ardern announced a ban on all military-style semi-automatic weapons and assault rifles in response to the Christchurch mosque shootings.",
      "date": "2019-03-21"
    },
    {
      "headline": "Perpetrator Charged",
      "text": "On 4 April 2019, the perpetrator was charged with 50 counts of murder and 39 counts of attempted murder.",
      "date": "2019-04-04"
    },
    {
      "headline": "Guilty Plea",
      "text": "On 26 March 2020, the perpetrator pleaded guilty to all charges, including 51 counts of murder, 40 counts of attempted murder, and one count of engaging in a terrorist act.",
      "date": "2020-03-26"
    },
    {
      "headline": "Sentencing",
      "text": "On 27 August 2020, the perpetrator was sentenced to life imprisonment without the possibility of parole, marking the first time such a sentence was handed down in New Zealand.",
      "date": "2020-08-27"
    }
  ]
}

