  "timeline": [
    {
      "headline": "Ancient Greek Contributions",
      "text": "In the 5th century BCE, ancient Greek philosophers such as Democritus and Leucippus proposed the idea of the atom as an indivisible component of matter.",
      "date": "-0500"
    },
