    },
    {
      "headline": "Ptolemaic System",
      "text": "In the 2nd century CE, Claudius Ptolemy developed the geocentric model of the universe, which dominated astronomical thought for over a millennium.",
      "date": "0150"
    },
    {
      "headline": "Copernican Revolution",
      "text": "In 1543, Nicolaus Copernicus published 'De revolutionibus orbium coelestium', proposing a heliocentric model of the solar system.",
      "date": "1543"
    },
    {
      "headline": "Galileo's Observations",
      "text": "In 1609, Galileo Galilei used a telescope to make significant astronomical observations, including the moons of Jupiter and the phases of Venus.",
      "date": "1609"
    },
