{
  "timeline": [
    {
      "headline": "Spanish Colonization",
      "text": "In 1884, Spain claimed a protectorate over the coastal areas of Western Sahara, which was later extended inland.",
      "date": "1884"
    },
    {
      "headline": "Spanish Sahara",
      "text": "In 1934, Spain formally established the territory as Spanish Sahara.",
      "date": "1934"
    },
    {
      "headline": "UN Involvement",
      "text": "In 1963, the United Nations included Spanish Sahara in its list of non-self-governing territories, calling for decolonization.",
      "date": "1963"
    },
    {
      "headline": "Sahrawi Nationalism",
      "text": "In 1973, the Polisario Front was formed with the aim of ending Spanish colonial rule and establishing an independent state.",
      "date": "1973"
    },
    {
      "headline": "Madrid Accords",
      "text": "On November 14, 1975, Spain, Morocco, and Mauritania signed the Madrid Accords, which divided the territory between Morocco and Mauritania.",
      "date": "1975-11-14"
    },
    {
      "headline": "Moroccan and Mauritanian Control",
      "text": "In 1976, Spain withdrew from Western Sahara, and Morocco and Mauritania took control of the territory.",
      "date": "1976"
    },
    {
      "headline": "SADR Proclamation",
      "text": "On February 27, 1976, the Polisario Front proclaimed the Sahrawi Arab Democratic Republic (SADR).",
      "date": "1976-02-27"
    },
    {
      "headline": "Mauritania Withdrawal",
      "text": "In 1979, Mauritania signed a peace treaty with the Polisario Front and withdrew from Western Sahara.",
      "date": "1979"
    },
    {
      "headline": "Moroccan Wall Construction",
      "text": "In the 1980s, Morocco began constructing a series of defensive walls, known as the Moroccan Wall, to control the territory.",
      "date": "1980"
    },
    {
      "headline": "UN Ceasefire",
      "text": "In 1991, a UN-brokered ceasefire was established between Morocco and the Polisario Front, leading to a halt in hostilities.",
      "date": "1991"
    },
    {
      "headline": "MINURSO Establishment",
      "text": "The United Nations Mission for the Referendum in Western Sahara (MINURSO) was established in 1991 to monitor the ceasefire and organize a referendum.",
      "date": "1991"
    },
    {
      "headline": "Referendum Delays",
      "text": "Throughout the 1990s and 2000s, efforts to hold a referendum on self-determination were repeatedly delayed due to disagreements over voter eligibility.",
      "date": "1990s"
    },
    {
      "headline": "Gdeim Izik Protest",
      "text": "In October 2010, the Gdeim Izik protest camp was established by Sahrawis near Laayoune, leading to clashes with Moroccan forces.",
      "date": "2010-10"
    }
  ]
}

