{
  "timeline": [
    {
      "headline": "Beginning of Anglo-Saxon Settlement",
      "text": "The Anglo-Saxon period in Britain is considered to have started around 450 AD, marked by the settlement of Germanic tribes in England.",
      "date": "0450"
    },
    {
      "headline": "Formation of Anglo-Saxon Kingdoms",
      "text": "By the 7th century, several Anglo-Saxon kingdoms had formed, including Northumbria, Mercia, East Anglia, Essex, Kent, Sussex, and Wessex.",
      "date": "0600"
    },
    {
      "headline": "Christianization of Anglo-Saxons",
      "text": "The Christianization of the Anglo-Saxons began in 597 with the arrival of Augustine of Canterbury, who was sent by Pope Gregory the Great.",
      "date": "0597"
    },
    {
      "headline": "Battle of Edington",
      "text": "In 878, King Alfred the Great of Wessex defeated the Viking Great Heathen Army at the Battle of Edington, leading to the Treaty of Wedmore and the establishment of the Danelaw.",
      "date": "0878"
    },
    {
      "headline": "Unification of England",
      "text": "By 927, King Æthelstan had unified the various Anglo-Saxon kingdoms into a single kingdom of England.",
      "date": "0927"
    },
    {
      "headline": "Viking Invasions",
      "text": "The late 10th and early 11th centuries saw renewed Viking invasions, leading to the rule of King Cnut the Great over England from 1016 to 1035.",
      "date": "1016"
    },
    {
      "headline": "Edward the Confessor's Reign",
      "text": "Edward the Confessor ruled from 1042 until his death in 1066, a period marked by relative peace and the construction of Westminster Abbey.",
      "date": "1042"
    },
    {
      "headline": "Norman Conquest",
      "text": "In 1066, the Norman Conquest led by William the Conqueror ended the Anglo-Saxon period, following the Battle of Hastings.",
      "date": "1066"
    }
  ]
}

