    {
      "headline": "Spanish Conquest",
      "text": "In the 16th century, the Spanish arrived in the Yucatán Peninsula, marking the beginning of the colonial period and the end of Chichen Itza's prominence.",
      "date": "1500"
    },
    {
      "headline": "Rediscovery and Archaeological Exploration",
      "text": "In the 19th century, Chichen Itza was rediscovered by explorers and became a focus of archaeological study.",
      "date": "1800"
    },
    {
      "headline": "UNESCO World Heritage Site",
      "text": "In 1988, Chichen Itza was designated a UNESCO World Heritage Site, recognizing its cultural and historical significance.",
      "date": "1988"
    },
    {
      "headline": "New Seven Wonders of the World",
      "text": "In 2007, Chichen Itza was named one of the New Seven Wonders of the World, highlighting its global importance.",
