{
  "timeline": [
    {
      "headline": "Nationalization of the Suez Canal",
      "text": "On July 26, 1956, Egyptian President Gamal Abdel Nasser nationalized the Suez Canal, transferring control from the foreign-owned Suez Canal Company to Egypt's new government-owned Suez Canal Authority.",
      "date": "1956-07-26"
    },
    {
      "headline": "Israeli Invasion of Sinai",
      "text": "On October 29, 1956, Israel invaded the Sinai Peninsula with the primary objective of re-opening the Straits of Tiran and the Gulf of Aqaba, which had been blocked by Egypt.",
      "date": "1956-10-29"
    },
    {
      "headline": "Anglo-French Ultimatum",
      "text": "On October 30, 1956, the United Kingdom and France issued a joint ultimatum to Egypt and Israel, demanding a ceasefire and withdrawal of forces from the vicinity of the Suez Canal.",
      "date": "1956-10-30"
    },
    {
      "headline": "British and French Invasion",
      "text": "On November 5, 1956, British and French forces joined the Israelis in invading Egypt, aiming to regain control of the Suez Canal and depose President Nasser.",
      "date": "1956-11-05"
    },
    {
      "headline": "UN Ceasefire Resolution",
      "text": "On November 7, 1956, the United Nations General Assembly adopted a resolution calling for an immediate ceasefire and the withdrawal of invading forces from Egypt.",
      "date": "1956-11-07"
    },
    {
      "headline": "Withdrawal of Invading Forces",
      "text": "Under heavy political pressure from the United States, the Soviet Union, and the United Nations, the United Kingdom, France, and Israel began withdrawing their forces from Egypt in December 1956.",
      "date": "1956-12"
    },
    {
      "headline": "Reopening of the Suez Canal",
      "text": "The Suez Canal, which had been closed due to the conflict, was reopened in March 1957 after the withdrawal of foreign troops and the resolution of the crisis.",
      "date": "1957-03"
    }
  ]
}

