    },
    {
      "headline": "Execution of Marie Antoinette",
      "text": "Marie Antoinette, the former queen of France, was executed by guillotine on October 16, 1793.",
      "date": "1793-10-16"
    },
    {
      "headline": "Execution of the Girondins",
      "text": "On October 31, 1793, leading members of the Girondin faction were executed, marking a significant political purge.",
      "date": "1793-10-31"
    },
    {
      "headline": "Law of 22 Prairial",
      "text": "On June 10, 1794, the Law of 22 Prairial was enacted, which expedited the process of trial and execution for those accused of treason.",
      "date": "1794-06-10"
    },
    {
      "headline": "Festival of the Supreme Being",
      "text": "On June 8, 1794, the Festival of the Supreme Being was celebrated, reflecting Robespierre's influence and the de-Christianization efforts.",
      "date": "1794-06-08"
    },
    {
      "headline": "Fall of Robespierre",
      "text": "Maximilien Robespierre was arrested on July 27, 1794, and executed the following day, marking the end of the Reign of Terror.",
      "date": "1794-07-27"
    },
    {
      "headline": "End of the Reign of Terror",
      "text": "The Reign of Terror effectively ended with the execution of Robespierre on July 28, 1794.",
