{
  "timeline": [
    {
      "headline": "Formation of the Mississippi River",
      "text": "The Mississippi River was formed over millions of years through geological processes, including glaciation and erosion, which shaped its current path and drainage basin.",
      "date": "-10000000"
    },
    {
      "headline": "Native American Settlements",
      "text": "For thousands of years, Native American tribes, such as the Mississippian culture, lived along the Mississippi River, utilizing it for transportation, trade, and sustenance.",
      "date": "-1000"
    },
    {
      "headline": "European Exploration",
      "text": "In 1541, Spanish explorer Hernando de Soto became the first European to document the Mississippi River, marking the beginning of European exploration and mapping of the river.",
      "date": "1541"
    },
    {
      "headline": "French Exploration and Naming",
      "text": "In 1682, French explorer René-Robert Cavelier, Sieur de La Salle, traveled the length of the Mississippi River and claimed the region for France, naming it 'La Louisiane' in honor of King Louis XIV.",
      "date": "1682"
    },
    {
      "headline": "Louisiana Purchase",
