    },
    {
      "headline": "Reagan Acknowledges Arms Sales",
      "text": "On November 25, 1986, President Ronald Reagan acknowledged that arms had been sold to Iran, but denied that they were part of an arms-for-hostages deal.",
      "date": "1986-11-25"
    },
    {
      "headline": "Tower Commission Report Released",
      "text": "On February 26, 1987, the Tower Commission released its report, criticizing the Reagan administration's handling of the Iran-Contra affair.",
      "date": "1987-02-26"
    },
    {
      "headline": "Congressional Hearings Begin",
      "text": "In May 1987, televised congressional hearings began, investigating the Iran-Contra affair.",
      "date": "1987-05"
    },
    {
