{
  "timeline": [
    {
      "headline": "George Floyd's Arrest",
      "text": "On May 25, 2020, George Floyd was arrested by Minneapolis police officers after a store clerk reported that he used a counterfeit $20 bill.",
      "date": "2020-05-25"
    },
    {
      "headline": "Murder of George Floyd",
      "text": "On May 25, 2020, during the arrest, officer Derek Chauvin knelt on George Floyd's neck for over nine minutes while Floyd was handcuffed and lying face-down in the street. Floyd repeatedly stated that he could not breathe.",
      "date": "2020-05-25"
    },
    {
      "headline": "Involvement of Other Officers",
      "text": "On May 25, 2020, officers J. Alexander Kueng and Thomas Lane assisted Derek Chauvin in restraining George Floyd. Lane had pointed a gun at Floyd's head before he was handcuffed. Officer Tou Thao prevented bystanders from intervening.",
      "date": "2020-05-25"
    },
    {
      "headline": "Public Outcry and Protests",
      "text": "Following the release of a bystander's video on May 25, 2020, showing the murder of George Floyd, widespread protests erupted across the United States and globally, calling for justice and police reform.",
      "date": "2020-05-25"
    },
    {
      "headline": "Derek Chauvin Charged",
      "text": "On May 29, 2020, Derek Chauvin was charged with third-degree murder and second-degree manslaughter in connection with George Floyd's death.",
      "date": "2020-05-29"
    },
    {
      "headline": "Upgraded Charges",
      "text": "On June 3, 2020, Derek Chauvin's charges were upgraded to second-degree murder. The other three officers, J. Alexander Kueng, Thomas Lane, and Tou Thao, were charged with aiding and abetting second-degree murder and manslaughter.",
      "date": "2020-06-03"
    },
    {
      "headline": "Derek Chauvin Convicted",
      "text": "On April 20, 2021, Derek Chauvin was found guilty of second-degree unintentional murder, third-degree murder, and second-degree manslaughter in the death of George Floyd.",
      "date": "2021-04-20"
    },
    {
      "headline": "Derek Chauvin Sentenced",
      "text": "On June 25, 2021, Derek Chauvin was sentenced to 22.5 years in prison for the murder of George Floyd.",
      "date": "2021-06-25"
    }
  ]
}

