{
  "timeline": [
    {
      "headline": "1884 United States Presidential Election",
      "text": "Presidential elections were held in the United States on November 4, 1884. Democratic Governor Grover Cleveland of New York narrowly defeated Republican James G. Blaine of Maine. This election was marked by mudslinging and personal allegations that overshadowed substantive issues, such as civil administration change.",
      "date": "1884-11-04"
    },
    {
      "headline": "Grover Cleveland Elected as President",
      "text": "Grover Cleveland became the first Democrat elected president of the United States since James Buchanan in 1856. His victory marked a significant interruption in the era when Republicans largely controlled the presidency between Reconstruction and the Great Depression.",
      "date": "1884-11-04"
    },
    {
      "headline": "Significance of the 1884 Election",
      "text": "The election of 1884 was significant in U.S. political history as it marked the first time a Democrat held the presidency since Andrew Johnson left office in 1869. Cleveland's election was the last time a Democrat would hold the office until Woodrow Wilson began his first term in 1913.",
      "date": "1884"
    }
  ]
}

{
  "timeline": [
    {
      "headline": "Brundtland Report Published",
      "text": "In 1987, the Brundtland Report, also known as 'Our Common Future', was published by the World Commission on Environment and Development. It popularized the concept of sustainable development and defined it as development that meets the needs of the present without compromising the ability of future generations to meet their own needs.",
      "date": "1987"
    },
    {
      "headline": "United Nations Conference on Environment and Development (Earth Summit)",
      "text": "In 1992, the Earth Summit was held in Rio de Janeiro, Brazil. It was a major United Nations conference that brought together leaders from around the world to discuss sustainable development. The summit resulted in the adoption of Agenda 21, a comprehensive plan of action to build a global partnership for sustainable development.",
      "date": "1992"
    },
    {
      "headline": "Millennium Development Goals (MDGs) Established",
      "text": "In 2000, the United Nations established the Millennium Development Goals, a set of eight international development goals that were to be achieved by 2015. These goals included eradicating extreme poverty and hunger, achieving universal primary education, and ensuring environmental sustainability.",
      "date": "2000"
    },
    {
      "headline": "World Summit on Sustainable Development",
      "text": "In 2002, the World Summit on Sustainable Development was held in Johannesburg, South Africa. The summit aimed to assess the progress made since the 1992 Earth Summit and to reinvigorate global commitment to sustainable development.",
      "date": "2002"
    },
    {
      "headline": "United Nations Sustainable Development Summit",
      "text": "In 2015, the United Nations Sustainable Development Summit was held in New York City. During the summit, the 2030 Agenda for Sustainable Development was adopted, which included 17 Sustainable Development Goals (SDGs) to be achieved by 2030.",
      "date": "2015"
    }
  ]
}

