{
  "timeline": [
    {
      "headline": "Establishment of Cape Town",
      "text": "Cape Town was established by the Dutch East India Company as a supply station for Dutch ships sailing to East Africa, India, and the Far East. The settlement was founded by Jan van Riebeeck on April 6, 1652.",
      "date": "1652-04-06"
    },
    {
      "headline": "British Occupation",
      "text": "The British occupied Cape Town during the Napoleonic Wars to prevent it from falling into French hands. The first occupation was from 1795 to 1803, and the second began in 1806.",
      "date": "1806"
    },
    {
      "headline": "Cape Colony becomes a British Colony",
      "text": "The Cape Colony was formally ceded to Britain by the Dutch in the Anglo-Dutch Treaty of 1814.",
      "date": "1814"
    },
    {
      "headline": "Cape Town becomes Legislative Capital",
      "text": "Cape Town was designated as the legislative capital of the Union of South Africa in 1910, when the Union was formed.",
      "date": "1910"
    },
    {
      "headline": "Apartheid Era",
      "text": "During the apartheid era, which began in 1948, Cape Town was subject to the policies of racial segregation and discrimination enforced by the South African government.",
      "date": "1948"
    },
    {
      "headline": "End of Apartheid",
      "text": "Apartheid officially ended in 1994, leading to the first democratic elections in South Africa. Cape Town, like the rest of the country, underwent significant political and social changes.",
      "date": "1994"
    },
    {
      "headline": "Cape Town Water Crisis",
      "text": "Cape Town faced a severe water crisis, known as 'Day Zero', when the city was at risk of running out of water. The crisis peaked in 2018.",
      "date": "2018"
    }
  ]
}

