    },
    {
      "headline": "Discovery of the Strait of Magellan",
      "text": "On October 21, 1520, Magellan's fleet discovered the strait that would later be named after him, allowing passage from the Atlantic Ocean to the Pacific Ocean.",
      "date": "1520-10-21"
    },
    {
      "headline": "Crossing the Pacific Ocean",
      "text": "Magellan's fleet became the first European expedition to cross the Pacific Ocean, reaching the Philippines in March 1521.",
      "date": "1521-03"
    },
    {
      "headline": "Death of Ferdinand Magellan",
