{
  "timeline": [
    {
      "headline": "Introduction of the Julian Calendar",
      "text": "The Julian calendar was introduced by Julius Caesar in 45 BCE as a reform of the Roman calendar. It took effect on January 1, 45 BCE.",
      "date": "-0045-01-01"
    },
    {
      "headline": "Leap Year Correction",
      "text": "The Julian calendar introduced a leap year every four years to account for the extra 0.25 days in the solar year. This correction was implemented starting in 45 BCE.",
      "date": "-0045"
    },
    {
      "headline": "Adoption in the Roman Empire",
      "text": "The Julian calendar was adopted throughout the Roman Empire, replacing the previous Roman calendar system. This widespread adoption occurred during the reign of Julius Caesar.",
      "date": "-0045"
    },
    {
      "headline": "Gregorian Calendar Reform",
      "text": "In 1582, Pope Gregory XIII introduced the Gregorian calendar as a reform of the Julian calendar to correct the drift of the calendar with respect to the equinoxes. The Gregorian calendar is now the most widely used civil calendar.",
      "date": "1582"
    },
    {
      "headline": "Continued Use in Eastern Orthodox Church",
      "text": "The Julian calendar continues to be used as a religious calendar in parts of the Eastern Orthodox Church and Oriental Orthodoxy. This continued use persists into the present day.",
      "date": "2023"
    }
  ]
}

{
  "timeline": [
    {
      "headline": "Founding of the French Foreign Legion",
      "text": "The French Foreign Legion was founded on March 10, 1831, by King Louis-Philippe to allow foreign nationals into French military service.",
      "date": "1831-03-10"
    },
    {
      "headline": "Battle of Camarón",
      "text": "On April 30, 1863, the Battle of Camarón took place during the French intervention in Mexico. A small infantry patrol of the French Foreign Legion made a famous last stand against a much larger Mexican army force.",
      "date": "1863-04-30"
    },
    {
      "headline": "World War I Participation",
      "text": "During World War I (1914-1918), the French Foreign Legion was heavily involved in combat, fighting in major battles on the Western Front.",
      "date": "1914"
    },
    {
      "headline": "World War II Involvement",
      "text": "In World War II (1939-1945), the Legion fought in various theaters, including North Africa, Europe, and the Middle East, under both Vichy and Free French forces.",
      "date": "1939"
    },
    {
      "headline": "Indochina War",
      "text": "The French Foreign Legion played a significant role in the First Indochina War (1946-1954), particularly in the Battle of Dien Bien Phu, which ended in a decisive defeat for the French.",
      "date": "1946"
    },
    {
      "headline": "Algerian War",
      "text": "From 1954 to 1962, the Legion was heavily involved in the Algerian War, which ultimately led to Algerian independence and the end of the Legion's association with the Armée d’Afrique.",
      "date": "1954"
    },
    {
      "headline": "End of the Algerian War",
      "text": "The Algerian War ended in 1962, marking the end of the French Foreign Legion's role in France's colonial project in North Africa.",
      "date": "1962"
    }
  ]
}

