{
  "timeline": [
    {
      "headline": "Establishment of the Republic of China",
      "text": "The Republic of China was officially established on January 1, 1912, following the 1911 Revolution which overthrew the Qing dynasty, marking the end of over two thousand years of imperial rule in China.",
      "date": "1912-01-01"
    },
    {
      "headline": "Provisional President Sun Yat-sen",
      "text": "Sun Yat-sen was inaugurated as the provisional president of the Republic of China on January 1, 1912.",
      "date": "1912-01-01"
    },
    {
      "headline": "Yuan Shikai becomes President",
      "text": "Yuan Shikai was elected as the first official President of the Republic of China on March 10, 1912.",
      "date": "1912-03-10"
    },
    {
      "headline": "Yuan Shikai's Monarchy Attempt",
      "text": "In December 1915, Yuan Shikai declared himself Emperor of China, attempting to establish a new dynasty, but faced widespread opposition and abandoned the plan in March 1916.",
      "date": "1915-12"
    },
    {
      "headline": "Death of Yuan Shikai",
      "text": "Yuan Shikai died on June 6, 1916, leading to a period of political fragmentation and warlordism in China.",
      "date": "1916-06-06"
    },
    {
      "headline": "May Fourth Movement",
      "text": "On May 4, 1919, a student-led protest in Beijing marked the beginning of the May Fourth Movement, which was a cultural and political movement against imperialism and traditional Confucian values.",
      "date": "1919-05-04"
    },
    {
      "headline": "Northern Expedition",
      "text": "The Northern Expedition, led by the Kuomintang (KMT) and its leader Chiang Kai-shek, began in 1926 to unify China by defeating warlords. It successfully ended in 1928.",
      "date": "1926"
    },
    {
      "headline": "Nanjing Decade",
      "text": "The period from 1927 to 1937 is known as the Nanjing Decade, during which the Kuomintang established a relatively stable government in Nanjing.",
      "date": "1927"
    },
    {
      "headline": "Japanese Invasion of Manchuria",
      "text": "On September 18, 1931, Japan invaded Manchuria, leading to the establishment of the puppet state of Manchukuo.",
      "date": "1931-09-18"
    },
    {
      "headline": "Second Sino-Japanese War",
      "text": "The Second Sino-Japanese War began on July 7, 1937, following the Marco Polo Bridge Incident, marking the start of full-scale hostilities between China and Japan.",
      "date": "1937-07-07"
    },
    {
      "headline": "Chinese Civil War Resumes",
      "text": "After the end of World War II in 1945, the Chinese Civil War between the Kuomintang and the Chinese Communist Party resumed in 1946.",
      "date": "1946"
    },
    {
      "headline": "Establishment of the People's Republic of China",
      "text": "On October 1, 1949, the Chinese Communist Party proclaimed the establishment of the People's Republic of China, marking the end of the Republic of China's control over mainland China.",
      "date": "1949-10-01"
    },
    {
      "headline": "Retreat to Taiwan",
      "text": "In December 1949, the government of the Republic of China retreated to Taiwan after losing the Chinese Civil War to the Chinese Communist Party.",
      "date": "1949-12"
    }
  ]
}

