{
  "timeline": [
    {
      "headline": "Roman Conquest",
      "text": "The Romans conquered the territory of present-day Catalonia, integrating it into the Roman Empire as part of the province of Hispania Tarraconensis.",
      "date": "-0197"
    },
    {
      "headline": "Visigothic Rule",
      "text": "After the fall of the Roman Empire, the Visigoths took control of the region, which became part of the Visigothic Kingdom.",
      "date": "0418"
    },
    {
      "headline": "Muslim Conquest",
      "text": "Muslim forces conquered most of the Iberian Peninsula, including Catalonia, in the early 8th century.",
      "date": "0711"
    },
    {
      "headline": "Frankish Conquest",
      "text": "The Carolingian Empire, under Charlemagne, conquered Catalonia, establishing the Spanish March as a buffer zone against Muslim territories.",
      "date": "0801"
    },
    {
      "headline": "County of Barcelona",
      "text": "Wilfred the Hairy became the Count of Barcelona, laying the foundations for the future Principality of Catalonia.",
      "date": "0878"
    },
    {
      "headline": "Union with Aragon",
      "text": "The County of Barcelona and the Kingdom of Aragon were united through the marriage of Ramon Berenguer IV and Petronilla of Aragon.",
      "date": "1137"
    },
    {
      "headline": "Catalan Constitutions",
      "text": "The first Catalan constitutions were established, marking the beginning of Catalonia's autonomous legal and political identity.",
      "date": "1283"
    },
    {
      "headline": "War of the Spanish Succession",
      "text": "Catalonia supported the Habsburg claimant, Charles VI, during the War of the Spanish Succession, leading to the Siege of Barcelona.",
      "date": "1701"
    },
    {
      "headline": "Fall of Barcelona",
      "text": "Barcelona fell to Bourbon forces on September 11, 1714, leading to the abolition of Catalan institutions and the imposition of the Nueva Planta decrees.",
      "date": "1714-09-11"
    },
    {
      "headline": "Renaixença Movement",
      "text": "The Renaixença, a cultural and literary movement, began in the 19th century, promoting Catalan language and identity.",
      "date": "1833"
    },
    {
      "headline": "Spanish Civil War",
      "text": "Catalonia became a major battleground during the Spanish Civil War, with Barcelona serving as the capital of the Republican government.",
      "date": "1936"
    },
    {
      "headline": "Francoist Repression",
      "text": "Under Francisco Franco's dictatorship, Catalan autonomy was suppressed, and the use of the Catalan language was restricted.",
      "date": "1939"
    },
    {
      "headline": "Restoration of Autonomy",
      "text": "Catalonia regained its autonomy with the approval of the Statute of Autonomy of Catalonia in 1979, following the end of Franco's regime.",
      "date": "1979"
    },
    {
      "headline": "2017 Independence Referendum",
      "text": "Catalonia held an independence referendum on October 1, 2017, which was declared illegal by the Spanish government.",
      "date": "2017-10-01"
    }
  ]
}

{
  "timeline": [
    {
      "headline": "First Hypothesis of the Sea Peoples",
      "text": "The hypothesis of the Sea Peoples was first proposed by 19th-century Egyptologists Emmanuel de Rougé and Gaston Maspero. They based their hypothesis on primary sources such as the reliefs on the Mortuary Temple of Ramesses III at Medinet Habu.",
      "date": "1800"
    },
    {
      "headline": "Attacks on Egypt",
      "text": "Around 1200 BCE, the Sea Peoples are hypothesized to have attacked Egypt and other Eastern Mediterranean regions. These events are depicted in the reliefs at the Mortuary Temple of Ramesses III.",
      "date": "-1200"
    },
    {
      "headline": "Battle of the Delta",
      "text": "In 1175 BCE, the Sea Peoples were defeated by Pharaoh Ramesses III in the Battle of the Delta. This battle is one of the most documented encounters with the Sea Peoples.",
      "date": "-1175"
    },
    {
      "headline": "Destruction of Ugarit",
      "text": "Around 1190-1185 BCE, the city of Ugarit was destroyed, an event often associated with the movements of the Sea Peoples.",
      "date": "-1190"
    },
    {
      "headline": "Late Bronze Age Collapse",
      "text": "The Sea Peoples are often linked to the Late Bronze Age collapse, a period of widespread societal collapse in the Eastern Mediterranean around 1200 BCE.",
      "date": "-1200"
    },
    {
      "headline": "Reevaluation of the Sea Peoples Hypothesis",
      "text": "More recent research generally regards the Sea Peoples as a symptom of events which were already in motion before their purported attacks, rather than the primary cause of the Late Bronze Age collapse.",
      "date": "2000"
    }
  ]
}

