{
  "timeline": [
    {
      "headline": "Discovery of Nuclein",
      "text": "In 1869, Friedrich Miescher discovered a substance he called 'nuclein' in the nuclei of human white blood cells, which was later identified as DNA.",
      "date": "1869"
    },
    {
      "headline": "Identification of DNA as a Distinct Molecule",
      "text": "In 1878, Albrecht Kossel isolated the five primary nucleobases that make up DNA and RNA, furthering the understanding of nucleic acids.",
      "date": "1878"
    },
    {
      "headline": "Discovery of DNA's Role in Heredity",
      "text": "In 1944, Oswald Avery, along with his colleagues Colin MacLeod and Maclyn McCarty, demonstrated that DNA is the substance that causes bacterial transformation, indicating its role in heredity.",
      "date": "1944"
    },
    {
      "headline": "Discovery of the Double Helix Structure",
      "text": "On April 25, 1953, James Watson and Francis Crick published their model of the DNA double helix structure, based on X-ray diffraction data produced by Rosalind Franklin and Maurice Wilkins.",
      "date": "1953-04-25"
    },
    {
      "headline": "Nobel Prize in Physiology or Medicine",
      "text": "In 1962, James Watson, Francis Crick, and Maurice Wilkins were awarded the Nobel Prize in Physiology or Medicine for their discoveries concerning the molecular structure of nucleic acids and its significance for information transfer in living material.",
      "date": "1962"
    },
    {
      "headline": "Development of DNA Sequencing Techniques",
      "text": "In 1977, Frederick Sanger developed the chain-termination method for sequencing DNA, which became the basis for the first generation of DNA sequencing technologies.",
      "date": "1977"
    },
    {
      "headline": "Completion of the Human Genome Project",
      "text": "In April 2003, the Human Genome Project was completed, mapping the entire human genome and marking a significant milestone in genetics and molecular biology.",
      "date": "2003-04"
    }
  ]
}

