    {
      "headline": "The Great Molasses Flood",
      "text": "On January 15, 1919, a large storage tank filled with 2.3 million gallons of molasses burst, sending a wave of molasses through the streets of Boston's North End. The wave reached speeds of up to 35 miles per hour and was 25 feet high at its peak.",
      "date": "1919-01-15"
    },
    {
      "headline": "Casualties and Damage",
      "text": "The disaster resulted in 21 deaths and about 150 injuries. Buildings were swept off their foundations, and the area was flooded with molasses, causing significant property damage.",
      "date": "1919-01-15"
    },
    {
      "headline": "Cleanup Efforts",
      "text": "Cleanup efforts began immediately after the disaster. It took weeks to remove the molasses from the streets, and the harbor remained brown with molasses until the summer.",
      "date": "1919-01"
    },
    {
      "headline": "Legal Aftermath",
      "text": "The disaster led to a lengthy legal battle, with over 125 lawsuits filed against the United States Industrial Alcohol Company. The court ruled in 1925 that the company was responsible for the disaster due to negligence.",
      "date": "1925"
    },
    {
      "headline": "Impact on Regulations",
      "text": "The Great Molasses Flood led to stricter regulations and building codes in Boston and influenced engineering practices across the United States to prevent similar disasters.",
      "date": "1925"
    }
  ]
}

