{
  "timeline": [
    {
      "headline": "Umayyad Conquest of Hispania",
      "text": "In 711, the Umayyad Caliphate began the conquest of the Iberian Peninsula, which would later be known as al-Andalus. This marked the beginning of Muslim rule in the region, which would last for several centuries.",
      "date": "0711"
    },
    {
      "headline": "Battle of Tours",
      "text": "In 732, the Moors were defeated by Frankish and Burgundian forces under Charles Martel at the Battle of Tours, halting their northward expansion into Europe.",
      "date": "0732"
    },
    {
      "headline": "Establishment of the Emirate of Córdoba",
      "text": "In 756, Abd al-Rahman I established the Emirate of Córdoba, which became a major center of Islamic culture and learning in Europe.",
      "date": "0756"
    },
    {
      "headline": "Golden Age of al-Andalus",
      "text": "During the 10th century, al-Andalus experienced a period of prosperity and cultural flourishing, particularly under the rule of Abd al-Rahman III, who declared himself Caliph in 929.",
      "date": "0929"
    },
    {
      "headline": "Fall of the Caliphate of Córdoba",
      "text": "In 1031, the Caliphate of Córdoba collapsed, leading to the fragmentation of al-Andalus into smaller kingdoms known as taifas.",
      "date": "1031"
    },
    {
      "headline": "Almoravid and Almohad Dynasties",
      "text": "In the 11th and 12th centuries, the Almoravid and Almohad dynasties from North Africa took control of al-Andalus, bringing a more orthodox form of Islam.",
      "date": "1100"
    },
    {
      "headline": "Battle of Las Navas de Tolosa",
      "text": "In 1212, the Christian forces of the Iberian Peninsula defeated the Almohads at the Battle of Las Navas de Tolosa, marking a turning point in the Reconquista.",
      "date": "1212"
    },
    {
      "headline": "Fall of Granada",
      "text": "In 1492, the last Muslim stronghold in Spain, the Emirate of Granada, fell to the Catholic Monarchs Ferdinand and Isabella, completing the Reconquista.",
      "date": "1492"
    },
    {
      "headline": "Expulsion of the Moriscos",
      "text": "Between 1609 and 1614, the Moriscos, Muslims who had converted to Christianity, were expelled from Spain, marking the end of significant Muslim presence in the region.",
      "date": "1609"
    }
  ]
}

