{
  "timeline": [
    {
      "headline": "Establishment of the Ming Dynasty",
      "text": "The Ming dynasty was officially established in 1368 by Zhu Yuanzhang, who became the Hongwu Emperor, following the collapse of the Mongol-led Yuan dynasty.",
      "date": "1368"
    },
    {
      "headline": "Reign of the Hongwu Emperor",
      "text": "Zhu Yuanzhang, known as the Hongwu Emperor, ruled from 1368 to 1398. He implemented major reforms to consolidate power and stabilize the economy.",
      "date": "1368"
    },
    {
      "headline": "Reign of the Yongle Emperor",
      "text": "The Yongle Emperor, Zhu Di, ruled from 1402 to 1424. He moved the capital from Nanjing to Beijing and commissioned the construction of the Forbidden City.",
      "date": "1402"
    },
    {
      "headline": "Completion of the Forbidden City",
      "text": "The construction of the Forbidden City in Beijing was completed in 1420, serving as the imperial palace for the Ming and subsequent Qing dynasties.",
      "date": "1420"
    },
    {
      "headline": "Zheng He's Voyages",
      "text": "Between 1405 and 1433, the Ming dynasty sponsored seven maritime expeditions led by Admiral Zheng He, reaching as far as East Africa.",
      "date": "1405"
    },
    {
      "headline": "Tumu Crisis",
      "text": "In 1449, the Ming army suffered a significant defeat at the hands of the Mongols at the Tumu Fortress, leading to the capture of the Zhengtong Emperor.",
      "date": "1449"
    },
    {
      "headline": "Reign of the Wanli Emperor",
      "text": "The Wanli Emperor ruled from 1572 to 1620, a period marked by internal strife and external threats, including the Imjin War against Japan.",
      "date": "1572"
    },
    {
      "headline": "Fall of Beijing",
      "text": "In 1644, Beijing fell to a rebellion led by Li Zicheng, marking the end of the Ming dynasty's control over China.",
      "date": "1644"
    },
    {
      "headline": "Southern Ming Regimes",
      "text": "After the fall of Beijing, remnants of the Ming imperial family established several rump regimes known as the Southern Ming, which lasted until 1662.",
      "date": "1644"
    },
    {
      "headline": "End of the Southern Ming",
      "text": "The last of the Southern Ming regimes was defeated in 1662, marking the definitive end of the Ming dynasty.",
      "date": "1662"
    }
  ]
}

