{
  "timeline": [
    {
      "headline": "Synthesis of Methaqualone",
      "text": "Methaqualone was first synthesized in India in 1951 by Indra Kishore Kacker and Syed Husain Zaheer at the Central Drug Research Institute.",
      "date": "1951"
    },
    {
      "headline": "Introduction to Medical Use",
      "text": "Methaqualone was introduced to the medical market as a hypnotic sedative in the 1960s. It was initially marketed as a safe alternative to barbiturates.",
      "date": "1960"
    },
    {
      "headline": "Popularity in the United States",
      "text": "During the late 1960s and early 1970s, methaqualone became widely popular in the United States under the brand name Quaalude.",
      "date": "1970"
    },
    {
      "headline": "Schedule II Classification",
      "text": "In 1973, due to increasing abuse and addiction, methaqualone was classified as a Schedule II controlled substance in the United States.",
      "date": "1973"
    },
    {
      "headline": "Reclassification to Schedule I",
      "text": "In 1984, methaqualone was reclassified as a Schedule I controlled substance in the United States, indicating a high potential for abuse and no accepted medical use.",
      "date": "1984"
    },
    {
      "headline": "Cessation of Commercial Production",
      "text": "Commercial production of methaqualone was halted in the mid-1980s due to widespread abuse and addictiveness.",
      "date": "1985"
    }
  ]
}

{
  "timeline": [
    {
      "headline": "Formation of SEAL Team Six",
      "text": "SEAL Team Six was formed in 1980 by Commander Richard Marcinko in response to the failed Operation Eagle Claw during the Iran hostage crisis. The unit was created to provide a dedicated counter-terrorism capability for the United States Navy.",
      "date": "1980"
    },
    {
      "headline": "Renaming to DEVGRU",
      "text": "In 1987, SEAL Team Six was officially disbanded and rebranded as the Naval Special Warfare Development Group (DEVGRU). This change was part of a broader reorganization of special operations forces.",
      "date": "1987"
    },
    {
      "headline": "Operation Just Cause",
      "text": "In December 1989, DEVGRU participated in Operation Just Cause, the United States invasion of Panama, to capture Panamanian leader Manuel Noriega.",
      "date": "1989-12"
    },
    {
      "headline": "Operation Gothic Serpent",
      "text": "In 1993, DEVGRU was involved in Operation Gothic Serpent in Somalia, which included the Battle of Mogadishu, famously depicted in the book and film 'Black Hawk Down'.",
      "date": "1993"
    },
    {
      "headline": "Operation Enduring Freedom",
      "text": "Following the September 11 attacks in 2001, DEVGRU was deployed as part of Operation Enduring Freedom in Afghanistan, conducting numerous missions against Taliban and Al-Qaeda targets.",
      "date": "2001"
    },
    {
      "headline": "Operation Neptune Spear",
      "text": "On May 2, 2011, DEVGRU conducted Operation Neptune Spear, which resulted in the death of Osama bin Laden in Abbottabad, Pakistan. This mission was one of the most high-profile operations in the unit's history.",
      "date": "2011-05-02"
    },
    {
      "headline": "Operation Octave Fusion",
      "text": "In January 2012, DEVGRU successfully rescued American hostage Jessica Buchanan in Somalia during Operation Octave Fusion.",
      "date": "2012-01"
    }
  ]
}

