      "headline": "Commissioning of the Arc de Triomphe",
      "text": "On 1806-02-18, Napoleon Bonaparte commissioned the construction of the Arc de Triomphe to honor the Grande Armée, the French army that had conquered most of Europe.",
      "date": "1806-02-18"
    },
    {
      "headline": "Laying of the Foundation Stone",
      "text": "The foundation stone of the Arc de Triomphe was laid on 1806-08-15, Napoleon's birthday.",
      "date": "1806-08-15"
    },
    {
      "headline": "Construction Halted",
      "text": "Construction was halted in 1814 following Napoleon's abdication and the fall of the First French Empire.",
      "date": "1814"
    },
    {
      "headline": "Construction Resumed",
      "text": "Construction resumed in 1826 during the reign of King Louis XVIII.",
      "date": "1826"
    },
    {
      "headline": "Completion of the Arc de Triomphe",
      "text": "The Arc de Triomphe was completed in 1836 under the reign of King Louis-Philippe.",
      "date": "1836"
    },
    {
      "headline": "Inauguration of the Arc de Triomphe",
      "text": "The Arc de Triomphe was officially inaugurated on 1836-07-29.",
      "date": "1836-07-29"
    },
    {
      "headline": "Installation of the Tomb of the Unknown Soldier",
      "text": "The Tomb of the Unknown Soldier was installed beneath the Arc de Triomphe on 1920-11-10 to honor unidentified soldiers who died in World War I.",
      "date": "1920-11-10"
    },
    {
      "headline": "First Eternal Flame Lit",
      "text": "The first eternal flame in Western Europe since the Vestal Virgins' fire was lit at the Tomb of the Unknown Soldier on 1923-11-11.",
      "date": "1923-11-11"
    }
  ]
}

{
  "timeline": [
    {
      "headline": "Birth of Arthur Wellesley",
      "text": "Arthur Wellesley was born on May 1, 1769, in Dublin, Ireland.",
      "date": "1769-05-01"
    },
    {
      "headline": "Commissioned as an Ensign",
      "text": "In 1787, Arthur Wellesley was commissioned as an ensign in the British Army.",
      "date": "1787"
