    {
      "headline": "Battle of Seringapatam",
      "text": "In 1799, Arthur Wellesley played a significant role in the Battle of Seringapatam, which led to the defeat of Tipu Sultan and the end of the Fourth Anglo-Mysore War.",
      "date": "1799"
    },
    {
      "headline": "Appointed Governor of Seringapatam and Mysore",
      "text": "In 1799, following the victory at Seringapatam, Wellesley was appointed Governor of Seringapatam and Mysore.",
      "date": "1799"
    },
    {
      "headline": "Battle of Assaye",
      "text": "On September 23, 1803, Wellesley led British forces to victory at the Battle of Assaye during the Second Anglo-Maratha War.",
      "date": "1803-09-23"
    },
    {
      "headline": "Battle of Argaon",
      "text": "On November 29, 1803, Wellesley achieved another victory at the Battle of Argaon.",
      "date": "1803-11-29"
    },
    {
      "headline": "Battle of Vimeiro",
      "text": "On August 21, 1808, Wellesley defeated French forces at the Battle of Vimeiro during the Peninsular War.",
      "date": "1808-08-21"
    },
    {
      "headline": "Battle of Talavera",
      "text": "On July 27-28, 1809, Wellesley secured a victory against the French at the Battle of Talavera.",
      "date": "1809-07-27"
    },
    {
      "headline": "Created Duke of Wellington",
      "text": "In 1814, Arthur Wellesley was created the Duke of Wellington for his military successes.",
      "date": "1814"
    },
    {
      "headline": "Battle of Waterloo",
      "text": "On June 18, 1815, Wellington led the allied forces to victory against Napoleon at the Battle of Waterloo, effectively ending the Napoleonic Wars.",
      "date": "1815-06-18"
    },
    {
      "headline": "First Term as Prime Minister",
      "text": "Wellington served as Prime Minister of the United Kingdom from January 22, 1828, to November 16, 1830.",
      "date": "1828-01-22"
    },
    {
      "headline": "Second Term as Prime Minister",
      "text": "Wellington briefly served as Prime Minister again from November 14, 1834, to December 10, 1834.",
      "date": "1834-11-14"
    },
    {
      "headline": "Death of Arthur Wellesley",
      "text": "Arthur Wellesley, 1st Duke of Wellington, died on September 14, 1852, at Walmer Castle in Kent, England.",
      "date": "1852-09-14"
    }
  ]
}

