    {
      "headline": "Establishment of the Reserve Bank of India",
      "text": "The Reserve Bank of India was established on April 1, 1935, in accordance with the provisions of the Reserve Bank of India Act, 1934.",
      "date": "1935-04-01"
    },
    {
      "headline": "Nationalization of the Reserve Bank of India",
      "text": "The Reserve Bank of India was nationalized on January 1, 1949, following the independence of India.",
      "date": "1949-01-01"
    },
    {
      "headline": "Introduction of the Indian Rupee",
      "text": "The Reserve Bank of India took over the responsibility of issuing currency and managing the Indian rupee, which became the sole legal tender in India.",
      "date": "1949"
    },
    {
      "headline": "Establishment of the State Bank of India",
      "text": "In 1955, the Reserve Bank of India played a key role in the establishment of the State Bank of India, which was formed by nationalizing the Imperial Bank of India.",
      "date": "1955"
    },
    {
      "headline": "Introduction of the Banking Regulation Act",
      "text": "The Banking Regulation Act was introduced in 1949, giving the Reserve Bank of India the power to regulate, control, and inspect banks in India.",
      "date": "1949"
    },
    {
      "headline": "Formation of the Deposit Insurance Corporation",
      "text": "In 1962, the Deposit Insurance Corporation was established under the aegis of the Reserve Bank of India to provide insurance of deposits and guarantee credit facilities.",
      "date": "1962"
    },
    {
      "headline": "Introduction of the Liberalization Policy",
      "text": "In 1991, the Reserve Bank of India played a crucial role in the economic liberalization policy, which led to significant reforms in the Indian economy.",
      "date": "1991"
    },
    {
      "headline": "Implementation of the Monetary Policy Framework Agreement",
      "text": "In 2016, the Reserve Bank of India and the Government of India signed the Monetary Policy Framework Agreement, which aimed to maintain price stability while keeping in mind the objective of growth.",
      "date": "2016"
    }
  ]
}

