    {
      "headline": "Birth of George Washington Carver",
      "text": "George Washington Carver was born into slavery in Diamond, Missouri, in January 1864.",
      "date": "1864-01"
    },
    {
      "headline": "Kidnapping and Return",
      "text": "In 1865, Carver was kidnapped along with his sister and mother by raiders from the neighboring state of Arkansas. He was eventually returned to his owners, Moses and Susan Carver.",
      "date": "1865"
    },
    {
      "headline": "Education Begins",
      "text": "In the late 1870s, Carver left the Carver farm to pursue an education. He attended a series of schools before earning his high school diploma in Minneapolis, Kansas.",
      "date": "1870"
    },
    {
      "headline": "Enrollment at Simpson College",
      "text": "In 1890, Carver enrolled at Simpson College in Indianola, Iowa, where he studied art and piano.",
      "date": "1890"
    },
    {
      "headline": "Transfer to Iowa State Agricultural College",
      "text": "In 1891, Carver transferred to Iowa State Agricultural College (now Iowa State University) to study botany.",
      "date": "1891"
    },
    {
      "headline": "Graduation and First African American Faculty Member",
      "text": "In 1896, Carver became the first African American to earn a Bachelor of Science degree from Iowa State Agricultural College. He was also appointed as the first African American faculty member at the college.",
      "date": "1896"
    },
    {
      "headline": "Joining Tuskegee Institute",
      "text": "In 1896, Carver accepted an invitation from Booker T. Washington to head the agriculture department at Tuskegee Institute in Alabama.",
      "date": "1896"
    },
    {
      "headline": "Promotion of Crop Rotation",
      "text": "Throughout the early 1900s, Carver promoted the practice of crop rotation and the planting of alternative crops such as peanuts, soybeans, and sweet potatoes to improve soil health.",
      "date": "1900"
    },
    {
      "headline": "Development of Peanut Products",
      "text": "In the early 1910s, Carver developed numerous products from peanuts, including dyes, plastics, and gasoline, which he showcased at the 1920 Peanut Growers Association convention.",
      "date": "1910"
    },
    {
      "headline": "Testimony Before Congress",
      "text": "In 1921, Carver testified before the United States Congress to promote the peanut industry, which led to the passage of a tariff on imported peanuts.",
      "date": "1921"
    },
    {
      "headline": "Death of George Washington Carver",
      "text": "George Washington Carver died on January 5, 1943, in Tuskegee, Alabama, after falling down the stairs at his home.",
      "date": "1943-01-05"
    }
  ]
}

