{
  "timeline": [
    {
      "headline": "Vedic Period",
      "text": "The Vedic period (c. 1500 – c. 500 BCE) is marked by the composition of the Vedas, the oldest scriptures of Hinduism, which laid the foundation for Hindu religious practices.",
      "date": "-1500"
    },
    {
      "headline": "Rise of Jainism",
      "text": "Jainism was established as a major religion in India around the 6th century BCE, with Mahavira, the 24th Tirthankara, playing a significant role in its development.",
      "date": "-0600"
    },
    {
      "headline": "Buddhism Founded",
      "text": "Buddhism was founded in the late 6th century BCE by Siddhartha Gautama, known as the Buddha, in northeastern India.",
      "date": "-0563"
    },
    {
      "headline": "Mauryan Empire and Ashoka's Conversion",
      "text": "During the reign of Emperor Ashoka (268–232 BCE), Buddhism spread widely across India and beyond, following Ashoka's conversion to Buddhism after the Kalinga War.",
      "date": "-0268"
    },
    {
      "headline": "Gupta Empire and Hindu Renaissance",
      "text": "The Gupta Empire (c. 320–550 CE) is often referred to as the Golden Age of India, during which Hindu culture, science, and political systems flourished.",
      "date": "0320"
    },
    {
      "headline": "Bhakti Movement",
      "text": "The Bhakti movement, which emphasized personal devotion to deities, began in South India in the 7th century and spread throughout the Indian subcontinent.",
      "date": "0700"
    },
    {
      "headline": "Birth of Sikhism",
      "text": "Sikhism was founded by Guru Nanak in the late 15th century in the Punjab region, emphasizing monotheism and equality.",
      "date": "1469"
    },
    {
      "headline": "Mughal Empire and Religious Syncretism",
      "text": "During the Mughal Empire (1526–1857), there was significant religious syncretism, especially under Akbar the Great, who promoted a policy of tolerance and attempted to create a syncretic religion called Din-i Ilahi.",
      "date": "1526"
    },
    {
      "headline": "British Colonial Rule and Religious Reform Movements",
      "text": "During British colonial rule (1858–1947), several religious reform movements emerged, such as the Brahmo Samaj and Arya Samaj, which sought to modernize Hinduism and address social issues.",
      "date": "1858"
    },
    {
      "headline": "Partition of India",
      "text": "In 1947, India gained independence from British rule, leading to the partition of India and Pakistan, which was largely based on religious lines, resulting in significant demographic changes.",
      "date": "1947"
    },
    {
      "headline": "Hindu-Muslim Riots and Ayodhya Dispute",
      "text": "The late 20th century saw increased Hindu-Muslim tensions, notably the Ayodhya dispute, which culminated in the demolition of the Babri Masjid in 1992.",
      "date": "1992"
    }
  ]
}

