  "timeline": [
    {
      "headline": "Birth of Yuri Gagarin",
      "text": "Yuri Alekseyevich Gagarin was born on March 9, 1934, in the village of Klushino, near Gzhatsk (now Gagarin), in the Smolensk Oblast of the Russian Soviet Federative Socialist Republic, Soviet Union.",
      "date": "1934-03-09"
    },
    {
      "headline": "Enrolled in Technical School",
      "text": "In 1951, Gagarin enrolled in a technical school in Saratov, where he studied tractors.",
      "date": "1951"
    },
    {
      "headline": "Joined Soviet Air Force",
      "text": "In 1955, Gagarin was drafted into the Soviet Army and sent to the First Chkalov Air Force Pilot's School in Orenburg.",
      "date": "1955"
    },
    {
      "headline": "Graduated as a Fighter Pilot",
      "text": "Gagarin graduated from the Orenburg Pilot's School on November 7, 1957, and was commissioned as a lieutenant in the Soviet Air Force.",
      "date": "1957-11-07"
    },
    {
      "headline": "Selected as a Cosmonaut",
      "text": "In 1960, Gagarin was selected with 19 other candidates for the Soviet space program. He was chosen as one of the top six candidates for the Vostok program.",
      "date": "1960"
    },
    {
      "headline": "First Human in Space",
      "text": "On April 12, 1961, Yuri Gagarin became the first human to journey into outer space. He orbited Earth once aboard the Vostok 1 spacecraft, a flight that lasted 108 minutes.",
      "date": "1961-04-12"
    },
    {
      "headline": "Hero of the Soviet Union",
      "text": "Following his successful spaceflight, Gagarin was awarded the title of Hero of the Soviet Union, the nation's highest honor, on April 14, 1961.",
      "date": "1961-04-14"
    },
    {
      "headline": "Deputy Training Director of Cosmonaut Training Centre",
      "text": "In 1963, Gagarin was appointed as the Deputy Training Director of the Cosmonaut Training Centre, where he worked on designs for a reusable spacecraft.",
      "date": "1963"
    },
    {
      "headline": "Death of Yuri Gagarin",
      "text": "Yuri Gagarin died on March 27, 1968, in a plane crash while on a routine training flight near the town of Kirzhach.",
      "date": "1968-03-27"
    }
  ]
}

