{
  "timeline": [
    {
      "headline": "Earliest Mentions of Yoga",
      "text": "The earliest references to yoga are found in the Rigveda, one of the oldest sacred texts of Hinduism, dating back to around 1500 BCE.",
      "date": "-1500"
    },
    {
      "headline": "Development of Yoga in the Upanishads",
      "text": "Between 800 and 500 BCE, the concept of yoga began to take a more defined shape in the Upanishads, which are philosophical texts that form the theoretical basis for the Hindu religion.",
      "date": "-0800"
    },
    {
      "headline": "Yoga in the Bhagavad Gita",
      "text": "Around 400 BCE, the Bhagavad Gita, a 700-verse Hindu scripture that is part of the Indian epic Mahabharata, discusses various forms of yoga, including karma yoga, bhakti yoga, and jnana yoga.",
      "date": "-0400"
    },
    {
      "headline": "Patanjali's Yoga Sutras",
      "text": "Around 400 CE, the sage Patanjali compiled the Yoga Sutras, a foundational text for classical yoga philosophy, outlining the eight limbs of yoga.",
      "date": "0400"
    },
    {
      "headline": "Hatha Yoga Pradipika",
      "text": "In the 15th century, the Hatha Yoga Pradipika was written by Swami Swatmarama. It is one of the most influential texts on hatha yoga, detailing physical postures and breathing techniques.",
      "date": "1400"
    },
    {
      "headline": "Introduction of Yoga to the West",
      "text": "In the late 19th and early 20th centuries, yoga began to be introduced to the Western world, notably through the efforts of Swami Vivekananda, who spoke at the Parliament of the World's Religions in Chicago in 1893.",
      "date": "1893"
    },
    {
      "headline": "Formation of the International Yoga Federation",
      "text": "In 1987, the International Yoga Federation was established to promote yoga worldwide.",
      "date": "1987"
    },
    {
      "headline": "International Day of Yoga",
      "text": "In 2014, the United Nations declared June 21 as the International Day of Yoga, following a proposal by Indian Prime Minister Narendra Modi.",
      "date": "2014"
    }
  ]
}

