      "text": "Lisbon is believed to have been founded by the Phoenicians around 1200 BCE, who established a settlement called Alis Ubo.",
      "date": "-1200"
    },
    {
      "headline": "Roman Rule",
      "text": "Lisbon, known as Olissipo, became part of the Roman Empire in 205 BCE after the defeat of the Carthaginians.",
      "date": "-0205"
    },
    {
      "headline": "Visigothic Rule",
      "text": "After the fall of the Roman Empire, Lisbon was ruled by the Visigoths starting in 585 CE.",
      "date": "0585"
    },
    {
      "headline": "Moorish Conquest",
      "text": "Lisbon was conquered by the Moors in 711 CE, becoming an important trading city in the Islamic world.",
      "date": "0711"
    },
    {
      "headline": "Reconquista and Christian Rule",
      "text": "Lisbon was reconquered by Christian forces led by King Afonso I of Portugal in 1147 CE during the Second Crusade.",
      "date": "1147"
    },
    {
      "headline": "Lisbon Becomes the Capital",
      "text": "In 1255, Lisbon was officially made the capital of Portugal, due to its strategic location and economic importance.",
      "date": "1255"
    },
    {
      "headline": "Great Lisbon Earthquake",
      "text": "On November 1, 1755, Lisbon was struck by a devastating earthquake, followed by a tsunami and fires, which destroyed much of the city.",
      "date": "1755-11-01"
    },
    {
      "headline": "Pombaline Reforms",
      "text": "Following the 1755 earthquake, the Marquis of Pombal implemented extensive rebuilding and modernization efforts in Lisbon.",
      "date": "1755"
    },
    {
      "headline": "Portuguese Revolution",
      "text": "On October 5, 1910, the Portuguese monarchy was overthrown, and Lisbon became the capital of the newly established Portuguese Republic.",
      "date": "1910-10-05"
    },
    {
      "headline": "Carnation Revolution",
      "text": "On April 25, 1974, the Carnation Revolution took place in Lisbon, leading to the fall of the Estado Novo regime and the establishment of democracy in Portugal.",
      "date": "1974-04-25"
    },
    {
      "headline": "Lisbon Expo '98",
      "text": "Lisbon hosted the World Exposition in 1998, which led to significant urban renewal and development in the city.",
      "date": "1998"
    }
  ]
}

