  "timeline": [
    {
      "headline": "Creation of C++",
      "text": "C++ was created by Bjarne Stroustrup at Bell Labs as an enhancement to the C programming language. The development began in 1979.",
      "date": "1979"
    },
    {
      "headline": "First Release of C++",
      "text": "The first version of C++ was released in 1985. This version included classes, basic inheritance, inlining, and default function arguments.",
      "date": "1985"
    },
    {
      "headline": "Publication of 'The C++ Programming Language'",
      "text": "Bjarne Stroustrup published the book 'The C++ Programming Language' in 1985, which served as the first comprehensive guide to the language.",
      "date": "1985"
    },
    {
      "headline": "C++ 2.0 Release",
      "text": "C++ 2.0 was released in 1989, introducing multiple inheritance, abstract classes, static member functions, const member functions, and protected members.",
      "date": "1989"
    },
    {
      "headline": "ANSI C++ Standardization",
      "text": "In 1990, the ANSI committee X3J16 was formed to standardize C++. This marked the beginning of the formal standardization process.",
      "date": "1990"
    },
    {
      "headline": "C++ 98 Standard",
      "text": "The first international standard for C++, ISO/IEC 14882:1998, was published in 1998. It included templates, the Standard Template Library (STL), and exception handling.",
      "date": "1998"
    },
    {
      "headline": "C++ 03 Standard",
      "text": "A bug fix release, C++03, was published in 2003. It addressed defects in C++98 but did not introduce new features.",
      "date": "2003"
    },
    {
      "headline": "C++ 11 Standard",
      "text": "C++11, formerly known as C++0x, was published in 2011. It introduced features like auto keyword, lambda expressions, nullptr, and smart pointers.",
      "date": "2011"
    },
    {
      "headline": "C++ 14 Standard",
      "text": "C++14 was published in 2014, providing bug fixes and small improvements over C++11, such as generic lambdas and relaxed constexpr restrictions.",
      "date": "2014"
    },
    {
      "headline": "C++ 17 Standard",
      "text": "C++17 was published in 2017, introducing features like std::optional, std::variant, and std::any, as well as improvements to the standard library.",
      "date": "2017"
    },
    {
      "headline": "C++ 20 Standard",
      "text": "C++20 was published in 2020, adding concepts, ranges, coroutines, and modules, among other features, significantly expanding the language's capabilities.",
      "date": "2020"
    }
  ]
}

