    },
    {
      "headline": "Standardization Reforms",
      "text": "Qin Shi Huang implemented major reforms, including standardizing weights, measures, and the writing system across China in 221 BCE.",
      "date": "-0221"
    },
    {
      "headline": "Construction of the Great Wall",
      "text": "Around 214 BCE, Qin Shi Huang began the construction of the Great Wall of China to protect against northern invasions.",
      "date": "-0214"
    },
    {
      "headline": "Assassination Attempts",
      "text": "Qin Shi Huang survived multiple assassination attempts, including one by Jing Ke in 227 BCE.",
      "date": "-0227"
    },
    {
      "headline": "Search for Immortality",
      "text": "Qin Shi Huang was obsessed with immortality and sent expeditions in search of elixirs of life around 210 BCE.",
      "date": "-0210"
    },
    {
      "headline": "Death of Qin Shi Huang",
      "text": "Qin Shi Huang died in 210 BCE during a tour of Eastern China.",
      "date": "-0210"
    },
    {
      "headline": "Burial in the Mausoleum",
      "text": "Qin Shi Huang was buried in a massive mausoleum near Xi'an, which is famously guarded by the Terracotta Army, completed around 210 BCE.",
      "date": "-0210"
    }
  ]
}

