{
  "timeline": [
    {
      "headline": "Birth of Nicolaus Copernicus",
      "text": "Nicolaus Copernicus was born on February 19, 1473, in Toruń, Poland.",
      "date": "1473-02-19"
    },
    {
      "headline": "Enrollment at University of Kraków",
      "text": "In 1491, Copernicus enrolled at the University of Kraków, where he studied mathematics and astronomy.",
      "date": "1491"
    },
    {
      "headline": "Studies in Italy",
      "text": "From 1496 to 1503, Copernicus studied at the University of Bologna, the University of Padua, and the University of Ferrara, focusing on law, medicine, and astronomy.",
      "date": "1496"
    },
    {
      "headline": "Appointment as Canon",
      "text": "In 1497, Copernicus was appointed a canon at Frombork Cathedral, a position he held for the rest of his life.",
      "date": "1497"
    },
    {
      "headline": "Return to Poland",
      "text": "Copernicus returned to Poland in 1503 after completing his studies in Italy.",
      "date": "1503"
    },
    {
      "headline": "Development of Heliocentric Theory",
      "text": "Between 1508 and 1514, Copernicus developed his heliocentric model of the universe, which placed the Sun at the center rather than the Earth.",
      "date": "1508"
    },
    {
      "headline": "Publication of Commentariolus",
      "text": "Around 1514, Copernicus circulated a manuscript known as the 'Commentariolus', outlining his heliocentric theory.",
      "date": "1514"
    },
    {
      "headline": "Publication of De revolutionibus orbium coelestium",
      "text": "In 1543, Copernicus published his seminal work 'De revolutionibus orbium coelestium' (On the Revolutions of the Celestial Spheres), which detailed his heliocentric theory.",
      "date": "1543"
    },
    {
      "headline": "Death of Nicolaus Copernicus",
      "text": "Nicolaus Copernicus died on May 24, 1543, in Frombork, Poland, shortly after the publication of his groundbreaking work.",
      "date": "1543-05-24"
    }
  ]
}

