{
  "timeline": [
    {
      "headline": "Establishment of Nokia",
      "text": "Nokia was founded as a pulp mill by Fredrik Idestam in 1865 in Tampere, Finland.",
      "date": "1865"
    },
    {
      "headline": "Nokia Moves to Nokia Town",
      "text": "In 1868, Fredrik Idestam opened a second mill in the town of Nokia, Finland, which later became the company's namesake.",
      "date": "1868"
    },
    {
      "headline": "Nokia Ab Formation",
      "text": "In 1871, Fredrik Idestam and Leo Mechelin transformed the company into a share company and renamed it Nokia Ab.",
      "date": "1871"
    },
    {
      "headline": "Merger with Finnish Rubber Works",
      "text": "In 1922, Nokia merged with Finnish Rubber Works, which later became a part of the Nokia Corporation.",
      "date": "1922"
    },
    {
      "headline": "Merger with Finnish Cable Works",
      "text": "In 1922, Nokia also merged with Finnish Cable Works, further expanding its industrial operations.",
      "date": "1922"
    },
    {
      "headline": "Nokia Corporation Formation",
      "text": "In 1967, the three companies, Nokia Ab, Finnish Rubber Works, and Finnish Cable Works, merged to form the Nokia Corporation.",
      "date": "1967"
    },
    {
      "headline": "Entry into Telecommunications",
      "text": "In the 1970s, Nokia entered the telecommunications industry by producing radio telephones for the army and emergency services.",
      "date": "1970"
    },
    {
      "headline": "Launch of the Mobira Senator",
      "text": "In 1982, Nokia launched the Mobira Senator, its first car phone.",
      "date": "1982"
    },
    {
      "headline": "Introduction of the Nokia 1011",
      "text": "In 1992, Nokia introduced the Nokia 1011, the first mass-produced GSM phone.",
      "date": "1992"
    },
    {
      "headline": "Nokia Becomes a Mobile Phone Leader",
      "text": "By the late 1990s, Nokia became the world's largest mobile phone manufacturer.",
      "date": "1998"
    },
    {
      "headline": "Peak Position in Fortune Global 500",
      "text": "In 2009, Nokia reached its peak position at 85th place in the Fortune Global 500 rankings.",
      "date": "2009"
    },
    {
      "headline": "Sale of Mobile Phone Business to Microsoft",
      "text": "In 2014, Nokia sold its mobile phone business to Microsoft.",
      "date": "2014"
    },
    {
      "headline": "Acquisition of Alcatel-Lucent",
      "text": "In 2016, Nokia completed the acquisition of Alcatel-Lucent, a French global telecommunications equipment company.",
      "date": "2016"
    },
    {
      "headline": "Nokia's Global Presence in 2020",
      "text": "By 2020, Nokia employed approximately 92,000 people across over 100 countries and did business in more than 130 countries.",
      "date": "2020"
    }
  ]
}

