      "headline": "Birth of Xerxes I",
      "text": "Xerxes I was born to Darius the Great and Atossa, a daughter of Cyrus the Great.",
      "date": "-0519"
    },
    {
      "headline": "Xerxes Becomes King of Kings",
      "text": "In 486 BC, Xerxes I ascended to the throne as the fourth King of Kings of the Achaemenid Empire following the death of his father, Darius the Great.",
      "date": "-0486"
    },
    {
      "headline": "Revolt in Egypt",
      "text": "Shortly after becoming king, Xerxes I faced a revolt in Egypt, which he successfully crushed, consolidating his power over the region.",
      "date": "-0486"
    },
    {
      "headline": "Revolt in Babylon",
      "text": "Xerxes I also dealt with a revolt in Babylon, further securing his rule over the Achaemenid Empire.",
      "date": "-0482"
    },
    {
      "headline": "Invasion of Greece",
      "text": "In 480 BC, Xerxes I launched a massive invasion of Greece, personally leading his army across the Hellespont into Europe.",
      "date": "-0480"
    },
    {
      "headline": "Battle of Thermopylae",
      "text": "Xerxes I achieved a significant victory at the Battle of Thermopylae in 480 BC, where his forces defeated a small Greek force led by King Leonidas of Sparta.",
      "date": "-0480"
    },
    {
      "headline": "Battle of Artemisium",
      "text": "In 480 BC, Xerxes I's navy engaged Greek forces at the Battle of Artemisium, achieving a tactical stalemate.",
      "date": "-0480"
    },
    {
      "headline": "Capture and Razing of Athens",
      "text": "Xerxes I captured and razed Athens in 480 BC, marking a high point in his campaign against Greece.",
      "date": "-0480"
    },
    {
      "headline": "Battle of Salamis",
      "text": "In 480 BC, Xerxes I's forces were defeated by the Greek navy at the Battle of Salamis, a turning point in the Greco-Persian Wars.",
      "date": "-0480"
    },
    {
      "headline": "Retreat from Greece",
      "text": "Following the defeat at Salamis, Xerxes I retreated with the majority of his army back to Asia, fearing entrapment in Europe.",
      "date": "-0480"
    },
    {
      "headline": "Battle of Plataea",
      "text": "In 479 BC, the Persian forces left behind by Xerxes I, led by Mardonius, were defeated at the Battle of Plataea, effectively ending the Persian invasion of Greece.",
      "date": "-0479"
    },
    {
      "headline": "Assassination of Xerxes I",
      "text": "Xerxes I was assassinated in 465 BC, ending his reign as the King of Kings of the Achaemenid Empire.",
      "date": "-0465"
    }
  ]
}

