    },
    {
      "headline": "Graduation from UCLA",
      "text": "Johnnie Cochran graduated from the University of California, Los Angeles (UCLA) in 1959 with a Bachelor of Arts degree in Business Economics.",
      "date": "1959"
    },
    {
      "headline": "Graduation from Loyola Law School",
      "text": "Cochran earned his Juris Doctor from Loyola Law School in Los Angeles in 1962.",
      "date": "1962"
    },
    {
      "headline": "Begins Legal Career",
      "text": "In 1963, Cochran began his legal career as a deputy city attorney in the criminal division of the Los Angeles City Attorney's Office.",
      "date": "1963"
    },
    {
      "headline": "Opens Own Law Firm",
      "text": "In 1965, Cochran opened his own law firm, Cochran, Atkins & Evans, focusing on civil rights and criminal defense cases.",
      "date": "1965"
    },
    {
      "headline": "Wins First Major Case",
      "text": "In 1966, Cochran won his first major civil rights case, representing Leonard Deadwyler, who was shot and killed by police while driving his pregnant wife to the hospital.",
      "date": "1966"
    },
    {
      "headline": "Joins Los Angeles County District Attorney's Office",
      "text": "In 1978, Cochran joined the Los Angeles County District Attorney's Office as the first African American assistant district attorney.",
      "date": "1978"
    },
    {
      "headline": "Returns to Private Practice",
      "text": "Cochran returned to private practice in 1983, where he continued to take on high-profile civil rights and police brutality cases.",
      "date": "1983"
    },
    {
      "headline": "O.J. Simpson Trial",
      "text": "In 1994, Cochran became the lead attorney for O.J. Simpson's defense team, famously known as the 'Dream Team,' during Simpson's murder trial. The trial concluded in 1995 with Simpson's acquittal.",
      "date": "1994"
    },
    {
      "headline": "Publishes Autobiography",
      "text": "In 1996, Cochran published his autobiography, 'Journey to Justice,' detailing his life and career.",
      "date": "1996"
    },
    {
      "headline": "Establishes Cochran Firm",
      "text": "In 1998, Cochran established The Cochran Firm, a national law firm specializing in personal injury, wrongful death, and civil rights cases.",
      "date": "1998"
    },
    {
      "headline": "Death of Johnnie Cochran",
      "text": "Johnnie Cochran passed away on March 29, 2005, in Los Angeles, California, due to a brain tumor.",
