{
  "timeline": [
    {
      "headline": "End of Tokugawa Shogunate",
      "text": "The Tokugawa shogunate, which had ruled Japan since 1603, began to weaken in the mid-19th century due to internal strife and external pressures, leading to its eventual collapse.",
      "date": "1867"
    },
    {
      "headline": "Emperor Meiji Ascends to the Throne",
      "text": "Emperor Meiji ascended to the throne on February 3, 1867, marking the beginning of a new era in Japanese history.",
      "date": "1867-02-03"
    },
    {
      "headline": "Meiji Restoration Begins",
      "text": "The Meiji Restoration officially began in 1868, marking the restoration of practical imperial rule under Emperor Meiji.",
      "date": "1868"
    },
    {
      "headline": "Charter Oath Issued",
      "text": "The Charter Oath was issued on April 6, 1868, outlining the goals of the new government, including the establishment of deliberative assemblies and the pursuit of knowledge.",
      "date": "1868-04-06"
    },
    {
      "headline": "Abolition of the Han System",
      "text": "In 1871, the new government abolished the han system, replacing it with a system of prefectures, thereby centralizing administrative control.",
      "date": "1871"
    },
    {
      "headline": "Iwakura Mission",
      "text": "The Iwakura Mission, a Japanese diplomatic journey around the world, took place from 1871 to 1873, aiming to study Western institutions and technologies.",
      "date": "1871"
    },
    {
      "headline": "Introduction of Conscription",
      "text": "In 1873, the Meiji government introduced conscription, establishing a modern military force.",
      "date": "1873"
    },
    {
      "headline": "Satsuma Rebellion",
      "text": "The Satsuma Rebellion occurred in 1877, led by disaffected samurai against the new government, ultimately resulting in the defeat of the rebels.",
      "date": "1877"
    },
    {
      "headline": "Promulgation of the Meiji Constitution",
      "text": "The Meiji Constitution was promulgated on February 11, 1889, establishing a constitutional monarchy in Japan.",
      "date": "1889-02-11"
    },
    {
      "headline": "First Sino-Japanese War",
      "text": "The First Sino-Japanese War took place from 1894 to 1895, resulting in a decisive Japanese victory and the Treaty of Shimonoseki.",
      "date": "1894"
    },
    {
      "headline": "Death of Emperor Meiji",
      "text": "Emperor Meiji died on July 30, 1912, marking the end of the Meiji era and the beginning of the Taisho era.",
      "date": "1912-07-30"
    }
  ]
}

