{
  "timeline": [
    {
      "headline": "Birth of Voltaire",
      "text": "François-Marie Arouet, later known as Voltaire, was born on November 21, 1694, in Paris, France.",
      "date": "1694-11-21"
    },
    {
      "headline": "Education at Collège Louis-le-Grand",
      "text": "Voltaire was educated at the Collège Louis-le-Grand in Paris from 1704 to 1711, where he received a classical education.",
      "date": "1704"
    },
    {
      "headline": "First Imprisonment in the Bastille",
      "text": "In May 1717, Voltaire was imprisoned in the Bastille for nearly a year due to his satirical writings about the French government.",
      "date": "1717-05"
    },
    {
      "headline": "Publication of 'Oedipus'",
      "text": "Voltaire's first major play, 'Oedipus', was performed in 1718, marking his success as a playwright.",
      "date": "1718"
    },
    {
      "headline": "Exile to England",
      "text": "In 1726, after a conflict with a nobleman, Voltaire was exiled to England, where he stayed until 1729.",
      "date": "1726"
    },
    {
      "headline": "Return to France",
      "text": "Voltaire returned to France in 1729 after his exile in England, bringing back influences from English philosophy and literature.",
      "date": "1729"
    },
    {
      "headline": "Publication of 'Letters Concerning the English Nation'",
      "text": "In 1733, Voltaire published 'Letters Concerning the English Nation', which praised English society and criticized French institutions.",
      "date": "1733"
    },
    {
      "headline": "Residence at Château de Cirey",
      "text": "Voltaire began residing at the Château de Cirey in 1734 with his companion Émilie du Châtelet, where he conducted scientific and philosophical studies.",
      "date": "1734"
    },
    {
      "headline": "Publication of 'Elements of the Philosophy of Newton'",
      "text": "In 1738, Voltaire published 'Elements of the Philosophy of Newton', popularizing Newtonian physics in France.",
      "date": "1738"
    },
    {
      "headline": "Move to Prussia",
      "text": "Voltaire moved to Prussia in 1750 to join the court of Frederick the Great, where he stayed until 1753.",
      "date": "1750"
    },
    {
      "headline": "Publication of 'Candide'",
      "text": "Voltaire published 'Candide' in 1759, one of his most famous works, which satirized optimism and the philosophy of Leibniz.",
      "date": "1759"
    },
    {
      "headline": "Return to France and Residence in Ferney",
      "text": "Voltaire returned to France in 1758 and settled in Ferney, near the Swiss border, where he lived until his death.",
      "date": "1758"
    },
    {
      "headline": "Death of Voltaire",
      "text": "Voltaire died on May 30, 1778, in Paris, France, at the age of 83.",
      "date": "1778-05-30"
    }
  ]
}

