      "headline": "Richard Feynman's Proposal",
      "text": "In 1981, physicist Richard Feynman proposed the idea of a quantum computer, suggesting that it could simulate physical processes that classical computers could not efficiently handle.",
      "date": "1981"
    },
    {
      "headline": "David Deutsch's Quantum Turing Machine",
      "text": "In 1985, David Deutsch described the concept of a universal quantum computer, or quantum Turing machine, which laid the foundation for quantum computing theory.",
      "date": "1985"
    },
    {
      "headline": "Shor's Algorithm",
      "text": "In 1994, mathematician Peter Shor developed an algorithm that could efficiently factor large numbers using a quantum computer, demonstrating a potential application for quantum computing in cryptography.",
      "date": "1994"
    },
    {
      "headline": "Grover's Algorithm",
      "text": "In 1996, Lov Grover developed an algorithm for searching unsorted databases with a quadratic speedup over classical algorithms, showcasing another potential application for quantum computing.",
      "date": "1996"
    },
    {
      "headline": "First Quantum Logic Gate",
      "text": "In 1998, researchers at Los Alamos National Laboratory and MIT created the first quantum logic gate, a fundamental building block for quantum computers.",
      "date": "1998"
    },
    {
      "headline": "First 2-Qubit Quantum Computer",
      "text": "In 2001, IBM and Stanford University successfully demonstrated the first 2-qubit quantum computer, capable of performing simple calculations.",
      "date": "2001"
    },
    {
      "headline": "D-Wave Systems' Quantum Annealer",
      "text": "In 2007, D-Wave Systems announced the first commercial quantum computer, a 16-qubit quantum annealer, although its quantum nature was debated.",
      "date": "2007"
    },
    {
      "headline": "Google's Quantum Supremacy Claim",
      "text": "In 2019, Google claimed to have achieved quantum supremacy with its 53-qubit Sycamore processor, performing a specific task faster than the fastest classical supercomputer.",
      "date": "2019"
    }
  ]
}

