{
  "timeline": [
    {
      "headline": "Start of the Battle of the Somme",
      "text": "The Battle of the Somme began on 1 July 1916. It was a major offensive by the British and French armies against the German Empire, intended to hasten a victory for the Allies.",
      "date": "1916-07-01"
    },
    {
      "headline": "First Day of the Battle",
      "text": "On 1 July 1916, the first day of the Battle of the Somme, the British Army suffered nearly 60,000 casualties, making it the bloodiest day in British military history.",
      "date": "1916-07-01"
    },
    {
      "headline": "Battle of Bazentin Ridge",
      "text": "From 14 to 17 July 1916, the Battle of Bazentin Ridge took place, where British forces captured the German second line of defense.",
      "date": "1916-07-14"
    },
    {
      "headline": "Battle of Delville Wood",
      "text": "The Battle of Delville Wood occurred from 15 July to 3 September 1916, with intense fighting as British and South African forces attempted to capture the wood from German forces.",
      "date": "1916-07-15"
    },
    {
      "headline": "Battle of Pozières",
      "text": "From 23 July to 7 August 1916, the Battle of Pozières took place, where Australian forces captured the village of Pozières, a key position on the German defensive line.",
      "date": "1916-07-23"
    },
    {
      "headline": "Battle of Guillemont",
      "text": "The Battle of Guillemont occurred from 3 to 6 September 1916, with British forces capturing the village of Guillemont after several attempts.",
      "date": "1916-09-03"
    },
    {
      "headline": "Battle of Ginchy",
      "text": "On 9 September 1916, the Battle of Ginchy took place, where the British captured the village of Ginchy, further advancing their position.",
      "date": "1916-09-09"
    },
    {
      "headline": "Battle of Flers–Courcelette",
      "text": "From 15 to 22 September 1916, the Battle of Flers–Courcelette was fought, notable for the first use of tanks in warfare by the British Army.",
      "date": "1916-09-15"
    },
    {
      "headline": "Battle of Thiepval Ridge",
      "text": "The Battle of Thiepval Ridge took place from 26 to 28 September 1916, resulting in a British victory and the capture of the Thiepval Ridge.",
      "date": "1916-09-26"
    },
    {
      "headline": "Battle of the Ancre Heights",
      "text": "From 1 October to 11 November 1916, the Battle of the Ancre Heights occurred, with British forces capturing key positions on the Ancre Heights.",
      "date": "1916-10-01"
    },
    {
      "headline": "Battle of the Ancre",
      "text": "The Battle of the Ancre took place from 13 to 18 November 1916, marking the final phase of the Battle of the Somme with British forces capturing the village of Beaumont-Hamel.",
      "date": "1916-11-13"
    },
    {
      "headline": "End of the Battle of the Somme",
      "text": "The Battle of the Somme concluded on 18 November 1916. It resulted in over one million men wounded or killed, making it one of the deadliest battles in history.",
      "date": "1916-11-18"
    }
  ]
}

