{
  "timeline": [
    {
      "headline": "Foundation of Assur",
      "text": "The city of Assur, which would become the capital of the Assyrian Empire, was founded around the 21st century BCE.",
      "date": "-2100"
    },
    {
      "headline": "Rise of the Old Assyrian Empire",
      "text": "The Old Assyrian Empire began to rise around the 20th century BCE, establishing trade colonies in Anatolia.",
      "date": "-2000"
    },
    {
      "headline": "Reign of Shamshi-Adad I",
      "text": "Shamshi-Adad I reigned from 1809 to 1776 BCE, expanding Assyrian control over northern Mesopotamia.",
      "date": "-1809"
    },
    {
      "headline": "Assyrian Decline",
      "text": "Following the death of Shamshi-Adad I, the Assyrian Empire experienced a period of decline and was eventually conquered by the Babylonian Empire around 1750 BCE.",
      "date": "-1750"
    },
    {
      "headline": "Middle Assyrian Empire",
      "text": "The Middle Assyrian Empire began to emerge around 1365 BCE, marked by territorial expansion and military conquests.",
      "date": "-1365"
    },
    {
      "headline": "Reign of Tiglath-Pileser I",
      "text": "Tiglath-Pileser I reigned from 1114 to 1076 BCE, known for his military campaigns and expansion of the empire.",
      "date": "-1114"
    },
    {
      "headline": "Neo-Assyrian Empire",
      "text": "The Neo-Assyrian Empire began around 911 BCE, becoming the largest empire the world had seen at the time.",
      "date": "-0911"
    },
    {
      "headline": "Reign of Ashurnasirpal II",
      "text": "Ashurnasirpal II reigned from 883 to 859 BCE, known for his military campaigns and the construction of a new capital at Kalhu (Nimrud).",
      "date": "-0883"
    },
    {
      "headline": "Reign of Tiglath-Pileser III",
      "text": "Tiglath-Pileser III reigned from 745 to 727 BCE, known for his military reforms and expansion of the empire.",
      "date": "-0745"
    },
    {
      "headline": "Reign of Sargon II",
      "text": "Sargon II reigned from 722 to 705 BCE, consolidating Assyrian control over the Levant and parts of Egypt.",
      "date": "-0722"
    },
    {
      "headline": "Reign of Sennacherib",
      "text": "Sennacherib reigned from 705 to 681 BCE, known for his campaigns against Babylon and Judah, and the construction of Nineveh.",
      "date": "-0705"
    },
    {
      "headline": "Reign of Ashurbanipal",
      "text": "Ashurbanipal reigned from 668 to 627 BCE, known for his vast library at Nineveh and the height of Assyrian cultural achievements.",
      "date": "-0668"
    },
