    },
    {
      "headline": "Mount St. Helens Eruption",
      "text": "On May 18, 1980, Mount St. Helens erupted catastrophically, resulting in 57 deaths, the destruction of 250 homes, 47 bridges, 15 miles of railways, and 185 miles of highway.",
      "date": "1980-05-18"
    },
    {
      "headline": "Renewed Volcanic Activity",
      "text": "Mount St. Helens showed renewed volcanic activity beginning in September 2004, with a series of small explosive eruptions and lava dome growth.",
      "date": "2004-09"
    },
    {
      "headline": "End of 2004-2008 Eruptive Period",
      "text": "The eruptive period that began in 2004 ended in January 2008, after the growth of a new lava dome.",
