    {
      "headline": "Founding of Theranos",
      "text": "Theranos was founded in 2003 by 19-year-old Elizabeth Holmes. The company aimed to revolutionize blood testing by developing technology that required only small amounts of blood.",
      "date": "2003"
    },
    {
      "headline": "Theranos Raises Significant Capital",
      "text": "Between 2003 and 2014, Theranos raised more than $700 million from venture capitalists and private investors, reaching a valuation of $9 billion at its peak in 2013 and 2014.",
      "date": "2014"
    },
    {
      "headline": "Partnership with Walgreens",
      "text": "In 2013, Theranos announced a partnership with Walgreens to offer its blood tests in-store, marking a significant step in its commercial expansion.",
      "date": "2013"
    },
    {
      "headline": "Media Exposure and Criticism",
      "text": "In October 2015, The Wall Street Journal published an article questioning the validity of Theranos' technology, sparking widespread scrutiny and criticism.",
      "date": "2015-10"
    },
    {
      "headline": "FDA Inspection and Sanctions",
      "text": "In 2015, the FDA conducted an inspection of Theranos' facilities, which led to the discovery of significant issues with the company's testing processes.",
      "date": "2015"
    },
    {
      "headline": "CMS Sanctions",
      "text": "In 2016, the Centers for Medicare & Medicaid Services (CMS) imposed sanctions on Theranos, including the revocation of its CLIA certificate, effectively banning it from operating a lab.",
      "date": "2016"
    },
    {
      "headline": "Theranos Settles with SEC",
      "text": "In March 2018, Theranos and Elizabeth Holmes settled with the U.S. Securities and Exchange Commission (SEC) over charges of fraud, with Holmes agreeing to pay a fine and surrender voting control of the company.",
      "date": "2018-03"
    },
    {
      "headline": "Theranos Dissolution",
      "text": "In September 2018, Theranos announced that it would dissolve, marking the end of the company following years of legal and financial troubles.",
      "date": "2018-09"
    }
  ]
}

