    {
      "headline": "Development of Narezushi",
      "text": "By the 10th century, narezushi, a type of sushi made with fermented fish and rice, became popular in Japan.",
      "date": "0900"
    },
    {
      "headline": "Evolution to Hayazushi",
      "text": "In the early 17th century, hayazushi was developed. This style of sushi combined rice and fish to be consumed at the same time, without fermentation.",
      "date": "1600"
    },
    {
      "headline": "Invention of Nigirizushi",
      "text": "In the early 19th century, nigirizushi, a style of sushi with a slice of fish atop a small ball of rice, was invented in Edo (modern-day Tokyo) by Hanaya Yohei.",
      "date": "1820"
    },
    {
      "headline": "Spread to the United States",
      "text": "Sushi was introduced to the United States in the early 20th century, but it gained significant popularity in the 1960s and 1970s.",
      "date": "1960"
    },
    {
      "headline": "Global Popularity",
      "text": "By the late 20th century, sushi had become a global phenomenon, with sushi restaurants and sushi bars opening worldwide.",
      "date": "1980"
    }
  ]
}

