{
  "timeline": [
    {
      "headline": "Treaty of San Ildefonso",
      "text": "On October 1, 1800, the Treaty of San Ildefonso was signed, in which Spain returned the territory of Louisiana to France.",
      "date": "1800-10-01"
    },
    {
      "headline": "France's Control of Louisiana",
      "text": "In 1801, France officially took control of the Louisiana territory from Spain, although the transfer was not publicly announced until 1802.",
      "date": "1801"
    },
    {
      "headline": "Napoleon's Plans for Louisiana",
      "text": "In 1802, Napoleon Bonaparte planned to use Louisiana as a base for French expansion in the Americas, but his plans were thwarted by the Haitian Revolution.",
      "date": "1802"
    },
    {
      "headline": "U.S. Interest in New Orleans",
      "text": "In 1802, President Thomas Jefferson sent James Monroe to France to negotiate the purchase of New Orleans and parts of Florida, as access to the Mississippi River was crucial for American trade.",
      "date": "1802"
    },
    {
      "headline": "Louisiana Purchase Negotiations",
      "text": "In April 1803, negotiations between the United States and France led to the offer of the entire Louisiana territory to the U.S. for $15 million.",
      "date": "1803-04"
    },
    {
      "headline": "Signing of the Louisiana Purchase Treaty",
      "text": "On April 30, 1803, the Louisiana Purchase Treaty was signed in Paris by Robert Livingston, James Monroe, and François Barbé-Marbois.",
      "date": "1803-04-30"
    },
    {
      "headline": "U.S. Senate Ratification",
      "text": "On October 20, 1803, the United States Senate ratified the Louisiana Purchase Treaty, effectively doubling the size of the United States.",
      "date": "1803-10-20"
    },
    {
      "headline": "Formal Transfer of Louisiana",
      "text": "On December 20, 1803, the formal transfer of the Louisiana territory from France to the United States took place in New Orleans.",
      "date": "1803-12-20"
    },
    {
      "headline": "Lewis and Clark Expedition",
      "text": "In May 1804, the Lewis and Clark Expedition set out to explore the newly acquired territory and find a route to the Pacific Ocean.",
      "date": "1804-05"
    }
  ]
}

