{
  "timeline": [
    {
      "headline": "USB-C Specification Published",
      "text": "The USB Type-C Specification 1.0 was published by the USB Implementers Forum (USB-IF) in August 2014. This marked the introduction of the USB-C connector, designed to replace previous USB connectors with a more versatile and reversible design.",
      "date": "2014-08"
    },
    {
      "headline": "First Devices with USB-C Released",
      "text": "The first devices featuring USB-C ports were released in 2015. Notably, the Apple MacBook and Google Chromebook Pixel were among the first laptops to adopt the new connector, showcasing its potential for both data transfer and power delivery.",
      "date": "2015"
    },
    {
      "headline": "USB-C Power Delivery Specification",
      "text": "In 2015, the USB Power Delivery (PD) specification was updated to support USB-C, allowing for increased power delivery capabilities of up to 100 watts, enabling the charging of larger devices such as laptops.",
      "date": "2015"
    },
    {
      "headline": "USB 3.1 and USB-C",
      "text": "USB 3.1, which offers data transfer speeds of up to 10 Gbps, was designed to work with USB-C connectors, further enhancing the performance and versatility of the USB-C standard.",
      "date": "2015"
    },
    {
      "headline": "USB-C and Thunderbolt 3 Integration",
      "text": "In 2015, Intel announced that Thunderbolt 3 would use the USB-C connector, providing a single cable solution for data transfer, video output, and power delivery, with speeds up to 40 Gbps.",
      "date": "2015"
    },
    {
      "headline": "USB 3.2 Specification",
      "text": "The USB 3.2 specification was released in September 2017, introducing multi-lane operation for USB-C, allowing for data transfer speeds of up to 20 Gbps.",
      "date": "2017-09"
    },
    {
      "headline": "USB4 Specification Announced",
      "text": "In 2019, the USB4 specification was announced, based on the Thunderbolt 3 protocol, and utilizing the USB-C connector. It supports data transfer speeds of up to 40 Gbps and improved resource allocation for video and data.",
      "date": "2019"
    },
    {
      "headline": "USB-C Adoption in Smartphones",
      "text": "By 2020, USB-C had become the standard charging and data port for most new smartphones, including those from major manufacturers like Samsung, Google, and Huawei.",
      "date": "2020"
    },
    {
      "headline": "European Union Mandates USB-C",
      "text": "In 2022, the European Union passed legislation requiring all new smartphones, tablets, and cameras sold in the EU to use USB-C for charging by 2024, aiming to reduce electronic waste and improve consumer convenience.",
      "date": "2022"
    }
  ]
}

