{
  "timeline": [
    {
      "headline": "Foundation of the Social Democratic Party of Germany",
      "text": "The Social Democratic Party of Germany (SPD) was founded on May 23, 1863, as the General German Workers' Association (ADAV) by Ferdinand Lassalle.",
      "date": "1863-05-23"
    },
    {
      "headline": "Merger to Form the SPD",
      "text": "In 1875, the ADAV merged with the Social Democratic Workers' Party of Germany (SDAP) to form the Socialist Workers' Party of Germany, which later became the SPD.",
      "date": "1875"
    },
    {
      "headline": "SPD Banned Under Anti-Socialist Laws",
      "text": "From 1878 to 1890, the SPD was banned under Otto von Bismarck's Anti-Socialist Laws, which prohibited socialist organizations, meetings, and publications.",
      "date": "1878"
    },
    {
      "headline": "SPD Legalized Again",
      "text": "In 1890, the Anti-Socialist Laws were lifted, allowing the SPD to operate legally once more.",
      "date": "1890"
    },
    {
      "headline": "SPD Wins Majority in Reichstag",
      "text": "In the 1912 federal election, the SPD became the largest party in the Reichstag, marking a significant political achievement.",
      "date": "1912"
    },
    {
      "headline": "SPD and the Weimar Republic",
      "text": "The SPD played a crucial role in the establishment of the Weimar Republic following World War I, with Friedrich Ebert becoming the first President of Germany.",
