    {
      "headline": "Discovery of Ceres",
      "text": "Ceres was discovered on 1 January 1801 by Giuseppe Piazzi at the Palermo Astronomical Observatory in Sicily. Initially, it was announced as a new planet.",
      "date": "1801-01-01"
    },
    {
      "headline": "Reclassification as an Asteroid",
      "text": "In the 1850s, Ceres was reclassified as an asteroid as more objects were discovered in the same region, leading to the creation of the asteroid belt classification.",
      "date": "1850"
    },
    {
      "headline": "Reclassification as a Dwarf Planet",
      "text": "In 2006, Ceres was reclassified as a dwarf planet by the International Astronomical Union, making it the only dwarf planet located in the asteroid belt between Mars and Jupiter.",
      "date": "2006"
    },
    {
      "headline": "Dawn Spacecraft Mission",
      "text": "NASA's Dawn spacecraft was launched in 2007 and entered orbit around Ceres on 6 March 2015, providing detailed images and data about the dwarf planet.",
      "date": "2015-03-06"
    }
  ]
}

