{
  "timeline": [
    {
      "headline": "Birth of John Locke",
      "text": "John Locke was born on August 29, 1632, in Wrington, Somerset, England.",
      "date": "1632-08-29"
    },
    {
      "headline": "Education at Westminster School",
      "text": "In 1647, John Locke was sent to Westminster School in London, where he received a classical education.",
      "date": "1647"
    },
    {
      "headline": "Studies at Christ Church, Oxford",
      "text": "In 1652, Locke entered Christ Church, Oxford, where he studied logic, metaphysics, and the classics.",
      "date": "1652"
    },
    {
      "headline": "Bachelor of Arts Degree",
      "text": "John Locke received his Bachelor of Arts degree in 1656 from Christ Church, Oxford.",
      "date": "1656"
    },
    {
      "headline": "Master of Arts Degree",
      "text": "Locke was awarded a Master of Arts degree in 1658 from Christ Church, Oxford.",
      "date": "1658"
    },
    {
      "headline": "Lecturer at Oxford",
      "text": "In 1660, Locke became a lecturer at Oxford, teaching Greek and rhetoric.",
      "date": "1660"
    },
    {
      "headline": "Medical Studies and Meeting Lord Ashley",
      "text": "In 1666, Locke met Anthony Ashley Cooper, later the 1st Earl of Shaftesbury, which led him to pursue medical studies.",
      "date": "1666"
    },
    {
      "headline": "Fellow of the Royal Society",
      "text": "In 1668, Locke was elected a fellow of the Royal Society, reflecting his growing interest in science and medicine.",
      "date": "1668"
    },
    {
      "headline": "Publication of 'An Essay Concerning Human Understanding'",
      "text": "In 1689, Locke published 'An Essay Concerning Human Understanding', a work that became foundational to modern empiricism.",
      "date": "1689"
    },
    {
      "headline": "Publication of 'Two Treatises of Government'",
      "text": "In 1689, Locke also published 'Two Treatises of Government', which laid the groundwork for modern theories of democracy and individual rights.",
      "date": "1689"
    },
    {
      "headline": "Return to England",
      "text": "In 1689, following the Glorious Revolution, Locke returned to England from exile in the Netherlands.",
      "date": "1689"
    },
    {
      "headline": "Publication of 'A Letter Concerning Toleration'",
      "text": "In 1689, Locke published 'A Letter Concerning Toleration', advocating for religious tolerance.",
      "date": "1689"
    },
    {
      "headline": "Publication of 'Some Thoughts Concerning Education'",
      "text": "In 1693, Locke published 'Some Thoughts Concerning Education', influencing educational theory.",
      "date": "1693"
    },
    {
      "headline": "Death of John Locke",
      "text": "John Locke died on October 28, 1704, in High Laver, Essex, England.",
      "date": "1704-10-28"
    }
  ]
}

