    },
    {
      "headline": "Annexation of Finland",
      "text": "In 1809, Alexander I became the Grand Duke of Finland after the Finnish War, incorporating Finland into the Russian Empire.",
      "date": "1809"
    },
    {
      "headline": "Napoleon's Invasion of Russia",
      "text": "In 1812, Napoleon invaded Russia, leading to the famous retreat from Moscow and a turning point in the Napoleonic Wars.",
      "date": "1812"
    },
    {
      "headline": "Congress of Vienna",
      "text": "Alexander I played a significant role at the Congress of Vienna in 1815, which reshaped Europe after the Napoleonic Wars.",
      "date": "1815"
    },
    {
      "headline": "King of Congress Poland",
      "text": "In 1815, Alexander I became the first King of Congress Poland, a title he held until his death.",
      "date": "1815"
    },
    {
