    {
      "headline": "Formation of the Parliament of Great Britain",
      "text": "The Parliament of Great Britain was formed in 1707 following the Acts of Union 1707, which united the separate English and Scottish Parliaments.",
      "date": "1707"
    },
    {
      "headline": "Formation of the Parliament of the United Kingdom",
      "text": "The Parliament of the United Kingdom was formed in 1801 following the Acts of Union 1800, which united the Parliaments of Great Britain and Ireland.",
      "date": "1801"
    },
    {
      "headline": "Reform Act 1832",
      "text": "The Reform Act 1832, also known as the Representation of the People Act 1832, was an Act of Parliament that introduced wide-ranging changes to the electoral system of England and Wales.",
      "date": "1832"
    },
    {
      "headline": "Parliament Acts 1911 and 1949",
      "text": "The Parliament Act 1911 and the Parliament Act 1949 limited the powers of the House of Lords, reducing their ability to block legislation passed by the House of Commons.",
      "date": "1911"
    },
    {
      "headline": "Parliament Acts 1911 and 1949",
      "text": "The Parliament Act 1949 further reduced the power of the House of Lords, allowing the House of Commons to bypass the Lords after a delay of one year.",
      "date": "1949"
    },
    {
      "headline": "Devolution Acts",
      "text": "The Scotland Act 1998, Government of Wales Act 1998, and Northern Ireland Act 1998 established devolved parliaments and assemblies in Scotland, Wales, and Northern Ireland, respectively.",
      "date": "1998"
    },
    {
      "headline": "Fixed-term Parliaments Act 2011",
      "text": "The Fixed-term Parliaments Act 2011 established fixed-term elections for the House of Commons, occurring every five years.",
      "date": "2011"
