{
  "timeline": [
    {
      "headline": "Birth of Henry I",
      "text": "Henry I was born in 1068, the fourth son of William the Conqueror and Matilda of Flanders.",
      "date": "1068"
    },
    {
      "headline": "Death of William the Conqueror",
      "text": "In 1087, William the Conqueror died, leaving his lands divided among his sons. Henry was left landless.",
      "date": "1087"
    },
    {
      "headline": "Purchase of the County of Cotentin",
      "text": "Henry purchased the County of Cotentin in western Normandy from his brother Robert Curthose in 1088.",
      "date": "1088"
    },
    {
      "headline": "Deposed from Cotentin",
      "text": "In 1091, Henry was deposed from the County of Cotentin by his brothers Robert Curthose and William Rufus.",
      "date": "1091"
    },
    {
      "headline": "Rebuilding Power Base",
      "text": "Henry gradually rebuilt his power base in the Cotentin and allied himself with William Rufus against Robert.",
      "date": "1091"
    },
    {
      "headline": "Accession to the English Throne",
      "text": "Henry became King of England on August 5, 1100, following the death of his brother William Rufus.",
      "date": "1100-08-05"
    },
    {
      "headline": "Marriage to Matilda of Scotland",
      "text": "Henry married Matilda of Scotland on November 11, 1100, strengthening his ties with the Anglo-Saxon nobility.",
      "date": "1100-11-11"
    },
    {
      "headline": "Charter of Liberties",
      "text": "In 1100, Henry issued the Charter of Liberties, a precursor to the Magna Carta, promising to reform abuses of royal power.",
      "date": "1100"
    },
    {
      "headline": "Battle of Tinchebray",
      "text": "On September 28, 1106, Henry defeated his brother Robert Curthose at the Battle of Tinchebray, gaining control of Normandy.",
      "date": "1106-09-28"
    },
    {
      "headline": "Death of Matilda of Scotland",
      "text": "Henry's wife, Matilda of Scotland, died on May 1, 1118.",
      "date": "1118-05-01"
    },
    {
      "headline": "White Ship Disaster",
      "text": "On November 25, 1120, Henry's heir, William Adelin, died in the White Ship disaster, leading to a succession crisis.",
      "date": "1120-11-25"
    },
    {
      "headline": "Marriage to Adeliza of Louvain",
      "text": "Henry married Adeliza of Louvain on January 29, 1121, in an attempt to produce a male heir.",
      "date": "1121-01-29"
    },
    {
      "headline": "Death of Henry I",
      "text": "Henry I died on December 1, 1135, in Lyons-la-Forêt, Normandy, leading to a period of civil war known as The Anarchy.",
      "date": "1135-12-01"
    }
  ]
}

