    {
      "headline": "Muslim Rule",
      "text": "In the 12th century, Varanasi came under Muslim rule, which led to the destruction of many Hindu temples.",
      "date": "1100"
    },
    {
      "headline": "Mughal Empire",
      "text": "During the Mughal Empire, particularly under Akbar's rule in the 16th century, Varanasi saw a revival of Hindu culture and the construction of new temples.",
      "date": "1500"
    },
    {
      "headline": "British Rule",
      "text": "In 1775, Varanasi became a part of British India, and the city continued to be a significant religious and cultural center.",
      "date": "1775"
    },
    {
      "headline": "Indian Independence",
      "text": "After India gained independence in 1947, Varanasi became part of the newly formed state of Uttar Pradesh.",
      "date": "1947"
