{
  "timeline": [
    {
      "headline": "Introduction of HTTPS",
      "text": "HTTPS was first introduced by Netscape Communications in 1994 as a secure version of HTTP, using SSL (Secure Sockets Layer) for encryption.",
      "date": "1994"
    },
    {
      "headline": "SSL 3.0 Released",
      "text": "SSL 3.0, a more secure version of the protocol, was released in 1996, providing improved encryption and security features.",
      "date": "1996"
    },
    {
      "headline": "TLS 1.0 Standardized",
      "text": "In January 1999, TLS 1.0 was standardized by the Internet Engineering Task Force (IETF) as an upgrade to SSL, providing enhanced security.",
      "date": "1999-01"
    },
    {
      "headline": "TLS 1.1 Released",
      "text": "TLS 1.1 was released in April 2006, addressing vulnerabilities found in TLS 1.0 and improving security.",
      "date": "2006-04"
    },
    {
      "headline": "TLS 1.2 Released",
      "text": "In August 2008, TLS 1.2 was released, introducing new cryptographic algorithms and improving the protocol's security.",
      "date": "2008-08"
    },
    {
      "headline": "Let's Encrypt Launch",
      "text": "Let's Encrypt, a free, automated, and open certificate authority, was launched in April 2016, significantly increasing the adoption of HTTPS by making it easier to obtain and manage SSL/TLS certificates.",
      "date": "2016-04"
    },
    {
      "headline": "TLS 1.3 Finalized",
      "text": "TLS 1.3 was finalized in August 2018, offering improved security and performance over previous versions, with a simplified handshake process and stronger encryption.",
      "date": "2018-08"
    },
    {
      "headline": "Google Chrome Marks HTTP as 'Not Secure'",
      "text": "In July 2018, Google Chrome began marking all HTTP sites as 'Not Secure', encouraging the widespread adoption of HTTPS.",
      "date": "2018-07"
    }
  ]
}

{
  "timeline": [
    {
      "headline": "Introduction of ELIZA",
      "text": "In 1966, ELIZA, one of the first chatbots, was created by Joseph Weizenbaum at the MIT Artificial Intelligence Laboratory. It simulated conversation by using pattern matching and substitution methodology.",
      "date": "1966"
    },
    {
      "headline": "Development of PARRY",
      "text": "In 1972, PARRY was developed by psychiatrist Kenneth Colby. It was designed to simulate a person with paranoid schizophrenia and was more advanced than ELIZA in terms of conversational capabilities.",
      "date": "1972"
    },
    {
      "headline": "Introduction of Racter",
      "text": "In 1983, Racter, a chatbot program that generated English prose, was released. It was one of the first chatbots to be commercially available.",
      "date": "1983"
    },
    {
      "headline": "Launch of A.L.I.C.E.",
      "text": "In 1995, A.L.I.C.E. (Artificial Linguistic Internet Computer Entity) was created by Richard Wallace. It used natural language processing and won the Loebner Prize multiple times.",
      "date": "1995"
    },
    {
      "headline": "Introduction of SmarterChild",
      "text": "In 2001, SmarterChild was launched on AOL Instant Messenger and MSN Messenger. It was an early example of a chatbot that could interact with users on popular messaging platforms.",
      "date": "2001"
    },
    {
      "headline": "Launch of Siri",
      "text": "In 2011, Apple launched Siri, a virtual assistant integrated into iOS devices, marking a significant advancement in voice-activated chatbot technology.",
      "date": "2011"
    },
    {
      "headline": "Introduction of Google Assistant",
      "text": "In 2016, Google Assistant was launched, offering advanced conversational capabilities and integration with various Google services.",
      "date": "2016"
    },
    {
      "headline": "Release of ChatGPT",
      "text": "In 2020, OpenAI released ChatGPT, a state-of-the-art language model capable of generating human-like text and engaging in complex conversations.",
      "date": "2020"
    }
  ]
}

