    {
      "headline": "Construction of the Louvre Fortress",
      "text": "The Louvre was originally built as a fortress in the late 12th to 13th century under the reign of Philip II to protect Paris from external attacks.",
      "date": "1200"
    },
    {
      "headline": "Conversion to Royal Residence",
      "text": "In 1546, King Francis I began the transformation of the Louvre from a fortress into the primary residence of the French kings.",
      "date": "1546"
    },
    {
      "headline": "Establishment as a Museum",
      "text": "The Louvre was officially opened as a museum on August 10, 1793, during the French Revolution, showcasing 537 paintings.",
      "date": "1793-08-10"
    },
    {
      "headline": "Napoleon's Expansion",
      "text": "Under Napoleon Bonaparte, the Louvre was expanded and renamed the Musée Napoléon, with many artworks acquired during his campaigns.",
      "date": "1803"
    },
    {
      "headline": "Return to the Name 'Louvre Museum'",
      "text": "After Napoleon's fall in 1815, the museum was renamed the Louvre Museum, and many looted artworks were returned to their countries of origin.",
      "date": "1815"
    },
    {
      "headline": "Opening of the Richelieu Wing",
      "text": "The Richelieu Wing of the Louvre was opened in 1993, significantly expanding the museum's exhibition space.",
      "date": "1993"
    },
    {
      "headline": "Completion of the Louvre Pyramid",
      "text": "The Louvre Pyramid, designed by architect I. M. Pei, was completed in 1989, serving as the main entrance to the museum.",
      "date": "1989"
    }
  ]
}

