      "text": "Martin Luther was born on November 10, 1483, in Eisleben, Saxony, in the Holy Roman Empire.",
      "date": "1483-11-10"
    },
    {
      "headline": "Ninety-Five Theses",
      "text": "On October 31, 1517, Martin Luther nailed his Ninety-Five Theses to the door of the Wittenberg Castle Church, challenging the Catholic Church's practice of selling indulgences.",
      "date": "1517-10-31"
    },
    {
      "headline": "Diet of Worms",
      "text": "In 1521, Martin Luther was summoned to the Diet of Worms, where he refused to recant his teachings, leading to his excommunication from the Catholic Church.",
      "date": "1521"
    },
    {
      "headline": "Translation of the New Testament",
      "text": "In 1522, Martin Luther completed his translation of the New Testament into German, making it more accessible to the general public.",
      "date": "1522"
    },
    {
      "headline": "Lutheranism Becomes State Religion in Prussia",
      "text": "In 1525, Lutheranism became the state religion of Prussia, marking the beginning of its establishment in Northern Europe.",
      "date": "1525"
    },
    {
      "headline": "Augsburg Confession",
      "text": "The Augsburg Confession, a fundamental document of Lutheran theology, was presented to the Holy Roman Emperor Charles V at the Diet of Augsburg on June 25, 1530.",
      "date": "1530-06-25"
    },
    {
      "headline": "Peace of Augsburg",
      "text": "The Peace of Augsburg was signed in 1555, allowing for the legal coexistence of Lutheranism and Catholicism in the Holy Roman Empire.",
      "date": "1555"
    },
    {
      "headline": "Book of Concord",
      "text": "The Book of Concord, a collection of Lutheran confessional documents, was published in 1580, solidifying Lutheran doctrine.",
      "date": "1580"
    }
  ]
}

