      "headline": "Birth of Niels Bohr",
      "text": "Niels Henrik David Bohr was born on October 7, 1885, in Copenhagen, Denmark.",
      "date": "1885-10-07"
    },
    {
      "headline": "Enrollment at University of Copenhagen",
      "text": "In 1903, Bohr enrolled at the University of Copenhagen, where he studied physics.",
      "date": "1903"
    },
    {
      "headline": "Awarded Gold Medal by the Royal Danish Academy of Sciences and Letters",
      "text": "In 1907, Bohr was awarded a gold medal by the Royal Danish Academy of Sciences and Letters for his work on the surface tension of water.",
      "date": "1907"
    },
    {
      "headline": "Completion of Doctorate",
      "text": "Bohr completed his doctorate in 1911 with a dissertation on the electron theory of metals.",
      "date": "1911"
    },
    {
      "headline": "Postdoctoral Work with J.J. Thomson",
      "text": "In 1911, Bohr went to Cambridge to study under J.J. Thomson at the Cavendish Laboratory.",
      "date": "1911"
    },
    {
      "headline": "Collaboration with Ernest Rutherford",
      "text": "In 1912, Bohr moved to Manchester to work with Ernest Rutherford, which led to his development of the Bohr model of the atom.",
      "date": "1912"
    },
    {
      "headline": "Publication of Bohr Model",
      "text": "In 1913, Bohr published his model of atomic structure, introducing the theory of electrons traveling in orbits around the atom's nucleus.",
      "date": "1913"
    },
    {
      "headline": "Nobel Prize in Physics",
      "text": "In 1922, Niels Bohr was awarded the Nobel Prize in Physics for his contributions to the understanding of atomic structure and quantum theory.",
      "date": "1922"
    },
    {
      "headline": "Establishment of the Institute of Theoretical Physics",
      "text": "In 1923, Bohr founded the Institute of Theoretical Physics at the University of Copenhagen, which became a center for theoretical physics research.",
      "date": "1923"
    },
    {
      "headline": "Development of Complementarity Principle",
      "text": "In 1927, Bohr introduced the principle of complementarity, a fundamental concept in quantum mechanics.",
      "date": "1927"
    },
    {
      "headline": "Escape to Sweden during World War II",
      "text": "In 1943, during the Nazi occupation of Denmark, Bohr fled to Sweden to escape arrest.",
      "date": "1943"
    },
    {
      "headline": "Work on the Manhattan Project",
      "text": "In 1943, after escaping to Sweden, Bohr traveled to the United States, where he worked on the Manhattan Project.",
      "date": "1943"
    },
    {
      "headline": "Return to Denmark",
      "text": "In 1945, after World War II, Bohr returned to Denmark and resumed his work at the Institute of Theoretical Physics.",
      "date": "1945"
    },
    {
      "headline": "Death of Niels Bohr",
      "text": "Niels Bohr passed away on November 18, 1962, in Copenhagen, Denmark.",
      "date": "1962-11-18"
    }
  ]
}

