{
  "timeline": [
    {
      "headline": "Start of the Beslan School Siege",
      "text": "On 1 September 2004, a group of armed terrorists took more than 1,100 people hostage, including 777 children, at School Number One in Beslan, North Ossetia, Russia.",
      "date": "2004-09-01"
    },
    {
      "headline": "Second Day of the Siege",
      "text": "On 2 September 2004, the hostages remained trapped in the school gymnasium without food or water, as negotiations between the terrorists and Russian authorities continued.",
      "date": "2004-09-02"
    },
    {
      "headline": "End of the Beslan School Siege",
      "text": "On 3 September 2004, the siege ended violently when Russian security forces stormed the school. The attack resulted in the deaths of 334 people, including 186 children, and 31 attackers.",
      "date": "2004-09-03"
    },
    {
      "headline": "Aftermath and Investigation",
      "text": "Following the siege, investigations were conducted to determine the circumstances and failures that led to the tragedy. The event had significant political and social repercussions in Russia and worldwide.",
      "date": "2004"
    }
  ]
}

