{
  "timeline": [
    {
      "headline": "Introduction of Quetelet Index",
      "text": "The concept of the Body Mass Index (BMI) was first introduced by the Belgian mathematician and statistician Adolphe Quetelet. He developed the Quetelet Index between 1830 and 1850 as a way to measure the degree of obesity in a population.",
      "date": "1830"
    },
    {
      "headline": "Publication of Quetelet's Work",
      "text": "Adolphe Quetelet published his work on the Quetelet Index in his book 'A Treatise on Man and the Development of His Faculties' in 1835, where he discussed the use of the index to study the average man and the distribution of human physical characteristics.",
      "date": "1835"
    },
    {
      "headline": "Adoption of BMI Term",
      "text": "The term 'Body Mass Index' (BMI) was coined by Ancel Keys in 1972. He recognized the Quetelet Index as a useful tool for epidemiologists and public health officials to assess the prevalence of obesity in populations.",
      "date": "1972"
    },
    {
      "headline": "World Health Organization BMI Classification",
      "text": "The World Health Organization (WHO) adopted the BMI as a standard for categorizing underweight, normal weight, overweight, and obesity in adults. This classification system is widely used in public health and clinical settings.",
      "date": "1995"
    }
  ]
}

