{
  "timeline": [
    {
      "headline": "Development of the Concept of IQ",
      "text": "The concept of intelligence quotient (IQ) was developed in the early 20th century as a means to measure human intelligence through standardized testing.",
      "date": "1900"
    },
    {
      "headline": "Introduction of the Binet-Simon Scale",
      "text": "In 1905, French psychologists Alfred Binet and Théodore Simon introduced the Binet-Simon scale, the first practical IQ test, designed to identify children needing educational assistance.",
      "date": "1905"
    },
    {
      "headline": "Introduction of the Term 'IQ'",
      "text": "In 1912, the term 'intelligence quotient' (IQ) was coined by the German psychologist William Stern. He proposed the formula of dividing mental age by chronological age and multiplying by 100.",
      "date": "1912"
    },
    {
      "headline": "Stanford-Binet Intelligence Scale",
      "text": "In 1916, Lewis Terman, a psychologist at Stanford University, adapted the Binet-Simon scale for use in the United States, resulting in the Stanford-Binet Intelligence Scale.",
      "date": "1916"
    },
    {
      "headline": "Development of the Wechsler Adult Intelligence Scale",
      "text": "In 1955, David Wechsler developed the Wechsler Adult Intelligence Scale (WAIS), which became one of the most widely used IQ tests for adults.",
      "date": "1955"
    },
    {
      "headline": "Introduction of the Deviation IQ",
      "text": "In the mid-20th century, the concept of deviation IQ was introduced, which transformed raw scores into a normal distribution with a mean of 100 and a standard deviation of 15.",
      "date": "1950"
    },
    {
      "headline": "Flynn Effect Identified",
      "text": "In 1984, James R. Flynn identified the 'Flynn effect', observing that IQ scores have been increasing over time across the world.",
      "date": "1984"
    }
  ]
}

