    {
      "headline": "Birth of René Descartes",
      "text": "René Descartes was born on March 31, 1596, in La Haye en Touraine, France.",
      "date": "1596-03-31"
    },
    {
      "headline": "Education at Jesuit College",
      "text": "In 1607, Descartes entered the Jesuit College of La Flèche, where he studied for eight years, receiving a classical education.",
      "date": "1607"
    },
    {
      "headline": "Graduation from University of Poitiers",
      "text": "Descartes graduated with a law degree from the University of Poitiers in 1616.",
      "date": "1616"
    },
    {
      "headline": "Military Service in the Dutch States Army",
      "text": "In 1618, Descartes joined the Dutch States Army under the command of Maurice of Nassau, where he began his studies in mathematics and physics.",
      "date": "1618"
    },
    {
      "headline": "Vision of the Scientific Method",
      "text": "On November 10, 1619, Descartes had a series of dreams that inspired him to develop a new scientific method, which he later described in his work.",
      "date": "1619-11-10"
    },
    {
      "headline": "Publication of 'Discourse on the Method'",
      "text": "In 1637, Descartes published 'Discourse on the Method', which included his famous statement 'Cogito, ergo sum' ('I think, therefore I am').",
      "date": "1637"
    },
    {
      "headline": "Publication of 'Meditations on First Philosophy'",
      "text": "In 1641, Descartes published 'Meditations on First Philosophy', a foundational text in modern philosophy.",
      "date": "1641"
    },
    {
      "headline": "Publication of 'Principles of Philosophy'",
      "text": "In 1644, Descartes published 'Principles of Philosophy', which attempted to provide a comprehensive framework for all of science.",
      "date": "1644"
    },
    {
      "headline": "Move to Sweden",
      "text": "In 1649, Descartes moved to Sweden at the invitation of Queen Christina to tutor her in philosophy.",
      "date": "1649"
    },
    {
      "headline": "Death of René Descartes",
      "text": "René Descartes died on February 11, 1650, in Stockholm, Sweden, reportedly due to pneumonia.",
      "date": "1650-02-11"
    }
  ]
}
